import http from 'k6/http';
import { check, group } from 'k6';
import { SharedArray } from 'k6/data';

const BASE = __ENV.BASE_URL || 'http://127.0.0.1:8000';

export const options = {
  scenarios: {
    flow: {
      executor: 'per-vu-iterations',
      vus: 2,
      iterations: 2,
      maxDuration: '5m',
    },
  },
  thresholds: {
    checks: ['rate==1'],
  },
};

const USERS = new SharedArray('users', function () {
  return ['bench-1', 'bench-2'];
});

function jar() {
  return http.cookieJar();
}

function parseCsrfFromForm(body) {
  // Find input[name=csrf] value, tolerant of attribute order and quoting.
  // Match an <input ...> tag containing name=csrf (any quoting) and extract value.
  const tagRe = /<input\b[^>]*>/gi;
  let m;
  while ((m = tagRe.exec(body)) !== null) {
    const tag = m[0];
    const nameMatch = tag.match(/\bname\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s>]+))/i);
    if (!nameMatch) continue;
    const name = nameMatch[1] !== undefined ? nameMatch[1] : (nameMatch[2] !== undefined ? nameMatch[2] : nameMatch[3]);
    if (name !== 'csrf') continue;
    const valMatch = tag.match(/\bvalue\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s>]+))/i);
    if (!valMatch) continue;
    const val = valMatch[1] !== undefined ? valMatch[1] : (valMatch[2] !== undefined ? valMatch[2] : valMatch[3]);
    if (val) return val;
  }
  return null;
}

function getLoginForm(cj) {
  const res = http.get(`${BASE}/v2/login-form`, { jar: cj, redirects: 0 });
  check(res, { 'login-form 200': (r) => r.status === 200 });
  const csrf = parseCsrfFromForm(res.body || '');
  check(csrf, { 'csrf extracted': (v) => !!v });
  return csrf;
}

function login(cj, username) {
  const csrf = getLoginForm(cj);
  if (!csrf) return null;
  const res = http.post(
    `${BASE}/v2/login`,
    JSON.stringify({ username, password: 'bench', csrf }),
    { jar: cj, redirects: 0, headers: { 'Content-Type': 'application/json' } }
  );
  let body = null;
  try { body = res.json(); } catch (e) { body = null; }
  if (res.status === 302) {
    const loc = res.headers['Location'];
    if (loc) {
      const follow = http.get(loc.startsWith('http') ? loc : `${BASE}${loc}`, { jar: cj, redirects: 0 });
      try { body = follow.json(); } catch (e) { body = null; }
    }
  }
  check(res, { 'login ok': (r) => r.status === 200 || r.status === 302 });
  if (!body || !body.csrf) return null;
  return { csrf: body.csrf, user: body.user };
}

function renew(cj, csrf) {
  const res = http.post(`${BASE}/v2/session/renew`, JSON.stringify({}), {
    jar: cj,
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf },
  });
  let body = null;
  try { body = res.json(); } catch (e) { body = null; }
  if (body && body.csrf) return body.csrf;
  return csrf;
}

function recoverCart(cj, csrf, cartId) {
  const res = http.post(`${BASE}/v2/carts/${cartId}/recover`, JSON.stringify({}), {
    jar: cj,
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf },
  });
  let body = null;
  try { body = res.json(); } catch (e) { body = null; }
  if (body && body.csrf) return body.csrf;
  return csrf;
}

function authed(cj, method, url, body, csrf, extraHeaders) {
  const headers = Object.assign(
    { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf },
    extraHeaders || {}
  );
  const params = { jar: cj, headers, redirects: 0 };
  let res;
  if (method === 'GET') res = http.get(url, params);
  else if (method === 'POST') res = http.post(url, body === undefined ? null : JSON.stringify(body), params);
  else if (method === 'PATCH') res = http.patch(url, JSON.stringify(body), params);
  else res = http.request(method, url, body === undefined ? null : JSON.stringify(body), params);
  return res;
}

function handleExpiry(cj, state, res, retryFn) {
  let body = null;
  try { body = res.json(); } catch (e) { body = null; }
  if (res.status === 401 && body && body.error === 'expired') {
    state.csrf = renew(cj, state.csrf);
    if (state.cartId) state.csrf = recoverCart(cj, state.csrf, state.cartId);
    return retryFn();
  }
  if (res.status === 401 && body && body.error === 'session') {
    // revoked: fresh login
    const fresh = login(cj, state.username);
    if (fresh) {
      state.csrf = fresh.csrf;
      if (state.cartId) state.csrf = recoverCart(cj, state.csrf, state.cartId);
      return retryFn();
    }
  }
  return res;
}

function fetchCatalog(cj, csrf) {
  const products = [];
  let url = `${BASE}/v2/catalog`;
  let res = authed(cj, 'GET', url, undefined, csrf);
  res = handleExpiry(cj, { csrf, username: null }, res, () => authed(cj, 'GET', url, undefined, csrf));
  let body = null;
  try { body = res.json(); } catch (e) { body = null; }
  if (body && body.data && body.data.products) {
    for (const p of body.data.products) products.push(p);
  }
  // paginate up to 3 pages
  let next = body && body.next;
  let pages = 0;
  while (next && pages < 3) {
    pages++;
    const nextUrl = next.startsWith('http') ? next : `${BASE}${next}`;
    let r = authed(cj, 'GET', nextUrl, undefined, csrf);
    let b = null;
    try { b = r.json(); } catch (e) { b = null; }
    if (b && b.data && b.data.products) for (const p of b.data.products) products.push(p);
    next = b && b.next;
  }
  return products;
}

function pickVariant(products) {
  for (const p of products) {
    if (!p.variants) continue;
    for (const v of p.variants) {
      if (v.in_stock) return { product_id: p.id, variant_id: v.id };
    }
  }
  return null;
}

function doChallenge(cj, csrf) {
  const res = http.get(`${BASE}/v2/challenge-form`, { jar: cj, redirects: 0 });
  check(res, { 'challenge-form 200': (r) => r.status === 200 });
  const body = res.body || '';
  const actionMatch = body.match(/<form\b[^>]*\baction\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s>]+))/i);
  const action = actionMatch ? (actionMatch[1] || actionMatch[2] || actionMatch[3]) : null;
  const tagRe = /<input\b[^>]*>/gi;
  let challenge = null;
  let m;
  while ((m = tagRe.exec(body)) !== null) {
    const tag = m[0];
    const nameMatch = tag.match(/\bname\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s>]+))/i);
    if (!nameMatch) continue;
    const name = nameMatch[1] || nameMatch[2] || nameMatch[3];
    if (name !== 'challenge') continue;
    const valMatch = tag.match(/\bvalue\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s>]+))/i);
    if (valMatch) challenge = valMatch[1] || valMatch[2] || valMatch[3];
  }
  if (!action || !challenge) return null;
  const actionUrl = action.startsWith('http') ? action : `${BASE}${action}`;
  const post = http.post(actionUrl, JSON.stringify({ challenge }), {
    jar: cj,
    redirects: 0,
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf },
  });
  if (post.status !== 302) return null;
  const loc = post.headers['Location'];
  if (!loc) return null;
  const locUrl = loc.startsWith('http') ? loc : `${BASE}${loc}`;
  const follow = http.get(locUrl, { jar: cj, redirects: 0 });
  let b = null;
  try { b = follow.json(); } catch (e) { b = null; }
  if (b && b.grant_id) return { grant_id: b.grant_id, csrf: b.csrf || csrf };
  return null;
}

function doReservation(cj, csrf, cartId) {
  let res = authed(cj, 'POST', `${BASE}/v2/reservations`, { cart_id: cartId }, csrf);
  let body = null;
  try { body = res.json(); } catch (e) { body = null; }
  if (!body || !body.status_url) return null;
  let statusUrl = body.status_url.startsWith('http') ? body.status_url : `${BASE}${body.status_url}`;
  let curCsrf = body.csrf || csrf;
  for (let i = 0; i < 5; i++) {
    if (i > 0) {
      // sleep at least 50ms
      const t = Date.now();
      while (Date.now() - t < 60) { /* busy wait minimal */ }
    }
    const r = authed(cj, 'GET', statusUrl, undefined, curCsrf);
    let b = null;
    try { b = r.json(); } catch (e) { b = null; }
    if (!b) continue;
    if (b.csrf) curCsrf = b.csrf;
    if (b.status === 'ready' && b.reservation_id) {
      return { reservation_id: b.reservation_id, csrf: curCsrf };
    }
    if (b.status === 'failed') return null;
  }
  return null;
}

function doWork(cj, csrf) {
  let attempts = 0;
  while (attempts < 5) {
    attempts++;
    const res = authed(cj, 'POST', `${BASE}/v2/work`, {}, csrf);
    if (res.status === 429) {
      const ra = parseInt(res.headers['Retry-After'] || '1', 10);
      const t = Date.now();
      while (Date.now() - t < ra * 1000) { /* wait */ }
      continue;
    }
    let b = null;
    try { b = res.json(); } catch (e) { b = null; }
    if (b && b.csrf) csrf = b.csrf;
    check(res, { 'work ok': (r) => r.status === 200 });
    return csrf;
  }
  return csrf;
}

export default function () {
  const vu = __VU;
  const username = USERS[(vu - 1) % USERS.length];
  const cj = jar();
  const state = { csrf: null, cartId: null, username };

  group('login', function () {
    const l = login(cj, username);
    check(l, { 'logged in': (v) => !!v });
    if (!l) return;
    state.csrf = l.csrf;
  });
  if (!state.csrf) return;

  group('catalog', function () {
    const products = fetchCatalog(cj, state.csrf);
    check(products, { 'catalog non-empty': (p) => p.length > 0 });
    const pick = pickVariant(products);
    check(pick, { 'variant picked': (v) => !!v });
    if (!pick) return;

    // challenge for grant
    let grant = null;
    try { grant = doChallenge(cj, state.csrf); } catch (e) { grant = null; }
    if (grant) state.csrf = grant.csrf;

    const cartBody = { product_id: pick.product_id, variant_id: pick.variant_id };
    if (grant && grant.grant_id) cartBody.grant_id = grant.grant_id;

    let res = authed(cj, 'POST', `${BASE}/v2/carts`, cartBody, state.csrf);
    res = handleExpiry(cj, state, res, () => authed(cj, 'POST', `${BASE}/v2/carts`, cartBody, state.csrf));
    let body = null;
    try { body = res.json(); } catch (e) { body = null; }
    check(res, { 'cart created': (r) => r.status === 201 });
    if (!body || !body.id) return;
    state.cartId = body.id;
    if (body.csrf) state.csrf = body.csrf;

    // GET cart for ETag
    let getRes = authed(cj, 'GET', `${BASE}/v2/carts/${state.cartId}`, undefined, state.csrf);
    getRes = handleExpiry(cj, state, getRes, () => authed(cj, 'GET', `${BASE}/v2/carts/${state.cartId}`, undefined, state.csrf));
    let etag = getRes.headers['Etag'] || getRes.headers['ETag'];
    check(etag, { 'etag present': (v) => !!v });

    // PATCH quantity
    const patchBody = { quantity: 1 };
    let patchRes = authed(cj, 'PATCH', `${BASE}/v2/carts/${state.cartId}`, patchBody, state.csrf, { 'If-Match': etag });
    if (patchRes.status === 412) {
      const re = authed(cj, 'GET', `${BASE}/v2/carts/${state.cartId}`, undefined, state.csrf);
      const reEtag = re.headers['Etag'] || re.headers['ETag'];
      patchRes = authed(cj, 'PATCH', `${BASE}/v2/carts/${state.cartId}`, patchBody, state.csrf, { 'If-Match': reEtag });
    }
    patchRes = handleExpiry(cj, state, patchRes, () => authed(cj, 'PATCH', `${BASE}/v2/carts/${state.cartId}`, patchBody, state.csrf, { 'If-Match': etag }));
    let pb = null;
    try { pb = patchRes.json(); } catch (e) { pb = null; }
    if (pb && pb.csrf) state.csrf = pb.csrf;
    check(patchRes, { 'patch ok': (r) => r.status === 200 || r.status === 204 });

    // reservation
    let reservation = null;
    try { reservation = doReservation(cj, state.csrf, state.cartId); } catch (e) { reservation = null; }
    if (reservation) state.csrf = reservation.csrf;

    // work
    state.csrf = doWork(cj, state.csrf);

    // order
    const orderBody = { cart_id: state.cartId };
    if (reservation && reservation.reservation_id) orderBody.reservation_id = reservation.reservation_id;
    const idemKey = `cart-${state.cartId}-${username}`;

    // re-read etag for order
    let orderGet = authed(cj, 'GET', `${BASE}/v2/carts/${state.cartId}`, undefined, state.csrf);
    let orderEtag = orderGet.headers['Etag'] || orderGet.headers['ETag'];

    const orderHeaders = { 'Idempotency-Key': idemKey };
    if (orderEtag) orderHeaders['If-Match'] = orderEtag;

    let orderRes = authed(cj, 'POST', `${BASE}/v2/orders`, orderBody, state.csrf, orderHeaders);
    orderRes = handleExpiry(cj, state, orderRes, () => authed(cj, 'POST', `${BASE}/v2/orders`, orderBody, state.csrf, orderHeaders));
    let ob = null;
    try { ob = orderRes.json(); } catch (e) { ob = null; }
    if (ob && ob.csrf) state.csrf = ob.csrf;
    check(orderRes, { 'order accepted': (r) => r.status === 201 });
    check(ob, { 'order accepted true': (b) => b && b.accepted === true });
  });
}
