import os
import re
import time
from urllib.parse import urljoin

from locust import HttpUser, task, between
from locust.exception import StopUser
from locust import LoadTestShape


BASE_URL = os.environ.get("BASE_URL", "http://127.0.0.1:8000")


def _extract_csrf(html):
    # Find input[name=csrf] value, tolerant of attribute order/quoting/decoy variants.
    # Look for <input ...> tags containing name=csrf and a value attribute.
    for m in re.finditer(r"<input\b[^>]*>", html, re.IGNORECASE):
        tag = m.group(0)
        if re.search(r"""name\s*=\s*["']?csrf["']?""", tag, re.IGNORECASE):
            vm = re.search(r"""value\s*=\s*["']([^"']*)["']""", tag, re.IGNORECASE)
            if vm:
                return vm.group(1)
    return None


class ShopUser(HttpUser):
    host = BASE_URL
    wait_time = between(0.05, 0.1)

    def on_start(self):
        self.iterations_done = 0
        self.max_iterations = 2
        self.csrf = None
        self.session_ok = False

    def _login(self):
        # Fresh login each journey
        with self.client.get("/v2/login-form", name="/v2/login-form",
                             catch_response=True, allow_redirects=False) as r:
            if r.status_code != 200:
                r.failure(f"login-form status {r.status_code}")
                return False
            token = _extract_csrf(r.text)
            if not token:
                r.failure("no csrf in login form")
                return False
            r.success()
        self.csrf = token

        payload = {"username": self.username, "password": "bench", "csrf": self.csrf}
        with self.client.post("/v2/login", json=payload, name="/v2/login",
                              catch_response=True, allow_redirects=False) as r:
            if r.status_code == 302:
                loc = r.headers.get("Location")
                if not loc:
                    r.failure("302 without Location")
                    return False
                r.success()
                with self.client.get(loc, name="/v2/login-redirect",
                                     catch_response=True, allow_redirects=False) as r2:
                    if r2.status_code != 200:
                        r2.failure(f"login redirect status {r2.status_code}")
                        return False
                    try:
                        data = r2.json()
                    except Exception:
                        r2.failure("login redirect not json")
                        return False
                    if data.get("csrf"):
                        self.csrf = data["csrf"]
                    r2.success()
                self.session_ok = True
                return True
            elif r.status_code == 200:
                try:
                    data = r.json()
                except Exception:
                    r.failure("login not json")
                    return False
                if data.get("csrf"):
                    self.csrf = data["csrf"]
                r.success()
                self.session_ok = True
                return True
            else:
                r.failure(f"login status {r.status_code}")
                return False

    def _headers(self, extra=None):
        h = {"X-CSRF-Token": self.csrf or ""}
        if extra:
            h.update(extra)
        return h

    def _renew(self):
        with self.client.post("/v2/session/renew", json={}, name="/v2/session/renew",
                              headers=self._headers(), catch_response=True,
                              allow_redirects=False) as r:
            if r.status_code == 200:
                try:
                    data = r.json()
                except Exception:
                    r.failure("renew not json")
                    return False
                if data.get("csrf"):
                    self.csrf = data["csrf"]
                r.success()
                return True
            r.failure(f"renew status {r.status_code}")
            return False

    def _recover_cart(self, cart_id):
        with self.client.post(f"/v2/carts/{cart_id}/recover", json={},
                              name="/v2/carts/[id]/recover",
                              headers=self._headers(), catch_response=True,
                              allow_redirects=False) as r:
            if r.status_code in (200, 204):
                try:
                    data = r.json()
                    if isinstance(data, dict) and data.get("csrf"):
                        self.csrf = data["csrf"]
                except Exception:
                    pass
                r.success()
                return True
            r.failure(f"recover status {r.status_code}")
            return False

    def _get_catalog_products(self):
        products = []
        # First page
        with self.client.get("/v2/catalog", name="/v2/catalog",
                             catch_response=True, allow_redirects=False) as r:
            if r.status_code != 200:
                r.failure(f"catalog status {r.status_code}")
                return None
            try:
                data = r.json()
            except Exception:
                r.failure("catalog not json")
                return None
            r.success()
        d = data.get("data") or {}
        products.extend(d.get("products") or [])
        nxt = data.get("next")

        pages = 0
        while nxt and pages < 3:
            pages += 1
            url = nxt if nxt.startswith("http") else urljoin(BASE_URL, nxt)
            with self.client.get(url, name="/v2/catalog/page",
                                 catch_response=True, allow_redirects=False) as r:
                if r.status_code != 200:
                    r.failure(f"catalog page status {r.status_code}")
                    return None
                try:
                    data = r.json()
                except Exception:
                    r.failure("catalog page not json")
                    return None
                r.success()
            # page returns one product plus next
            prod = data.get("product") or data.get("data")
            if isinstance(prod, dict) and prod.get("id") is not None:
                products.append(prod)
            elif isinstance(data.get("data"), dict):
                p = data["data"].get("product")
                if p:
                    products.append(p)
            nxt = data.get("next")
        return products

    def _pick_variant(self, products):
        for p in products:
            variants = p.get("variants") or []
            for v in variants:
                if v.get("in_stock"):
                    return p.get("id"), v.get("id")
        return None, None

    def _get_challenge_grant(self):
        with self.client.get("/v2/challenge-form", name="/v2/challenge-form",
                             catch_response=True, allow_redirects=False) as r:
            if r.status_code != 200:
                r.failure(f"challenge-form status {r.status_code}")
                return None
            html = r.text
            r.success()
        am = re.search(r"""action\s*=\s*["']([^"']+)["']""", html, re.IGNORECASE)
        cm = re.search(r"""<input\b[^>]*name\s*=\s*["']?challenge["']?[^>]*>""", html, re.IGNORECASE)
        if not am or not cm:
            return None
        action = am.group(1)
        tag = cm.group(0)
        vm = re.search(r"""value\s*=\s*["']([^"']*)["']""", tag, re.IGNORECASE)
        if not vm:
            return None
        challenge = vm.group(1)
        url = action if action.startswith("http") else urljoin(BASE_URL, action)
        with self.client.post(url, json={"challenge": challenge},
                              name="/v2/challenges/[id]",
                              headers=self._headers(), catch_response=True,
                              allow_redirects=False) as r:
            if r.status_code != 302:
                r.failure(f"challenge post status {r.status_code}")
                return None
            loc = r.headers.get("Location")
            if not loc:
                r.failure("challenge 302 no Location")
                return None
            r.success()
        loc_url = loc if loc.startswith("http") else urljoin(BASE_URL, loc)
        with self.client.get(loc_url, name="/v2/challenges/claim",
                             catch_response=True, allow_redirects=False) as r:
            if r.status_code != 200:
                r.failure(f"challenge claim status {r.status_code}")
                return None
            try:
                data = r.json()
            except Exception:
                r.failure("challenge claim not json")
                return None
            if data.get("csrf"):
                self.csrf = data["csrf"]
            grant = data.get("grant_id")
            r.success()
            return grant

    def _create_cart(self, product_id, variant_id, grant_id):
        payload = {"product_id": product_id, "variant_id": variant_id}
        if grant_id:
            payload["grant_id"] = grant_id
        with self.client.post("/v2/carts", json=payload, name="/v2/carts",
                              headers=self._headers(), catch_response=True,
                              allow_redirects=False) as r:
            if r.status_code == 401:
                try:
                    err = r.json().get("error")
                except Exception:
                    err = None
                if err == "expired":
                    r.success()
                    if self._renew():
                        return self._create_cart(product_id, variant_id, grant_id)
                    return None
                r.failure(f"cart 401 {err}")
                return None
            if r.status_code != 201:
                r.failure(f"cart status {r.status_code}")
                return None
            try:
                data = r.json()
            except Exception:
                r.failure("cart not json")
                return None
            if data.get("csrf"):
                self.csrf = data["csrf"]
            etag = r.headers.get("ETag")
            r.success()
            return {"id": data.get("id"), "etag": etag}

    def _patch_quantity(self, cart_id, etag, qty):
        headers = self._headers({"If-Match": etag} if etag else None)
        with self.client.patch(f"/v2/carts/{cart_id}", json={"quantity": qty},
                               name="/v2/carts/[id]",
                               headers=headers, catch_response=True,
                               allow_redirects=False) as r:
            if r.status_code == 412:
                r.success()
                # re-read and retry once
                with self.client.get(f"/v2/carts/{cart_id}", name="/v2/carts/[id]",
                                     catch_response=True, allow_redirects=False) as rg:
                    if rg.status_code != 200:
                        rg.failure(f"cart get status {rg.status_code}")
                        return False
                    new_etag = rg.headers.get("ETag")
                    rg.success()
                headers2 = self._headers({"If-Match": new_etag} if new_etag else None)
                with self.client.patch(f"/v2/carts/{cart_id}", json={"quantity": qty},
                                       name="/v2/carts/[id]",
                                       headers=headers2, catch_response=True,
                                       allow_redirects=False) as r2:
                    if r2.status_code in (200, 204):
                        try:
                            d = r2.json()
                            if isinstance(d, dict) and d.get("csrf"):
                                self.csrf = d["csrf"]
                        except Exception:
                            pass
                        r2.success()
                        return True
                    r2.failure(f"cart patch retry status {r2.status_code}")
                    return False
            if r.status_code in (200, 204):
                try:
                    d = r.json()
                    if isinstance(d, dict) and d.get("csrf"):
                        self.csrf = d["csrf"]
                except Exception:
                    pass
                r.success()
                return True
            if r.status_code == 401:
                try:
                    err = r.json().get("error")
                except Exception:
                    err = None
                if err == "expired":
                    r.success()
                    if self._renew():
                        return self._patch_quantity(cart_id, etag, qty)
                    return False
                r.failure(f"patch 401 {err}")
                return False
            r.failure(f"cart patch status {r.status_code}")
            return False

    def _reserve(self, cart_id):
        with self.client.post("/v2/reservations", json={"cart_id": cart_id},
                              name="/v2/reservations",
                              headers=self._headers(), catch_response=True,
                              allow_redirects=False) as r:
            if r.status_code != 202:
                r.failure(f"reservation status {r.status_code}")
                return None
            try:
                data = r.json()
            except Exception:
                r.failure("reservation not json")
                return None
            if data.get("csrf"):
                self.csrf = data["csrf"]
            status_url = data.get("status_url")
            r.success()
        if not status_url:
            return None
        url = status_url if status_url.startswith("http") else urljoin(BASE_URL, status_url)
        for i in range(5):
            time.sleep(0.06)
            with self.client.get(url, name="/v2/reservations/status",
                                 catch_response=True, allow_redirects=False) as r:
                if r.status_code != 200:
                    r.failure(f"res status {r.status_code}")
                    return None
                try:
                    data = r.json()
                except Exception:
                    r.failure("res status not json")
                    return None
                if data.get("csrf"):
                    self.csrf = data["csrf"]
                status = data.get("status")
                r.success()
                if status == "ready":
                    return data.get("reservation_id")
                if status in ("pending",):
                    continue
                # failed
                return None
        return None

    def _order(self, cart_id, reservation_id):
        payload = {"cart_id": cart_id}
        if reservation_id:
            payload["reservation_id"] = reservation_id
        headers = self._headers({"Idempotency-Key": f"cart-{cart_id}"})
        with self.client.post("/v2/orders", json=payload, name="/v2/orders",
                              headers=headers, catch_response=True,
                              allow_redirects=False) as r:
            if r.status_code == 401:
                try:
                    err = r.json().get("error")
                except Exception:
                    err = None
                if err == "expired":
                    r.success()
                    if self._renew():
                        return self._order(cart_id, reservation_id)
                    return False
                r.failure(f"order 401 {err}")
                return False
            if r.status_code != 201:
                r.failure(f"order status {r.status_code}")
                return False
            try:
                data = r.json()
            except Exception:
                r.failure("order not json")
                return False
            if data.get("csrf"):
                self.csrf = data["csrf"]
            if data.get("accepted") is not True:
                r.failure("order not accepted")
                return False
            r.success()
            return True

    def _do_work(self):
        # optional work sample
        with self.client.post("/v2/work", json={}, name="/v2/work",
                              headers=self._headers(), catch_response=True,
                              allow_redirects=False) as r:
            if r.status_code == 429:
                ra = r.headers.get("Retry-After", "1")
                try:
                    delay = float(ra)
                except Exception:
                    delay = 1.0
                r.success()
                time.sleep(min(delay, 1.0))
                return
            if r.status_code == 200:
                r.success()
                return
            r.failure(f"work status {r.status_code}")

    @task
    def journey(self):
        if self.iterations_done >= self.max_iterations:
            raise StopUser()
        self.iterations_done += 1

        if not self._login():
            raise StopUser()

        products = self._get_catalog_products()
        if not products:
            raise StopUser()
        pid, vid = self._pick_variant(products)
        if pid is None:
            raise StopUser()

        grant = self._get_challenge_grant()

        cart = self._create_cart(pid, vid, grant)
        if not cart or not cart.get("id"):
            raise StopUser()

        if not self._patch_quantity(cart["id"], cart.get("etag"), 1):
            raise StopUser()

        reservation_id = self._reserve(cart["id"])
        if not reservation_id:
            raise StopUser()

        if not self._order(cart["id"], reservation_id):
            raise StopUser()

        self._do_work()


class ShopUser2(ShopUser):
