import io.gatling.javaapi.core.*;
import io.gatling.javaapi.http.*;

import java.time.Duration;
import java.util.*;
import java.util.concurrent.ThreadLocalRandom;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

import static io.gatling.javaapi.core.CoreDsl.*;
import static io.gatling.javaapi.http.HttpDsl.*;

public class ModelSimulation extends Simulation {

    private static final String BASE = System.getenv().getOrDefault("BASE_URL", "http://127.0.0.1:8000");

    private static final Pattern CSRF_INPUT = Pattern.compile(
            "<input\\b[^>]*\\bname\\s*=\\s*[\"']csrf[\"'][^>]*>", Pattern.CASE_INSENSITIVE);
    private static final Pattern ATTR_VALUE = Pattern.compile(
            "\\b([a-zA-Z_:][-a-zA-Z0-9_:.]*)\\s*=\\s*(\"([^\"]*)\"|'([^']*)'|([^\\s>]+))");

    private static String extractCsrf(String html) {
        if (html == null) return null;
        Matcher m = CSRF_INPUT.matcher(html);
        while (m.find()) {
            String tag = m.group();
            Matcher a = ATTR_VALUE.matcher(tag);
            while (a.find()) {
                String name = a.group(1);
                if ("name".equalsIgnoreCase(name)) continue;
                String val = a.group(3) != null ? a.group(3)
                        : a.group(4) != null ? a.group(4) : a.group(5);
                if (val != null && !val.isEmpty()) return val;
            }
        }
        return null;
    }

    private static final Pattern LOCATION = Pattern.compile("Location:\\s*(\\S+)", Pattern.CASE_INSENSITIVE);

    private static final HttpProtocolBuilder HTTP = http
            .baseUrl(BASE)
            .disableAutoRedirect()
            .acceptHeader("application/json, text/html")
            .contentTypeHeader("application/json");

    private static ChainBuilder loginFlow() {
        return exec(
                http("GET login form")
                        .get("/v2/login-form")
                        .check(status().is(200))
                        .check(bodyString().transform(ModelSimulation::extractCsrf).saveAs("loginCsrf"))
        ).exec(session -> {
            String csrf = session.getString("loginCsrf");
            if (csrf == null) {
                throw new IllegalStateException("login csrf not found");
            }
            return session;
        }).exec(
                http("POST login")
                        .post("/v2/login")
                        .body(StringBody(session -> {
                            String user = session.getString("username");
                            String csrf = session.getString("loginCsrf");
                            return "{\"username\":\"" + user + "\",\"password\":\"bench\",\"csrf\":\"" + csrf + "\"}";
                        }))
                        .check(status().in(200, 302))
                        .check(header("Location").optional().saveAs("loginLocation"))
                        .check(bodyString().optional().saveAs("loginBody"))
        ).exec(session -> {
            String loc = session.getString("loginLocation");
            if (loc != null && !loc.isEmpty()) {
                return session.set("loginRedirect", loc);
            }
            return session;
        }).doIf(session -> session.getString("loginRedirect") != null).then(
                exec(
                        http("GET login redirect")
                                .get(session -> session.getString("loginRedirect"))
                                .check(status().is(200))
                                .check(bodyString().saveAs("loginBody2"))
                )
        ).exec(session -> {
            String body = session.getString("loginBody2");
            if (body == null) body = session.getString("loginBody");
            String csrf = extractJsonString(body, "csrf");
            if (csrf != null) {
                return session.set("csrf", csrf);
            }
            return session;
        });
    }

    private static String extractJsonString(String json, String key) {
        if (json == null) return null;
        Pattern p = Pattern.compile("\"" + Pattern.quote(key) + "\"\\s*:\\s*\"([^\"]*)\"");
        Matcher m = p.matcher(json);
        if (m.find()) return m.group(1);
        return null;
    }

    private static ChainBuilder catalogFlow() {
        return exec(
                http("GET catalog")
                        .get("/v2/catalog")
                        .check(status().is(200))
                        .check(bodyString().saveAs("catalogBody"))
        ).exec(session -> {
            String body = session.getString("catalogBody");
            String pid = null, vid = null;
            if (body != null) {
                Pattern pp = Pattern.compile("\"id\"\\s*:\\s*\"?([A-Za-z0-9_-]+)\"?");
                Matcher pm = pp.matcher(body);
                if (pm.find()) pid = pm.group(1);
                Pattern vp = Pattern.compile("\"variants\"\\s*:\\s*\\[\\s*\\{[^}]*\"id\"\\s*:\\s*\"?([A-Za-z0-9_-]+)\"?");
                Matcher vm = vp.matcher(body);
                if (vm.find()) vid = vm.group(1);
            }
            return session.set("productId", pid).set("variantId", vid);
        });
    }

    private static ChainBuilder challengeFlow() {
        return exec(
                http("GET challenge form")
                        .get("/v2/challenge-form")
                        .check(status().is(200))
                        .check(bodyString().saveAs("challengeBody"))
        ).exec(session -> {
            String body = session.getString("challengeBody");
            String action = null, challenge = null;
            if (body != null) {
                Matcher am = Pattern.compile("action\\s*=\\s*[\"']([^\"']+)[\"']").matcher(body);
                if (am.find()) action = am.group(1);
                Matcher cm = Pattern.compile("name\\s*=\\s*[\"']challenge[\"'][^>]*value\\s*=\\s*[\"']([^\"']+)[\"']").matcher(body);
                if (!cm.find()) {
                    cm = Pattern.compile("value\\s*=\\s*[\"']([^\"']+)[\"'][^>]*name\\s*=\\s*[\"']challenge[\"']").matcher(body);
                }
                if (cm.find()) challenge = cm.group(1);
            }
            return session.set("challengeAction", action).set("challengeValue", challenge);
        }).doIf(session -> session.getString("challengeAction") != null).then(
                exec(
                        http("POST challenge")
                                .post(session -> session.getString("challengeAction"))
                                .header("X-CSRF-Token", session -> session.getString("csrf"))
                                .body(StringBody(session -> "{\"challenge\":\"" + session.getString("challengeValue") + "\"}"))
                                .check(status().in(200, 302))
                                .check(header("Location").optional().saveAs("challengeLocation"))
                ).doIf(session -> session.getString("challengeLocation") != null).then(
                        exec(
                                http("GET challenge redirect")
                                        .get(session -> session.getString("challengeLocation"))
                                        .check(status().is(200))
                                        .check(bodyString().saveAs("grantBody"))
                        ).exec(session -> {
                            String g = extractJsonString(session.getString("grantBody"), "grant_id");
                            String c = extractJsonString(session.getString("grantBody"), "csrf");
                            Session s = session;
                            if (g != null) s = s.set("grantId", g);
                            if (c != null) s = s.set("csrf", c);
                            return s;
                        })
                )
        );
    }

    private static ChainBuilder cartFlow() {
        return exec(
                http("POST cart")
                        .post("/v2/carts")
                        .header("X-CSRF-Token", session -> session.getString("csrf"))
                        .body(StringBody(session -> {
                            String pid = session.getString("productId");
                            String vid = session.getString("variantId");
                            String gid = session.getString("grantId");
                            StringBuilder sb = new StringBuilder("{");
                            sb.append("\"product_id\":\"").append(pid).append("\",");
                            sb.append("\"variant_id\":\"").append(vid).append("\"");
                            if (gid != null) sb.append(",\"grant_id\":\"").append(gid).append("\"");
                            sb.append("}");
                            return sb.toString();
                        }))
                        .check(status().is(201))
                        .check(bodyString().saveAs("cartBody"))
                        .check(header("ETag").optional().saveAs("cartEtag"))
        ).exec(session -> {
            String body = session.getString("cartBody");
            String id = extractJsonString(body, "id");
            String csrf = extractJsonString(body, "csrf");
            Session s = session.set("cartId", id);
            if (csrf != null) s = s.set("csrf", csrf);
            return s;
        });
    }

    private static ChainBuilder patchCartFlow() {
        return exec(
                http("GET cart")
                        .get(session -> "/v2/carts/" + session.getString("cartId"))
                        .check(status().is(200))
                        .check(header("ETag").optional().saveAs("cartEtag"))
        ).exec(
                http("PATCH cart")
                        .patch(session -> "/v2/carts/" + session.getString("cartId"))
                        .header("X-CSRF-Token", session -> session.getString("csrf"))
                        .header("If-Match", session -> {
                            String e = session.getString("cartEtag");
                            return e == null ? "*" : e;
                        })
                        .body(StringBody("{\"quantity\":1}"))
                        .check(status().in(200, 204, 412))
        ).doIf(session -> {
            Integer st = session.getInt("patchStatus");
            return st != null && st == 412;
        }).then(
                exec(
                        http("GET cart retry")
                                .get(session -> "/v2/carts/" + session.getString("cartId"))
                                .check(status().is(200))
                                .check(header("ETag").optional().saveAs("cartEtag"))
                ).exec(
                        http("PATCH cart retry")
                                .patch(session -> "/v2/carts/" + session.getString("cartId"))
                                .header("X-CSRF-Token", session -> session.getString("csrf"))
                                .header("If-Match", session -> {
                                    String e = session.getString("cartEtag");
                                    return e == null ? "*" : e;
                                })
                                .body(StringBody("{\"quantity\":1}"))
                                .check(status().in(200, 204))
                )
        );
    }

    private static ChainBuilder reservationFlow() {
        return exec(
                http("POST reservation")
                        .post("/v2/reservations")
                        .header("X-CSRF-Token", session -> session.getString("csrf"))
                        .body(StringBody(session -> "{\"cart_id\":\"" + session.getString("cartId") + "\"}"))
                        .check(status().is(202))
                        .check(bodyString().saveAs("resBody"))
        ).exec(session -> {
            String body = session.getString("resBody");
            String url = extractJsonString(body, "status_url");
            String csrf = extractJsonString(body, "csrf");
            Session s = session.set("statusUrl", url);
            if (csrf != null) s = s.set("csrf", csrf);
            return s;
        }).asLongAs(session -> {
            Integer n = session.getInt("pollCount");
            return n == null || n < 5;
        }).on(
                pause(Duration.ofMillis(60)).exec(
                        http("GET reservation status")
                                .get(session -> session.getString("statusUrl"))
                                .check(status().is(200))
                                .check(bodyString().saveAs("statusBody"))
                ).exec(session -> {
                    String body = session.getString("statusBody");
                    String status = extractJsonString(body, "status");
                    String rid = extractJsonString(body, "reservation_id");
                    String csrf = extractJsonString(body, "csrf");
                    Integer n = session.getInt("pollCount");
                    int next = (n == null ? 0 : n) + 1;
                    Session s = session.set("pollCount", next).set("resStatus", status);
                    if (rid != null) s = s.set("reservationId", rid);
                    if (csrf != null) s = s.set("csrf", csrf);
                    return s;
                })
        ).exec(session -> {
            String status = session.getString("resStatus");
            if (!"ready".equals(status)) {
                throw new IllegalStateException("reservation not ready: " + status);
            }
            return session;
        });
    }

    private static ChainBuilder orderFlow() {
        return exec(
                http("POST order")
                        .post("/v2/orders")
                        .header("X-CSRF-Token", session -> session.getString("csrf"))
                        .header("Idempotency-Key", session -> "idem-" + session.getString("cartId"))
                        .body(StringBody(session -> {
                            String cid = session.getString("cartId");
                            String rid = session.getString("reservationId");
                            StringBuilder sb = new StringBuilder("{");
                            sb.append("\"cart_id\":\"").append(cid).append("\"");
                            if (rid != null) sb.append(",\"reservation_id\":\"").append(rid).append("\"");
                            sb.append("}");
                            return sb.toString();
                        }))
                        .check(status().is(201))
                        .check(bodyString().saveAs("orderBody"))
        ).exec(session -> {
            String body = session.getString("orderBody");
            String accepted = extractJsonString(body, "accepted");
            if (!"true".equals(accepted)) {
                throw new IllegalStateException("order not accepted");
            }
            return session;
        });
    }

    private static ChainBuilder workFlow() {
        return exec(
                http("POST work")
                        .post("/v2/work")
                        .header("X-CSRF-Token", session -> session.getString("csrf"))
                        .body(StringBody("{}"))
                        .check(status().in(200, 429))
        );
    }

    private ScenarioBuilder scenario(String name) {
        return scenario(name)
                .exec(session -> session.set("username", "bench-" + (session.userId() % 16 + 1)))
                .exec(loginFlow())
                .exec(catalogFlow())
                .exec(challengeFlow())
                .exec(cartFlow())
                .exec(patchCartFlow())
                .exec(reservationFlow())
                .exec(orderFlow())
                .exec(workFlow());
    }

    {
        setUp(
                scenario("flow").injectOpen(
                        rampUsers(2).during(Duration.ofSeconds(1))
                )
        ).protocols(HTTP);
    }
}
