function createReservation(cartId, csrf) {
  const res = req('POST', '/v2/reservations', { cart_id: cartId }, { headers: { 'X-CSRF-Token': csrf } });
  check(res, { 'reservation 202': (r) => r.status === 202 });
  const body = parseJson(res);
  return {
    statusUrl: body && body.status_url,
    csrf: (body && body.csrf) || csrf,
  };
