function pollReservation(statusUrl, csrf) {
  let reservationId = null;
  for (let i = 0; i < 5; i++) {
    if (i > 0) {
      // sleep at least 50ms
      const start = Date.now();
      while (Date.now() - start < 60) { /* busy wait */ }
    }
    const res = req('GET', statusUrl, null, { headers: { 'X-CSRF-Token': csrf } });
    const body = parseJson(res);
    if (!body) continue;
    if (body.status === 'ready' && body.reservation_id) {
      reservationId = body.reservation_id;
      break;
    }
    if (body.status === 'failed') break;
  }
  return reservationId;
}

function placeOrder(cartId, reservationId, csrf, idemKey, etag) {
  const payload = { cart_id: cartId };
  if (reservationId) payload.reservation_id = reservationId;
  const headers = { 'X-CSRF-Token': csrf, 'Idempotency-Key': idemKey, 'Content-Type': 'application/json' };
