function handleExpiry(opFn, csrf, cartId) {
  // opFn returns {res, csrf}
  let result = opFn(csrf);
  if (result.res.status === 401) {
    const body = parseJson(result.res);
    const err = body && body.error;
    if (err === 'expired') {
      const renewed = renewSession(result.csrf);
      let newCsrf = renewed.csrf;
      if (cartId) {
