                    ) as r2:
                        if r2.status_code not in (200, 204):
                            r2.failure(f"patch retry status {r2.status_code}")
                            return None
                        try:
                            data = r2.json()
                        except Exception:
                            data = {}
                        if data.get("csrf"):
                            self.csrf = data["csrf"]
                        return r2.headers.get("ETag") or etag
                r.failure("patch 401 unrecoverable")
                return None
            if r.status_code not in (200, 204):
                r.failure(f"patch status {r.status_code}")
                return None
            try:
                data = r.json()
            except Exception:
                data = {}
            if data.get("csrf"):
                self.csrf = data["csrf"]
            return r.headers.get("ETag") or etag

    def _reserve(self, cart_id):
        with self.client.post(
            "/v2/reservations",
            json={"cart_id": cart_id},
            headers=self._headers(),
            name="POST /v2/reservations",
            catch_response=True,
        ) as r:
            if r.status_code == 401:
                if self._handle_401(r, cart_id):
                    with self.client.post(
                        "/v2/reservations",
                        json={"cart_id": cart_id},
                        headers=self._headers(),
                        name="POST /v2/reservations",
                        catch_response=True,
                    ) as r2:
                        if r2.status_code != 202:
                            r2.failure(f"reservation retry status {r2.status_code}")
                            return None
                        try:
                            data = r2.json()
                        except Exception:
                            data = {}
                        if data.get("csrf"):
                            self.csrf = data["csrf"]
                        return data.get("status_url")
                r.failure("reservation 401 unrecoverable")
                return None
            if r.status_code != 202:
                r.failure(f"reservation status {r.status_code}")
                return None
            try:
                data = r.json()
            except Exception:
                data = {}
            if data.get("csrf"):
                self.csrf = data["csrf"]
            return data.get("status_url")

    def _poll_reservation(self, status_url):
        for i in range(5):
            if i > 0:
                time.sleep(0.06)
            with self.client.get(
                _abs(status_url),
                name="GET reservation status",
                catch_response=True,
            ) as r:
                if r.status_code != 200:
                    r.failure(f"status poll {r.status_code}")
                    return None
                try:
                    data = r.json()
                except Exception:
                    data = {}
                if data.get("csrf"):
                    self.csrf = data["csrf"]
                status = data.get("status")
                if status == "ready":
                    return data.get("reservation_id")
                if status in ("pending",):
                    continue
                if status in ("failed",):
                    r.failure("reservation failed")
                    return None
        return None

    def _checkout(self, cart_id, reservation_id, etag):
        headers = self._headers({"Idempotency-Key": f"cart-{cart_id}"})
        if etag:
            headers["If-Match"] = etag
        payload = {"cart_id": cart_id}
        if reservation_id:
            payload["reservation_id"] = reservation_id

        def _do():
            with self.client.post(
                "/v2/orders",
                json=payload,
                headers=headers,
                name="POST /v2/orders",
                catch_response=True,
            ) as r:
                if r.status_code == 401:
                    if self._handle_401(r, cart_id):
                        return "retry"
                    r.failure("order 401 unrecoverable")
                    return "fail"
                if r.status_code == 200:
                    try:
                        data = r.json()
                    except Exception:
                        data = {}
                    if data.get("accepted") is False:
                        r.failure("order accepted:false")
                        return "fail"
                    if data.get("csrf"):
                        self.csrf = data["csrf"]
                    return "ok"
                if r.status_code == 201:
                    try:
                        data = r.json()
                    except Exception:
                        data = {}
                    if data.get("accepted") is not True:
                        r.failure("order 201 without accepted:true")
                        return "fail"
                    if data.get("csrf"):
                        self.csrf = data["csrf"]
                    return "ok"
                r.failure(f"order status {r.status_code}")
                return "fail"

        res = _do()
        if res == "retry":
            res = _do()
        return res == "ok"

    def _work(self):
        with self.client.post(
            "/v2/work",
            json={},
            headers=self._headers(),
            name="POST /v2/work",
            catch_response=True,
        ) as r:
            if r.status_code == 429:
                ra = r.headers.get("Retry-After", "1")
                try:
                    delay = float(ra)
                except Exception:
                    delay = 1.0
                time.sleep(min(delay, 1.0))
                # one retry
                with self.client.post(
                    "/v2/work",
                    json={},
                    headers=self._headers(),
                    name="POST /v2/work",
                    catch_response=True,
                ) as r2:
                    if r2.status_code == 200:
                        return
                    if r2.status_code == 429:
                        return
                    r2.failure(f"work retry status {r2.status_code}")
                return
            if r.status_code == 200:
                return
            r.failure(f"work status {r.status_code}")

    # ---------- journey ----------

    @task
    def journey(self):
        if self.iterations_done >= self.max_iterations:
            raise StopUser()

        if not self.session_ready:
            if not self._login():
                self.iterations_done += 1
                if self.iterations_done >= self.max_iterations:
                    raise StopUser()
                return

        # catalog
        products = self._get_catalog_products()
        product_id, variant_id = self._pick_variant(products)
        if not product_id or not variant_id:
            self.iterations_done += 1
            if self.iterations_done >= self.max_iterations:
                raise StopUser()
            return

        # challenge grant
        grant_id = self._challenge_grant()

        # cart
        cart_id, etag = self._create_cart(product_id, variant_id, grant_id)
        if not cart_id:
            self.iterations_done += 1
            if self.iterations_done >= self.max_iterations:
                raise StopUser()
            return

        # patch quantity
        new_etag = self._patch_quantity(cart_id, etag, 1)
        if new_etag is not None:
            etag = new_etag

        # reservation
        status_url = self._reserve(cart_id)
        reservation_id = None
        if status_url:
            reservation_id = self._poll_reservation(status_url)

        # checkout
        self._checkout(cart_id, reservation_id, etag)

        # work sample
        self._work()

        self.iterations_done += 1
        if self.iterations_done >= self.max_iterations:
            raise StopUser()


class ShopShape(LoadTestShape):
    def tick(self):
        run_time = self.get_run_time()
        if run_time > 60:
            return None
        return (2, 2)
