    private static final String BASE = System.getenv().getOrDefault("BASE_URL", "http://127.0.0.1:8000");

    private static final Pattern CSRF_INPUT = Pattern.compile(
            "name=\"csrf\"[^>]*value=\"([^\"]+)\"|value=\"([^\"]+)\"[^>]*name=\"csrf\"");
    private static final Pattern CHALLENGE_ACTION = Pattern.compile("action=\"(/v2/challenges/[^\"]+)\"");
    private static final Pattern CHALLENGE_INPUT = Pattern.compile(
            "name=\"challenge\"[^>]*value=\"([^\"]+)\"|value=\"([^\"]+)\"[^>]*name=\"challenge\"");

    private static final AtomicInteger IDEMP = new AtomicInteger(0);

    private static String extract(Pattern p, String body, int group) {
        if (body == null) return null;
        Matcher m = p.matcher(body);
        if (m.find()) {
            String v = m.group(group);
            if (v == null) v = m.group(1);
            return v;
        }
        return null;
    }

    private static String extractCsrf(String body) {
        if (body == null) return null;
        Matcher m = CSRF_INPUT.matcher(body);
        if (m.find()) {
            return m.group(1) != null ? m.group(1) : m.group(2);
        }
        return null;
    }

    private static String extractChallenge(String body) {
        if (body == null) return null;
        Matcher m = CHALLENGE_INPUT.matcher(body);
        if (m.find()) {
            return m.group(1) != null ? m.group(1) : m.group(2);
        }
        return null;
    }

    private static String extractChallengeAction(String body) {
        if (body == null) return null;
        Matcher m = CHALLENGE_ACTION.matcher(body);
        if (m.find()) return m.group(1);
        return null;
    }

    private static final HttpProtocolBuilder HTTP = http
            .baseUrl(BASE)
            .disableAutoRedirect()
            .acceptHeader("application/json")
            .contentTypeHeader("application/json");

    private static ChainBuilder login(String user) {
        return exec(
                http("login-form")
                        .get("/v2/login-form")
                        .check(status().is(200))
                        .check(bodyString().saveAs("loginFormBody"))
        ).exec(session -> {
            String csrf = extractCsrf(session.getString("loginFormBody"));
            return session.set("csrf", csrf);
        }).exec(
                http("login")
                        .post("/v2/login")
                        .body(StringBody(session ->
                                "{\"username\":\"" + user + "\",\"password\":\"bench\",\"csrf\":\"" +
                                        session.getString("csrf") + "\"}"))
                        .check(status().in(200, 302))
                        .check(bodyString().saveAs("loginBody"))
        ).exec(session -> {
            String body = session.getString("loginBody");
            String csrf = extractCsrf(body);
            if (csrf != null) {
                return session.set("csrf", csrf);
            }
            return session;
        });
    }

    private static ChainBuilder fetchCatalog() {
        return exec(
                http("catalog")
                        .get("/v2/catalog")
                        .check(status().is(200))
                        .check(bodyString().saveAs("catalogBody"))
        );
