    private static ChainBuilder fetchCatalogPage(int page) {
        return exec(
                http("catalog-page-" + page)
                        .get("/v2/catalog/page")
                        .check(status().is(200))
                        .check(bodyString().saveAs("catalogPageBody" + page))
        );
