    private static ChainBuilder selectProduct() {
        return exec(session -> {
            List<String> bodies = new ArrayList<>();
            String main = session.getString("catalogBody");
            if (main != null) bodies.add(main);
            for (int i = 1; i <= 3; i++) {
                String b = session.getString("catalogPageBody" + i);
                if (b != null) bodies.add(b);
            }
            String productId = null;
            String variantId = null;
            for (String body : bodies) {
                String[] found = findInStock(body);
                if (found != null) {
                    productId = found[0];
                    variantId = found[1];
                    break;
                }
            }
            if (productId == null) {
                return session.markAsFailed();
            }
            return session.set("productId", productId).set("variantId", variantId);
        });
    }

    private static String[] findInStock(String body) {
        if (body == null) return null;
        int idx = 0;
        while (true) {
            int pIdx = body.indexOf("\"products\"", idx);
            if (pIdx < 0) break;
            int arrStart = body.indexOf('[', pIdx);
            if (arrStart < 0) break;
            int depth = 0;
            int arrEnd = -1;
            for (int i = arrStart; i < body.length(); i++) {
                char c = body.charAt(i);
                if (c == '[') depth++;
                else if (c == ']') {
                    depth--;
                    if (depth == 0) { arrEnd = i; break; }
                }
            }
            if (arrEnd < 0) break;
            String arr = body.substring(arrStart + 1, arrEnd);
            String[] r = scanProducts(arr);
            if (r != null) return r;
            idx = arrEnd + 1;
        }
        return null;
    }

    private static String[] scanProducts(String arr) {
        int i = 0;
        while (i < arr.length()) {
            int objStart = arr.indexOf('{', i);
            if (objStart < 0) break;
            int depth = 0;
            int objEnd = -1;
            for (int j = objStart; j < arr.length(); j++) {
                char c = arr.charAt(j);
                if (c == '{') depth++;
                else if (c == '}') {
                    depth--;
                    if (depth == 0) { objEnd = j; break; }
                }
            }
            if (objEnd < 0) break;
            String obj = arr.substring(objStart, objEnd + 1);
            String pid = extractStringField(obj, "id");
            int vIdx = obj.indexOf("\"variants\"");
            if (pid != null && vIdx >= 0) {
                int vArrStart = obj.indexOf('[', vIdx);
                if (vArrStart >= 0) {
                    int vDepth = 0;
                    int vArrEnd = -1;
                    for (int k = vArrStart; k < obj.length(); k++) {
                        char c = obj.charAt(k);
                        if (c == '[') vDepth++;
                        else if (c == ']') {
                            vDepth--;
                            if (vDepth == 0) { vArrEnd = k; break; }
                        }
                    }
                    if (vArrEnd > 0) {
                        String vArr = obj.substring(vArrStart + 1, vArrEnd);
                        String vid = findInStockVariant(vArr);
                        if (vid != null) {
                            return new String[]{pid, vid};
                        }
                    }
                }
            }
            i = objEnd + 1;
        }
        return null;
    }

    private static String findInStockVariant(String vArr) {
        int i = 0;
        while (i < vArr.length()) {
            int objStart = vArr.indexOf('{', i);
            if (objStart < 0) break;
            int depth = 0;
            int objEnd = -1;
            for (int j = objStart; j < vArr.length(); j++) {
                char c = vArr.charAt(j);
                if (c == '{') depth++;
                else if (c == '}') {
                    depth--;
                    if (depth == 0) { objEnd = j; break; }
                }
            }
            if (objEnd < 0) break;
            String obj = vArr.substring(objStart, objEnd + 1);
            String vid = extractStringField(obj, "id");
            boolean inStock = obj.contains("\"in_stock\":true") || obj.contains("\"in_stock\": true");
            if (vid != null && inStock) return vid;
            i = objEnd + 1;
        }
        return null;
    }

    private static String extractStringField(String obj, String field) {
        String key = "\"" + field + "\"";
        int idx = obj.indexOf(key);
        if (idx < 0) return null;
        int colon = obj.indexOf(':', idx + key.length());
        if (colon < 0) return null;
        int q1 = obj.indexOf('"', colon + 1);
        if (q1 < 0) return null;
        int q2 = obj.indexOf('"', q1 + 1);
        if (q2 < 0) return null;
        return obj.substring(q1 + 1, q2);
    }

    private static ChainBuilder createCart() {
        return exec(
