import http from 'k6/http';
import { check } from 'k6';
import { SharedArray } from 'k6/data';

const BASE = __ENV.BASE_URL || 'http://127.0.0.1:8000';

export const options = {
  scenarios: {
    flow: {
      executor: 'per-vu-iterations',
      vus: 2,
      iterations: 2,
      maxDuration: '120s',
    },
  },
};

const USERS = new SharedArray('users', function () {
  return ['bench-1', 'bench-2'];
});

function jar() {
  return http.cookieJar();
}

function parseCsrfFromForm(body) {
  // input[name=csrf] with possible attribute variants / decoys
  const re = /<input\b[^>]*\bname\s*=\s*["']?csrf["']?[^>]*>/gi;
  let m;
  while ((m = re.exec(body)) !== null) {
    const tag = m[0];
    const vm = tag.match(/\bvalue\s*=\s*["']([^"']*)["']/i);
    if (vm) return vm[1];
  }
  // fallback: any value= near csrf
  const re2 = /name\s*=\s*["']?csrf["']?[^>]*value\s*=\s*["']([^"']*)["']/i;
  const m2 = body.match(re2);
  if (m2) return m2[1];
  return null;
}

function getLoginForm() {
  const res = http.get(`${BASE}/v2/login-form`, { redirects: 0 });
  check(res, { 'login-form 200': (r) => r.status === 200 });
  return parseCsrfFromForm(res.body || '');
}

function login(username, password) {
  let csrf = getLoginForm();
  if (!csrf) return null;
  const res = http.post(`${BASE}/v2/login`, JSON.stringify({ username, password, csrf }), {
    headers: { 'Content-Type': 'application/json' },
    redirects: 0,
  });
  if (res.status === 302) {
    const loc = res.headers['Location'];
    if (loc) {
      const r2 = http.get(loc.startsWith('http') ? loc : `${BASE}${loc}`, { redirects: 0 });
      if (r2.status === 200 && r2.body) {
        try {
          const j = JSON.parse(r2.body);
          if (j && j.csrf) return { csrf: j.csrf, user: j.user };
        } catch (e) {}
      }
    }
  }
  if (res.status === 200 && res.body) {
    try {
      const j = JSON.parse(res.body);
      if (j && j.csrf) return { csrf: j.csrf, user: j.user };
    } catch (e) {}
  }
  return null;
}

function authHeaders(csrf, extra) {
  const h = { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf };
  if (extra) Object.assign(h, extra);
  return h;
}

function pickProductFromCatalog() {
  const res = http.get(`${BASE}/v2/catalog`, { redirects: 0 });
  check(res, { 'catalog 200': (r) => r.status === 200 });
  if (res.status !== 200) return null;
  let j;
  try { j = JSON.parse(res.body); } catch (e) { return null; }
  const products = (j && j.data && j.data.products) || [];
  for (const p of products) {
    if (!p || !Array.isArray(p.variants)) continue;
    for (const v of p.variants) {
      if (v && v.in_stock) {
        return { product_id: p.id, variant_id: v.id };
      }
    }
  }
  return null;
}

function pickProductFromPages() {
  let url = `${BASE}/v2/catalog/page`;
  for (let i = 0; i < 3; i++) {
    const res = http.get(url, { redirects: 0 });
    check(res, { 'catalog page 200': (r) => r.status === 200 });
    if (res.status !== 200) return null;
    let j;
    try { j = JSON.parse(res.body); } catch (e) { return null; }
    const p = j && j.product;
    if (p && Array.isArray(p.variants)) {
      for (const v of p.variants) {
        if (v && v.in_stock) return { product_id: p.id, variant_id: v.id };
      }
    }
    const next = j && j.next;
    if (!next) return null;
    url = next.startsWith('http') ? next : `${BASE}${next}`;
  }
  return null;
}

function selectProduct() {
  let sel = pickProductFromCatalog();
  if (sel) return sel;
  return pickProductFromPages();
}

function createCart(csrf, product_id, variant_id, grant_id) {
  const payload = { product_id, variant_id };
  if (grant_id) payload.grant_id = grant_id;
  const res = http.post(`${BASE}/v2/carts`, JSON.stringify(payload), {
    headers: authHeaders(csrf),
    redirects: 0,
  });
  check(res, { 'cart 201': (r) => r.status === 201 });
  if (res.status !== 201) return null;
  let j;
  try { j = JSON.parse(res.body); } catch (e) { return null; }
  return { id: j.id, csrf: j.csrf || csrf, etag: res.headers['ETag'] };
}

function getCart(csrf, cartId) {
  const res = http.get(`${BASE}/v2/carts/${cartId}`, {
    headers: authHeaders(csrf),
    redirects: 0,
  });
  return { status: res.status, etag: res.headers['ETag'], body: res.body };
}

function patchCart(csrf, cartId, etag, quantity) {
  const res = http.patch(`${BASE}/v2/carts/${cartId}`, JSON.stringify({ quantity }), {
    headers: authHeaders(csrf, { 'If-Match': etag || '' }),
    redirects: 0,
  });
  return res;
}

function setQuantity(csrf, cartId, quantity) {
  let cur = getCart(csrf, cartId);
  let etag = cur.etag;
  let res = patchCart(csrf, cartId, etag, quantity);
  if (res.status === 412) {
    cur = getCart(csrf, cartId);
    etag = cur.etag;
    res = patchCart(csrf, cartId, etag, quantity);
  }
  check(res, { 'cart patch ok': (r) => r.status === 200 || r.status === 204 });
  return res;
}

function createOrder(csrf, cartId, etag, idemKey) {
  const res = http.post(`${BASE}/v2/orders`, JSON.stringify({ cart_id: cartId }), {
    headers: authHeaders(csrf, {
      'Idempotency-Key': idemKey,
      'If-Match': etag || '',
    }),
    redirects: 0,
  });
  return res;
}

function renewSession(csrf) {
  const res = http.post(`${BASE}/v2/session/renew`, JSON.stringify({}), {
    headers: authHeaders(csrf),
    redirects: 0,
  });
  if (res.status === 200 && res.body) {
    try {
      const j = JSON.parse(res.body);
      if (j && j.csrf) return j.csrf;
    } catch (e) {}
  }
  return null;
}

function recoverCart(csrf, cartId) {
  const res = http.post(`${BASE}/v2/carts/${cartId}/recover`, JSON.stringify({}), {
    headers: authHeaders(csrf),
    redirects: 0,
  });
  return res.status === 200 || res.status === 204;
}

function doWork(csrf) {
  let attempts = 0;
  while (attempts < 5) {
    const res = http.post(`${BASE}/v2/work`, JSON.stringify({}), {
      headers: authHeaders(csrf),
      redirects: 0,
    });
    if (res.status === 429) {
      attempts++;
      const ra = parseInt(res.headers['Retry-After'] || '1', 10);
      // sleep via busy wait not allowed; use k6 sleep
      // eslint-disable-next-line no-undef
      try { require('k6').sleep(ra); } catch (e) {}
      continue;
    }
    check(res, { 'work ok': (r) => r.status === 200 });
    return res;
  }
  return null;
}

