            cm = re.search(r'name=["\']?challenge["\']?[^>]*value=["\']([^"\']*)["\']', r.text, re.I)
            if not cm:
                cm = re.search(r'value=["\']([^"\']*)["\'][^>]*name=["\']?challenge["\']?', r.text, re.I)
            if not cm:
                r.failure("no challenge value")
