            if body.get("accepted") is not True:
                r.failure("order not accepted")
                return False
            if not body.get("id"):
                r.failure("order no id")
                return False
            if body.get("csrf"):
                self.csrf = body["csrf"]
            return True

    def _do_work(self):
        for _ in range(4):
            with self.client.post(
                "/v2/work",
                json={},
