                catch_response=True,
                allow_redirects=False,
            ) as r:
                if r.status_code == 429:
                    ra = r.headers.get("Retry-After", "1")
                    try:
                        delay = float(ra)
                    except Exception:
                        delay = 1.0
                    r.success()
                    time.sleep(delay)
                    continue
                if r.status_code == 200:
                    try:
                        body = r.json()
                    except Exception:
                        r.failure("work not json")
                        return
                    if body.get("ok") is True:
                        return
                    r.failure("work not ok")
                    return
                r.failure("work status %s" % r.status_code)
                return

    @task
    def journey(self):
        if self.iterations >= self.max_iterations:
            raise StopUser()
        self.iterations += 1
        self.session_ok = False
        if not self._login():
            raise StopUser()

        sel = self._select_product()
        if not sel:
            raise StopUser()
        product_id, variant_id = sel

        grant_id = self._solve_challenge()
        if not grant_id:
            raise StopUser()

        cart = self._create_cart(product_id, variant_id, grant_id)
        if not cart:
            raise StopUser()
        cart_id, etag = cart

        new_etag = self._patch_quantity(cart_id, etag, 1)
        if new_etag is None:
            raise StopUser()

        rid = self._reserve(cart_id)
        if not rid:
            raise StopUser()

        if not self._checkout(cart_id, rid, new_etag):
            raise StopUser()

        self._do_work()


