import io.gatling.javaapi.core.*;
import io.gatling.javaapi.http.*;

import java.time.Duration;
import java.util.*;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

import static io.gatling.javaapi.core.CoreDsl.*;
import static io.gatling.javaapi.http.HttpDsl.*;

public class ModelSimulation extends Simulation {

    private static final String BASE = System.getenv().getOrDefault("BASE_URL", "http://127.0.0.1:8000");

    private static final Pattern CSRF_INPUT = Pattern.compile(
            "<input[^>]*name\\s*=\\s*[\"']csrf[\"'][^>]*value\\s*=\\s*[\"']([^\"']+)[\"']",
            Pattern.CASE_INSENSITIVE);
    private static final Pattern CSRF_INPUT_REV = Pattern.compile(
            "<input[^>]*value\\s*=\\s*[\"']([^\"']+)[\"'][^>]*name\\s*=\\s*[\"']csrf[\"']",
            Pattern.CASE_INSENSITIVE);
    private static final Pattern CHALLENGE_INPUT = Pattern.compile(
            "<input[^>]*name\\s*=\\s*[\"']challenge[\"'][^>]*value\\s*=\\s*[\"']([^\"']+)[\"']",
            Pattern.CASE_INSENSITIVE);
    private static final Pattern CHALLENGE_INPUT_REV = Pattern.compile(
            "<input[^>]*value\\s*=\\s*[\"']([^\"']+)[\"'][^>]*name\\s*=\\s*[\"']challenge[\"']",
            Pattern.CASE_INSENSITIVE);
    private static final Pattern FORM_ACTION = Pattern.compile(
            "<form[^>]*action\\s*=\\s*[\"']([^\"']+)[\"']",
            Pattern.CASE_INSENSITIVE);

    private static String extract(Pattern p1, Pattern p2, String body) {
        if (body == null) return null;
        Matcher m = p1.matcher(body);
        if (m.find()) return m.group(1);
        m = p2.matcher(body);
        if (m.find()) return m.group(1);
        return null;
    }

    private static final AtomicInteger USER_SEQ = new AtomicInteger(0);

    private HttpProtocolBuilder httpProtocol = http
            .baseUrl(BASE)
            .disableAutoRedirect()
            .acceptHeader("application/json, text/html")
            .contentTypeHeader("application/json");

    private static final String[] ACCOUNTS = {
            "bench-1", "bench-2", "bench-3", "bench-4", "bench-5", "bench-6", "bench-7", "bench-8",
            "bench-9", "bench-10", "bench-11", "bench-12", "bench-13", "bench-14", "bench-15", "bench-16"
    };

    private ChainBuilder login() {
        return exec(session -> {
                    int idx = USER_SEQ.getAndIncrement();
                    String user = ACCOUNTS[idx % ACCOUNTS.length];
                    return session.set("username", user).set("password", "bench");
                })
                .exec(http("login-form")
                        .get("/v2/login-form")
                        .check(status().is(200))
                        .check(bodyString().saveAs("loginFormBody")))
                .exec(session -> {
                    String body = session.getString("loginFormBody");
                    String csrf = extract(CSRF_INPUT, CSRF_INPUT_REV, body);
                    return session.set("csrf", csrf);
                })
                .exec(http("login")
                        .post("/v2/login")
                        .body(StringBody(session -> {
                            String u = session.getString("username");
                            String p = session.getString("password");
                            String c = session.getString("csrf");
                            return "{\"username\":\"" + u + "\",\"password\":\"" + p + "\",\"csrf\":\"" + c + "\"}";
                        }))
                        .check(status().in(200, 302))
                        .check(header("Location").optional().saveAs("loginLocation"))
                        .check(bodyString().optional().saveAs("loginBody")))
                .exec(session -> {
                    String loc = session.getString("loginLocation");
                    if (loc != null && !loc.isEmpty()) {
                        return session.set("loginRedirect", loc);
                    }
                    return session;
                })
                .doIf(session -> session.getString("loginRedirect") != null).then(
                        exec(http("login-redirect")
                                .get(session -> session.getString("loginRedirect"))
                                .check(status().in(200, 204)))
                )
                .exec(session -> {
                    String body = session.getString("loginBody");
                    String csrf = extract(CSRF_INPUT, CSRF_INPUT_REV, body);
                    if (csrf == null) csrf = session.getString("csrf");
                    return session.set("csrf", csrf);
                });
    }

    private ChainBuilder challenge() {
        return exec(http("challenge-form")
                .get("/v2/challenge-form")
                .check(status().is(200))
                .check(bodyString().saveAs("challengeFormBody")))
                .exec(session -> {
                    String body = session.getString("challengeFormBody");
                    String action = null;
                    Matcher m = FORM_ACTION.matcher(body == null ? "" : body);
                    if (m.find()) action = m.group(1);
                    String ch = extract(CHALLENGE_INPUT, CHALLENGE_INPUT_REV, body);
                    return session.set("challengeAction", action).set("challengeValue", ch);
                })
                .exec(http("challenge-submit")
                        .post(session -> session.getString("challengeAction"))
                        .header("X-CSRF-Token", session -> session.getString("csrf"))
                        .body(StringBody(session -> "{\"challenge\":\"" + session.getString("challengeValue") + "\"}"))
                        .check(status().in(200, 302))
                        .check(header("Location").optional().saveAs("challengeLocation")))
                .exec(session -> {
                    String loc = session.getString("challengeLocation");
                    return session.set("challengeRedirect", loc);
                })
                .doIf(session -> session.getString("challengeRedirect") != null).then(
                        exec(http("challenge-grant")
                                .get(session -> session.getString("challengeRedirect"))
                                .check(status().is(200))
                                .check(bodyString().saveAs("grantBody")))
                )
                .exec(session -> {
                    String body = session.getString("grantBody");
                    String grant = null;
                    if (body != null) {
                        Matcher m = Pattern.compile("\"grant_id\"\\s*:\\s*\"([^\"]+)\"").matcher(body);
                        if (m.find()) grant = m.group(1);
                    }
                    String csrf = extract(CSRF_INPUT, CSRF_INPUT_REV, body);
                    if (csrf == null) csrf = session.getString("csrf");
                    return session.set("grantId", grant).set("csrf", csrf);
                });
    }

    private ChainBuilder createCart() {
        return exec(http("cart-create")
                .post("/v2/carts")
                .header("X-CSRF-Token", session -> session.getString("csrf"))
                .body(StringBody(session -> {
                    String pid = session.getString("productId");
                    String vid = session.getString("variantId");
                    String grant = session.getString("grantId");
                    StringBuilder sb = new StringBuilder();
                    sb.append("{\"product_id\":\"").append(pid).append("\",\"variant_id\":\"").append(vid).append("\"");
                    if (grant != null && !grant.isEmpty()) {
                        sb.append(",\"grant_id\":\"").append(grant).append("\"");
                    }
                    sb.append("}");
                    return sb.toString();
                }))
                .check(status().is(201))
                .check(header("ETag").optional().saveAs("cartEtag"))
                .check(bodyString().saveAs("cartBody")))
                .exec(session -> {
                    String body = session.getString("cartBody");
                    String id = null;
                    String csrf = null;
                    if (body != null) {
                        Matcher m = Pattern.compile("\"id\"\\s*:\\s*\"([^\"]+)\"").matcher(body);
                        if (m.find()) id = m.group(1);
                        Matcher c = Pattern.compile("\"csrf\"\\s*:\\s*\"([^\"]+)\"").matcher(body);
                        if (c.find()) csrf = c.group(1);
                    }
                    if (csrf == null) csrf = session.getString("csrf");
                    return session.set("cartId", id).set("csrf", csrf);
                });
    }

    private ChainBuilder patchQuantity() {
        return exec(http("cart-get")
                .get(session -> "/v2/carts/" + session.getString("cartId"))
                .check(status().is(200))
                .check(header("ETag").optional().saveAs("cartEtag")))
                .exec(http("cart-patch")
                .patch(session -> "/v2/carts/" + session.getString("cartId"))
                .header("X-CSRF-Token", session -> session.getString("csrf"))
                .header("If-Match", session -> {
                    String e = session.getString("cartEtag");
                    return e == null ? "*" : e;
                })
                .body(StringBody("{\"quantity\":1}"))
                .check(status().in(200, 204, 412))
                .check(header("ETag").optional().saveAs("cartEtag2")))
                .exec(session -> {
                    String e2 = session.getString("cartEtag2");
                    if (e2 != null) return session.set("cartEtag", e2);
                    return session;
                });
    }

    private ChainBuilder reservation() {
        return exec(http("reservation-create")
                .post("/v2/reservations")
                .header("X-CSRF-Token", session -> session.getString("csrf"))
                .body(StringBody(session -> "{\"cart_id\":\"" + session.getString("cartId") + "\"}"))
                .check(status().is(202))
                .check(bodyString().saveAs("resBody")))
                .exec(session -> {
                    String body = session.getString("resBody");
                    String statusUrl = null;
                    String csrf = null;
                    if (body != null) {
                        Matcher m = Pattern.compile("\"status_url\"\\s*:\\s*\"([^\"]+)\"").matcher(body);
                        if (m.find()) statusUrl = m.group(1);
                        Matcher c = Pattern.compile("\"csrf\"\\s*:\\s*\"([^\"]+)\"").matcher(body);
                        if (c.find()) csrf = c.group(1);
                    }
                    if (csrf == null) csrf = session.getString("csrf");
                    return session.set("statusUrl", statusUrl).set("csrf", csrf);
                })
                .asLongAs(session -> session.getInt("pollCount") < 5).on(
                        exec(session -> session.set("pollCount", session.getInt("pollCount") + 1))
                                .pause(Duration.ofMillis(60))
                                .exec(http("reservation-poll")
                                        .get(session -> session.getString("statusUrl"))
                                        .check(status().is(200))
                                        .check(bodyString().saveAs("pollBody")))
                                .exec(session -> {
                                    String body = session.getString("pollBody");
                                    String status = null;
                                    String rid = null;
                                    if (body != null) {
                                        Matcher s = Pattern.compile("\"status\"\\s*:\\s*\"([^\"]+)\"").matcher(body);
                                        if (s.find()) status = s.group(1);
                                        Matcher r = Pattern.compile("\"reservation_id\"\\s*:\\s*\"([^\"]+)\"").matcher(body);
                                        if (r.find()) rid = r.group(1);
                                    }
                                    if ("ready".equals(status) && rid != null) {
                                        return session.set("reservationId", rid).set("pollDone", true);
                                    }
                                    if ("failed".equals(status)) {
                                        return session.set("pollDone", true).set("reservationFailed", true);
                                    }
                                    return session;
                                })
                )
                .exec(session -> {
                    if (session.getBoolean("reservationFailed")) {
                        return session.markAsFailed();
                    }
                    return session;
                });
    }

    private ChainBuilder checkout() {
        return exec(http("order-create")
                .post("/v2/orders")
                .header("X-CSRF-Token", session -> session.getString("csrf"))
                .header("Idempotency-Key", session -> "idem-" + session.getString("cartId"))
                .header("If-Match", session -> {
                    String e = session.getString("cartEtag");
                    return e == null ? "*" : e;
                })
                .body(StringBody(session -> {
                    String rid = session.getString("reservationId");
                    StringBuilder sb = new StringBuilder();
                    sb.append("{\"cart_id\":\"").append(session.getString("cartId")).append("\"");
                    if (rid != null && !rid.isEmpty()) {
                        sb.append(",\"reservation_id\":\"").append(rid).append("\"");
                    }
                    sb.append("}");
                    return sb.toString();
                }))
                .check(status().is(201))
                .check(bodyString().saveAs("orderBody")))
                .exec(session -> {
                    String body = session.getString("orderBody");
                    boolean accepted = false;
                    String orderId = null;
                    if (body != null) {
                        Matcher a = Pattern.compile("\"accepted\"\\s*:\\s*(true|false)").matcher(body);
                        if (a.find()) accepted = "true".equals(a.group(1));
                        Matcher o = Pattern.compile("\"id\"\\s*:\\s*\"([^\"]+)\"").matcher(body);
                        if (o.find()) orderId = o.group(1);
                    }
                    if (!accepted) {
                        return session.markAsFailed();
                    }
                    return session.set("orderId", orderId);
                });
    }

    private ChainBuilder catalogPage() {
        return exec(http("catalog-page")
                .get("/v2/catalog/page")
                .check(status().is(200))
                .check(bodyString().saveAs("catalogPageBody")))
                .exec(session -> {
                    String body = session.getString("catalogPageBody");
                    String pid = null;
                    String vid = null;
                    String next = null;
                    if (body != null) {
                        Matcher p = Pattern.compile("\"id\"\\s*:\\s*\"([^\"]+)\"").matcher(body);
                        if (p.find()) pid = p.group(1);
                        Matcher v = Pattern.compile("\"variants\"\\s*:\\s*\\[\\s*\\{[^}]*\"id\"\\s*:\\s*\"([^\"]+)\"[^}]*\"in_stock\"\\s*:\\s*true").matcher(body);
                        if (v.find()) vid = v.group(1);
                        if (vid == null) {
                            Matcher v2 = Pattern.compile("\"id\"\\s*:\\s*\"([^\"]+)\"[^}]*\"in_stock\"\\s*:\\s*true").matcher(body);
                            if (v2.find()) vid = v2.group(1);
                        }
                        Matcher n = Pattern.compile("\"next\"\\s*:\\s*\"([^\"]+)\"").matcher(body);
                        if (n.find()) next = n.group(1);
                    }
                    return session.set("productId", pid).set("variantId", vid).set("nextUrl", next);
                });
    }

    private ChainBuilder catalogTraverse() {
        return exec(session -> session.set("pageCount", 0).set("found", false))
                .asLongAs(session -> !session.getBoolean("found") && session.getInt("pageCount") < 3).on(
                        exec(session -> session.set("pageCount", session.getInt("pageCount") + 1))
                                .exec(catalogPage())
                                .exec(session -> {
                                    String pid = session.getString("productId");
                                    String vid = session.getString("variantId");
                                    if (pid != null && vid != null) {
                                        return session.set("found", true);
                                    }
                                    String next = session.getString("nextUrl");
                                    if (next == null || next.isEmpty()) {
                                        return session.set("found", true);
                                    }
                                    return session;
                                })
                                .doIf(session -> !session.getBoolean("found") && session.getString("nextUrl") != null).then(
                                        exec(http("catalog-next")
                                                .get(session -> session.getString("nextUrl"))
                                                .check(status().is(200))
                                                .check(bodyString().saveAs("catalogPageBody")))
                                                .exec(session -> {
                                                    String body = session.getString("catalogPageBody");
                                                    String pid = null;
                                                    String vid = null;
                                                    String next = null;
                                                    if (body != null) {
                                                        Matcher p = Pattern.compile("\"id\"\\s*:\\s*\"([^\"]+)\"").matcher(body);
                                                        if (p.find()) pid = p.group(1);
                                                        Matcher v = Pattern.compile("\"variants\"\\s*:\\s*\\[\\s*\\{[^}]*\"id\"\\s*:\\s*\"([^\"]+)\"[^}]*\"in_stock\"\\s*:\\s*true").matcher(body);
                                                        if (v.find()) vid = v.group(1);
                                                        if (vid == null) {
                                                            Matcher v2 = Pattern.compile("\"id\"\\s*:\\s*\"([^\"]+)\"[^}]*\"in_stock\"\\s*:\\s*true").matcher(body);
                                                            if (v2.find()) vid = v2.group(1);
                                                        }
                                                        Matcher n = Pattern.compile("\"next\"\\s*:\\s*\"([^\"]+)\"").matcher(body);
                                                        if (n.find()) next = n.group(1);
                                                    }
                                                    if (pid != null && vid != null) {
                                                        return session.set("productId", pid).set("variantId", vid).set("found", true);
                                                    }
                                                    return session.set("nextUrl", next);
                                                })
                                )
                )
                .exec(session -> {
                    if (!session.getBoolean("found") || session.getString("productId") == null) {
                        return session.markAsFailed();
                    }
                    return session;
                });
    }

    private ScenarioBuilder scenario = scenario("ModelSimulation")
            .exec(session -> session.set("pollCount", 0).set("pollDone", false).set("reservationFailed", false))
            .exec(login())
            .exec(challenge())
            .exec(catalogTraverse())
            .exec(createCart())
            .exec(patchQuantity())
            .exec(reservation())
            .exec(checkout());

    {
        setUp(
                scenario.injectOpen(
                        atOnceUsers(2)
                ).protocols(httpProtocol)
        ).maxDuration(Duration.ofMinutes(5));
    }
}
