```javascript
import http from 'k6/http';
import { check, sleep } from 'k6';
import { SharedArray } from 'k6/data';

const BASE = __ENV.BASE_URL || 'http://127.0.0.1:8000';

export const options = {
  scenarios: {
    journeys: {
      executor: 'per-vu-iterations',
      vus: 2,
      iterations: 2,
      maxDuration: '120s',
    },
  },
  thresholds: {
    checks: ['rate==1'],
  },
};

const USERS = ['bench-1', 'bench-2'];

function parseCsrf(html) {
  // find input[name=csrf] value, tolerate attribute variants
  const re = /<input\b[^>]*\bname\s*=\s*["']?csrf["']?[^>]*>/i;
  const m = html.match(re);
  if (!m) return null;
  const tag = m[0];
  const vm = tag.match(/\bvalue\s*=\s*["']([^"']*)["']/i);
  return vm ? vm[1] : null;
}

function parseChallengeForm(html) {
  const actionM = html.match(/<form\b[^>]*\baction\s*=\s*["']([^"']+)["']/i);
  const inputM = html.match(/<input\b[^>]*\bname\s*=\s*["']?challenge["']?[^>]*>/i);
  let value = null;
  if (inputM) {
    const vm = inputM[0].match(/\bvalue\s*=\s*["']([^"']*)["']/i);
    value = vm ? vm[1] : null;
  }
  return { action: actionM ? actionM[1] : null, value };
}

function absUrl(u) {
  if (!u) return null;
  if (/^https?:\/\//i.test(u)) return u;
  if (u.startsWith('/')) return BASE + u;
  return BASE + '/' + u;
}

function getCookieJar() {
  return http.cookieJar();
}

function login(user) {
  const jar = http.cookieJar();
  jar.clear(BASE);
  const formRes = http.get(BASE + '/v2/login-form', { redirects: 0 });
  check(formRes, { 'login-form 200': (r) => r.status === 200 });
  const csrf = parseCsrf(formRes.body || '');
  check(csrf, { 'csrf found': (c) => !!c });
  const loginRes = http.post(
    BASE + '/v2/login',
    JSON.stringify({ username: user, password: 'bench', csrf }),
    { headers: { 'Content-Type': 'application/json' }, redirects: 0 }
  );
  let token = csrf;
  if (loginRes.status === 302) {
    const loc = loginRes.headers['Location'];
    if (loc) {
      const follow = http.get(absUrl(loc), { redirects: 0 });
      check(follow, { 'login redirect followed': (r) => r.status < 400 });
      try {
        const b = JSON.parse(follow.body || '{}');
        if (b.csrf) token = b.csrf;
      } catch (e) {}
    }
  } else {
    try {
      const b = JSON.parse(loginRes.body || '{}');
      if (b.csrf) token = b.csrf;
    } catch (e) {}
  }
  check(loginRes, { 'login ok': (r) => r.status === 200 || r.status === 302 });
  return token;
}

function renewSession(token) {
  const r = http.post(BASE + '/v2/session/renew', JSON.stringify({}), {
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': token },
    redirects: 0,
  });
  let newToken = token;
  try {
    const b = JSON.parse(r.body || '{}');
    if (b.csrf) newToken = b.csrf;
  } catch (e) {}
  return { ok: r.status === 200, token: newToken };
}

function recoverCart(cartId, token) {
  const r = http.post(BASE + '/v2/carts/' + cartId + '/recover', JSON.stringify({}), {
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': token },
    redirects: 0,
  });
  let newToken = token;
  try {
    const b = JSON.parse(r.body || '{}');
    if (b.csrf) newToken = b.csrf;
  } catch (e) {}
  return { ok: r.status === 200 || r.status === 201, token: newToken };
}

function handle401(res, token, cartId) {
  let err = null;
  try {
    const b = JSON.parse(res.body || '{}');
    err = b.error;
  } catch (e) {}
  if (err === 'expired') {
    const rn = renewSession(token);
    let t = rn.token;
    if (cartId) {
      const rc = recoverCart(cartId, t);
      t = rc.token;
    }
    return { retry: true, token: t };
  }
  if (err === 'session') {
    // revoked: fresh login
    return { retry: true, token: null, relogin: true };
  }
  return { retry: false, token };
}

function traverseCatalog() {
  // Try paginated catalog first
  let url = BASE + '/v2/catalog/page';
  let pages = 0;
  const seen = [];
  while (url && pages < 3) {
    const r = http.get(url, { redirects: 0 });
    if (r.status !== 200) break;
    let body;
    try {
      body = JSON.parse(r.body || '{}');
    } catch (e) {
      break;
    }
    if (body && body.id) seen.push(body);
    else if (body && body.data && body.data.product) seen.push(body.data.product);
    else if (body && body.product) seen.push(body.product);
    const next = body && body.next;
    url = next ? absUrl(next) : null;
    pages++;
  }
  if (seen.length > 0) return seen;
  // fallback to catalog
  const r = http.get(BASE + '/v2/catalog', { redirects: 0 });
  if (r.status === 200) {
    try {
      const b = JSON.parse(r.body || '{}');
      if (b.data && b.data.products) return b.data.products;
    } catch (e) {}
  }
  return [];
}

function pickVariant(product) {
  if (!product || !product.variants) return null;
  for (const v of product.variants) {
    if (v.in_stock) return v;
  }
  return null;
}

function solveChallenge(token) {
  const formRes = http.get(BASE + '/v2/challenge-form', { redirects: 0 });
  if (formRes.status !== 200) return { ok: false, token };
  const { action, value } = parseChallengeForm(formRes.body || '');
  if (!action || !value) return { ok: false, token };
  const postRes = http.post(absUrl(action), JSON.stringify({ challenge: value }), {
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': token },
    redirects: 0,
  });
  let t = token;
  if (postRes.status === 302) {
    const loc = postRes.headers['Location'];
    if (loc) {
      const follow = http.get(absUrl(loc), { redirects: 0 });
      try {
        const b = JSON.parse(follow.body || '{}');
        if (b.csrf) t = b.csrf;
        if (b.grant_id) return { ok: true, token: t, grant_id: b.grant_id };
      } catch (e) {}
    }
  }
  return { ok: false, token: t };
}

function createCart(productId, variantId, grantId, token) {
  const payload = { product_id: productId, variant_id: variantId };
  if (grantId) payload.grant_id = grantId;
  let res = http.post(BASE + '/v2/carts', JSON.stringify(payload), {
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': token },
    redirects: 0,
  });
  let t = token;
  if (res.status === 401) {
    const h = handle401(res, t, null);
    if (h.relogin) return { ok: false, relogin: true };
    if (h.retry) {
      t = h.token;
      res = http.post(BASE + '/v2/carts', JSON.stringify(payload), {
        headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': t },
        redirects: 0,
      });
    }
  }
  if (res.status !== 201) return { ok: false, token: t };
