    if (h.retry) {
      t = h.token;
      res = http.post(BASE + '/v2/reservations', JSON.stringify({ cart_id: cartId }), {
        headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': t },
        redirects: 0,
      });
    }
  }
