            r'<input\b[^>]*\bname\s*=\s*["\']?csrf["\']?[^>]*>',
            text,
            re.IGNORECASE,
        )
        if not m:
            return None
        tag = m.group(0)
        vm = re.search(r'\bvalue\s*=\s*["\']([^"\']*)["\']', tag, re.IGNORECASE)
        if vm:
            return vm.group(1)
        return None

    def _login(self):
        # pick a bench account
        idx = (id(self) % 16) + 1
        self.username = "bench-%d" % idx
        password = "bench"

        with self.client.get(
            "/v2/login-form",
