        # check inline products first
        data = body.get("data") or {}
        products = data.get("products") or []
        for p in products:
            for v in p.get("variants") or []:
                if v.get("in_stock"):
                    return (p.get("id"), v.get("id"))

        next_url = body.get("next")
        pages = 0
        while next_url and pages < 3:
            pages += 1
            page = self._get_catalog_page(_abs(next_url))
            if page is None:
                return None
            # page returns one product plus next
            prod = page.get("product") or page.get("data", {}).get("product")
            if prod is None:
                # maybe data.products
                d = page.get("data") or {}
                plist = d.get("products") or []
                if plist:
