        if not found:
            raise StopUser()
        product_id, variant_id = found

        grant_id = self._solve_challenge()

        cart = self._create_cart(product_id, variant_id, grant_id)
        if not cart or not cart.get("id"):
            raise StopUser()
        cart_id = cart["id"]
        etag = cart.get("etag")

        new_etag = self._patch_quantity(cart_id, etag, 1)
        if new_etag is not None:
            etag = new_etag

        reservation_id = self._reserve(cart_id)
        if not reservation_id:
            raise StopUser()

        order_id = self._checkout(cart_id, reservation_id, etag)
        if not order_id:
            raise StopUser()

        self._do_work()

        if self.iterations_done >= self.max_iterations:
            raise StopUser()


