import io.gatling.javaapi.core.*;
import io.gatling.javaapi.http.*;

import java.time.Duration;
import java.util.*;
import java.util.concurrent.ThreadLocalRandom;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

import static io.gatling.javaapi.core.CoreDsl.*;
import static io.gatling.javaapi.http.HttpDsl.*;

public class ModelSimulation extends Simulation {

    private static final String BASE = System.getenv().getOrDefault("BASE_URL", "http://127.0.0.1:8000");

    private static final Pattern CSRF_INPUT = Pattern.compile(
            "<input[^>]*name\\s*=\\s*[\"']csrf[\"'][^>]*>", Pattern.CASE_INSENSITIVE);
    private static final Pattern VALUE_ATTR = Pattern.compile(
            "value\\s*=\\s*[\"']([^\"']*)[\"']", Pattern.CASE_INSENSITIVE);
    private static final Pattern ACTION_ATTR = Pattern.compile(
            "action\\s*=\\s*[\"']([^\"']*)[\"']", Pattern.CASE_INSENSITIVE);
    private static final Pattern CHALLENGE_INPUT = Pattern.compile(
            "<input[^>]*name\\s*=\\s*[\"']challenge[\"'][^>]*>", Pattern.CASE_INSENSITIVE);

    private static String extractCsrf(String html) {
        if (html == null) return null;
        Matcher m = CSRF_INPUT.matcher(html);
        if (m.find()) {
            Matcher v = VALUE_ATTR.matcher(m.group());
            if (v.find()) return v.group(1);
        }
        return null;
    }

    private static String extractChallenge(String html) {
        if (html == null) return null;
        Matcher m = CHALLENGE_INPUT.matcher(html);
        if (m.find()) {
            Matcher v = VALUE_ATTR.matcher(m.group());
            if (v.find()) return v.group(1);
        }
        return null;
    }

    private static String extractAction(String html) {
        if (html == null) return null;
        Matcher m = ACTION_ATTR.matcher(html);
        if (m.find()) return m.group(1);
        return null;
    }

    private static String extractEtag(String header) {
        if (header == null) return null;
        String h = header.trim();
        if (h.startsWith("W/")) h = h.substring(2);
        return h;
    }

    private static final HttpProtocolBuilder HTTP = http
            .baseUrl(BASE)
            .disableAutoReferer()
            .disableFollowRedirect()
            .acceptHeader("application/json, text/html")
            .contentTypeHeader("application/json");

    private static ChainBuilder login(String user) {
        return exec(
                http("login-form")
                        .get("/v2/login-form")
                        .check(status().is(200))
                        .check(bodyString().saveAs("loginHtml"))
        ).exec(session -> {
            String csrf = extractCsrf(session.getString("loginHtml"));
            return session.set("csrf", csrf);
        }).exec(
                http("login")
                        .post("/v2/login")
                        .body(StringBody(s -> "{\"username\":\"" + user + "\",\"password\":\"bench\",\"csrf\":\"" + s.getString("csrf") + "\"}"))
                        .check(status().in(200, 302))
                        .check(header("Location").optional().saveAs("loginLoc"))
                        .check(bodyString().optional().saveAs("loginBody"))
        ).exec(session -> {
            String loc = session.getString("loginLoc");
            if (loc != null && !loc.isEmpty()) {
                return session.set("loginRedirect", loc);
            }
            return session;
        }).doIf(session -> session.getString("loginRedirect") != null).then(
                http("login-redirect")
                        .get(session -> session.getString("loginRedirect"))
                        .check(status().is(200))
                        .check(bodyString().saveAs("loginBody2"))
        ).exec(session -> {
            String body = session.getString("loginBody2");
            if (body == null) body = session.getString("loginBody");
            String csrf = extractCsrf(body);
            if (csrf != null) return session.set("csrf", csrf);
            return session;
        });
    }

    private static ChainBuilder ensureCsrf() {
        return exec(session -> {
            if (session.getString("csrf") == null) {
                return session.markAsFailed();
            }
            return session;
        });
    }

    private static ChainBuilder createCart() {
        return exec(
                http("create-cart")
                        .post("/v2/carts")
                        .header("X-CSRF-Token", session -> session.getString("csrf"))
                        .body(StringBody(s -> {
                            String pid = s.getString("productId");
                            String vid = s.getString("variantId");
                            String grant = s.getString("grantId");
                            StringBuilder sb = new StringBuilder();
                            sb.append("{\"product_id\":\"").append(pid).append("\",\"variant_id\":\"").append(vid).append("\"");
                            if (grant != null) sb.append(",\"grant_id\":\"").append(grant).append("\"");
                            sb.append("}");
                            return sb.toString();
                        }))
                        .check(status().is(201))
                        .check(header("ETag").saveAs("cartEtag"))
                        .check(jsonPath("$.id").saveAs("cartId"))
                        .check(jsonPath("$.csrf").optional().saveAs("newCsrf"))
        ).exec(session -> {
            String nc = session.getString("newCsrf");
            if (nc != null) return session.set("csrf", nc);
            return session;
        });
    }

    private static ChainBuilder readCart() {
        return exec(
                http("read-cart")
                        .get(session -> "/v2/carts/" + session.getString("cartId"))
                        .check(status().is(200))
                        .check(header("ETag").saveAs("cartEtag"))
        );
    }

    private static ChainBuilder patchCart(int qty) {
        return exec(
                http("patch-cart")
                        .patch(session -> "/v2/carts/" + session.getString("cartId"))
                        .header("X-CSRF-Token", session -> session.getString("csrf"))
                        .header("If-Match", session -> session.getString("cartEtag"))
                        .body(StringBody("{\"quantity\":" + qty + "}"))
                        .check(status().in(200, 412))
                        .check(header("ETag").optional().saveAs("newEtag"))
                        .check(jsonPath("$.csrf").optional().saveAs("newCsrf"))
        ).exec(session -> {
            String nc = session.getString("newCsrf");
            if (nc != null) session = session.set("csrf", nc);
            String ne = session.getString("newEtag");
            if (ne != null) session = session.set("cartEtag", ne);
            return session;
        });
    }

    private static ChainBuilder patchWithConflictRecovery(int qty) {
        return exec(patchCart(qty))
                .doIf(session -> session.status().name().equals("KO") || is412(session)).then(
                        readCart(),
                        patchCart(qty)
                );
    }

    private static boolean is412(Session s) {
        Object code = s.get("patchStatus");
        return code != null && "412".equals(code.toString());
    }

    private static ChainBuilder createOrder() {
        return exec(session -> session.set("idemKey", UUID.randomUUID().toString()))
                .exec(
                        http("create-order")
                                .post("/v2/orders")
                                .header("X-CSRF-Token", session -> session.getString("csrf"))
                                .header("Idempotency-Key", session -> session.getString("idemKey"))
                                .header("If-Match", session -> session.getString("cartEtag"))
                                .body(StringBody(s -> "{\"cart_id\":\"" + s.getString("cartId") + "\"}"))
                                .check(status().is(201))
                                .check(jsonPath("$.accepted").is("true"))
                                .check(jsonPath("$.id").saveAs("orderId"))
                                .check(jsonPath("$.csrf").optional().saveAs("newCsrf"))
                ).exec(session -> {
                    String nc = session.getString("newCsrf");
                    if (nc != null) return session.set("csrf", nc);
                    return session;
                });
    }

    private static ChainBuilder pickProduct() {
        return exec(
                http("catalog")
                        .get("/v2/catalog")
                        .check(status().is(200))
                        .check(jsonPath("$.data.products[*].id").findAll().saveAs("productIds"))
                        .check(jsonPath("$.data.products[*].variants[*].id").findAll().saveAs("variantIds"))
        ).exec(session -> {
            List<String> pids = session.getList("productIds");
            List<String> vids = session.getList("variantIds");
            if (pids == null || pids.isEmpty() || vids == null || vids.isEmpty()) {
                return session.markAsFailed();
            }
            int i = ThreadLocalRandom.current().nextInt(pids.size());
            int j = ThreadLocalRandom.current().nextInt(vids.size());
            return session.set("productId", pids.get(i)).set("variantId", vids.get(j));
        });
    }

    private static ChainBuilder work() {
        return exec(
                http("work")
                        .post("/v2/work")
                        .header("X-CSRF-Token", session -> session.getString("csrf"))
                        .body(StringBody("{}"))
                        .check(status().in(200, 429))
        );
    }

    private static ScenarioBuilder scenario(String name, String user) {
        return scenario(name)
                .exec(session -> session.set("user", user))
                .exec(login(user))
                .exec(ensureCsrf())
                .exec(pickProduct())
                .exec(createCart())
                .exec(readCart())
                .exec(patchWithConflictRecovery(2))
                .exec(createOrder());
    }

    {
        List<ScenarioBuilder> scenarios = new ArrayList<>();
        for (int u = 1; u <= 2; u++) {
            String user = "bench-" + u;
            scenarios.add(scenario("user-" + u, user));
        }
        setUp(
                scenarios.get(0).injectOpen(atOnceUsers(1)),
                scenarios.get(1).injectOpen(atOnceUsers(1))
        ).protocols(HTTP);
    }
}
