import http from 'k6/http';
import { check } from 'k6';
import { Counter } from 'k6/metrics';

const BASE = __ENV.BASE_URL || 'http://127.0.0.1:8000';

const businessFailures = new Counter('business_failures');

export const options = {
  scenarios: {
    journeys: {
      executor: 'per-vu-iterations',
      vus: 2,
      iterations: 2,
      maxDuration: '120s',
    },
  },
  thresholds: {
    checks: ['rate==1'],
  },
};

function parseCsrf(html) {
  // input[name=csrf] with possible attribute variants / decoys
  const re = /<input\b[^>]*>/gi;
  let m;
  while ((m = re.exec(html)) !== null) {
    const tag = m[0];
    if (!/\bname\s*=\s*["']?csrf["']?/i.test(tag)) continue;
    const vm = tag.match(/\bvalue\s*=\s*["']([^"']*)["']/i);
    if (vm) return vm[1];
  }
  return null;
}

function parseChallenge(html) {
  const re = /<input\b[^>]*>/gi;
  let m;
  while ((m = re.exec(html)) !== null) {
    const tag = m[0];
    if (!/\bname\s*=\s*["']?challenge["']?/i.test(tag)) continue;
    const vm = tag.match(/\bvalue\s*=\s*["']([^"']*)["']/i);
    if (vm) return vm[1];
  }
  return null;
}

function parseFormAction(html) {
  const m = html.match(/<form\b[^>]*\baction\s*=\s*["']([^"']+)["']/i);
  return m ? m[1] : null;
}

function getEtag(res) {
  return res.headers['Etag'] || res.headers['ETag'] || res.headers['etag'] || null;
}

function absUrl(u) {
  if (!u) return null;
  if (/^https?:\/\//i.test(u)) return u;
  if (u.startsWith('/')) return BASE + u;
  return BASE + '/' + u;
}

function login(username) {
  const formRes = http.get(`${BASE}/v2/login-form`, { redirects: 0 });
  check(formRes, { 'login-form 200': (r) => r.status === 200 });
  const csrf = parseCsrf(formRes.body);
  check(csrf, { 'login csrf extracted': (v) => !!v });

  const loginRes = http.post(
    `${BASE}/v2/login`,
    JSON.stringify({ username, password: 'bench', csrf }),
    { headers: { 'Content-Type': 'application/json' }, redirects: 0 }
  );

  let body = null;
  try { body = loginRes.json(); } catch (e) { body = null; }

  if (loginRes.status === 302) {
    const loc = loginRes.headers['Location'];
    check(loc, { 'login redirect location': (v) => !!v });
    const followRes = http.get(absUrl(loc), { redirects: 0 });
    check(followRes, { 'login redirect follow 200': (r) => r.status === 200 });
    try { body = followRes.json(); } catch (e) { body = null; }
  }

  check(loginRes, { 'login ok': (r) => r.status === 200 || r.status === 302 });
  check(body, { 'login body': (b) => b && b.csrf && b.user });
  return body ? body.csrf : null;
}

function renewSession(csrf) {
  const res = http.post(`${BASE}/v2/session/renew`, JSON.stringify({}), {
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf },
    redirects: 0,
  });
  let body = null;
  try { body = res.json(); } catch (e) { body = null; }
  if (body && body.csrf) return body.csrf;
  return csrf;
}

function recoverCart(cartId, csrf) {
  const res = http.post(`${BASE}/v2/carts/${cartId}/recover`, JSON.stringify({}), {
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf },
    redirects: 0,
  });
  let body = null;
  try { body = res.json(); } catch (e) { body = null; }
  if (body && body.csrf) return body.csrf;
  return csrf;
}

function pickProduct() {
  const res = http.get(`${BASE}/v2/catalog`, { redirects: 0 });
  check(res, { 'catalog 200': (r) => r.status === 200 });
  let body = null;
  try { body = res.json(); } catch (e) { body = null; }
  check(body, { 'catalog body': (b) => b && b.data && Array.isArray(b.data.products) });

  const products = (body && body.data && body.data.products) || [];
  for (const p of products) {
    const variants = p.variants || [];
    for (const v of variants) {
      if (v.in_stock) return { product_id: p.id, variant_id: v.id };
    }
  }
  // fallback: traverse pages
  let next = body && body.next;
  let pages = 0;
  while (next && pages < 3) {
    pages++;
    const pr = http.get(absUrl(next), { redirects: 0 });
    check(pr, { 'catalog page 200': (r) => r.status === 200 });
    let pb = null;
    try { pb = pr.json(); } catch (e) { pb = null; }
    if (!pb) break;
    const list = pb.data && pb.data.products ? pb.data.products : (pb.product ? [pb.product] : []);
    for (const p of list) {
      for (const v of (p.variants || [])) {
        if (v.in_stock) return { product_id: p.id, variant_id: v.id };
      }
    }
    next = pb.next;
  }
  return null;
}

function solveChallenge(csrf) {
  const formRes = http.get(`${BASE}/v2/challenge-form`, { redirects: 0 });
  check(formRes, { 'challenge-form 200': (r) => r.status === 200 });
  const action = parseFormAction(formRes.body);
  const challenge = parseChallenge(formRes.body);
  check(action, { 'challenge action': (v) => !!v });
  check(challenge, { 'challenge value': (v) => !!v });
  if (!action || !challenge) return null;

  const postRes = http.post(absUrl(action), JSON.stringify({ challenge }), {
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf },
    redirects: 0,
  });
  check(postRes, { 'challenge post 302': (r) => r.status === 302 });
  const loc = postRes.headers['Location'];
  check(loc, { 'challenge location': (v) => !!v });
  if (!loc) return null;

  const grantRes = http.get(absUrl(loc), { redirects: 0 });
  check(grantRes, { 'grant 200': (r) => r.status === 200 });
  let gb = null;
  try { gb = grantRes.json(); } catch (e) { gb = null; }
  check(gb, { 'grant body': (b) => b && b.grant_id });
  return gb ? { grant_id: gb.grant_id, csrf: gb.csrf || csrf } : null;
}

function scheduledWork() {
  // optional scheduled 429 handling for /v2/work
  let retries = 0;
  while (retries <= 4) {
    const res = http.post(`${BASE}/v2/work`, JSON.stringify({}), {
      headers: { 'Content-Type': 'application/json' },
      redirects: 0,
    });
    if (res.status === 429) {
      retries++;
      if (retries > 4) return res;
      const ra = parseFloat(res.headers['Retry-After'] || '1');
      // k6 sleep
      // eslint-disable-next-line no-undef
      sleep(ra > 0 ? ra : 1);
      continue;
    }
    return res;
  }
  return null;
}

export default function () {
  const vu = __VU;
  const username = `bench-${((vu - 1) % 16) + 1}`;

  let csrf = login(username);
  if (!csrf) return;

  // pick product
  const prod = pickProduct();
  check(prod, { 'product selected': (v) => !!v });
  if (!prod) return;

  // solve challenge for grant
  const grant = solveChallenge(csrf);
  check(grant, { 'grant obtained': (v) => !!v });
  if (!grant) return;
  csrf = grant.csrf;

  // create cart
  const cartPayload = { product_id: prod.product_id, variant_id: prod.variant_id, grant_id: grant.grant_id };
  let cartRes = http.post(`${BASE}/v2/carts`, JSON.stringify(cartPayload), {
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf },
    redirects: 0,
  });

  if (cartRes.status === 401) {
    let eb = null;
    try { eb = cartRes.json(); } catch (e) { eb = null; }
    if (eb && eb.error === 'expired') {
      csrf = renewSession(csrf);
      cartRes = http.post(`${BASE}/v2/carts`, JSON.stringify(cartPayload), {
        headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf },
        redirects: 0,
      });
    }
  }

  check(cartRes, { 'cart created 201': (r) => r.status === 201 });
  let cartBody = null;
  try { cartBody = cartRes.json(); } catch (e) { cartBody = null; }
  check(cartBody, { 'cart body': (b) => b && b.id });
  if (!cartBody || !cartBody.id) return;
  const cartId = cartBody.id;
  if (cartBody.csrf) csrf = cartBody.csrf;

  let etag = getEtag(cartRes);
  check(etag, { 'cart etag present': (v) => !!v });

  // GET cart to extract initial revision/etag
  let getRes = http.get(`${BASE}/v2/carts/${cartId}`, { redirects: 0 });
  if (getRes.status === 401) {
    let eb = null;
    try { eb = getRes.json(); } catch (e) { eb = null; }
    if (eb && eb.error === 'expired') {
      csrf = renewSession(csrf);
      csrf = recoverCart(cartId, csrf);
      getRes = http.get(`${BASE}/v2/carts/${cartId}`, { redirects: 0 });
    }
  }
  check(getRes, { 'cart get 200': (r) => r.status === 200 });
  const initialEtag = getEtag(getRes);
  check(initialEtag, { 'initial etag extracted': (v) => !!v });
  if (initialEtag) etag = initialEtag;

  // PATCH with If-Match; on 412 re-read and retry same payload once
  const patchPayload = JSON.stringify({ quantity: 2 });
  const patchHeaders = {
    'Content-Type': 'application/json',
    'X-CSRF-Token': csrf,
    'If-Match': etag,
  };

  let patchRes = http.patch(`${BASE}/v2/carts/${cartId}`, patchPayload, {
    headers: patchHeaders,
    redirects: 0,
  });

  if (patchRes.status === 401) {
    let eb = null;
    try { eb = patchRes.json(); } catch (e) { eb = null; }
    if (eb && eb.error === 'expired') {
      csrf = renewSession(csrf);
      csrf = recoverCart(cartId, csrf);
      patchHeaders['X-CSRF-Token'] = csrf;
      patchRes = http.patch(`${BASE}/v2/carts/${cartId}`, patchPayload, {
        headers: patchHeaders,
        redirects: 0,
      });
    }
  }

  if (patchRes.status === 412) {
    // re-read
    let reRead = http.get(`${BASE}/v2/carts/${cartId}`, { redirects: 0 });
    if (reRead.status === 401) {
      let eb = null;
      try { eb = reRead.json(); } catch (e) { eb = null; }
      if (eb && eb.error === 'expired') {
        csrf = renewSession(csrf);
        csrf = recoverCart(cartId, csrf);
        reRead = http.get(`${BASE}/v2/carts/${cartId}`, { redirects: 0 });
      }
    }
    check(reRead, { 'reread 200': (r) => r.status === 200 });
    const freshEtag = getEtag(reRead);
    check(freshEtag, { 'fresh etag': (v) => !!v });
    if (freshEtag) {
      patchHeaders['If-Match'] = freshEtag;
      patchHeaders['X-CSRF-Token'] = csrf;
      patchRes = http.patch(`${BASE}/v2/carts/${cartId}`, patchPayload, {
        headers: patchHeaders,
        redirects: 0,
      });
    }
  }

  check(patchRes, { 'patch success': (r) => r.status === 200 || r.status === 204 });
  let pb = null;
  try { pb = patchRes.json(); } catch (e) { pb = null; }
  if (pb && pb.csrf) csrf = pb.csrf;

  // reservation
  let resRes = http.post(`${BASE}/v2/reservations`, JSON.stringify({ cart_id: cartId }), {
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf },
    redirects: 0,
  });
  if (resRes.status === 401) {
    let eb = null;
    try { eb = resRes.json(); } catch (e) { eb = null; }
    if (eb && eb.error === 'expired') {
      csrf = renewSession(csrf);
      csrf = recoverCart(cartId, csrf);
      resRes = http.post(`${BASE}/v2/reservations`, JSON.stringify({ cart_id: cartId }), {
        headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf },
        redirects: 0,
      });
    }
  }
  check(resRes, { 'reservation 202': (r) => r.status === 202 });
  let rb = null;
  try { rb = resRes.json(); } catch (e) { rb = null; }
  check(rb, { 'reservation body': (b) => b && b.status_url });
  if (rb && rb.csrf) csrf = rb.csrf;

  let reservationId = null;
  if (rb && rb.status_url) {
    for (let i = 0; i < 5; i++) {
      // eslint-disable-next-line no-undef
      sleep(0.06);
      const sr = http.get(absUrl(rb.status_url), { redirects: 0 });
      let sb = null;
      try { sb = sr.json(); } catch (e) { sb = null; }
      if (sb && sb.status === 'ready' && sb.reservation_id) {
        reservationId = sb.reservation_id;
        if (sb.csrf) csrf = sb.csrf;
        break;
      }
      if (sb && (sb.status === 'failed')) break;
    }
  }
  check(reservationId, { 'reservation ready': (v) => !!v });

  // order
  const orderPayload = { cart_id: cartId };
  if (reservationId) orderPayload.reservation_id = reservationId;
  const idemKey = `order-${cartId}`;

  let orderRes = http.post(`${BASE}/v2/orders`, JSON.stringify(orderPayload), {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': csrf,
      'Idempotency-Key': idemKey,
    },
    redirects: 0,
  });

  if (orderRes.status === 401) {
    let eb = null;
    try { eb = orderRes.json(); } catch (e) { eb = null; }
    if (eb && eb.error === 'expired') {
