import os
import re
import time
import random
from urllib.parse import urljoin

from locust import HttpUser, task, between
from locust.exception import StopUser


BASE_URL = os.environ.get("BASE_URL", "http://127.0.0.1:8000")


def _abs(url):
    if not url:
        return url
    return urljoin(BASE_URL + "/", url)


class ShopUser(HttpUser):
    host = BASE_URL
    wait_time = between(0.05, 0.15)

    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self.iterations_done = 0
        self.max_iterations = 2
        self.csrf = None
        self.username = None
        self.password = "bench"

    # ---------- helpers ----------
    def _extract_csrf_from_form(self, text):
        # input[name=csrf] with mixed attribute variants / decoys
        # find input tags, then check name=csrf and value
        for m in re.finditer(r"<input\b[^>]*>", text, re.IGNORECASE):
            tag = m.group(0)
            name_m = re.search(r"""name\s*=\s*["']?csrf["']?""", tag, re.IGNORECASE)
            if not name_m:
                continue
            val_m = re.search(r"""value\s*=\s*["']([^"']*)["']""", tag, re.IGNORECASE)
            if val_m:
                return val_m.group(1)
        return None

    def _extract_etag(self, resp):
        etag = resp.headers.get("ETag") or resp.headers.get("etag")
        return etag

    def _login(self):
        # pick account
        idx = random.randint(1, 16)
        self.username = "bench-%d" % idx
        # GET login form
        with self.client.get("/v2/login-form", catch_response=True, name="GET /v2/login-form") as r:
            if r.status_code != 200:
                r.failure("login-form status %s" % r.status_code)
                return False
            csrf = self._extract_csrf_from_form(r.text)
            if not csrf:
                r.failure("no csrf in login form")
                return False
            self.csrf = csrf
        # POST login
        with self.client.post(
            "/v2/login",
            json={"username": self.username, "password": self.password, "csrf": self.csrf},
            catch_response=True,
            name="POST /v2/login",
            allow_redirects=False,
        ) as r:
            if r.status_code == 302:
                loc = r.headers.get("Location")
                if not loc:
                    r.failure("302 without Location")
                    return False
                with self.client.get(_abs(loc), catch_response=True, name="GET login redirect") as r2:
                    if r2.status_code != 200:
                        r2.failure("login redirect status %s" % r2.status_code)
                        return False
                    try:
                        data = r2.json()
                    except Exception:
                        r2.failure("login redirect not json")
                        return False
                    if data.get("csrf"):
                        self.csrf = data["csrf"]
                return True
            elif r.status_code == 200:
                try:
                    data = r.json()
                except Exception:
                    r.failure("login not json")
                    return False
                if data.get("csrf"):
                    self.csrf = data["csrf"]
                return True
            else:
                r.failure("login status %s" % r.status_code)
                return False

    def _renew_session(self):
        with self.client.post(
            "/v2/session/renew",
            json={},
            headers={"X-CSRF-Token": self.csrf or ""},
            catch_response=True,
            name="POST /v2/session/renew",
        ) as r:
            if r.status_code == 200:
                try:
                    data = r.json()
                except Exception:
                    r.failure("renew not json")
                    return False
                if data.get("csrf"):
                    self.csrf = data["csrf"]
                return True
            r.failure("renew status %s" % r.status_code)
            return False

    def _recover_cart(self, cart_id):
        with self.client.post(
            "/v2/carts/%s/recover" % cart_id,
            json={},
            headers={"X-CSRF-Token": self.csrf or ""},
            catch_response=True,
            name="POST /v2/carts/{id}/recover",
        ) as r:
            if r.status_code in (200, 201, 204):
                try:
                    data = r.json()
                    if isinstance(data, dict) and data.get("csrf"):
                        self.csrf = data["csrf"]
                except Exception:
                    pass
                return True
            r.failure("recover status %s" % r.status_code)
            return False

    def _handle_401(self, resp, cart_id=None):
        # returns True if recovered
        try:
            data = resp.json()
        except Exception:
            return False
        err = data.get("error")
        if err == "expired":
            if self._renew_session():
                if cart_id:
                    self._recover_cart(cart_id)
                return True
            return False
        elif err == "session":
            # revoked: fresh login
            if self._login():
                if cart_id:
                    self._recover_cart(cart_id)
                return True
            return False
        elif err == "denied":
            return False
        return False

    def _get_catalog_product(self):
        # traverse at most 3 pages
        url = "/v2/catalog/page"
        for _ in range(3):
            with self.client.get(url, catch_response=True, name="GET /v2/catalog/page") as r:
                if r.status_code != 200:
                    r.failure("catalog page status %s" % r.status_code)
                    return None
                try:
                    data = r.json()
                except Exception:
                    r.failure("catalog page not json")
                    return None
            product = data.get("product") or data.get("data", {}).get("product")
            if not product:
                # maybe data.products
                prods = data.get("data", {}).get("products") if isinstance(data.get("data"), dict) else None
                if prods:
                    product = prods[0]
            if product:
                variants = product.get("variants") or []
                for v in variants:
                    if v.get("in_stock"):
                        return {"product_id": product.get("id"), "variant_id": v.get("id")}
            nxt = data.get("next")
            if not nxt:
                break
            url = _abs(nxt)
        return None

    def _maybe_challenge(self):
        # attempt challenge flow to get grant_id
        with self.client.get("/v2/challenge-form", catch_response=True, name="GET /v2/challenge-form") as r:
            if r.status_code != 200:
                r.failure("challenge-form status %s" % r.status_code)
                return None
            text = r.text
        action_m = re.search(r"""action\s*=\s*["']([^"']+)["']""", text, re.IGNORECASE)
        chal_m = re.search(r"""name\s*=\s*["']?challenge["']?[^>]*value\s*=\s*["']([^"']*)["']""", text, re.IGNORECASE)
        if not chal_m:
            chal_m = re.search(r"""value\s*=\s*["']([^"']*)["'][^>]*name\s*=\s*["']?challenge["']?""", text, re.IGNORECASE)
        if not action_m or not chal_m:
            return None
        action = _abs(action_m.group(1))
        challenge = chal_m.group(1)
        with self.client.post(
            action,
            json={"challenge": challenge},
            headers={"X-CSRF-Token": self.csrf or ""},
            catch_response=True,
            name="POST /v2/challenges/{id}",
            allow_redirects=False,
        ) as r:
            if r.status_code != 302:
                r.failure("challenge post status %s" % r.status_code)
                return None
            loc = r.headers.get("Location")
            if not loc:
                r.failure("challenge 302 no Location")
                return None
        with self.client.get(_abs(loc), catch_response=True, name="GET challenge redirect") as r2:
            if r2.status_code != 200:
                r2.failure("challenge redirect status %s" % r2.status_code)
                return None
            try:
                data = r2.json()
            except Exception:
                r2.failure("challenge redirect not json")
                return None
            if data.get("csrf"):
                self.csrf = data["csrf"]
            return data.get("grant_id")

    def _create_cart(self, product_id, variant_id, grant_id=None):
        payload = {"product_id": product_id, "variant_id": variant_id}
        if grant_id:
            payload["grant_id"] = grant_id
        with self.client.post(
            "/v2/carts",
            json=payload,
            headers={"X-CSRF-Token": self.csrf or ""},
            catch_response=True,
            name="POST /v2/carts",
        ) as r:
            if r.status_code == 401:
                if self._handle_401(r):
                    # retry once
                    with self.client.post(
                        "/v2/carts",
                        json=payload,
                        headers={"X-CSRF-Token": self.csrf or ""},
                        catch_response=True,
                        name="POST /v2/carts retry",
                    ) as r2:
                        if r2.status_code != 201:
                            r2.failure("cart create retry status %s" % r2.status_code)
                            return None
                        try:
                            data = r2.json()
                        except Exception:
                            r2.failure("cart create retry not json")
                            return None
