                            self.csrf = data["csrf"]
                        return {"id": data.get("id"), "etag": self._extract_etag(r2)}
                r.failure("cart create 401 unrecovered")
                return None
            if r.status_code != 201:
                r.failure("cart create status %s" % r.status_code)
                return None
            try:
                data = r.json()
            except Exception:
                r.failure("cart create not json")
                return None
            if data.get("csrf"):
                self.csrf = data["csrf"]
            return {"id": data.get("id"), "etag": self._extract_etag(r)}

    def _get_cart_etag(self, cart_id):
        with self.client.get(
            "/v2/carts/%s" % cart_id,
            catch_response=True,
            name="GET /v2/carts/{id}",
        ) as r:
            if r.status_code == 401:
                if self._handle_401(r, cart_id):
                    with self.client.get(
                        "/v2/carts/%s" % cart_id,
                        catch_response=True,
                        name="GET /v2/carts/{id} retry",
