                        if r2.status_code != 200:
                            r2.failure("cart get retry status %s" % r2.status_code)
                            return None
                        return self._extract_etag(r2)
                r.failure("cart get 401 unrecovered")
                return None
            if r.status_code != 200:
                r.failure("cart get status %s" % r.status_code)
                return None
            return self._extract_etag(r)

    def _patch_cart(self, cart_id, etag, quantity):
        headers = {"X-CSRF-Token": self.csrf or "", "If-Match": etag or ""}
        payload = {"quantity": quantity}
