            "/v2/carts/%s" % cart_id,
            json=payload,
            headers=headers,
            catch_response=True,
            name="PATCH /v2/carts/{id}",
        ) as r:
            if r.status_code == 412:
                # re-read and retry same payload once
                new_etag = self._get_cart_etag(cart_id)
