                headers2 = {"X-CSRF-Token": self.csrf or "", "If-Match": new_etag}
                with self.client.patch(
                    "/v2/carts/%s" % cart_id,
                    json=payload,
                    headers=headers2,
                    catch_response=True,
                    name="PATCH /v2/carts/{id} retry",
