                                        self.csrf = d["csrf"]
                                except Exception:
                                    pass
                                return True
                        r2.failure("patch retry 401 unrecovered")
                        return False
                    if r2.status_code not in (200, 204):
                        r2.failure("patch retry status %s" % r2.status_code)
                        return False
                    try:
                        d = r2.json()
                        if isinstance(d, dict) and d.get("csrf"):
                            self.csrf = d["csrf"]
                    except Exception:
                        pass
                    return True
            if r.status_code == 401:
                if self._handle_401(r, cart_id):
                    new_etag = self._get_cart_etag(cart_id)
                    if not new_etag:
                        r.failure("401 retry no etag")
                        return False
                    with self.client.patch(
                        "/v2/carts/%s" % cart_id,
                        json=payload,
                        headers={"X-CSRF-Token": self.csrf or "", "If-Match": new_etag},
                        catch_response=True,
                        name="PATCH /v2/carts/{id} retry",
