                                self.csrf = d["csrf"]
                        except Exception:
                            pass
                        return True
                r.failure("patch 401 unrecovered")
                return False
            if r.status_code not in (200, 204):
                r.failure("patch status %s" % r.status_code)
                return False
            try:
                d = r.json()
                if isinstance(d, dict) and d.get("csrf"):
                    self.csrf = d["csrf"]
            except Exception:
                pass
            return True

    def _reserve(self, cart_id):
        with self.client.post(
            "/v2/reservations",
            json={"cart_id": cart_id},
            headers={"X-CSRF-Token": self.csrf or ""},
            catch_response=True,
            name="POST /v2/reservations",
        ) as r:
            if r.status_code == 401:
                if self._handle_401(r, cart_id):
                    with self.client.post(
                        "/v2/reservations",
                        json={"cart_id": cart_id},
                        headers={"X-CSRF-Token": self.csrf or ""},
                        catch_response=True,
                        name="POST /v2/reservations retry",
                    ) as r2:
                        if r2.status_code != 202:
                            r2.failure("reservation retry status %s" % r2.status_code)
                            return None
                        try:
                            data = r2.json()
                        except Exception:
                            r2.failure("reservation retry not json")
                            return None
                        if data.get("csrf"):
                            self.csrf = data["csrf"]
                        return data.get("status_url")
                r.failure("reservation 401 unrecovered")
                return None
            if r.status_code != 202:
                r.failure("reservation status %s" % r.status_code)
                return None
            try:
                data = r.json()
            except Exception:
                r.failure("reservation not json")
                return None
            if data.get("csrf"):
                self.csrf = data["csrf"]
            return data.get("status_url")

    def _poll_reservation(self, status_url):
        url = _abs(status_url)
        for i in range(5):
            if i > 0:
                time.sleep(0.06)
            with self.client.get(url, catch_response=True, name="GET reservation status") as r:
                if r.status_code != 200:
                    r.failure("reservation status %s" % r.status_code)
                    return None
                try:
                    data = r.json()
                except Exception:
                    r.failure("reservation status not json")
                    return None
            status = data.get("status")
            if status == "ready":
                return data.get("reservation_id")
            if status in ("pending",):
                continue
            if status in ("failed",):
                return None
        return None

    def _create_order(self, cart_id, reservation_id, etag):
        headers = {"X-CSRF-Token": self.csrf or ""}
        if etag:
            headers["If-Match"] = etag
        headers["Idempotency-Key"] = "cart-%s" % cart_id
        payload = {"cart_id": cart_id}
        if reservation_id:
            payload["reservation_id"] = reservation_id
        with self.client.post(
            "/v2/orders",
            json=payload,
            headers=headers,
            catch_response=True,
            name="POST /v2/orders",
        ) as r:
            if r.status_code == 401:
                if self._handle_401(r, cart_id):
                    with self.client.post(
                        "/v2/orders",
                        json=payload,
                        headers=headers,
                        catch_response=True,
                        name="POST /v2/orders retry",
                    ) as r2:
                        return self._check_order(r2)
                r.failure("order 401 unrecovered")
                return False
            return self._check_order(r)

    def _check_order(self, r):
        if r.status_code == 201:
            try:
                data = r.json()
            except Exception:
                r.failure("order not json")
                return False
            if data.get("accepted") is True:
                if data.get("csrf"):
                    self.csrf = data["csrf"]
                return True
            r.failure("order 201 not accepted")
            return False
        if r.status_code == 200:
            try:
                data = r.json()
            except Exception:
                r.failure("order 200 not json")
                return False
            if data.get("accepted") is False:
                r.failure("order business failure accepted=false")
                return False
            r.failure("order 200 unexpected")
            return False
        r.failure("order status %s" % r.status_code)
        return False

    def _do_work(self):
        # scheduled 429 handling
        for attempt in range(5):
            with self.client.post(
                "/v2/work",
                json={},
                headers={"X-CSRF-Token": self.csrf or ""},
                catch_response=True,
                name="POST /v2/work",
            ) as r:
                if r.status_code == 429:
                    ra = r.headers.get("Retry-After", "1")
                    try:
                        delay = float(ra)
                    except Exception:
                        delay = 1.0
                    time.sleep(delay)
                    continue
                if r.status_code == 200:
                    return True
                if r.status_code == 500:
                    r.failure("work 500")
                    return False
                r.failure("work status %s" % r.status_code)
                return False
        return False

    # ---------- journey ----------
    @task
    def journey(self):
        if self.iterations_done >= self.max_iterations:
            raise StopUser()
        self.iterations_done += 1

        if not self._login():
            raise StopUser()

        # catalog
        prod = self._get_catalog_product()
        if not prod:
            raise StopUser()

        # optional challenge for grant
        grant_id = None
        try:
            grant_id = self._maybe_challenge()
        except Exception:
            grant_id = None

        cart = self._create_cart(prod["product_id"], prod["variant_id"], grant_id)
        if not cart or not cart.get("id"):
            raise StopUser()
        cart_id = cart["id"]
        etag = cart.get("etag")
        if not etag:
            etag = self._get_cart_etag(cart_id)
        if not etag:
            raise StopUser()

        # update cart with If-Match (quantity 2)
        if not self._patch_cart(cart_id, etag, 2):
            raise StopUser()

        # reservation
        status_url = self._reserve(cart_id)
        reservation_id = None
        if status_url:
            reservation_id = self._poll_reservation(status_url)

        # order
        cur_etag = self._get_cart_etag(cart_id)
        self._create_order(cart_id, reservation_id, cur_etag)

        # work sample
        self._do_work()

        if self.iterations_done >= self.max_iterations:
            raise StopUser()


