            Session s = session;
            if (csrf != null) s = s.set("csrf", csrf);
            return s;
        });
    }

    private static ChainBuilder journey() {
        return exec(session -> session
                        .set("username", USERS[ThreadLocalRandom.current().nextInt(USERS.length)]))
                .exec(loginFlow())
                .exec(fetchCatalog())
                .exec(challengeFlow())
                .exec(createCart())
                .exec(patchCart())
                .exec(reserveFlow())
                .exec(checkoutFlow())
                .exec(workFlow());
    }

    private static final ScenarioBuilder SCENARIO = scenario("ModelSimulation")
            .exec(journey());

    {
        setUp(
                SCENARIO.injectOpen(
                        atOnceUsers(2)
                )
        ).protocols(HTTP);
    }
}
