function parseCsrf(html) {
  // Find input[name=csrf] value, tolerant of attribute order/quotes and decoys.
  const re = /<input\b[^>]*>/gi;
  let m;
  while ((m = re.exec(html)) !== null) {
    const tag = m[0];
    const nameMatch = tag.match(/\bname\s*=\s*("([^"]*)"|'([^']*)'|([^\s>]+))/i);
    if (!nameMatch) continue;
    const name = nameMatch[2] !== undefined ? nameMatch[2] : (nameMatch[3] !== undefined ? nameMatch[3] : nameMatch[4]);
    if (name !== 'csrf') continue;
    const valMatch = tag.match(/\bvalue\s*=\s*("([^"]*)"|'([^']*)'|([^\s>]+))/i);
    if (!valMatch) continue;
    const val = valMatch[2] !== undefined ? valMatch[2] : (valMatch[3] !== undefined ? valMatch[3] : valMatch[4]);
    return val;
  }
  return null;
}

function parseChallengeForm(html) {
  // Find form action /v2/challenges/{id} and input[name=challenge]
  const formRe = /<form\b[^>]*>/gi;
  let m;
  let action = null;
  while ((m = formRe.exec(html)) !== null) {
    const tag = m[0];
    const aMatch = tag.match(/\baction\s*=\s*("([^"]*)"|'([^']*)'|([^\s>]+))/i);
    if (!aMatch) continue;
    const a = aMatch[2] !== undefined ? aMatch[2] : (aMatch[3] !== undefined ? aMatch[3] : aMatch[4]);
    if (/\/v2\/challenges\//.test(a)) { action = a; break; }
  }
  let challenge = null;
  const re = /<input\b[^>]*>/gi;
  while ((m = re.exec(html)) !== null) {
    const tag = m[0];
    const nameMatch = tag.match(/\bname\s*=\s*("([^"]*)"|'([^']*)'|([^\s>]+))/i);
    if (!nameMatch) continue;
    const name = nameMatch[2] !== undefined ? nameMatch[2] : (nameMatch[3] !== undefined ? nameMatch[3] : nameMatch[4]);
    if (name !== 'challenge') continue;
    const valMatch = tag.match(/\bvalue\s*=\s*("([^"]*)"|'([^']*)'|([^\s>]+))/i);
    if (!valMatch) continue;
    challenge = valMatch[2] !== undefined ? valMatch[2] : (valMatch[3] !== undefined ? valMatch[3] : valMatch[4]);
    break;
  }
  return { action, challenge };
}

function absUrl(u) {
  if (!u) return u;
  if (/^https?:\/\//i.test(u)) return u;
  if (u.startsWith('/')) return BASE + u;
  return BASE + '/' + u;
}

function sleepMs(ms) {
  const end = Date.now() + ms;
  while (Date.now() < end) { /* busy wait */ }
}

function doLogin(username) {
  // Fresh login: GET form, extract csrf, POST login.
  const formRes = http.get(BASE + '/v2/login-form', { redirects: 0, tags: { name: 'login-form' } });
  check(formRes, { 'login-form 200': (r) => r.status === 200 });
  const csrf = parseCsrf(formRes.body || '');
  check(csrf, { 'login csrf extracted': (v) => !!v });

  const loginRes = http.post(BASE + '/v2/login', JSON.stringify({ username, password: 'bench', csrf }), {
    headers: { 'Content-Type': 'application/json' },
    redirects: 0,
    tags: { name: 'login' },
  });

  let body = null;
  try { body = loginRes.json(); } catch (e) { body = null; }

  if (loginRes.status === 302) {
    const loc = loginRes.headers['Location'] || loginRes.headers['location'];
    check(loc, { 'login redirect location': (v) => !!v });
    const followRes = http.get(absUrl(loc), { redirects: 0, tags: { name: 'login-follow' } });
    check(followRes, { 'login follow 200': (r) => r.status === 200 });
    try { body = followRes.json(); } catch (e) { body = null; }
  } else {
    check(loginRes, { 'login 200': (r) => r.status === 200 });
  }

  check(body, { 'login body has csrf': (b) => b && typeof b.csrf === 'string' && b.csrf.length > 0 });
  return body ? body.csrf : null;
}

function renewSession(csrf) {
  const res = http.post(BASE + '/v2/session/renew', '{}', {
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf },
    redirects: 0,
    tags: { name: 'session-renew' },
  });
  let body = null;
  try { body = res.json(); } catch (e) { body = null; }
  return { res, body };
}

function recoverCart(cartId, csrf) {
  const res = http.post(BASE + '/v2/carts/' + cartId + '/recover', '{}', {
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf },
    redirects: 0,
    tags: { name: 'cart-recover' },
  });
  let body = null;
  try { body = res.json(); } catch (e) { body = null; }
  return { res, body };
}

function isExpired(res) {
  if (res.status !== 401) return false;
  try {
    const b = res.json();
    return b && b.error === 'expired';
  } catch (e) { return false; }
}

function isSessionRevoked(res) {
  if (res.status !== 401) return false;
  try {
    const b = res.json();
    return b && b.error === 'session';
  } catch (e) { return false; }
}

function isDenied(res) {
  if (res.status !== 401) return false;
  try {
    const b = res.json();
    return b && b.error === 'denied';
  } catch (e) { return false; }
}

function extractCsrfFromBody(body) {
  if (body && typeof body.csrf === 'string' && body.csrf.length > 0) return body.csrf;
  return null;
}

function pickProduct(catalogBody) {
  if (!catalogBody || !catalogBody.data || !Array.isArray(catalogBody.data.products)) return null;
  for (const p of catalogBody.data.products) {
    if (!p || !Array.isArray(p.variants)) continue;
    for (const v of p.variants) {
      if (v && v.in_stock) return { product_id: p.id, variant_id: v.id };
    }
  }
  return null;
}

function traverseCatalog() {
  // Try /v2/catalog first
  const res = http.get(BASE + '/v2/catalog', { redirects: 0, tags: { name: 'catalog' } });
  check(res, { 'catalog 200': (r) => r.status === 200 });
  let body = null;
  try { body = res.json(); } catch (e) { body = null; }
  let pick = pickProduct(body);
  if (pick) return pick;

  // Fall back to paged traversal, at most 3 pages
  let next = '/v2/catalog/page';
  let pages = 0;
  while (next && pages < 3) {
    pages++;
    const r = http.get(absUrl(next), { redirects: 0, tags: { name: 'catalog-page' } });
    check(r, { 'catalog-page 200': (x) => x.status === 200 });
    let b = null;
    try { b = r.json(); } catch (e) { b = null; }
    if (b && b.data && b.data.product) {
      const p = b.data.product;
      if (p && Array.isArray(p.variants)) {
        for (const v of p.variants) {
          if (v && v.in_stock) return { product_id: p.id, variant_id: v.id };
        }
      }
    }
    next = b ? b.next : null;
  }
  return null;
}

function solveChallenge(csrf) {
  const formRes = http.get(BASE + '/v2/challenge-form', { redirects: 0, tags: { name: 'challenge-form' } });
  check(formRes, { 'challenge-form 200': (r) => r.status === 200 });
  const { action, challenge } = parseChallengeForm(formRes.body || '');
  check(action, { 'challenge action found': (v) => !!v });
  check(challenge, { 'challenge value found': (v) => !!v });
  if (!action || !challenge) return { grant_id: null, csrf };

  const postRes = http.post(absUrl(action), JSON.stringify({ challenge }), {
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf },
    redirects: 0,
    tags: { name: 'challenge-post' },
  });
  check(postRes, { 'challenge post 302': (r) => r.status === 302 });
  const loc = postRes.headers['Location'] || postRes.headers['location'];
  check(loc, { 'challenge redirect location': (v) => !!v });
  if (!loc) return { grant_id: null, csrf };

  const followRes = http.get(absUrl(loc), { redirects: 0, tags: { name: 'challenge-follow' } });
  check(followRes, { 'challenge follow 200': (r) => r.status === 200 });
  let body = null;
  try { body = followRes.json(); } catch (e) { body = null; }
  const newCsrf = extractCsrfFromBody(body) || csrf;
  return { grant_id: body ? body.grant_id : null, csrf: newCsrf };
}

function createCart(pick, grantId, csrf) {
  const payload = { product_id: pick.product_id, variant_id: pick.variant_id };
  if (grantId) payload.grant_id = grantId;
  const res = http.post(BASE + '/v2/carts', JSON.stringify(payload), {
