function patchCart(cartId, quantity, etag, csrf) {
  const headers = { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf };
  if (etag) headers['If-Match'] = etag;
  const res = http.patch(BASE + '/v2/carts/' + cartId, JSON.stringify({ quantity }), {
