function pollReservation(statusUrl, csrf) {
  let last = null;
  for (let i = 0; i < 5; i++) {
    if (i > 0) sleepMs(60);
    const res = http.get(absUrl(statusUrl), {
      headers: { 'X-CSRF-Token': csrf },
      redirects: 0,
      tags: { name: 'reservation-poll' },
    });
    let body = null;
    try { body = res.json(); } catch (e) { body = null; }
    last = { res, body };
    if (body && body.status === 'ready') return last;
    if (body && body.status === 'failed') return last;
  }
  return last;
}

function createOrder(cartId, reservationId, etag, csrf, idemKey) {
  const payload = { cart_id: cartId };
  if (reservationId) payload.reservation_id = reservationId;
  const headers = {
    'Content-Type': 'application/json',
    'X-CSRF-Token': csrf,
    'Idempotency-Key': idemKey,
