  if (!cartRes.body || !cartRes.body.id) return;
  const cartId = cartRes.body.id;
  if (cartRes.body.csrf) csrf = cartRes.body.csrf;
  let etag = cartRes.res.headers['Etag'] || cartRes.res.headers['ETag'] || cartRes.res.headers['etag'];

  // GET cart to refresh etag
  let cartGet = getCart(cartId, csrf);
  if (isExpired(cartGet.res)) {
    const rn = renewSession(csrf);
    if (rn.body && rn.body.csrf) csrf = rn.body.csrf;
    recoverCart(cartId, csrf);
    cartGet = getCart(cartId, csrf);
  }
  if (cartGet.res.headers['Etag'] || cartGet.res.headers['ETag'] || cartGet.res.headers['etag']) {
    etag = cartGet.res.headers['Etag'] || cartGet.res.headers['ETag'] || cartGet.res.headers['etag'];
  }
  if (cartGet.body && cartGet.body.csrf) csrf = cartGet.body.csrf;

  // PATCH cart quantity
  let patchRes = patchCart(cartId, 2, etag, csrf);
  if (patchRes.res.status === 412) {
    const reread = getCart(cartId, csrf);
    if (reread.body && reread.body.csrf) csrf = reread.body.csrf;
    const newEtag = reread.res.headers['Etag'] || reread.res.headers['ETag'] || reread.res.headers['etag'];
    patchRes = patchCart(cartId, 2, newEtag, csrf);
    etag = newEtag;
  } else if (isExpired(patchRes.res)) {
    const rn = renewSession(csrf);
    if (rn.body && rn.body.csrf) csrf = rn.body.csrf;
    recoverCart(cartId, csrf);
    const reread = getCart(cartId, csrf);
    if (reread.body && reread.body.csrf) csrf = reread.body.csrf;
    const newEtag = reread.res.headers['Etag'] || reread.res.headers['ETag'] || reread.res.headers['etag'];
    patchRes = patchCart(cartId, 2, newEtag, csrf);
    etag = newEtag;
  }
  check(patchRes.res, { 'cart patch ok': (r) => r.status === 200 || r.status === 204 });
  if (patchRes.body && patchRes.body.csrf) csrf = patchRes.body.csrf;
  const patchEtag = patchRes.res.headers['Etag'] || patchRes.res.headers['ETag'] || patchRes.res.headers['etag'];
  if (patchEtag) etag = patchEtag;

  // Reservation
  let resvRes = createReservation(cartId, csrf);
  if (isExpired(resvRes.res)) {
    const rn = renewSession(csrf);
    if (rn.body && rn.body.csrf) csrf = rn.body.csrf;
    recoverCart(cartId, csrf);
    resvRes = createReservation(cartId, csrf);
  }
  check(resvRes.res, { 'reservation 202': (r) => r.status === 202 });
  if (resvRes.body && resvRes.body.csrf) csrf = resvRes.body.csrf;
  const statusUrl = resvRes.body ? resvRes.body.status_url : null;
  check(statusUrl, { 'reservation status_url': (v) => !!v });
  if (!statusUrl) return;

  const polled = pollReservation(statusUrl, csrf);
  if (polled && polled.body && polled.body.csrf) csrf = polled.body.csrf;
  const ready = polled && polled.body && polled.body.status === 'ready';
  check(ready, { 'reservation ready': (v) => v === true });
  if (!ready) return;
  const reservationId = polled.body.reservation_id;
  check(reservationId, { 'reservation_id present': (v) => !!v });
  if (!reservationId) return;

  // Work (business response)
  const work = doWork(csrf);
  if (work.res) {
    check(work.res, { 'work 200': (r) => r.status === 200 });
    if (work.body && work.body.csrf) csrf = work.body.csrf;
  }

  // Order
  const idemKey = 'idem-' + username + '-' + iter + '-' + cartId;
  let orderRes = createOrder(cartId, reservationId, etag, csrf, idemKey);
  if (isExpired(orderRes.res)) {
    const rn = renewSession(csrf);
    if (rn.body && rn.body.csrf) csrf = rn.body.csrf;
    recoverCart(cartId, csrf);
    orderRes = createOrder(cartId, reservationId, etag, csrf, idemKey);
  }
  check(orderRes.res, { 'order 201': (r) => r.status === 201 });
  check(orderRes.body, { 'order accepted': (b) => b && b.accepted === true });
  if (orderRes.body && orderRes.body.csrf) csrf = orderRes.body.csrf;
}
