import static io.gatling.javaapi.core.CoreDsl.*;
import static io.gatling.javaapi.http.HttpDsl.*;

public class ModelSimulation extends Simulation {

    private static final String BASE = System.getenv().getOrDefault("BASE_URL", "http://127.0.0.1:8000");
    private static final String PASSWORD = "bench";

    private static final Pattern CSRF_INPUT = Pattern.compile(
            "name\\s*=\\s*[\"']csrf[\"'][^>]*value\\s*=\\s*[\"']([^\"']+)[\"']|value\\s*=\\s*[\"']([^\"']+)[\"'][^>]*name\\s*=\\s*[\"']csrf[\"']",
            Pattern.CASE_INSENSITIVE);
    private static final Pattern CHALLENGE_ACTION = Pattern.compile(
            "action\\s*=\\s*[\"']([^\"']*?/v2/challenges/[^\"']+)[\"']", Pattern.CASE_INSENSITIVE);
    private static final Pattern CHALLENGE_INPUT = Pattern.compile(
            "name\\s*=\\s*[\"']challenge[\"'][^>]*value\\s*=\\s*[\"']([^\"']*)[\"']|value\\s*=\\s*[\"']([^\"']*)[\"'][^>]*name\\s*=\\s*[\"']challenge[\"']",
            Pattern.CASE_INSENSITIVE);

    private static String extractCsrf(String body) {
        if (body == null) return null;
        Matcher m = CSRF_INPUT.matcher(body);
        if (m.find()) return m.group(1) != null ? m.group(1) : m.group(2);
        return null;
    }

    private static String extractChallengeAction(String body) {
        if (body == null) return null;
        Matcher m = CHALLENGE_ACTION.matcher(body);
        if (m.find()) return m.group(1);
        return null;
    }

    private static String extractChallengeValue(String body) {
        if (body == null) return null;
        Matcher m = CHALLENGE_INPUT.matcher(body);
        if (m.find()) return m.group(1) != null ? m.group(1) : m.group(2);
        return null;
    }

    private static String jsonStr(String body, String key) {
        if (body == null) return null;
        Pattern p = Pattern.compile("\"" + Pattern.quote(key) + "\"\\s*:\\s*\"([^\"]*)\"");
        Matcher m = p.matcher(body);
        if (m.find()) return m.group(1);
        return null;
    }

    private static String jsonNum(String body, String key) {
        if (body == null) return null;
        Pattern p = Pattern.compile("\"" + Pattern.quote(key) + "\"\\s*:\\s*(-?\\d+)");
        Matcher m = p.matcher(body);
        if (m.find()) return m.group(1);
        return null;
    }

    private static boolean jsonBool(String body, String key) {
        if (body == null) return false;
        Pattern p = Pattern.compile("\"" + Pattern.quote(key) + "\"\\s*:\\s*(true|false)");
        Matcher m = p.matcher(body);
        if (m.find()) return "true".equals(m.group(1));
        return false;
    }

    private static String firstProductId(String body) {
        if (body == null) return null;
        Pattern p = Pattern.compile("\"products\"\\s*:\\s*\\[\\s*\\{[^}]*?\"id\"\\s*:\\s*\"?([^,\"}\\s]+)\"?");
        Matcher m = p.matcher(body);
        if (m.find()) return m.group(1);
        return null;
    }

    private static String firstVariantId(String body) {
        if (body == null) return null;
        Pattern p = Pattern.compile("\"variants\"\\s*:\\s*\\[\\s*\\{[^}]*?\"id\"\\s*:\\s*\"?([^,\"}\\s]+)\"?");
        Matcher m = p.matcher(body);
        if (m.find()) return m.group(1);
        return null;
    }

    private static String firstInStockVariantId(String body) {
        if (body == null) return null;
        Pattern p = Pattern.compile("\"variants\"\\s*:\\s*\\[(.*?)\\]", Pattern.DOTALL);
        Matcher m = p.matcher(body);
        if (!m.find()) return null;
        String variants = m.group(1);
        Pattern vp = Pattern.compile("\\{[^}]*?\"id\"\\s*:\\s*\"?([^,\"}\\s]+)\"?[^}]*?\"in_stock\"\\s*:\\s*(true|false)");
        Matcher vm = vp.matcher(variants);
        while (vm.find()) {
            if ("true".equals(vm.group(2))) return vm.group(1);
        }
        return null;
    }

    private static String nextLink(String body) {
        if (body == null) return null;
        Pattern p = Pattern.compile("\"next\"\\s*:\\s*(\"([^\"]*)\"|null)");
        Matcher m = p.matcher(body);
        if (m.find()) {
            if (m.group(2) != null) return m.group(2);
        }
        return null;
    }

    private static String etagOf(io.gatling.javaapi.http.Response r) {
        return r.header("ETag");
    }

    private static final HttpProtocolBuilder HTTP = http
            .baseUrl(BASE)
            .disableAutoReferer()
            .disableFollowRedirect()
            .acceptHeader("application/json, text/html")
            .contentTypeHeader("application/json");

    private static ChainBuilder loginFlow(String user) {
        return exec(
                http("GET login-form")
                        .get("/v2/login-form")
                        .check(status().is(200))
                        .check(bodyString().saveAs("loginFormBody"))
        ).exec(session -> {
            String csrf = extractCsrf(session.getString("loginFormBody"));
            return session.set("csrf", csrf);
        }).exec(
                http("POST login")
                        .post("/v2/login")
                        .body(StringBody(s -> "{\"username\":\"" + user + "\",\"password\":\"" + PASSWORD + "\",\"csrf\":\"" + s.getString("csrf") + "\"}"))
                        .check(status().in(200, 302))
                        .check(bodyString().saveAs("loginBody"))
        ).exec(session -> {
            String body = session.getString("loginBody");
            String csrf = jsonStr(body, "csrf");
            if (csrf != null) return session.set("csrf", csrf);
            return session;
        });
    }

    private static ChainBuilder renewSession() {
        return exec(
                http("POST session renew")
                        .post("/v2/session/renew")
                        .header("X-CSRF-Token", "#{csrf}")
                        .body(StringBody("{}"))
                        .check(status().in(200, 401))
                        .check(bodyString().saveAs("renewBody"))
        ).exec(session -> {
            String body = session.getString("renewBody");
            String csrf = jsonStr(body, "csrf");
            if (csrf != null) return session.set("csrf", csrf);
            return session;
        });
    }

    private static ChainBuilder recoverCart() {
        return exec(
                http("POST cart recover")
                        .post("/v2/carts/#{cartId}/recover")
                        .header("X-CSRF-Token", "#{csrf}")
                        .body(StringBody("{}"))
                        .check(status().in(200, 201, 204, 401))
                        .check(bodyString().saveAs("recoverBody"))
        ).exec(session -> {
            String body = session.getString("recoverBody");
            String csrf = jsonStr(body, "csrf");
            if (csrf != null) return session.set("csrf", csrf);
            return session;
        });
    }

    private static ChainBuilder fullRelogin(String user) {
        return exec(loginFlow(user));
    }

    private static ChainBuilder handleExpiry(String user, ChainBuilder retry) {
        return exec(session -> session.set("recoveryAttempts", 0))
                .asLongAs(session -> session.getInt("recoveryAttempts") < 2).on(
                        exec(session -> session.set("recoveryAttempts", session.getInt("recoveryAttempts") + 1))
                                .exec(renewSession())
                                .exec(session -> {
                                    String body = session.getString("renewBody");
                                    if (body != null && body.contains("\"error\"")) {
                                        return session.set("needRelogin", true);
                                    }
                                    return session.set("needRelogin", false);
                                })
                                .doIf(session -> session.getBoolean("needRelogin")).then(
                                        exec(fullRelogin(user))
                                )
                                .doIf(session -> session.contains("cartId")).then(
                                        exec(recoverCart())
                                )
                                .exec(retry)
                                .exec(session -> {
                                    Integer last = session.get("lastStatus");
                                    if (last != null && last == 401) {
                                        return session;
                                    }
                                    return session.set("recoveryAttempts", 99);
                                })
                );
    }

    private static ChainBuilder fetchCatalog() {
        return exec(
                http("GET catalog")
                        .get("/v2/catalog")
                        .check(status().is(200))
