    private static ChainBuilder fetchChallenge(String user) {
        return exec(
                http("GET challenge-form")
                        .get("/v2/challenge-form")
                        .check(status().is(200))
                        .check(bodyString().saveAs("challengeFormBody"))
        ).exec(session -> {
            String body = session.getString("challengeFormBody");
