    private static ChainBuilder patchQuantity() {
        return exec(
                http("GET cart")
                        .get("/v2/carts/#{cartId}")
                        .check(status().in(200, 401))
                        .check(header("ETag").saveAs("cartEtag"))
        ).exec(
