                        .header("X-CSRF-Token", "#{csrf}")
                        .header("If-Match", "#{cartEtag}")
                        .body(StringBody("{\"quantity\":2}"))
                        .check(status().in(200, 412, 401))
                        .check(bodyString().saveAs("patchBody"))
        ).exec(session -> {
            String body = session.getString("patchBody");
            String csrf = jsonStr(body, "csrf");
            if (csrf != null) return session.set("csrf", csrf);
            return session;
        });
    }

    private static ChainBuilder reserve() {
        return exec(
                http("POST reservation")
                        .post("/v2/reservations")
                        .header("X-CSRF-Token", "#{csrf}")
                        .body(StringBody("{\"cart_id\":\"" + "#{cartId}" + "\"}"))
                        .check(status().in(202, 401))
                        .check(bodyString().saveAs("resBody"))
        ).exec(session -> {
            String body = session.getString("resBody");
            String statusUrl = jsonStr(body, "status_url");
            String csrf = jsonStr(body, "csrf");
            if (csrf != null) session = session.set("csrf", csrf);
            return session.set("statusUrl", statusUrl).set("pollCount", 0).set("reservationId", null);
        }).asLongAs(session -> session.getInt("pollCount") < 5 && session.getString("reservationId") == null).on(
                exec(session -> session.set("pollCount", session.getInt("pollCount") + 1))
                        .pause(Duration.ofMillis(60))
                        .exec(
                                http("GET reservation status")
                                        .get("#{statusUrl}")
                                        .check(status().in(200, 401))
                                        .check(bodyString().saveAs("statusBody"))
                        )
                        .exec(session -> {
                            String body = session.getString("statusBody");
                            String status = jsonStr(body, "status");
                            String rid = jsonStr(body, "reservation_id");
                            String csrf = jsonStr(body, "csrf");
                            if (csrf != null) session = session.set("csrf", csrf);
                            if ("ready".equals(status) && rid != null) {
                                return session.set("reservationId", rid);
                            }
                            if ("failed".equals(status)) {
                                return session.set("pollCount", 99);
                            }
                            return session;
                        })
        );
    }

    private static ChainBuilder checkout() {
        return exec(
                http("POST order")
                        .post("/v2/orders")
                        .header("X-CSRF-Token", "#{csrf}")
                        .header("Idempotency-Key", "#{cartId}-order")
                        .body(StringBody(s -> {
                            String rid = s.getString("reservationId");
                            String base = "{\"cart_id\":\"" + s.getString("cartId") + "\"";
                            if (rid != null && !rid.isEmpty()) base += ",\"reservation_id\":\"" + rid + "\"";
                            return base + "}";
                        }))
                        .check(status().in(201, 200, 401))
                        .check(bodyString().saveAs("orderBody"))
        ).exec(session -> {
            String body = session.getString("orderBody");
            String csrf = jsonStr(body, "csrf");
            if (csrf != null) session = session.set("csrf", csrf);
            boolean accepted = jsonBool(body, "accepted");
            return session.set("orderAccepted", accepted);
        });
    }

    private static ChainBuilder workCall() {
        return exec(
                http("POST work")
                        .post("/v2/work")
                        .header("X-CSRF-Token", "#{csrf}")
                        .body(StringBody("{}"))
                        .check(status().in(200, 429))
                        .check(bodyString().saveAs("workBody"))
        ).exec(session -> {
            String body = session.getString("workBody");
            String csrf = jsonStr(body, "csrf");
            if (csrf != null) return session.set("csrf", csrf);
            return session;
        });
    }

    private static ChainBuilder journey(String user) {
        return exec(loginFlow(user))
                .exec(fetchCatalog())
                .exec(fetchChallenge(user))
                .exec(createCart())
                .exec(patchQuantity())
                .exec(reserve())
                .exec(checkout())
                .exec(workCall());
    }

    private ScenarioBuilder scenario(String name, String user) {
        return scenario(name)
                .exec(journey(user));
    }

    {
        setUp(
                scenario("bench-1", "bench-1").injectOpen(atOnceUsers(1)),
                scenario("bench-2", "bench-2").injectOpen(atOnceUsers(1))
        ).protocols(HTTP);
    }
