import http from 'k6/http';
import { check, sleep } from 'k6';
import { Counter } from 'k6/metrics';

const BASE = __ENV.BASE_URL || 'http://127.0.0.1:8000';

const businessFailures = new Counter('business_failures');
const unexpectedFailures = new Counter('unexpected_failures');

export const options = {
  scenarios: {
    journeys: {
      executor: 'per-vu-iterations',
      vus: 2,
      iterations: 2,
      maxDuration: '5m',
    },
  },
  thresholds: {
    checks: ['rate==1'],
  },
};

function parseCsrf(html) {
  if (!html) return null;
  // find input[name=csrf] with value, tolerant of attribute order/quoting
  const re = /<input\b[^>]*>/gi;
  let m;
  while ((m = re.exec(html)) !== null) {
    const tag = m[0];
    if (!/\bname\s*=\s*["']?csrf["']?/i.test(tag)) continue;
    const vm = tag.match(/\bvalue\s*=\s*["']([^"']*)["']/i);
    if (vm) return vm[1];
  }
  return null;
}

function parseChallenge(html) {
  if (!html) return null;
  const re = /<input\b[^>]*>/gi;
  let m;
  while ((m = re.exec(html)) !== null) {
    const tag = m[0];
    if (!/\bname\s*=\s*["']?challenge["']?/i.test(tag)) continue;
    const vm = tag.match(/\bvalue\s*=\s*["']([^"']*)["']/i);
    if (vm) return vm[1];
  }
  return null;
}

function parseFormAction(html) {
  if (!html) return null;
  const m = html.match(/<form\b[^>]*\baction\s*=\s*["']([^"']+)["']/i);
  return m ? m[1] : null;
}

function absUrl(u) {
  if (!u) return null;
  if (/^https?:\/\//i.test(u)) return u;
  if (u.startsWith('/')) return BASE + u;
  return BASE + '/' + u;
}

function isExpired(res) {
  if (!res || res.status !== 401) return false;
  try {
    const b = res.json();
    return b && b.error === 'expired';
  } catch (e) {
    return false;
  }
}

function isSessionRevoked(res) {
  if (!res || res.status !== 401) return false;
  try {
    const b = res.json();
    return b && b.error === 'session';
  } catch (e) {
    return false;
  }
}

function isDenied(res) {
  if (!res || res.status !== 401) return false;
  try {
    const b = res.json();
    return b && b.error === 'denied';
  } catch (e) {
    return false;
  }
}

function getCsrfFromBody(res) {
  try {
    const b = res.json();
    if (b && typeof b.csrf === 'string') return b.csrf;
  } catch (e) {}
  return null;
}

function login(username) {
  const formRes = http.get(BASE + '/v2/login-form', { tags: { name: 'login-form' } });
  check(formRes, { 'login-form 200': (r) => r.status === 200 });
  const csrf = parseCsrf(formRes.body);
  check(csrf, { 'login-form csrf': (v) => !!v });
  const loginRes = http.post(
    BASE + '/v2/login',
    JSON.stringify({ username: username, password: 'bench', csrf: csrf }),
    {
      headers: { 'Content-Type': 'application/json' },
      redirects: 0,
      tags: { name: 'login' },
    }
  );
  let body = null;
  try { body = loginRes.json(); } catch (e) {}
  if (loginRes.status === 302) {
    const loc = loginRes.headers['Location'] || loginRes.headers['location'];
    if (loc) {
      const follow = http.get(absUrl(loc), { redirects: 0, tags: { name: 'login-redirect' } });
      try { body = follow.json(); } catch (e) {}
    }
  }
  check(body && body.csrf, { 'login csrf': (v) => !!v });
  return { csrf: body ? body.csrf : null, user: body ? body.user : null };
}

function renewSession(csrf) {
  const res = http.post(
    BASE + '/v2/session/renew',
    JSON.stringify({}),
    {
      headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf },
      tags: { name: 'session-renew' },
    }
  );
  const fresh = getCsrfFromBody(res);
  return { ok: res.status >= 200 && res.status < 300, csrf: fresh || csrf, res };
}

function recoverCart(cartId, csrf) {
  const res = http.post(
    BASE + '/v2/carts/' + cartId + '/recover',
    JSON.stringify({}),
    {
      headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf },
      tags: { name: 'cart-recover' },
    }
  );
  const fresh = getCsrfFromBody(res);
  return { ok: res.status >= 200 && res.status < 300, csrf: fresh || csrf, res };
}

function fetchCatalog() {
  const res = http.get(BASE + '/v2/catalog', { tags: { name: 'catalog' } });
  check(res, { 'catalog 200': (r) => r.status === 200 });
  try {
    const b = res.json();
    return (b && b.data && b.data.products) || [];
  } catch (e) {
    return [];
  }
}

function fetchCatalogPage(url) {
  const res = http.get(absUrl(url), { tags: { name: 'catalog-page' } });
  check(res, { 'catalog-page 200': (r) => r.status === 200 });
  try {
    return res.json();
  } catch (e) {
    return null;
  }
}

function pickProduct(products) {
  for (const p of products) {
    if (!p || !p.variants) continue;
    for (const v of p.variants) {
      if (v && v.in_stock) {
        return { product_id: p.id, variant_id: v.id };
      }
    }
  }
  return null;
}

function solveChallenge(csrf) {
  const formRes = http.get(BASE + '/v2/challenge-form', { tags: { name: 'challenge-form' } });
  check(formRes, { 'challenge-form 200': (r) => r.status === 200 });
  const action = parseFormAction(formRes.body);
  const challenge = parseChallenge(formRes.body);
  check(action && challenge, { 'challenge parsed': (v) => !!v });
  if (!action || !challenge) return { ok: false, csrf };
  const postRes = http.post(
    absUrl(action),
    JSON.stringify({ challenge: challenge }),
    {
      headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf },
      redirects: 0,
      tags: { name: 'challenge-post' },
    }
  );
  let loc = postRes.headers['Location'] || postRes.headers['location'];
  let body = null;
  if (postRes.status === 302 && loc) {
    const follow = http.get(absUrl(loc), { redirects: 0, tags: { name: 'challenge-follow' } });
    try { body = follow.json(); } catch (e) {}
  } else {
    try { body = postRes.json(); } catch (e) {}
  }
  const grant = body && body.grant_id;
  const fresh = body && body.csrf;
  check(grant, { 'grant_id': (v) => !!v });
  return { ok: !!grant, grant_id: grant, csrf: fresh || csrf };
}

function createCart(product, variant, grantId, csrf) {
  const payload = { product_id: product, variant_id: variant };
  if (grantId) payload.grant_id = grantId;
  const res = http.post(
    BASE + '/v2/carts',
    JSON.stringify(payload),
    {
      headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf },
      tags: { name: 'cart-create' },
    }
  );
  let body = null;
  try { body = res.json(); } catch (e) {}
  const fresh = body && body.csrf;
  return {
    status: res.status,
    cartId: body && body.id,
    csrf: fresh || csrf,
    etag: res.headers['Etag'] || res.headers['ETag'] || res.headers['etag'],
    res,
  };
}

function getCart(cartId, csrf) {
  const res = http.get(BASE + '/v2/carts/' + cartId, {
    headers: { 'X-CSRF-Token': csrf },
    tags: { name: 'cart-get' },
  });
  const fresh = getCsrfFromBody(res);
  return {
    status: res.status,
    etag: res.headers['Etag'] || res.headers['ETag'] || res.headers['etag'],
    csrf: fresh || csrf,
    res,
  };
}

function patchCart(cartId, etag, csrf) {
  const payload = JSON.stringify({ quantity: 1 });
  const headers = { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf };
  if (etag) headers['If-Match'] = etag;
  let res = http.patch(BASE + '/v2/carts/' + cartId, payload, {
    headers: headers,
    tags: { name: 'cart-patch' },
  });
  let fresh = getCsrfFromBody(res);
  if (res.status === 412) {
    const reread = getCart(cartId, fresh || csrf);
    const h2 = { 'Content-Type': 'application/json', 'X-CSRF-Token': reread.csrf };
    if (reread.etag) h2['If-Match'] = reread.etag;
    res = http.patch(BASE + '/v2/carts/' + cartId, payload, {
      headers: h2,
      tags: { name: 'cart-patch-retry' },
    });
    fresh = getCsrfFromBody(res) || reread.csrf;
  }
  return { status: res.status, csrf: fresh || csrf, res };
}

function createReservation(cartId, csrf) {
  const res = http.post(
    BASE + '/v2/reservations',
    JSON.stringify({ cart_id: cartId }),
    {
      headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf },
      tags: { name: 'reservation-create' },
    }
  );
  let body = null;
  try { body = res.json(); } catch (e) {}
  const fresh = body && body.csrf;
  return {
    status: res.status,
    statusUrl: body && body.status_url,
    csrf: fresh || csrf,
    res,
  };
}

function pollReservation(statusUrl, csrf) {
  let last = null;
  for (let i = 0; i < 5; i++) {
    sleep(0.06);
    const res = http.get(absUrl(statusUrl), {
      headers: { 'X-CSRF-Token': csrf },
      tags: { name: 'reservation-poll' },
    });
    let body = null;
    try { body = res.json(); } catch (e) {}
    const fresh = body && body.csrf;
    if (fresh) csrf = fresh;
    last = body;
    if (body && body.status === 'ready') {
      return { ready: true, reservation_id: body.reservation_id, csrf };
    }
    if (body && (body.status === 'failed')) {
      return { ready: false, csrf };
    }
  }
  return { ready: false, csrf };
}

function createOrder(cartId, reservationId, csrf, idemKey) {
  const payload = { cart_id: cartId };
  if (reservationId) payload.reservation_id = reservationId;
  const headers = {
    'Content-Type': 'application/json',
    'X-CSRF-Token': csrf,
    'Idempotency-Key': idemKey,
  };
  const res = http.post(BASE + '/v2/orders', JSON.stringify(payload), {
    headers: headers,
    tags: { name: 'order-create' },
  });
  let body = null;
  try { body = res.json(); } catch (e) {}
  const fresh = body && body.csrf;
  return {
    status: res.status,
    accepted: body && body.accepted === true,
    id: body && body.id,
    csrf: fresh || csrf,
    res,
  };
}

function doWork(csrf) {
  let attempts = 0;
  while (attempts < 5) {
    attempts++;
    const res = http.post(BASE + '/v2/work', JSON.stringify({}), {
      headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf },
      tags: { name: 'work' },
    });
    const fresh = getCsrfFromBody(res);
    if (fresh) csrf = fresh;
    if (res.status === 429) {
      const ra = res.headers['Retry-After'] || res.headers['retry-after'];
      const wait = ra ? parseFloat(ra) : 1;
      sleep(wait);
      continue;
    }
    if (res.status === 500) {
      unexpectedFailures.add(1);
      businessFailures.add(1);
      return { ok: false, csrf };
    }
    if (res.status >= 200 && res.status < 300) {
      businessFailures.add(1);
      return { ok: true, csrf };
    }
    businessFailures.add(1);
    return { ok: false, csrf };
  }
  return { ok: false, csrf };
}

export default function () {
  const vu = __VU;
  const username = 'bench-' + (((vu - 1) % 16) + 1);

  // Fresh login per journey
  let auth = login(username);
  let csrf = auth.csrf;
  check(csrf, { 'have csrf': (v) => !!v });
  if (!csrf) return;

  // Catalog
  let products = fetchCatalog();
  if (!products || products.length === 0) {
    // try paged catalog
    let pageUrl = '/v2/catalog/page';
    let pages = 0;
    while (pageUrl && pages < 3) {
      pages++;
      const page = fetchCatalogPage(pageUrl);
      if (!page) break;
      if (page.product) products.push(page.product);
      pageUrl = page.next;
    }
  }
  const pick = pickProduct(products);
  check(pick, { 'picked product': (v) => !!v });
  if (!pick) return;

  // Challenge for grant
  let ch = solveChallenge(csrf);
  csrf = ch.csrf;
  const grantId = ch.ok ? ch.grant_id : null;

  // Create cart
  let cart = createCart(pick.product_id, pick.variant_id, grantId, csrf);
  csrf = cart.csrf;
  check(cart.cartId, { 'cart created': (v) => !!v });
  if (!cart.cartId) return;
  const cartId = cart.cartId;

  // Simulate expiry between cart creation and checkout: renew session
  let renewed = renewSession(csrf);
  csrf = renewed.csrf;
  check(renewed.ok, { 'session renewed': (v) => !!v });

  // Recover cart
  let rec = recoverCart(cartId, csrf);
  csrf = rec.csrf;
  check(rec.ok, { 'cart recovered': (v) => !!v });

  // Get cart to obtain ETag
  let cg = getCart(cartId, csrf);
  csrf = cg.csrf;
  check(cg.status === 200, { 'cart get 200': (v) => !!v });

  // Patch cart quantity
  let patch = patchCart(cartId, cg.etag, csrf);
  csrf = patch.csrf;
  check(patch.status >= 200 && patch.status < 300, { 'cart patched': (v) => !!v });

  // Reservation
  let resv = createReservation(cartId, csrf);
  csrf = resv.csrf;
  check(resv.status === 202, { 'reservation 202': (v) => !!v });
  let reservationId = null;
  if (resv.statusUrl) {
    const poll = pollReservation(resv.statusUrl, csrf);
    csrf = poll.csrf;
    if (poll.ready) reservationId = poll.reservation_id;
  }

  // Order
  const idemKey = 'idem-' + cartId + '-' + Date.now();
  let order = createOrder(cartId, reservationId, csrf, idemKey);
  csrf = order.csrf;
  check(order.accepted, { 'order accepted': (v) => !!v });
  check(order.id, { 'order id': (v) => !!v });

  // Business work
  doWork(csrf);
}
