from urllib.parse import urljoin

from locust import HttpUser, task, between
from locust.exception import StopUser, RescheduleTaskImmediately


BASE_URL = os.environ.get("BASE_URL", "http://127.0.0.1:8000")


def _abs(url):
    if not url:
        return url
    return urljoin(BASE_URL + "/", url)


class ShopUser(HttpUser):
    host = BASE_URL
    wait_time = between(0.05, 0.15)

    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self.username = None
        self.password = "bench"
        self.csrf = None
        self.session_ready = False
        self.iterations_done = 0
        self.max_iterations = 2

    # ---------- low level helpers ----------
    def _req(self, method, path, name=None, expect=None, allow=None, **kwargs):
        url = _abs(path)
        with self.client.request(
            method, url, name=name or path, catch_response=True,
            allow_redirects=False, **kwargs
        ) as resp:
            code = resp.status_code
            if allow is not None and code in allow:
                return resp
            if expect is not None:
                if code != expect:
                    resp.failure(f"expected {expect} got {code} for {method} {path}")
                return resp
            if code >= 500:
                resp.failure(f"unexpected {code} for {method} {path}")
            return resp

    def _json(self, resp):
        try:
            return resp.json()
        except Exception:
            return None

    def _extract_csrf_from_html(self, text):
        if not text:
            return None
        # input[name=csrf] with value, tolerant of attribute order/quotes
        m = re.search(
            r'<input[^>]*name\s*=\s*["\']?csrf["\']?[^>]*>',
            text, re.IGNORECASE,
        )
        if not m:
            return None
        tag = m.group(0)
        vm = re.search(r'value\s*=\s*["\']([^"\']*)["\']', tag, re.IGNORECASE)
        if vm:
            return vm.group(1)
        return None

    def _extract_form_action(self, text, action_path):
        if not text:
            return None
        m = re.search(
            r'<form[^>]*action\s*=\s*["\']([^"\']*' + re.escape(action_path) + r'[^"\']*)["\']',
            text, re.IGNORECASE,
        )
        if m:
            return m.group(1)
        return None

    def _extract_challenge_input(self, text):
        if not text:
            return None
        m = re.search(
            r'<input[^>]*name\s*=\s*["\']?challenge["\']?[^>]*>',
            text, re.IGNORECASE,
        )
        if not m:
            return None
        tag = m.group(0)
        vm = re.search(r'value\s*=\s*["\']([^"\']*)["\']', tag, re.IGNORECASE)
        if vm:
            return vm.group(1)
        return None

    # ---------- auth ----------
    def _login(self):
        # fresh form
        r = self._req("GET", "/v2/login-form", name="GET /v2/login-form", expect=200)
        if r.status_code != 200:
            return False
        csrf = self._extract_csrf_from_html(r.text)
        if not csrf:
            r.failure("no csrf in login form")
            return False
        payload = {"username": self.username, "password": self.password, "csrf": csrf}
        r2 = self._req(
            "POST", "/v2/login", name="POST /v2/login",
            json=payload, allow=[200, 302],
        )
        if r2.status_code == 302:
            loc = r2.headers.get("Location")
            if not loc:
                r2.failure("302 without Location")
                return False
            r3 = self._req("GET", loc, name="GET login redirect", expect=200)
            if r3.status_code != 200:
                return False
            body = self._json(r3)
            if not body or "csrf" not in body:
                r3.failure("no csrf in login redirect body")
                return False
            self.csrf = body["csrf"]
            self.session_ready = True
            return True
        if r2.status_code == 200:
            body = self._json(r2)
            if not body or "csrf" not in body:
                r2.failure("no csrf in login response")
                return False
            self.csrf = body["csrf"]
            self.session_ready = True
            return True
        return False

    def _renew(self):
        if not self.csrf:
            return False
        r = self._req(
            "POST", "/v2/session/renew", name="POST /v2/session/renew",
            json={}, headers={"X-CSRF-Token": self.csrf},
            allow=[200, 401],
        )
        if r.status_code == 200:
            body = self._json(r)
            if body and body.get("csrf"):
                self.csrf = body["csrf"]
            return True
        return False

    def _reauth(self):
        # full fresh login
        self.session_ready = False
        self.csrf = None
        return self._login()

    def _handle_401(self, resp, retry_fn):
        """Return True if retry_fn was invoked successfully."""
        body = self._json(resp)
        err = (body or {}).get("error")
        if err == "expired":
            if self._renew():
                return retry_fn()
            if self._reauth():
                return retry_fn()
            return False
        if err == "session":
            if self._reauth():
                return retry_fn()
            return False
        if err == "denied":
            resp.failure("denied is not expiry")
            return False
        resp.failure(f"unexpected 401 error={err}")
        return False

    # ---------- catalog ----------
    def _pick_product(self):
        r = self._req("GET", "/v2/catalog", name="GET /v2/catalog", expect=200)
        if r.status_code != 200:
            return None
        body = self._json(r)
        if not body:
            r.failure("catalog not json")
            return None
        products = (body.get("data") or {}).get("products") or []
        for p in products:
            for v in p.get("variants") or []:
                if v.get("in_stock"):
                    return (p["id"], v["id"])
        # fallback to paged catalog
        next_url = body.get("next")
        pages = 0
        while next_url and pages < 3:
            pages += 1
            r2 = self._req("GET", next_url, name="GET /v2/catalog/page", expect=200)
            if r2.status_code != 200:
                return None
            b2 = self._json(r2)
            if not b2:
                return None
            p = b2.get("product") or b2.get("data", {}).get("product")
            if p:
                for v in p.get("variants") or []:
                    if v.get("in_stock"):
                        return (p["id"], v["id"])
            next_url = b2.get("next")
        return None

    # ---------- challenge ----------
    def _solve_challenge(self):
        r = self._req("GET", "/v2/challenge-form", name="GET /v2/challenge-form", expect=200)
        if r.status_code != 200:
            return None
        action = self._extract_form_action(r.text, "/v2/challenges/")
        challenge = self._extract_challenge_input(r.text)
        if not action or not challenge:
            r.failure("challenge form missing action/input")
            return None
        r2 = self._req(
            "POST", action, name="POST /v2/challenges/{id}",
            json={"challenge": challenge},
            headers={"X-CSRF-Token": self.csrf},
            allow=[302, 200],
        )
        if r2.status_code == 302:
            loc = r2.headers.get("Location")
            if not loc:
                r2.failure("challenge 302 no Location")
                return None
            r3 = self._req("GET", loc, name="GET challenge redirect", expect=200)
            if r3.status_code != 200:
                return None
            body = self._json(r3)
            if not body:
                r3.failure("challenge redirect not json")
                return None
            if body.get("csrf"):
                self.csrf = body["csrf"]
            return body.get("grant_id")
        if r2.status_code == 200:
            body = self._json(r2)
            if body and body.get("csrf"):
                self.csrf = body["csrf"]
            return (body or {}).get("grant_id")
