    def _patch_quantity(self, cart_id, etag, qty):
        headers = {"X-CSRF-Token": self.csrf, "If-Match": etag or ""}
        payload = {"quantity": qty}
        r = self._req(
            "PATCH", f"/v2/carts/{cart_id}", name="PATCH /v2/carts/{id}",
            json=payload, headers=headers, allow=[200, 412, 401],
        )
        if r.status_code == 401:
            def retry():
                h = {"X-CSRF-Token": self.csrf, "If-Match": etag or ""}
                rr = self._req(
                    "PATCH", f"/v2/carts/{cart_id}", name="PATCH /v2/carts/{id} (retry)",
                    json=payload, headers=h, allow=[200, 412, 401],
                )
                return rr if rr.status_code in (200, 412) else None
            res = self._handle_401(r, retry)
            if res is None or res is False:
                return None
            r = res
        if r.status_code == 412:
            # re-read and retry once
            rg = self._req("GET", f"/v2/carts/{cart_id}", name="GET /v2/carts/{id}", expect=200)
            if rg.status_code != 200:
                return None
            new_etag = rg.headers.get("ETag")
            h = {"X-CSRF-Token": self.csrf, "If-Match": new_etag or ""}
            r2 = self._req(
                "PATCH", f"/v2/carts/{cart_id}", name="PATCH /v2/carts/{id} (412 retry)",
                json=payload, headers=h, allow=[200, 412, 401],
            )
            if r2.status_code == 401:
