            return r2.headers.get("ETag") or new_etag
        if r.status_code != 200:
            return None
        body = self._json(r)
        if body and body.get("csrf"):
            self.csrf = body["csrf"]
        return r.headers.get("ETag") or etag

    # ---------- reservation ----------
    def _reserve(self, cart_id):
        r = self._req(
            "POST", "/v2/reservations", name="POST /v2/reservations",
            json={"cart_id": cart_id}, headers={"X-CSRF-Token": self.csrf},
            allow=[202, 401],
        )
        if r.status_code == 401:
            def retry():
                rr = self._req(
                    "POST", "/v2/reservations", name="POST /v2/reservations (retry)",
                    json={"cart_id": cart_id}, headers={"X-CSRF-Token": self.csrf},
                    allow=[202, 401],
                )
                return rr if rr.status_code == 202 else None
            res = self._handle_401(r, retry)
            if res is None or res is False:
                return None
            r = res
