            return None
        body = self._json(r)
        if not body:
            r.failure("reservation not json")
            return None
        if body.get("csrf"):
            self.csrf = body["csrf"]
        status_url = body.get("status_url")
        if not status_url:
            r.failure("reservation missing status_url")
            return None
        for i in range(5):
            if i > 0:
                time.sleep(0.06)
            rs = self._req("GET", status_url, name="GET reservation status", expect=200)
            if rs.status_code != 200:
                return None
            sb = self._json(rs)
            if not sb:
                rs.failure("status not json")
                return None
            st = sb.get("status")
            if st == "ready":
                rid = sb.get("reservation_id")
                if not rid:
                    rs.failure("ready without reservation_id")
                    return None
                return rid
            if st in ("pending",):
                continue
            if st in ("failed",):
                rs.failure("reservation failed")
                return None
            rs.failure(f"unknown reservation status {st}")
            return None
        return None

    # ---------- order ----------
    def _place_order(self, cart_id, reservation_id, idem_key, etag):
        payload = {"cart_id": cart_id}
        if reservation_id:
            payload["reservation_id"] = reservation_id
        headers = {"X-CSRF-Token": self.csrf, "Idempotency-Key": idem_key}
        if etag:
            headers["If-Match"] = etag
        r = self._req(
            "POST", "/v2/orders", name="POST /v2/orders",
            json=payload, headers=headers, allow=[201, 200, 401],
        )
        if r.status_code == 401:
            def retry():
                h = {"X-CSRF-Token": self.csrf, "Idempotency-Key": idem_key}
                if etag:
                    h["If-Match"] = etag
                rr = self._req(
                    "POST", "/v2/orders", name="POST /v2/orders (retry)",
                    json=payload, headers=h, allow=[201, 200, 401],
                )
                return rr if rr.status_code in (201, 200) else None
            res = self._handle_401(r, retry)
            if res is None or res is False:
                return False
            r = res
        if r.status_code == 201:
            body = self._json(r)
            if not body or not body.get("accepted"):
                r.failure("201 without accepted:true")
                return False
            if body.get("csrf"):
                self.csrf = body["csrf"]
            return True
        if r.status_code == 200:
            body = self._json(r)
            if body and body.get("accepted") is False:
                r.failure("order accepted:false")
                return False
            r.failure("unexpected 200 order response")
            return False
        return False

    # ---------- work ----------
    def _do_work(self):
        for attempt in range(5):
            r = self._req(
                "POST", "/v2/work", name="POST /v2/work",
                json={}, headers={"X-CSRF-Token": self.csrf},
                allow=[200, 429, 401],
            )
            if r.status_code == 429:
                ra = r.headers.get("Retry-After", "1")
                try:
                    delay = float(ra)
                except Exception:
                    delay = 1.0
                time.sleep(delay)
                continue
            if r.status_code == 401:
                def retry():
                    rr = self._req(
                        "POST", "/v2/work", name="POST /v2/work (retry)",
                        json={}, headers={"X-CSRF-Token": self.csrf},
                        allow=[200, 429, 401],
                    )
                    return rr if rr.status_code in (200, 429) else None
                res = self._handle_401(r, retry)
                if res is None or res is False:
                    return
                r = res
                if r.status_code == 429:
                    time.sleep(1.0)
                    continue
            if r.status_code == 200:
                body = self._json(r)
                if not body or not body.get("ok"):
                    r.failure("work not ok")
                return
            return

    # ---------- journey ----------
    def _journey(self):
        if not self.session_ready:
            if not self._login():
                return
        # work sample
        self._do_work()

        picked = self._pick_product()
        if not picked:
            return
        product_id, variant_id = picked

        grant_id = self._solve_challenge()

        cart = self._create_cart(product_id, variant_id, grant_id)
        if not cart:
            return
        cart_id = cart["id"]
        etag = cart["etag"]

        # simulate expiry between cart creation and checkout
        # force a renew attempt to exercise recovery path
        if self.csrf:
            self._renew()

        # patch quantity (may hit 401 expired)
        new_etag = self._patch_quantity(cart_id, etag, 1)
        if new_etag is None:
            # try recover then retry once
            if self._recover_cart(cart_id):
                new_etag = self._patch_quantity(cart_id, etag, 1)
            if new_etag is None:
                return
        etag = new_etag

        reservation_id = self._reserve(cart_id)
        if not reservation_id:
            return

        idem_key = str(uuid.uuid4())
        ok = self._place_order(cart_id, reservation_id, idem_key, etag)
        if not ok:
            return

    @task
    def run_journey(self):
        if self.username is None:
            # assign a stable username per user instance
            idx = (id(self) % 16) + 1
            self.username = f"bench-{idx}"
        if self.iterations_done >= self.max_iterations:
            raise StopUser()
        self._journey()
        self.iterations_done += 1
        if self.iterations_done >= self.max_iterations:
            raise StopUser()


