import io.gatling.javaapi.core.*;
import io.gatling.javaapi.http.*;

import java.time.Duration;
import java.util.*;
import java.util.concurrent.ThreadLocalRandom;

import static io.gatling.javaapi.core.CoreDsl.*;
import static io.gatling.javaapi.http.HttpDsl.*;

public class ModelSimulation extends Simulation {

    private static final String BASE = System.getenv("BASE_URL") != null
            ? System.getenv("BASE_URL") : "http://127.0.0.1:8000";

    private static final HttpProtocolBuilder HTTP = http
            .baseUrl(BASE)
            .disableAutoRedirect()
            .acceptHeader("application/json")
            .contentTypeHeader("application/json");

    // ---- helpers -------------------------------------------------------

    private static String csrf() {
        return "#{csrf}";
    }

    private static ChainBuilder login() {
        return exec(
                http("login-form")
                        .get("/v2/login-form")
                        .check(status().is(200))
                        .check(regex("name=\"csrf\"[^>]*value=\"([^\"]+)\"").saveAs("csrf"))
        ).exec(
                http("login")
                        .post("/v2/login")
                        .body(StringBody("{\"username\":\"#{user}\",\"password\":\"bench\",\"csrf\":\"#{csrf}\"}"))
                        .check(status().in(200, 302))
                        .check(header("Location").optional().saveAs("loginLoc"))
                        .check(jsonPath("$.csrf").optional().saveAs("csrf2"))
                        .check(jsonPath("$.user").optional().saveAs("user2"))
        ).exec(session -> {
            String loc = session.getString("loginLoc");
            if (loc != null && !loc.isEmpty()) {
                return session.set("loginLoc", loc);
            }
            return session;
        }).doIf(session -> session.getString("loginLoc") != null)
                .then(exec(
                        http("login-redirect")
                                .get("#{loginLoc}")
                                .check(status().is(200))
                                .check(jsonPath("$.csrf").optional().saveAs("csrf2"))
                ))
        .exec(session -> {
            String c2 = session.getString("csrf2");
            if (c2 != null && !c2.isEmpty()) {
                return session.set("csrf", c2);
            }
            return session;
        });
    }

    private static ChainBuilder challenge() {
        return exec(
                http("challenge-form")
                        .get("/v2/challenge-form")
                        .check(status().is(200))
                        .check(regex("action=\"(/v2/challenges/[^\"]+)\"").saveAs("chAction"))
                        .check(regex("name=\"challenge\"[^>]*value=\"([^\"]+)\"").saveAs("challenge"))
        ).exec(
                http("challenge-submit")
                        .post("#{chAction}")
                        .header("X-CSRF-Token", csrf())
                        .body(StringBody("{\"challenge\":\"#{challenge}\"}"))
                        .check(status().in(200, 302))
                        .check(header("Location").optional().saveAs("chLoc"))
        ).exec(
                http("challenge-claim")
                        .get("#{chLoc}")
                        .check(status().is(200))
                        .check(jsonPath("$.grant_id").saveAs("grant_id"))
                        .check(jsonPath("$.csrf").optional().saveAs("csrf2"))
        ).exec(session -> {
            String c2 = session.getString("csrf2");
            if (c2 != null && !c2.isEmpty()) return session.set("csrf", c2);
            return session;
        });
    }

    private static ChainBuilder createCart() {
        return exec(
                http("cart-create")
                        .post("/v2/carts")
                        .header("X-CSRF-Token", csrf())
                        .body(StringBody("{\"product_id\":\"#{product_id}\",\"variant_id\":\"#{variant_id}\",\"grant_id\":\"#{grant_id}\"}"))
                        .check(status().is(201))
                        .check(jsonPath("$.id").saveAs("cart_id"))
                        .check(jsonPath("$.csrf").optional().saveAs("csrf2"))
                        .check(header("ETag").optional().saveAs("cart_etag"))
        ).exec(session -> {
            String c2 = session.getString("csrf2");
            if (c2 != null && !c2.isEmpty()) return session.set("csrf", c2);
            return session;
        });
    }

    private static ChainBuilder readCart() {
        return exec(
                http("cart-read")
                        .get("/v2/carts/#{cart_id}")
                        .check(status().is(200))
                        .check(header("ETag").optional().saveAs("cart_etag"))
        );
    }

    private static ChainBuilder patchCart() {
        return exec(
                http("cart-patch")
                        .patch("/v2/carts/#{cart_id}")
                        .header("X-CSRF-Token", csrf())
                        .header("If-Match", "#{cart_etag}")
                        .body(StringBody("{\"quantity\":1}"))
                        .check(status().in(200, 412))
                        .check(header("ETag").optional().saveAs("cart_etag"))
                        .check(jsonPath("$.csrf").optional().saveAs("csrf2"))
        ).exec(session -> {
            String c2 = session.getString("csrf2");
            if (c2 != null && !c2.isEmpty()) return session.set("csrf", c2);
            return session;
        });
    }

    private static ChainBuilder reservation() {
        return exec(
                http("reservation-create")
                        .post("/v2/reservations")
                        .header("X-CSRF-Token", csrf())
                        .body(StringBody("{\"cart_id\":\"#{cart_id}\"}"))
                        .check(status().is(202))
                        .check(jsonPath("$.status_url").saveAs("status_url"))
                        .check(jsonPath("$.csrf").optional().saveAs("csrf2"))
        ).exec(session -> {
            String c2 = session.getString("csrf2");
            if (c2 != null && !c2.isEmpty()) return session.set("csrf", c2);
            return session;
        });
    }

    // Poll loop: at most 5 polls, separated by poll_interval, only ready supplies reservation_id.
    private static ChainBuilder pollReservation() {
        return asLongAs(session -> {
            Integer polls = session.getInt("poll_count");
            String status = session.getString("res_status");
            return polls < 5 && !"ready".equals(status) && !"failed".equals(status);
        }, "poll-loop").on(
                pause(session -> Duration.ofMillis((long) (session.getDouble("poll_interval") * 1000)))
                        .exec(
                                http("reservation-status")
                                        .get("#{status_url}")
                                        .check(status().is(200))
                                        .check(jsonPath("$.status").saveAs("res_status"))
                                        .check(jsonPath("$.reservation_id").optional().saveAs("reservation_id"))
                        )
                        .exec(session -> session.set("poll_count", session.getInt("poll_count") + 1))
        );
    }

    private static ChainBuilder checkout() {
        return doIf(session -> "ready".equals(session.getString("res_status"))
                && session.getString("reservation_id") != null)
                .then(exec(
                        http("order-create")
                                .post("/v2/orders")
                                .header("X-CSRF-Token", csrf())
                                .header("Idempotency-Key", "#{idem_key}")
                                .header("If-Match", "#{cart_etag}")
                                .body(StringBody("{\"cart_id\":\"#{cart_id}\",\"reservation_id\":\"#{reservation_id}\"}"))
                                .check(status().is(201))
                                .check(jsonPath("$.accepted").is("true"))
                                .check(jsonPath("$.id").saveAs("order_id"))
                ));
    }

    // ---- scenario ------------------------------------------------------

    private static final ScenarioBuilder SCENARIO = scenario("reservation-journey")
            .exec(session -> {
                int u = session.userId();
                String user = "bench-" + (u % 16 + 1);
                return session
                        .set("user", user)
                        .set("poll_count", 0)
                        .set("poll_interval", 0.02)
                        .set("idem_key", UUID.randomUUID().toString());
            })
            .exec(login())
            .exec(challenge())
            .exec(
                    http("catalog")
                            .get("/v2/catalog")
                            .check(status().is(200))
                            .check(jsonPath("$.data.products[0].id").saveAs("product_id"))
                            .check(jsonPath("$.data.products[0].variants[0].id").saveAs("variant_id"))
            )
            .exec(createCart())
            .exec(readCart())
            .exec(patchCart())
            .exec(reservation())
            .exec(pollReservation())
            .exec(checkout());

    {
        setUp(
                SCENARIO.injectClosed(
                        rampConcurrentUsers(2).to(2).during(Duration.ofSeconds(1)),
                        constantConcurrentUsers(2).during(Duration.ofSeconds(1))
                ).protocols(HTTP)
        );
    }
}
