    checks: ['rate==1'],
  },
};

const PROFILES = [
  { job_polls: 2, poll_interval: 0.02 },
  { job_polls: 3, poll_interval: 0.02, html_layout: 1, reverse_catalog: true },
];

const NEGATIVE = [{ job_fails: true }];

function parseCsrf(html) {
  // find input[name=csrf] value, tolerate attribute variants/order
  const re = /<input\b[^>]*>/gi;
  let m;
  while ((m = re.exec(html)) !== null) {
    const tag = m[0];
    if (/name\s*=\s*["']?csrf["']?/i.test(tag)) {
      const vm = tag.match(/value\s*=\s*["']([^"']*)["']/i);
      if (vm) return vm[1];
    }
  }
  return null;
}

function parseChallengeForm(html) {
  const actionM = html.match(/action\s*=\s*["']([^"']*\/v2\/challenges\/[^"']*)["']/i);
  const action = actionM ? actionM[1] : null;
  let challenge = null;
  const re = /<input\b[^>]*>/gi;
  let m;
  while ((m = re.exec(html)) !== null) {
    const tag = m[0];
    if (/name\s*=\s*["']?challenge["']?/i.test(tag)) {
      const vm = tag.match(/value\s*=\s*["']([^"']*)["']/i);
      if (vm) { challenge = vm[1]; break; }
    }
  }
  return { action, challenge };
}

function absUrl(u) {
  if (!u) return null;
  if (/^https?:\/\//i.test(u)) return u;
  if (u.startsWith('/')) return BASE + u;
  return BASE + '/' + u;
}

function getCookieJar() {
  return http.cookieJar();
}

function login(user) {
  const jar = getCookieJar();
  jar.clear(BASE);
  const formRes = http.get(`${BASE}/v2/login-form`, { tags: { name: 'login-form' } });
  check(formRes, { 'login form 200': (r) => r.status === 200 });
  const csrf = parseCsrf(formRes.body || '');
  check(csrf, { 'login csrf found': (v) => !!v });
  const loginRes = http.post(`${BASE}/v2/login`, JSON.stringify({ username: user, password: 'bench', csrf }), {
    headers: { 'Content-Type': 'application/json' },
    redirects: 0,
    tags: { name: 'login' },
  });
  let body = {};
  try { body = loginRes.json() || {}; } catch (e) { body = {}; }
  let token = body.csrf || csrf;
  if (loginRes.status === 302) {
    const loc = loginRes.headers['Location'];
    if (loc) {
      const follow = http.get(absUrl(loc), { redirects: 0, tags: { name: 'login-redirect' } });
      try { const b = follow.json() || {}; if (b.csrf) token = b.csrf; } catch (e) {}
    }
  }
  check(loginRes, { 'login ok': (r) => r.status === 200 || r.status === 302 });
  return token;
}

function renewSession(csrf) {
  const r = http.post(`${BASE}/v2/session/renew`, JSON.stringify({}), {
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf },
    tags: { name: 'renew' },
  });
  let b = {};
  try { b = r.json() || {}; } catch (e) {}
  return { status: r.status, csrf: b.csrf || csrf, error: b.error };
