}

function fetchCatalog(reverse) {
  const products = [];
  let url = `${BASE}/v2/catalog`;
  let pages = 0;
  while (url && pages < 3) {
    const r = http.get(url, { tags: { name: 'catalog' } });
    if (r.status !== 200) break;
    let b = {};
    try { b = r.json() || {}; } catch (e) { break; }
    const data = b.data || {};
    const list = data.products || [];
    for (const p of list) products.push(p);
    const next = b.next;
    if (!next) break;
    url = absUrl(next);
    pages++;
  }
  if (reverse) products.reverse();
  return products;
}

function fetchCatalogPage(reverse) {
  const products = [];
  let url = `${BASE}/v2/catalog/page`;
  let pages = 0;
  while (url && pages < 3) {
    const r = http.get(url, { tags: { name: 'catalog-page' } });
    if (r.status !== 200) break;
    let b = {};
    try { b = r.json() || {}; } catch (e) { break; }
    const p = b.data && b.data.product ? b.data.product : (b.product || null);
    if (p) products.push(p);
    const next = b.next;
    if (!next) break;
    url = absUrl(next);
