  }
  if (reverse) products.reverse();
  return products;
}

function pickVariant(products) {
  for (const p of products) {
    const variants = p.variants || [];
    for (const v of variants) {
      if (v.in_stock) return { product_id: p.id, variant_id: v.id };
    }
  }
  return null;
}

function solveChallenge(csrf) {
  const formRes = http.get(`${BASE}/v2/challenge-form`, { tags: { name: 'challenge-form' } });
  if (formRes.status !== 200) return { grant_id: null, csrf };
  const { action, challenge } = parseChallengeForm(formRes.body || '');
  if (!action || !challenge) return { grant_id: null, csrf };
  const postRes = http.post(absUrl(action), JSON.stringify({ challenge }), {
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf },
    redirects: 0,
    tags: { name: 'challenge-post' },
  });
  let token = csrf;
  let loc = postRes.headers['Location'];
  if (postRes.status === 302 && loc) {
    const follow = http.get(absUrl(loc), { redirects: 0, tags: { name: 'challenge-follow' } });
    try {
      const b = follow.json() || {};
      if (b.csrf) token = b.csrf;
      return { grant_id: b.grant_id || null, csrf: token };
    } catch (e) {}
  }
  return { grant_id: null, csrf: token };
}

function createCart(product_id, variant_id, grant_id, csrf) {
  const payload = { product_id, variant_id };
  if (grant_id) payload.grant_id = grant_id;
  const r = http.post(`${BASE}/v2/carts`, JSON.stringify(payload), {
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf },
    tags: { name: 'cart-create' },
  });
  let b = {};
  try { b = r.json() || {}; } catch (e) {}
  return { status: r.status, id: b.id, csrf: b.csrf || csrf, etag: r.headers['Etag'] || r.headers['ETag'] };
}

function getCart(cartId, csrf) {
  const r = http.get(`${BASE}/v2/carts/${cartId}`, {
    headers: { 'X-CSRF-Token': csrf },
    tags: { name: 'cart-get' },
  });
  return { status: r.status, etag: r.headers['Etag'] || r.headers['ETag'] };
}

function patchCart(cartId, quantity, etag, csrf) {
  const headers = { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf };
  if (etag) headers['If-Match'] = etag;
  const r = http.patch(`${BASE}/v2/carts/${cartId}`, JSON.stringify({ quantity }), {
    headers,
    tags: { name: 'cart-patch' },
  });
  let b = {};
  try { b = r.json() || {}; } catch (e) {}
  return { status: r.status, csrf: b.csrf || csrf, etag: r.headers['Etag'] || r.headers['ETag'] };
}

function createReservation(cartId, csrf) {
  const r = http.post(`${BASE}/v2/reservations`, JSON.stringify({ cart_id: cartId }), {
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf },
    tags: { name: 'reservation-create' },
  });
  let b = {};
  try { b = r.json() || {}; } catch (e) {}
  return { status: r.status, status_url: b.status_url, csrf: b.csrf || csrf };
}

function pollStatus(statusUrl, maxPolls, interval, csrf) {
  let token = csrf;
  let last = null;
  const polls = Math.min(maxPolls, 5);
  for (let i = 0; i < polls; i++) {
    if (i > 0) sleep(interval);
    const r = http.get(absUrl(statusUrl), {
      headers: { 'X-CSRF-Token': token },
      tags: { name: 'reservation-poll' },
    });
    let b = {};
    try { b = r.json() || {}; } catch (e) {}
    if (b.csrf) token = b.csrf;
    last = { status: r.status, body: b };
    if (b.status === 'ready' || b.status === 'failed') break;
  }
  return { last, csrf: token };
}

function placeOrder(cartId, reservationId, csrf, etag) {
  const headers = { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf };
  if (etag) headers['If-Match'] = etag;
  const payload = { cart_id: cartId };
  if (reservationId) payload.reservation_id = reservationId;
  const idem = `idem-${cartId}-${Date.now()}`;
  headers['Idempotency-Key'] = idem;
  const r = http.post(`${BASE}/v2/orders`, JSON.stringify(payload), {
    headers,
    tags: { name: 'order-create' },
  });
  let b = {};
  try { b = r.json() || {}; } catch (e) {}
  return { status: r.status, body: b, csrf: b.csrf || csrf };
}

function doWork(csrf) {
  const r = http.post(`${BASE}/v2/work`, JSON.stringify({}), {
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf },
    tags: { name: 'work' },
  });
  let b = {};
  try { b = r.json() || {}; } catch (e) {}
  return { status: r.status, body: b, csrf: b.csrf || csrf };
}

export default function () {
  const vu = __VU;
  const iter = __ITER;
  const user = `bench-${((vu - 1) % 16) + 1}`;
  const profile = PROFILES[(vu + iter) % PROFILES.length];
  const negative = NEGATIVE[0];

  let csrf = login(user);
  check(csrf, { 'have csrf': (v) => !!v });

  // catalog
  let products = profile.html_layout ? fetchCatalogPage(profile.reverse_catalog) : fetchCatalog(profile.reverse_catalog);
  if (!products.length) {
    products = fetchCatalog(profile.reverse_catalog);
  }
  const pick = pickVariant(products);
  check(pick, { 'found in-stock variant': (v) => !!v });
  if (!pick) return;

  // challenge
  const ch = solveChallenge(csrf);
  csrf = ch.csrf;

  // cart
  let cart = createCart(pick.product_id, pick.variant_id, ch.grant_id, csrf);
  if (cart.status === 401) {
    const rn = renewSession(csrf);
    csrf = rn.csrf;
    cart = createCart(pick.product_id, pick.variant_id, ch.grant_id, csrf);
  }
  check(cart, { 'cart created': (c) => c.status === 201 && !!c.id });
  if (!cart.id) return;
  csrf = cart.csrf;
  const cartId = cart.id;

  // patch quantity
  let etag = cart.etag;
  let patch = patchCart(cartId, 1, etag, csrf);
  if (patch.status === 412) {
    const g = getCart(cartId, csrf);
    etag = g.etag;
    patch = patchCart(cartId, 1, etag, csrf);
  }
  if (patch.status === 401) {
    const rn = renewSession(csrf);
    csrf = rn.csrf;
    recoverCart(cartId, csrf);
    patch = patchCart(cartId, 1, etag, csrf);
  }
  csrf = patch.csrf;
  etag = patch.etag || etag;
  check(patch, { 'cart patched': (p) => p.status === 200 || p.status === 204 });

  // reservation
  let res = createReservation(cartId, csrf);
  if (res.status === 401) {
    const rn = renewSession(csrf);
    csrf = rn.csrf;
    recoverCart(cartId, csrf);
    res = createReservation(cartId, csrf);
  }
  csrf = res.csrf;
  check(res, { 'reservation 202': (r) => r.status === 202 && !!r.status_url });
  if (!res.status_url) return;

  // poll
  const polled = pollStatus(res.status_url, profile.job_polls, profile.poll_interval, csrf);
  csrf = polled.csrf;
  const finalStatus = polled.last && polled.last.body ? polled.last.body.status : null;
  const reservationId = polled.last && polled.last.body ? polled.last.body.reservation_id : null;

  if (negative.job_fails) {
    check(finalStatus, { 'negative: job failed': (s) => s === 'failed' });
    check(reservationId, { 'negative: no reservation id': (v) => !v });
    // must not checkout
    return;
  }

  check(finalStatus, { 'reservation ready': (s) => s === 'ready' });
  check(reservationId, { 'have reservation id': (v) => !!v });
  if (finalStatus !== 'ready' || !reservationId) return;

  // order
  let order = placeOrder(cartId, reservationId, csrf, etag);
  if (order.status === 401) {
    const rn = renewSession(csrf);
    csrf = rn.csrf;
    recoverCart(cartId, csrf);
    order = placeOrder(cartId, reservationId, csrf, etag);
  }
  check(order, { 'order accepted': (o) => o.status === 201 && o.body && o.body.accepted === true && !!o.body.id });

  // work
  let w = doWork(csrf);
  let retries = 0;
  while (w.status === 429 && retries < 4) {
    sleep(1);
    w = doWork(csrf);
    retries++;
  }
  check(w, { 'work ok': (r) => r.status === 200 && r.body && r.body.ok === true });
}
