import os
import re
import time
from urllib.parse import urljoin

from locust import HttpUser, task, between
from locust.exception import StopUser


BASE_URL = os.environ.get("BASE_URL", "http://127.0.0.1:8000")


def _find_csrf(html):
    # input[name=csrf] mixed with decoys/attribute variants
    patterns = [
        r'<input[^>]*name=["\']csrf["\'][^>]*value=["\']([^"\']+)["\']',
        r'<input[^>]*value=["\']([^"\']+)["\'][^>]*name=["\']csrf["\']',
    ]
    for p in patterns:
        m = re.search(p, html, re.IGNORECASE)
        if m:
            return m.group(1)
    return None


def _find_challenge(html):
    action = None
    m = re.search(r'<form[^>]*action=["\']([^"\']*?/v2/challenges/[^"\']+)["\']', html, re.IGNORECASE)
    if m:
        action = m.group(1)
    token = None
    m2 = re.search(r'<input[^>]*name=["\']challenge["\'][^>]*value=["\']([^"\']+)["\']', html, re.IGNORECASE)
    if m2:
        token = m2.group(1)
    else:
        m3 = re.search(r'<input[^>]*value=["\']([^"\']+)["\'][^>]*name=["\']challenge["\']', html, re.IGNORECASE)
        if m3:
            token = m3.group(1)
    return action, token


class ShopUser(HttpUser):
    host = BASE_URL
    wait_time = between(0.01, 0.05)

    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self._iterations_done = 0
        self._max_iterations = 2
        self._profile_index = 0
        self._profiles = [
            {"job_polls": 2, "poll_interval": 0.02},
            {"job_polls": 3, "poll_interval": 0.02, "html_layout": 1, "reverse_catalog": True},
        ]
        self._negative_control = {"job_fails": True}

    # ---------- helpers ----------
    def _login(self):
        self.client.cookies.clear()
        with self.client.get("/v2/login-form", catch_response=True, allow_redirects=False) as r:
            if r.status_code != 200:
                r.failure("login-form status %s" % r.status_code)
                return None
            csrf = _find_csrf(r.text)
            if not csrf:
                r.failure("no csrf in login form")
                return None
        username = "bench-%d" % ((self._iterations_done % 16) + 1)
        payload = {"username": username, "password": "bench", "csrf": csrf}
        with self.client.post("/v2/login", json=payload, catch_response=True, allow_redirects=False) as r:
            if r.status_code == 302:
                loc = r.headers.get("Location")
                if loc:
                    with self.client.get(loc, catch_response=True, allow_redirects=False) as r2:
                        if r2.status_code not in (200, 201):
                            r2.failure("login redirect status %s" % r2.status_code)
                            return None
                        try:
                            data = r2.json()
                        except Exception:
                            r2.failure("login redirect not json")
                            return None
                        return data.get("csrf")
            if r.status_code != 200:
                r.failure("login status %s" % r.status_code)
                return None
            try:
                data = r.json()
            except Exception:
                r.failure("login not json")
                return None
            return data.get("csrf")

    def _get_catalog_product(self, reverse=False):
        with self.client.get("/v2/catalog", catch_response=True) as r:
            if r.status_code != 200:
                r.failure("catalog status %s" % r.status_code)
                return None
            try:
                data = r.json()
            except Exception:
                r.failure("catalog not json")
                return None
        products = (data.get("data") or {}).get("products") or []
        if reverse:
            products = list(reversed(products))
        for p in products:
            for v in p.get("variants") or []:
                if v.get("in_stock"):
                    return p.get("id"), v.get("id")
        # fallback to paged catalog
        next_url = data.get("next")
        pages = 0
        while next_url and pages < 3:
            pages += 1
            url = next_url if next_url.startswith("http") else urljoin(BASE_URL, next_url)
            with self.client.get(url, catch_response=True) as r:
                if r.status_code != 200:
                    r.failure("catalog page status %s" % r.status_code)
                    return None
                try:
                    pdata = r.json()
                except Exception:
                    r.failure("catalog page not json")
                    return None
            prods = pdata.get("products") or (pdata.get("data") or {}).get("products") or []
            if reverse:
                prods = list(reversed(prods))
            for p in prods:
                for v in p.get("variants") or []:
                    if v.get("in_stock"):
                        return p.get("id"), v.get("id")
            next_url = pdata.get("next")
        return None

    def _solve_challenge(self, csrf):
        with self.client.get("/v2/challenge-form", catch_response=True) as r:
            if r.status_code != 200:
                r.failure("challenge-form status %s" % r.status_code)
                return None, csrf
            action, token = _find_challenge(r.text)
            if not action or not token:
                r.failure("challenge form parse failed")
                return None, csrf
        url = action if action.startswith("http") else urljoin(BASE_URL, action)
        headers = {"X-CSRF-Token": csrf}
        with self.client.post(url, json={"challenge": token}, headers=headers,
                              catch_response=True, allow_redirects=False) as r:
            if r.status_code != 302:
                r.failure("challenge post status %s" % r.status_code)
                return None, csrf
            loc = r.headers.get("Location")
        if not loc:
            return None, csrf
        loc_url = loc if loc.startswith("http") else urljoin(BASE_URL, loc)
        with self.client.get(loc_url, catch_response=True, allow_redirects=False) as r:
            if r.status_code != 200:
                r.failure("challenge claim status %s" % r.status_code)
                return None, csrf
            try:
                data = r.json()
            except Exception:
                r.failure("challenge claim not json")
                return None, csrf
        return data.get("grant_id"), data.get("csrf") or csrf

    def _create_cart(self, csrf, product_id, variant_id, grant_id):
        headers = {"X-CSRF-Token": csrf}
        payload = {"product_id": product_id, "variant_id": variant_id}
        if grant_id:
            payload["grant_id"] = grant_id
        with self.client.post("/v2/carts", json=payload, headers=headers,
                              catch_response=True, allow_redirects=False) as r:
            if r.status_code != 201:
                r.failure("cart create status %s" % r.status_code)
                return None, csrf, None
            try:
                data = r.json()
            except Exception:
                r.failure("cart create not json")
                return None, csrf, None
            etag = r.headers.get("ETag")
            return data.get("id"), data.get("csrf") or csrf, etag

    def _patch_quantity(self, csrf, cart_id, etag, qty):
        headers = {"X-CSRF-Token": csrf}
        if etag:
            headers["If-Match"] = etag
        payload = {"quantity": qty}
        with self.client.patch("/v2/carts/%s" % cart_id, json=payload, headers=headers,
                               catch_response=True, allow_redirects=False) as r:
            if r.status_code == 412:
                # re-read and retry once
                with self.client.get("/v2/carts/%s" % cart_id, catch_response=True) as rg:
                    if rg.status_code != 200:
                        rg.failure("cart re-read status %s" % rg.status_code)
                        return csrf, etag
                    new_etag = rg.headers.get("ETag")
                headers2 = {"X-CSRF-Token": csrf}
                if new_etag:
                    headers2["If-Match"] = new_etag
                with self.client.patch("/v2/carts/%s" % cart_id, json=payload, headers=headers2,
                                       catch_response=True, allow_redirects=False) as r2:
                    if r2.status_code not in (200, 204):
                        r2.failure("cart patch retry status %s" % r2.status_code)
                        return csrf, new_etag
                    try:
                        d = r2.json()
                        return d.get("csrf") or csrf, r2.headers.get("ETag") or new_etag
                    except Exception:
                        return csrf, r2.headers.get("ETag") or new_etag
            if r.status_code not in (200, 204):
                r.failure("cart patch status %s" % r.status_code)
                return csrf, etag
            try:
                d = r.json()
                return d.get("csrf") or csrf, r.headers.get("ETag") or etag
            except Exception:
                return csrf, r.headers.get("ETag") or etag

    def _reserve(self, csrf, cart_id, profile):
        headers = {"X-CSRF-Token": csrf}
        with self.client.post("/v2/reservations", json={"cart_id": cart_id}, headers=headers,
                              catch_response=True, allow_redirects=False) as r:
            if r.status_code != 202:
                r.failure("reservation status %s" % r.status_code)
                return None, csrf
            try:
                data = r.json()
            except Exception:
                r.failure("reservation not json")
                return None, csrf
            status_url = data.get("status_url")
            csrf = data.get("csrf") or csrf
        if not status_url:
            return None, csrf
        url = status_url if status_url.startswith("http") else urljoin(BASE_URL, status_url)
        max_polls = min(profile.get("job_polls", 2), 5)
        interval = profile.get("poll_interval", 0.02)
        reservation_id = None
        for i in range(max_polls):
            if i > 0:
                time.sleep(interval)
            with self.client.get(url, catch_response=True) as r:
                if r.status_code != 200:
                    r.failure("status poll status %s" % r.status_code)
                    return None, csrf
                try:
                    sdata = r.json()
                except Exception:
                    r.failure("status poll not json")
                    return None, csrf
            status = sdata.get("status")
            if status == "ready":
                reservation_id = sdata.get("reservation_id")
                break
            if status == "failed":
                return None, csrf
            # pending -> continue
        return reservation_id, csrf

    def _checkout(self, csrf, cart_id, reservation_id, etag):
        headers = {"X-CSRF-Token": csrf, "Idempotency-Key": "idem-%s" % cart_id}
        if etag:
            headers["If-Match"] = etag
        payload = {"cart_id": cart_id}
        if reservation_id:
            payload["reservation_id"] = reservation_id
        with self.client.post("/v2/orders", json=payload, headers=headers,
                              catch_response=True, allow_redirects=False) as r:
            if r.status_code == 200:
                try:
                    d = r.json()
                except Exception:
                    r.failure("order not json")
                    return False
                if not d.get("accepted"):
                    r.failure("order business failure")
                    return False
                return True
            if r.status_code != 201:
                r.failure("order status %s" % r.status_code)
                return False
            try:
                d = r.json()
            except Exception:
                r.failure("order not json")
                return False
            if not d.get("accepted"):
                r.failure("order not accepted")
                return False
            return True

    # ---------- journey ----------
    @task
    def journey(self):
        if self._iterations_done >= self._max_iterations:
            raise StopUser()
        profile = self._profiles[self._profile_index % len(self._profiles)]
        self._profile_index += 1

        csrf = self._login()
        if not csrf:
            self._iterations_done += 1
            if self._iterations_done >= self._max_iterations:
                raise StopUser()
            return

        prod = self._get_catalog_product(reverse=profile.get("reverse_catalog", False))
        if not prod:
            self._iterations_done += 1
            if self._iterations_done >= self._max_iterations:
                raise StopUser()
            return
        product_id, variant_id = prod

        grant_id, csrf = self._solve_challenge(csrf)

        cart_id, csrf, etag = self._create_cart(csrf, product_id, variant_id, grant_id)
        if not cart_id:
            self._iterations_done += 1
            if self._iterations_done >= self._max_iterations:
                raise StopUser()
            return

        csrf, etag = self._patch_quantity(csrf, cart_id, etag, 1)

        reservation_id, csrf = self._reserve(csrf, cart_id, profile)

        if reservation_id:
            self._checkout(csrf, cart_id, reservation_id, etag)

        self._iterations_done += 1
        if self._iterations_done >= self._max_iterations:
            raise StopUser()


class ShopUserA(ShopUser):
    weight = 1


class ShopUserB(ShopUser):
    weight = 1


from locust import LoadTestShape


class SingleTickShape(LoadTestShape):
    def __init__(self):
        super().__init__()
        self._done = False

    def tick(self):
        if self._done:
            return None
        self._done = True
        return (2, 2, 1, 1)
