import io.gatling.javaapi.core.*;
import io.gatling.javaapi.http.*;

import java.time.Duration;
import java.util.*;
import java.util.concurrent.ThreadLocalRandom;

import static io.gatling.javaapi.core.CoreDsl.*;
import static io.gatling.javaapi.http.HttpDsl.*;

public class ModelSimulation extends Simulation {

    private static final String BASE_URL = System.getenv().getOrDefault("BASE_URL", "http://127.0.0.1:8000");

    private static final HttpProtocolBuilder HTTP = http
            .baseUrl(BASE_URL)
            .disableAutoReferer()
            .disableFollowRedirect()
            .acceptHeader("application/json")
            .contentTypeHeader("application/json")
            .userAgentHeader("gatling-model-simulation");

    // ---------- helpers ----------

    private static String jsonStr(String s) {
        if (s == null) return "null";
        StringBuilder b = new StringBuilder("\"");
        for (char c : s.toCharArray()) {
            switch (c) {
                case '"': b.append("\\\""); break;
                case '\\': b.append("\\\\"); break;
                case '\n': b.append("\\n"); break;
                case '\r': b.append("\\r"); break;
                case '\t': b.append("\\t"); break;
                default: b.append(c);
            }
        }
        return b.append('"').toString();
    }

    private static String loginBody(String user, String csrf) {
        return "{\"username\":" + jsonStr(user) + ",\"password\":\"bench\",\"csrf\":" + jsonStr(csrf) + "}";
    }

    private static String challengeBody(String challenge) {
        return "{\"challenge\":" + jsonStr(challenge) + "}";
    }

    private static String cartBody(String productId, String variantId, String grantId) {
        StringBuilder b = new StringBuilder("{\"product_id\":").append(jsonStr(productId))
                .append(",\"variant_id\":").append(jsonStr(variantId));
        if (grantId != null && !grantId.isEmpty()) {
            b.append(",\"grant_id\":").append(jsonStr(grantId));
        }
        return b.append('}').toString();
    }

    private static String patchBody(int qty) {
        return "{\"quantity\":" + qty + "}";
    }

    private static String orderBody(String cartId, String reservationId) {
        StringBuilder b = new StringBuilder("{\"cart_id\":").append(jsonStr(cartId));
        if (reservationId != null && !reservationId.isEmpty()) {
            b.append(",\"reservation_id\":").append(jsonStr(reservationId));
        }
        return b.append('}').toString();
    }

    private static String reservationBody(String cartId) {
        return "{\"cart_id\":" + jsonStr(cartId) + "}";
    }

    // ---------- chains ----------

    private static ChainBuilder login(String user) {
        return exec(
                http("login-form")
                        .get("/v2/login-form")
                        .check(status().is(200))
                        .check(css("input[name=csrf]", "value").saveAs("csrf"))
        ).exec(
                http("login")
                        .post("/v2/login")
                        .body(StringBody(session -> loginBody(user, session.getString("csrf"))))
                        .check(status().in(200, 302))
                        .check(header("Location").optional().saveAs("loginLocation"))
                        .check(bodyString().optional().saveAs("loginBody"))
        ).exec(session -> {
            String loc = session.getString("loginLocation");
            if (loc != null && !loc.isEmpty()) {
                return session.set("loginRedirect", loc);
            }
            return session;
        }).doIf(session -> session.getString("loginRedirect") != null).then(
                exec(
                        http("login-redirect")
                                .get(session -> session.getString("loginRedirect"))
                                .check(status().is(200))
                                .check(jsonPath("$.csrf").saveAs("csrf"))
                                .check(jsonPath("$.user").saveAs("user"))
                )
        ).doIf(session -> session.getString("loginRedirect") == null).then(
                exec(session -> {
                    String body = session.getString("loginBody");
                    if (body != null) {
                        // best-effort parse of csrf from body
                        int i = body.indexOf("\"csrf\"");
                        if (i >= 0) {
                            int q1 = body.indexOf('"', i + 6);
                            int q2 = body.indexOf('"', q1 + 1);
                            if (q1 > 0 && q2 > q1) {
                                return session.set("csrf", body.substring(q1 + 1, q2));
                            }
                        }
                    }
                    return session;
                })
        );
    }

    private static ChainBuilder challenge() {
        return exec(
                http("challenge-form")
                        .get("/v2/challenge-form")
                        .check(status().is(200))
                        .check(regex("action=\"(/v2/challenges/[^\"]+)\"").saveAs("challengeAction"))
                        .check(css("input[name=challenge]", "value").saveAs("challengeValue"))
        ).exec(
                http("challenge-submit")
                        .post(session -> session.getString("challengeAction"))
                        .header("X-CSRF-Token", session -> session.getString("csrf"))
                        .body(StringBody(session -> challengeBody(session.getString("challengeValue"))))
                        .check(status().in(200, 302))
                        .check(header("Location").optional().saveAs("challengeLocation"))
        ).exec(
                http("challenge-claim")
                        .get(session -> session.getString("challengeLocation"))
                        .check(status().is(200))
                        .check(jsonPath("$.grant_id").saveAs("grantId"))
                        .check(jsonPath("$.csrf").optional().saveAs("csrfNew"))
        ).exec(session -> {
            String c = session.getString("csrfNew");
            if (c != null && !c.isEmpty()) return session.set("csrf", c);
            return session;
        });
    }

    private static ChainBuilder pickProduct() {
        return exec(
                http("catalog")
                        .get("/v2/catalog")
                        .check(status().is(200))
                        .check(jsonPath("$.data.products[*].id").findAll().optional().saveAs("productIds"))
                        .check(jsonPath("$.data.products[*].variants[*].id").findAll().optional().saveAs("variantIds"))
                        .check(jsonPath("$.data.products[*].variants[*].in_stock").findAll().optional().saveAs("inStock"))
        ).exec(session -> {
            List<String> pids = session.getList("productIds");
            List<String> vids = session.getList("variantIds");
            List<String> stock = session.getList("inStock");
            if (pids != null && !pids.isEmpty() && vids != null && !vids.isEmpty()) {
                int idx = ThreadLocalRandom.current().nextInt(vids.size());
                String pid = pids.get(Math.min(idx, pids.size() - 1));
                String vid = vids.get(idx);
                return session.set("productId", pid).set("variantId", vid);
            }
            return session;
        }).doIf(session -> session.getString("productId") == null).then(
                exec(
                        http("catalog-page")
                                .get("/v2/catalog/page")
                                .check(status().is(200))
                                .check(jsonPath("$.data.product.id").saveAs("productId"))
                                .check(jsonPath("$.data.product.variants[0].id").saveAs("variantId"))
                )
        );
    }

    private static ChainBuilder createCart() {
        return exec(
                http("cart-create")
                        .post("/v2/carts")
                        .header("X-CSRF-Token", session -> session.getString("csrf"))
                        .body(StringBody(session -> cartBody(
                                session.getString("productId"),
                                session.getString("variantId"),
                                session.getString("grantId"))))
                        .check(status().is(201))
                        .check(jsonPath("$.id").saveAs("cartId"))
                        .check(jsonPath("$.csrf").optional().saveAs("csrfNew"))
                        .check(header("ETag").optional().saveAs("cartEtag"))
        ).exec(session -> {
            String c = session.getString("csrfNew");
            if (c != null && !c.isEmpty()) return session.set("csrf", c);
            return session;
        });
    }

    private static ChainBuilder patchCart() {
        return exec(
                http("cart-patch")
                        .patch(session -> "/v2/carts/" + session.getString("cartId"))
                        .header("X-CSRF-Token", session -> session.getString("csrf"))
                        .header("If-Match", session -> {
                            String e = session.getString("cartEtag");
                            return e == null ? "*" : e;
                        })
                        .body(StringBody(session -> patchBody(1)))
                        .check(status().in(200, 204, 412))
                        .check(header("ETag").optional().saveAs("cartEtagNew"))
        ).exec(session -> {
            String e = session.getString("cartEtagNew");
            if (e != null && !e.isEmpty()) return session.set("cartEtag", e);
            return session;
        });
    }

    private static ChainBuilder reserve() {
        return exec(
                http("reservation-create")
                        .post("/v2/reservations")
                        .header("X-CSRF-Token", session -> session.getString("csrf"))
                        .body(StringBody(session -> reservationBody(session.getString("cartId"))))
                        .check(status().is(202))
                        .check(jsonPath("$.status_url").saveAs("statusUrl"))
                        .check(jsonPath("$.csrf").optional().saveAs("csrfNew"))
        ).exec(session -> {
            String c = session.getString("csrfNew");
            if (c != null && !c.isEmpty()) return session.set("csrf", c);
            return session;
        }).exec(
                asLongAs(session -> session.getInt("pollCount") < 5).on(
                        exec(session -> session.set("pollCount", session.getInt("pollCount") + 1))
                                .pause(Duration.ofMillis(60))
                                .exec(
                                        http("reservation-poll")
                                                .get(session -> session.getString("statusUrl"))
                                                .check(status().is(200))
                                                .check(jsonPath("$.status").saveAs("resStatus"))
                                                .check(jsonPath("$.reservation_id").optional().saveAs("reservationId"))
                                )
                                .exec(session -> {
                                    String st = session.getString("resStatus");
                                    if ("ready".equals(st) || "failed".equals(st)) {
                                        return session.set("pollDone", true);
                                    }
                                    return session;
                                })
                )
        );
    }

    private static ChainBuilder checkout() {
        return exec(
                http("order-create")
                        .post("/v2/orders")
                        .header("X-CSRF-Token", session -> session.getString("csrf"))
                        .header("Idempotency-Key", session -> "idem-" + session.getString("cartId"))
                        .header("If-Match", session -> {
                            String e = session.getString("cartEtag");
                            return e == null ? "*" : e;
                        })
                        .body(StringBody(session -> orderBody(
                                session.getString("cartId"),
                                session.getString("reservationId"))))
                        .check(status().is(201))
                        .check(jsonPath("$.accepted").is("true"))
                        .check(jsonPath("$.id").saveAs("orderId"))
                        .check(jsonPath("$.csrf").optional().saveAs("csrfNew"))
        ).exec(session -> {
            String c = session.getString("csrfNew");
            if (c != null && !c.isEmpty()) return session.set("csrf", c);
            return session;
        });
    }

    private static ChainBuilder work() {
        return exec(
                http("work")
                        .post("/v2/work")
                        .header("X-CSRF-Token", session -> session.getString("csrf"))
                        .body(StringBody("{}"))
                        .check(status().in(200, 429))
                        .check(jsonPath("$.ok").optional().saveAs("workOk"))
        );
    }

    private static ChainBuilder journey(String user) {
        return exec(session -> session
                        .set("pollCount", 0)
                        .set("pollDone", false)
                        .set("csrf", "")
                        .set("grantId", "")
                        .set("reservationId", "")
                        .set("cartId", "")
                        .set("productId", "")
                        .set("variantId", ""))
                .exec(login(user))
                .exec(challenge())
                .exec(pickProduct())
                .exec(createCart())
                .exec(patchCart())
                .exec(reserve())
                .exec(checkout())
                .exec(work());
    }

    // ---------- scenario ----------

    private static final int USERS = 2;
    private static final int ITERATIONS = 2;

    private ScenarioBuilder scenario() {
        return scenario("challenge-journey")
                .exec(session -> session.set("username", "bench-" + (session.userId() % 16 + 1)))
                .repeat(ITERATIONS).on(
                        exec(journey("bench"))
                );
    }

    {
        setUp(
                scenario().injectOpen(
                        rampUsers(USERS).during(Duration.ofSeconds(1))
                )
        ).protocols(HTTP);
    }
}
