```javascript
import http from 'k6/http';
import { check, group, fail } from 'k6';
import { Counter, Rate } from 'k6/metrics';

const BASE = __ENV.BASE_URL || 'http://127.0.0.1:8000';

const businessFailures = new Counter('business_failures');
const businessResponses = new Counter('business_responses');
const unexpectedFailures = new Counter('unexpected_failures');

export const options = {
  scenarios: {
    challenge: {
      executor: 'per-vu-iterations',
      vus: 2,
      iterations: 2,
      maxDuration: '120s',
    },
  },
  thresholds: {
    checks: ['rate==1'],
  },
};

const PROFILES = [
  { require_challenge: true },
  { require_challenge: true, html_layout: 1, reverse_catalog: true },
];

function jar() {
  return http.cookieJar();
}

function parseCsrfFromForm(body) {
  // input[name=csrf] with possible attribute variants / decoys
  const re = /<input\b[^>]*\bname\s*=\s*["']?csrf["']?[^>]*>/gi;
  let m;
  while ((m = re.exec(body)) !== null) {
    const tag = m[0];
    const vm = tag.match(/\bvalue\s*=\s*["']([^"']*)["']/i);
    if (vm) return vm[1];
  }
  // fallback: value before name
  const re2 = /<input\b[^>]*\bvalue\s*=\s*["']([^"']*)["'][^>]*\bname\s*=\s*["']?csrf["']?/gi;
  while ((m = re2.exec(body)) !== null) {
    return m[1];
  }
  return null;
}

function extractChallenge(body) {
  // form action /v2/challenges/{id} and input[name=challenge]
  const actionRe = /<form\b[^>]*\baction\s*=\s*["']([^"']*\/v2\/challenges\/[^"']+)["']/i;
  const am = body.match(actionRe);
  if (!am) return null;
  const action = am[1];
  const inputRe = /<input\b[^>]*\bname\s*=\s*["']?challenge["']?[^>]*>/gi;
  let m;
  while ((m = inputRe.exec(body)) !== null) {
    const vm = m[0].match(/\bvalue\s*=\s*["']([^"']*)["']/i);
    if (vm) return { action, challenge: vm[1] };
  }
  const re2 = /<input\b[^>]*\bvalue\s*=\s*["']([^"']*)["'][^>]*\bname\s*=\s*["']?challenge["']?/gi;
  while ((m = re2.exec(body)) !== null) {
    return { action, challenge: m[1] };
  }
  return null;
}

function login(user) {
  const j = jar();
  const formRes = http.get(`${BASE}/v2/login-form`, { jar: j, redirects: 0 });
  check(formRes, { 'login-form 200': (r) => r.status === 200 });
  const csrf = parseCsrfFromForm(formRes.body);
  if (!csrf) fail('no csrf in login form');

  const loginRes = http.post(
    `${BASE}/v2/login`,
    JSON.stringify({ username: user, password: 'bench', csrf }),
    { jar: j, redirects: 0, headers: { 'Content-Type': 'application/json' } }
  );

  let sessionCsrf = csrf;
  if (loginRes.status === 302) {
    const loc = loginRes.headers['Location'];
    if (loc) {
      const follow = http.get(loc.startsWith('http') ? loc : `${BASE}${loc}`, { jar: j, redirects: 0 });
      check(follow, { 'login redirect follow ok': (r) => r.status < 400 });
      try {
        const b = JSON.parse(follow.body);
        if (b.csrf) sessionCsrf = b.csrf;
      } catch (e) {}
    }
  } else {
    check(loginRes, { 'login 200': (r) => r.status === 200 });
    try {
      const b = JSON.parse(loginRes.body);
      if (b.csrf) sessionCsrf = b.csrf;
    } catch (e) {}
  }
  return { jar: j, csrf: sessionCsrf };
}

function getCatalog(j, csrf) {
  const res = http.get(`${BASE}/v2/catalog`, { jar: j });
  check(res, { 'catalog 200': (r) => r.status === 200 });
  let products = [];
  try {
    const b = JSON.parse(res.body);
    products = (b.data && b.data.products) || [];
  } catch (e) {}
  return products;
}

function getCatalogPage(j, csrf, reverse) {
  const products = [];
  let url = `${BASE}/v2/catalog/page`;
  let pages = 0;
  while (url && pages < 3) {
    const res = http.get(url, { jar: j });
    check(res, { 'catalog page 200': (r) => r.status === 200 });
    let b;
    try { b = JSON.parse(res.body); } catch (e) { break; }
    if (b.product) products.push(b.product);
    else if (b.data && b.data.product) products.push(b.data.product);
    const next = b.next;
    if (!next) break;
    url = next.startsWith('http') ? next : `${BASE}${next}`;
    pages++;
  }
  if (reverse) products.reverse();
  return products;
}

function pickVariant(products) {
  for (const p of products) {
    if (!p || !p.variants) continue;
    for (const v of p.variants) {
      if (v.in_stock) return { product_id: p.id, variant_id: v.id };
    }
  }
  return null;
}

function solveChallenge(j, csrf) {
  const formRes = http.get(`${BASE}/v2/challenge-form`, { jar: j });
  check(formRes, { 'challenge-form 200': (r) => r.status === 200 });
  const ch = extractChallenge(formRes.body);
  if (!ch) fail('no challenge extracted');
  const action = ch.action.startsWith('http') ? ch.action : `${BASE}${ch.action}`;
  const postRes = http.post(
    action,
    JSON.stringify({ challenge: ch.challenge }),
    { jar: j, redirects: 0, headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf } }
  );
  check(postRes, { 'challenge post 302': (r) => r.status === 302 });
  const loc = postRes.headers['Location'];
  if (!loc) fail('no challenge redirect');
  const follow = http.get(loc.startsWith('http') ? loc : `${BASE}${loc}`, { jar: j, redirects: 0 });
  check(follow, { 'challenge follow 200': (r) => r.status === 200 });
  let grant_id = null;
  let newCsrf = csrf;
  try {
    const b = JSON.parse(follow.body);
    grant_id = b.grant_id;
    if (b.csrf) newCsrf = b.csrf;
  } catch (e) {}
  if (!grant_id) fail('no grant_id');
  return { grant_id, csrf: newCsrf };
}

function createCart(j, csrf, product_id, variant_id, grant_id) {
  const payload = { product_id, variant_id };
  if (grant_id) payload.grant_id = grant_id;
  const res = http.post(`${BASE}/v2/carts`, JSON.stringify(payload), {
    jar: j,
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf },
  });
  check(res, { 'cart 201': (r) => r.status === 201 });
  let cart = null;
  try { cart = JSON.parse(res.body); } catch (e) {}
  if (!cart || !cart.id) fail('no cart id');
  return { id: cart.id, csrf: cart.csrf || csrf, etag: res.headers['ETag'] };
}

function patchCart(j, csrf, cartId, etag, quantity) {
  const payload = JSON.stringify({ quantity });
  let res = http.patch(`${BASE}/v2/carts/${cartId}`, payload, {
    jar: j,
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf, 'If-Match': etag || '' },
  });
  if (res.status === 412) {
    const re = http.get(`${BASE}/v2/carts/${cartId}`, { jar: j });
    const newEtag = re.headers['ETag'];
    res = http.patch(`${BASE}/v2/carts/${cartId}`, payload, {
      jar: j,
      headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf, 'If-Match': newEtag || '' },
    });
  }
  check(res, { 'cart patch ok': (r) => r.status === 200 || r.status === 204 });
  let newCsrf = csrf;
  try { const b = JSON.parse(res.body); if (b.csrf) newCsrf = b.csrf; } catch (e) {}
  return { csrf: newCsrf, etag: res.headers['ETag'] || etag };
}

function reserve(j, csrf, cartId) {
  const res = http.post(`${BASE}/v2/reservations`, JSON.stringify({ cart_id: cartId }), {
    jar: j,
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf },
  });
  check(res, { 'reservation 202': (r) => r.status === 202 });
  let b = {};
  try { b = JSON.parse(res.body); } catch (e) {}
  let newCsrf = b.csrf || csrf;
  const statusUrl = b.status_url;
  if (!statusUrl) fail('no status_url');
  let reservation_id = null;
  for (let i = 0; i < 5; i++) {
    const poll = http.get(statusUrl.startsWith('http') ? statusUrl : `${BASE}${statusUrl}`, { jar: j });
    let pb = {};
    try { pb = JSON.parse(poll.body); } catch (e) {}
    if (pb.csrf) newCsrf = pb.csrf;
    if (pb.status === 'ready') { reservation_id = pb.reservation_id; break; }
    if (pb.status === 'failed') break;
    // sleep at least 50ms
    const start = Date.now();
    while (Date.now() - start < 60) {}
  }
  return { reservation_id, csrf: newCsrf };
}

function placeOrder(j, csrf, cartId, reservation_id, etag) {
  const payload = { cart_id: cartId };
  if (reservation_id) payload.reservation_id = reservation_id;
  const headers = {
    'Content-Type': 'application/json',
    'X-CSRF-Token': csrf,
    'Idempotency-Key': `idem-${cartId}-${__VU}-${__ITER}`,
  };
  if (etag) headers['If-Match'] = etag;
  const res = http.post(`${BASE}/v2/orders`, JSON.stringify(payload), { jar: j, headers });
  businessResponses.add(1);
  let ok = false;
  let newCsrf = csrf;
  if (res.status === 201) {
    try {
      const b = JSON.parse(res.body);
      if (b.accepted === true && b.id) ok = true;
      if (b.csrf) newCsrf = b.csrf;
    } catch (e) {}
  } else if (res.status === 200) {
    try {
      const b = JSON.parse(res.body);
      if (b.accepted === false) {
        businessFailures.add(1);
      }
    } catch (e) {}
  } else if (res.status === 401) {
    // expected expiry path
  } else if (res.status >= 500) {
    unexpectedFailures.add(1);
  }
  check(res, { 'order accepted': () => ok });
  return { ok, csrf: newCsrf };
}

function doWork(j, csrf) {
  let attempts = 0;
  while (attempts < 5) {
    const res = http.post(`${BASE}/v2/work`, '{}', {
      jar: j,
      headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf },
    });
    businessResponses.add(1);
    if (res.status === 429) {
      const ra = parseInt(res.headers['Retry-After'] || '1', 10);
      const start = Date.now();
      while (Date.now() - start < ra * 1000) {}
      attempts++;
      continue;
    }
    if (res.status >= 500) unexpectedFailures.add(1);
    check(res, { 'work ok': (r) => r.status === 200 });
    return;
  }
}

export default function () {
  const userIdx = ((__VU - 1) % 16) + 1;
  const user = `bench-${userIdx}`;
  const profile = PROFILES[(__ITER) % PROFILES.length];

  group('journey', () => {
    const { jar: j, csrf: loginCsrf } = login(user);
    let csrf = loginCsrf;

    let products;
    if (profile.reverse_catalog) {
      products = getCatalogPage(j, csrf, true);
    } else {
      products = getCatalog(j, csrf);
    }
    const pick = pickVariant(products);
    if (!pick) fail('no in-stock variant');

    let grant_id = null;
    if (profile.require_challenge) {
      const ch = solveChallenge(j, csrf);
      grant_id = ch.grant_id;
      csrf = ch.csrf;
    }

    const cart = createCart(j, csrf, pick.product_id, pick.variant_id, grant_id);
    csrf = cart.csrf;

    const patched = patchCart(j, csrf, cart.id, cart.etag, 1);
    csrf = patched.csrf;

    const resv = reserve(j, csrf, cart.id);
    csrf = resv.csrf;

    if (resv.reservation_id) {
      placeOrder(j, csrf, cart.id, resv.reservation_id, patched.etag);
    } else {
      check(null, { 'reservation ready': () => false });
    }

    doWork(j, csrf);
  });
}
