import os
import re
import time
import json
from locust import HttpUser, task, between, LoadTestShape
from locust.exception import StopUser

BASE_URL = os.environ["BASE_URL"]


def _extract_csrf(html):
    # input[name=csrf] mixed with decoys/attribute variants
    m = re.search(r'<input[^>]*name=["\']csrf["\'][^>]*value=["\']([^"\']+)["\']', html)
    if not m:
        m = re.search(r'<input[^>]*value=["\']([^"\']+)["\'][^>]*name=["\']csrf["\']', html)
    return m.group(1) if m else None


def _extract_challenge(html):
    action = None
    m = re.search(r'<form[^>]*action=["\']([^"\']*?/v2/challenges/[^"\']+)["\']', html)
    if m:
        action = m.group(1)
    else:
        m = re.search(r'action=["\']([^"\']*?/v2/challenges/[^"\']+)["\']', html)
        if m:
            action = m.group(1)
    cm = re.search(r'<input[^>]*name=["\']challenge["\'][^>]*value=["\']([^"\']+)["\']', html)
    if not cm:
        cm = re.search(r'<input[^>]*value=["\']([^"\']+)["\'][^>]*name=["\']challenge["\']', html)
    challenge = cm.group(1) if cm else None
    return action, challenge


class ShopUser(HttpUser):
    host = BASE_URL
    wait_time = between(0.05, 0.15)

    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self.csrf = None
        self.username = None
        self.iterations_done = 0
        self.max_iterations = 2

    def on_start(self):
        # pick a bench account deterministically per user
        idx = (id(self) % 16) + 1
        self.username = "bench-%d" % idx

    def _login(self):
        with self.client.get("/v2/login-form", catch_response=True, allow_redirects=False) as r:
            if r.status_code != 200:
                r.failure("login-form status %s" % r.status_code)
                return False
            csrf = _extract_csrf(r.text)
            if not csrf:
                r.failure("no csrf in login form")
                return False
        with self.client.post(
            "/v2/login",
            json={"username": self.username, "password": "bench", "csrf": csrf},
            catch_response=True,
            allow_redirects=False,
        ) as r:
            if r.status_code == 302:
                loc = r.headers.get("Location")
                if not loc:
                    r.failure("302 without Location")
                    return False
                with self.client.get(loc, catch_response=True, allow_redirects=False) as r2:
                    if r2.status_code != 200:
                        r2.failure("login redirect status %s" % r2.status_code)
                        return False
                    try:
                        body = r2.json()
                    except Exception:
                        r2.failure("login redirect not json")
                        return False
                    self.csrf = body.get("csrf")
                    if not self.csrf:
                        r2.failure("no csrf after login")
                        return False
            elif r.status_code == 200:
                try:
                    body = r.json()
                except Exception:
                    r.failure("login not json")
                    return False
                self.csrf = body.get("csrf")
                if not self.csrf:
                    r.failure("no csrf after login")
                    return False
            else:
                r.failure("login status %s" % r.status_code)
                return False
        return True

    def _renew(self):
        with self.client.post(
            "/v2/session/renew",
            json={},
            headers={"X-CSRF-Token": self.csrf or ""},
            catch_response=True,
            allow_redirects=False,
        ) as r:
            if r.status_code == 200:
                try:
                    body = r.json()
                except Exception:
                    r.failure("renew not json")
                    return False
                if body.get("csrf"):
                    self.csrf = body["csrf"]
                return True
            r.failure("renew status %s" % r.status_code)
            return False

    def _recover_cart(self, cart_id):
        with self.client.post(
            "/v2/carts/%s/recover" % cart_id,
            json={},
            headers={"X-CSRF-Token": self.csrf or ""},
            catch_response=True,
            allow_redirects=False,
        ) as r:
            if r.status_code in (200, 201):
                try:
                    body = r.json()
                except Exception:
                    return True
                if body.get("csrf"):
                    self.csrf = body["csrf"]
                return True
            r.failure("recover status %s" % r.status_code)
            return False

    def _get_challenge(self):
        with self.client.get("/v2/challenge-form", catch_response=True, allow_redirects=False) as r:
            if r.status_code != 200:
                r.failure("challenge-form status %s" % r.status_code)
                return None
            action, challenge = _extract_challenge(r.text)
            if not action or not challenge:
                r.failure("challenge not extracted")
                return None
            return action, challenge

    def _solve_challenge(self):
        got = self._get_challenge()
        if not got:
            return None
        action, challenge = got
        with self.client.post(
            action,
            json={"challenge": challenge},
            headers={"X-CSRF-Token": self.csrf or ""},
            catch_response=True,
            allow_redirects=False,
        ) as r:
            if r.status_code == 302:
                loc = r.headers.get("Location")
                if not loc:
                    r.failure("challenge 302 no Location")
                    return None
                with self.client.get(loc, catch_response=True, allow_redirects=False) as r2:
                    if r2.status_code != 200:
                        r2.failure("challenge claim status %s" % r2.status_code)
                        return None
                    try:
                        body = r2.json()
                    except Exception:
                        r2.failure("claim not json")
                        return None
                    if body.get("csrf"):
                        self.csrf = body["csrf"]
                    grant = body.get("grant_id")
                    if not grant:
                        r2.failure("no grant_id")
                        return None
                    return grant
            elif r.status_code == 200:
                try:
                    body = r.json()
                except Exception:
                    r.failure("challenge not json")
                    return None
                if body.get("csrf"):
                    self.csrf = body["csrf"]
                grant = body.get("grant_id")
                if not grant:
                    r.failure("no grant_id")
                    return None
                return grant
            else:
                r.failure("challenge status %s" % r.status_code)
                return None

    def _pick_product(self):
        # traverse catalog pages up to 3
        url = "/v2/catalog/page"
        for _ in range(3):
            with self.client.get(url, catch_response=True, allow_redirects=False) as r:
                if r.status_code != 200:
                    r.failure("catalog page status %s" % r.status_code)
                    return None
                try:
                    body = r.json()
                except Exception:
                    r.failure("catalog page not json")
                    return None
                prod = body.get("product") or body.get("data", {}).get("product")
                if prod is None and isinstance(body.get("data"), dict):
                    prods = body["data"].get("products")
                    if prods:
                        prod = prods[0]
                if prod:
                    variants = prod.get("variants") or []
                    for v in variants:
                        if v.get("in_stock"):
                            return prod.get("id"), v.get("id")
                nxt = body.get("next")
                if not nxt:
                    break
                url = nxt
        return None

    def _create_cart(self, product_id, variant_id, grant_id):
        payload = {"product_id": product_id, "variant_id": variant_id}
        if grant_id:
            payload["grant_id"] = grant_id
        with self.client.post(
            "/v2/carts",
            json=payload,
            headers={"X-CSRF-Token": self.csrf or ""},
            catch_response=True,
            allow_redirects=False,
        ) as r:
            if r.status_code == 201:
                try:
                    body = r.json()
                except Exception:
                    r.failure("cart not json")
                    return None
                if body.get("csrf"):
                    self.csrf = body["csrf"]
                cid = body.get("id")
                if not cid:
                    r.failure("no cart id")
                    return None
                return cid
            elif r.status_code == 401:
                try:
                    body = r.json()
                except Exception:
                    body = {}
                err = body.get("error")
                if err == "expired":
                    if self._renew():
                        return self._create_cart(product_id, variant_id, grant_id)
                r.failure("cart create 401 %s" % err)
                return None
            else:
                r.failure("cart create status %s" % r.status_code)
                return None

    def _patch_quantity(self, cart_id, qty):
        # read etag
        with self.client.get("/v2/carts/%s" % cart_id, catch_response=True, allow_redirects=False) as r:
            if r.status_code != 200:
                r.failure("cart get status %s" % r.status_code)
                return False
            etag = r.headers.get("ETag")
        if not etag:
            return False
        for attempt in range(2):
            with self.client.patch(
                "/v2/carts/%s" % cart_id,
                json={"quantity": qty},
                headers={"X-CSRF-Token": self.csrf or "", "If-Match": etag},
                catch_response=True,
                allow_redirects=False,
            ) as r:
                if r.status_code in (200, 204):
                    try:
                        body = r.json()
                        if body.get("csrf"):
                            self.csrf = body["csrf"]
                    except Exception:
                        pass
                    return True
                elif r.status_code == 412:
                    with self.client.get("/v2/carts/%s" % cart_id, catch_response=True, allow_redirects=False) as r2:
                        if r2.status_code != 200:
                            r2.failure("cart re-read status %s" % r2.status_code)
                            return False
                        etag = r2.headers.get("ETag")
                    continue
                elif r.status_code == 401:
                    try:
                        body = r.json()
                    except Exception:
                        body = {}
                    if body.get("error") == "expired":
                        if self._renew():
                            self._recover_cart(cart_id)
                            continue
                    r.failure("patch 401")
                    return False
                else:
                    r.failure("patch status %s" % r.status_code)
                    return False
        return False

    def _reserve(self, cart_id):
        with self.client.post(
            "/v2/reservations",
            json={"cart_id": cart_id},
            headers={"X-CSRF-Token": self.csrf or ""},
            catch_response=True,
            allow_redirects=False,
        ) as r:
            if r.status_code != 202:
                r.failure("reservation status %s" % r.status_code)
                return None
            try:
                body = r.json()
            except Exception:
                r.failure("reservation not json")
                return None
            if body.get("csrf"):
                self.csrf = body["csrf"]
            status_url = body.get("status_url")
            if not status_url:
                r.failure("no status_url")
                return None
        for _ in range(5):
            time.sleep(0.06)
            with self.client.get(status_url, catch_response=True, allow_redirects=False) as r:
                if r.status_code != 200:
                    r.failure("status poll %s" % r.status_code)
                    return None
                try:
                    body = r.json()
                except Exception:
                    r.failure("status not json")
                    return None
                st = body.get("status")
                if st == "ready":
                    rid = body.get("reservation_id")
                    if not rid:
                        r.failure("ready without reservation_id")
                        return None
                    return rid
                elif st in ("pending",):
                    continue
                else:
                    r.failure("reservation status %s" % st)
                    return None
        return None

    def _order(self, cart_id, reservation_id):
        headers = {"X-CSRF-Token": self.csrf or "", "Idempotency-Key": "cart-%s" % cart_id}
        with self.client.get("/v2/carts/%s" % cart_id, catch_response=True, allow_redirects=False) as r:
            if r.status_code == 200:
                etag = r.headers.get("ETag")
                if etag:
                    headers["If-Match"] = etag
        payload = {"cart_id": cart_id}
        if reservation_id:
            payload["reservation_id"] = reservation_id
        with self.client.post(
            "/v2/orders",
            json=payload,
            headers=headers,
            catch_response=True,
            allow_redirects=False,
        ) as r:
            if r.status_code == 201:
                try:
                    body = r.json()
                except Exception:
                    r.failure("order not json")
                    return False
                if not body.get("accepted"):
                    r.failure("order not accepted")
                    return False
                if body.get("csrf"):
                    self.csrf = body["csrf"]
                return True
            elif r.status_code == 200:
                try:
                    body = r.json()
                except Exception:
                    body = {}
                if body.get("accepted") is False:
                    r.failure("order business failure")
                    return False
                r.failure("order 200 unexpected")
                return False
            elif r.status_code == 401:
                try:
                    body = r.json()
                except Exception:
                    body = {}
                if body.get("error") == "expired":
                    if self._renew():
                        self._recover_cart(cart_id)
                        return self._order(cart_id, reservation_id)
                r.failure("order 401")
                return False
            else:
                r.failure("order status %s" % r.status_code)
                return False

    def _work(self):
        retries = 0
        while retries <= 4:
            with self.client.post(
                "/v2/work",
                json={},
                headers={"X-CSRF-Token": self.csrf or ""},
                catch_response=True,
                allow_redirects=False,
            ) as r:
                if r.status_code == 200:
                    try:
                        body = r.json()
                    except Exception:
                        r.failure("work not json")
                        return
                    if not body.get("ok"):
                        r.failure("work not ok")
                    return
                elif r.status_code == 429:
                    ra = r.headers.get("Retry-After", "1")
                    try:
                        delay = float(ra)
                    except Exception:
                        delay = 1.0
                    time.sleep(delay)
                    retries += 1
                    continue
                elif r.status_code == 500:
                    r.failure("work 500")
                    return
                else:
                    r.failure("work status %s" % r.status_code)
                    return

    @task
    def journey(self):
        if self.iterations_done >= self.max_iterations:
            raise StopUser()
        self.iterations_done += 1

        if not self._login():
            raise StopUser()

        grant = self._solve_challenge()
        if not grant:
            raise StopUser()

        picked = self._pick_product()
        if not picked:
            raise StopUser()
        product_id, variant_id = picked

        cart_id = self._create_cart(product_id, variant_id, grant)
        if not cart_id:
            raise StopUser()

        if not self._patch_quantity(cart_id, 1):
            raise StopUser()

        rid = self._reserve(cart_id)
        if not rid:
            raise StopUser()

        if not self._order(cart_id, rid):
            raise StopUser()

        self._work()


