function parseCookies(res) {
  const jar = {};
  const setCookie = res.headers['Set-Cookie'];
  if (setCookie) {
    const arr = Array.isArray(setCookie) ? setCookie : [setCookie];
    for (const c of arr) {
      const kv = c.split(';')[0];
      const idx = kv.indexOf('=');
      if (idx > 0) jar[kv.substring(0, idx).trim()] = kv.substring(idx + 1).trim();
    }
  }
  return jar;
}

function mergeCookies(jar, res) {
  const nc = parseCookies(res);
  for (const k in nc) jar[k] = nc[k];
}

function cookieHeader(jar) {
  return Object.keys(jar).map(k => `${k}=${jar[k]}`).join('; ');
}

function extractCsrf(html) {
  // input[name=csrf] with mixed attribute variants
  const re = /<input\b[^>]*>/gi;
  let m;
  while ((m = re.exec(html)) !== null) {
    const tag = m[0];
    if (/name\s*=\s*["']?csrf["']?/i.test(tag)) {
      const vm = tag.match(/value\s*=\s*["']([^"']*)["']/i);
      if (vm) return vm[1];
    }
  }
  return null;
}

function extractChallengeForm(html) {
  const actionM = html.match(/<form\b[^>]*action\s*=\s*["']([^"']*\/v2\/challenges\/[^"']*)["']/i);
  const inputM = html.match(/<input\b[^>]*name\s*=\s*["']?challenge["']?[^>]*>/i);
  let challengeVal = null;
  if (inputM) {
    const vm = inputM[0].match(/value\s*=\s*["']([^"']*)["']/i);
    if (vm) challengeVal = vm[1];
  }
  return { action: actionM ? actionM[1] : null, challenge: challengeVal };
}

function absUrl(u) {
  if (!u) return null;
  if (u.startsWith('http')) return u;
  return BASE + (u.startsWith('/') ? u : '/' + u);
}

function doLogin(username, password) {
  const jar = {};
  const formRes = http.get(`${BASE}/v2/login-form`, { redirects: 0 });
  mergeCookies(jar, formRes);
  const csrf = extractCsrf(formRes.body);
  check(formRes, { 'login-form 200': r => r.status === 200 });
  check(csrf, { 'login csrf present': c => !!c });

  const loginRes = http.post(`${BASE}/v2/login`, JSON.stringify({ username, password, csrf }), {
    headers: { 'Content-Type': 'application/json', 'Cookie': cookieHeader(jar) },
    redirects: 0,
  });
  mergeCookies(jar, loginRes);

  let body = null;
  try { body = JSON.parse(loginRes.body); } catch (e) {}

  if (loginRes.status === 302) {
    const loc = loginRes.headers['Location'];
    if (loc) {
      const followRes = http.get(absUrl(loc), { headers: { 'Cookie': cookieHeader(jar) }, redirects: 0 });
      mergeCookies(jar, followRes);
      try { body = JSON.parse(followRes.body); } catch (e) {}
    }
  }

  check(loginRes, { 'login status ok': r => r.status === 200 || r.status === 302 });
  check(body, { 'login body has csrf': b => b && b.csrf });
  check(body, { 'login body has user': b => b && b.user });

  return { jar, csrf: body ? body.csrf : null, user: body ? body.user : null };
}

function renewSession(jar, csrf) {
  const res = http.post(`${BASE}/v2/session/renew`, JSON.stringify({}), {
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf, 'Cookie': cookieHeader(jar) },
    redirects: 0,
  });
  mergeCookies(jar, res);
  let body = null;
  try { body = JSON.parse(res.body); } catch (e) {}
  return { res, body };
}

function recoverCart(jar, csrf, cartId) {
  const res = http.post(`${BASE}/v2/carts/${cartId}/recover`, JSON.stringify({}), {
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf, 'Cookie': cookieHeader(jar) },
    redirects: 0,
  });
  mergeCookies(jar, res);
  let body = null;
  try { body = JSON.parse(res.body); } catch (e) {}
  return { res, body };
}

function getCatalog(jar) {
  const res = http.get(`${BASE}/v2/catalog`, { headers: { 'Cookie': cookieHeader(jar) }, redirects: 0 });
  mergeCookies(jar, res);
  let body = null;
  try { body = JSON.parse(res.body); } catch (e) {}
  return { res, body };
}

function getCatalogPage(jar, url) {
  const res = http.get(absUrl(url), { headers: { 'Cookie': cookieHeader(jar) }, redirects: 0 });
  mergeCookies(jar, res);
  let body = null;
  try { body = JSON.parse(res.body); } catch (e) {}
  return { res, body };
}

function pickProduct(catalogBody) {
  if (!catalogBody || !catalogBody.data || !catalogBody.data.products) return null;
  for (const p of catalogBody.data.products) {
    if (p.variants) {
      for (const v of p.variants) {
        if (v.in_stock) return { product_id: p.id, variant_id: v.id };
      }
    }
  }
  return null;
}

function solveChallenge(jar, csrf) {
  const formRes = http.get(`${BASE}/v2/challenge-form`, { headers: { 'Cookie': cookieHeader(jar) }, redirects: 0 });
  mergeCookies(jar, formRes);
  const { action, challenge } = extractChallengeForm(formRes.body);
  check(action, { 'challenge action present': a => !!a });
  check(challenge, { 'challenge value present': c => !!c });
  if (!action || !challenge) return { grant_id: null, csrf };

  const postRes = http.post(absUrl(action), JSON.stringify({ challenge }), {
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf, 'Cookie': cookieHeader(jar) },
    redirects: 0,
  });
  mergeCookies(jar, postRes);
  let loc = postRes.headers['Location'];
  let body = null;
  if (loc) {
    const followRes = http.get(absUrl(loc), { headers: { 'Cookie': cookieHeader(jar) }, redirects: 0 });
    mergeCookies(jar, followRes);
    try { body = JSON.parse(followRes.body); } catch (e) {}
  } else {
    try { body = JSON.parse(postRes.body); } catch (e) {}
  }
  return { grant_id: body ? body.grant_id : null, csrf: body && body.csrf ? body.csrf : csrf };
}

function createCart(jar, csrf, product_id, variant_id, grant_id) {
  const payload = { product_id, variant_id };
  if (grant_id) payload.grant_id = grant_id;
  const res = http.post(`${BASE}/v2/carts`, JSON.stringify(payload), {
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf, 'Cookie': cookieHeader(jar) },
    redirects: 0,
  });
  mergeCookies(jar, res);
  let body = null;
  try { body = JSON.parse(res.body); } catch (e) {}
  return { res, body, etag: res.headers['Etag'] || res.headers['ETag'] };
}

function patchCart(jar, csrf, cartId, etag, quantity) {
  const res = http.patch(`${BASE}/v2/carts/${cartId}`, JSON.stringify({ quantity }), {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': csrf,
      'Cookie': cookieHeader(jar),
      'If-Match': etag || '',
    },
    redirects: 0,
  });
  mergeCookies(jar, res);
  let body = null;
  try { body = JSON.parse(res.body); } catch (e) {}
  return { res, body, etag: res.headers['Etag'] || res.headers['ETag'] };
}

function getCart(jar, cartId) {
  const res = http.get(`${BASE}/v2/carts/${cartId}`, { headers: { 'Cookie': cookieHeader(jar) }, redirects: 0 });
  mergeCookies(jar, res);
  let body = null;
  try { body = JSON.parse(res.body); } catch (e) {}
  return { res, body, etag: res.headers['Etag'] || res.headers['ETag'] };
}

function createReservation(jar, csrf, cartId) {
  const res = http.post(`${BASE}/v2/reservations`, JSON.stringify({ cart_id: cartId }), {
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf, 'Cookie': cookieHeader(jar) },
    redirects: 0,
  });
  mergeCookies(jar, res);
  let body = null;
  try { body = JSON.parse(res.body); } catch (e) {}
  return { res, body };
}

function pollReservation(jar, statusUrl) {
  let last = null;
  for (let i = 0; i < 5; i++) {
    sleep(0.06);
    const res = http.get(absUrl(statusUrl), { headers: { 'Cookie': cookieHeader(jar) }, redirects: 0 });
    mergeCookies(jar, res);
    let body = null;
    try { body = JSON.parse(res.body); } catch (e) {}
    last = { res, body };
    if (body && (body.status === 'ready' || body.status === 'failed')) return last;
  }
  return last;
}

function placeOrder(jar, csrf, cartId, reservationId, etag, idemKey) {
  const payload = { cart_id: cartId };
  if (reservationId) payload.reservation_id = reservationId;
  const headers = {
    'Content-Type': 'application/json',
    'X-CSRF-Token': csrf,
    'Cookie': cookieHeader(jar),
    'Idempotency-Key': idemKey,
  };
  if (etag) headers['If-Match'] = etag;
  const res = http.post(`${BASE}/v2/orders`, JSON.stringify(payload), { headers, redirects: 0 });
  mergeCookies(jar, res);
  let body = null;
  try { body = JSON.parse(res.body); } catch (e) {}
  return { res, body };
}

function doWork(jar, csrf) {
  let retries = 0;
  while (retries <= 4) {
    const res = http.post(`${BASE}/v2/work`, JSON.stringify({}), {
      headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf, 'Cookie': cookieHeader(jar) },
      redirects: 0,
    });
    mergeCookies(jar, res);
    if (res.status === 429) {
      const ra = parseInt(res.headers['Retry-After'] || '1', 10);
      sleep(ra);
      retries++;
      continue;
    }
    return res;
  }
  return null;
}

function isExpired(res) {
  if (res.status !== 401) return false;
  try {
    const b = JSON.parse(res.body);
    return b && b.error === 'expired';
  } catch (e) { return false; }
}

function isRevoked(res) {
  if (res.status !== 401) return false;
  try {
    const b = JSON.parse(res.body);
    return b && b.error === 'session';
  } catch (e) { return false; }
}

export default function () {
  const vu = exec.vu.idInTest;
  const idx = (vu - 1) % accounts.length;
  const acct = accounts[idx];
  const username = acct.username;
  const password = acct.password;
  const quantity = acct.quantity;
  const delay = acct.delay || 0;

  // Initial login
  let session = doLogin(username, password);
  let jar = session.jar;
  let csrf = session.csrf;

  // Synchronize after initial logins: barrier via sleep
  sleep(0.5);

  // Detect revocation: try a work call
  let workRes = doWork(jar, csrf);
  let revoked = false;
  if (workRes && isRevoked(workRes)) {
    revoked = true;
  } else if (workRes && isExpired(workRes)) {
    // try renew
    const r = renewSession(jar, csrf);
    if (r.body && r.body.csrf) csrf = r.body.csrf;
    if (r.res.status === 401) revoked = true;
  }

  check(revoked, { 'detected revocation': v => v === true });

  // Recover deliberately: fresh login
  if (revoked) {
    session = doLogin(username, password);
    jar = session.jar;
    csrf = session.csrf;
  }

  // Per-VU delay stagger
  if (delay > 0) sleep(delay / 1000);

  // Fresh journey: catalog
  let catalog = getCatalog(jar);
  let product = pickProduct(catalog.body);
  let pages = 0;
  let next = catalog.body ? catalog.body.next : null;
  while (!product && next && pages < 3) {
    const page = getCatalogPage(jar, next);
    product = pickProduct(page.body);
    next = page.body ? page.body.next : null;
    pages++;
  }
  check(product, { 'found in-stock product': p => !!p });
  if (!product) return;

  // Challenge
  const ch = solveChallenge(jar, csrf);
  csrf = ch.csrf;
  const grant_id = ch.grant_id;

  // Create cart
  let cart = createCart(jar, csrf, product.product_id, product.variant_id, grant_id);
  if (cart.body && cart.body.csrf) csrf = cart.body.csrf;
  check(cart.res, { 'cart created 201': r => r.status === 201 });
  check(cart.body, { 'cart has id': b => b && b.id });
  if (!cart.body || !cart.body.id) return;
  const cartId = cart.body.id;
  let etag = cart.etag;

  // Patch quantity
  let patch = patchCart(jar, csrf, cartId, etag, quantity);
  if (patch.res.status === 412) {
    const reread = getCart(jar, cartId);
    etag = reread.etag;
    patch = patchCart(jar, csrf, cartId, etag, quantity);
  }
  if (patch.body && patch.body.csrf) csrf = patch.body.csrf;
  if (patch.etag) etag = patch.etag;
  check(patch.res, { 'patch ok': r => r.status === 200 || r.status === 204 });

  // Reservation
  let resv = createReservation(jar, csrf, cartId);
  if (resv.body && resv.body.csrf) csrf = resv.body.csrf;
  check(resv.res, { 'reservation 202': r => r.status === 202 });
  let reservationId = null;
  if (resv.body && resv.body.status_url) {
    const polled = pollReservation(jar, resv.body.status_url);
    if (polled && polled.body && polled.body.status === 'ready') {
      reservationId = polled.body.reservation_id;
    }
    check(polled && polled.body && polled.body.status === 'ready', { 'reservation ready': v => v === true });
  }

  // Order
  const idemKey = `cart-${cartId}-${vu}-${Date.now()}`;
  let order = placeOrder(jar, csrf, cartId, reservationId, etag, idemKey);
  if (order.body && order.body.csrf) csrf = order.body.csrf;

  // Handle expiry/revocation on order
  if (isExpired(order.res)) {
    const r = renewSession(jar, csrf);
    if (r.body && r.body.csrf) csrf = r.body.csrf;
    if (r.res.status !== 401) {
      const rec = recoverCart(jar, csrf, cartId);
      if (rec.body && rec.body.csrf) csrf = rec.body.csrf;
      order = placeOrder(jar, csrf, cartId, reservationId, etag, idemKey);
      if (order.body && order.body.csrf) csrf = order.body.csrf;
    }
  } else if (isRevoked(order.res)) {
    session = doLogin(username, password);
    jar = session.jar;
    csrf = session.csrf;
    const rec = recoverCart(jar, csrf, cartId);
    if (rec.body && rec.body.csrf) csrf = rec.body.csrf;
    order = placeOrder(jar, csrf, cartId, reservationId, etag, idemKey);
    if (order.body && order.body.csrf) csrf = order.body.csrf;
  }

  check(order.res, { 'order 201': r => r.status === 201 });
  check(order.body, { 'order accepted': b => b && b.accepted === true });
  check(order.body, { 'order has id': b => b && b.id });
}
