                "password": row["password"],
                "quantity": int(row.get("quantity", 1)),
                "delay": float(row.get("delay", 0)) / 1000.0,
            })
    except Exception:
        for name in ("account-1.csv", "account-2.csv"):
            try:
                with open(os.path.join(FIXTURES, name), "r") as f:
                    for row in csv.DictReader(f):
                        accounts.append({
                            "username": row["username"],
                            "password": row["password"],
                            "quantity": int(row.get("quantity", 1)),
                            "delay": float(row.get("delay", 0)) / 1000.0,
                        })
            except Exception:
                pass
    if not accounts:
        accounts = [{"username": "bench", "password": "bench", "quantity": 2, "delay": 0.0}]
    return accounts


ACCOUNTS = _load_accounts()


def _extract_csrf(html):
    # input[name=csrf] with attribute variants / decoys
    if not html:
        return None
    # find input tags
    for m in re.finditer(r"<input\b[^>]*>", html, re.IGNORECASE):
        tag = m.group(0)
        if re.search(r'name\s*=\s*["\']?csrf["\']?', tag, re.IGNORECASE):
            vm = re.search(r'value\s*=\s*["\']([^"\']*)["\']', tag, re.IGNORECASE)
            if vm:
                return vm.group(1)
    return None


def _extract_challenge(html):
    if not html:
        return None, None
    action = None
    am = re.search(r'<form\b[^>]*action\s*=\s*["\']([^"\']+)["\']', html, re.IGNORECASE)
    if am:
        action = am.group(1)
    token = None
    for m in re.finditer(r"<input\b[^>]*>", html, re.IGNORECASE):
        tag = m.group(0)
        if re.search(r'name\s*=\s*["\']?challenge["\']?', tag, re.IGNORECASE):
            vm = re.search(r'value\s*=\s*["\']([^"\']*)["\']', tag, re.IGNORECASE)
            if vm:
                token = vm.group(1)
                break
    return action, token


class ShopUser(HttpUser):
    host = BASE_URL
    wait_time = between(0.05, 0.15)

    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self.account = None
        self.csrf = None
        self.user_info = None
        self.iterations_done = 0
        self.target_iterations = 1
        self.delay = 0.0
        self._assigned = False

    def on_start(self):
        # Assign account deterministically by index
        idx = getattr(self, "index", None)
        if idx is None:
            idx = random.randrange(len(ACCOUNTS))
        self.account = ACCOUNTS[idx % len(ACCOUNTS)]
        self.target_iterations = 1
        self.delay = self.account.get("delay", 0.0)
        self._assigned = True

    # ---------- auth helpers ----------
    def _get_login_form(self):
        with self.client.get("/v2/login-form", catch_response=True, allow_redirects=False) as r:
            if r.status_code != 200:
                r.failure(f"login-form status {r.status_code}")
                return None
            csrf = _extract_csrf(r.text)
            if not csrf:
                r.failure("no csrf in login form")
                return None
            return csrf

    def _login(self):
        csrf = self._get_login_form()
        if not csrf:
            return False
        payload = {
            "username": self.account["username"],
            "password": self.account["password"],
            "csrf": csrf,
        }
        with self.client.post("/v2/login", json=payload, catch_response=True,
                              allow_redirects=False) as r:
            if r.status_code == 302:
                loc = r.headers.get("Location")
                if loc:
                    with self.client.get(loc, catch_response=True, allow_redirects=False) as r2:
                        if r2.status_code not in (200, 201):
                            r2.failure(f"login redirect status {r2.status_code}")
                            return False
                        try:
                            body = r2.json()
                        except Exception:
                            body = {}
                        if body.get("csrf"):
                            self.csrf = body["csrf"]
                        if body.get("user"):
                            self.user_info = body["user"]
                        return True
                r.failure("302 without Location")
                return False
            if r.status_code in (200, 201):
                try:
                    body = r.json()
                except Exception:
                    body = {}
                if body.get("csrf"):
                    self.csrf = body["csrf"]
                if body.get("user"):
                    self.user_info = body["user"]
                return True
            r.failure(f"login status {r.status_code}")
            return False

    def _renew(self):
        headers = {"X-CSRF-Token": self.csrf or ""}
        with self.client.post("/v2/session/renew", json={}, headers=headers,
                              catch_response=True, allow_redirects=False) as r:
            if r.status_code in (200, 201):
                try:
                    body = r.json()
                except Exception:
                    body = {}
                if body.get("csrf"):
                    self.csrf = body["csrf"]
                return True
            return False

    def _recover_cart(self, cart_id):
        headers = {"X-CSRF-Token": self.csrf or ""}
        with self.client.post(f"/v2/carts/{cart_id}/recover", json={}, headers=headers,
                              catch_response=True, allow_redirects=False) as r:
            if r.status_code in (200, 201):
                try:
                    body = r.json()
                except Exception:
                    body = {}
                if body.get("csrf"):
                    self.csrf = body["csrf"]
                return True
            return False

    def _handle_401(self, r, cart_id=None):
        """Return True if recovered (caller should retry once)."""
        try:
            body = r.json()
        except Exception:
            body = {}
        err = body.get("error")
        if err == "expired":
            if self._renew():
                if cart_id:
                    self._recover_cart(cart_id)
                return True
            return False
        if err == "session":
            # revoked: renew may fail; fresh login
            if self._renew():
                if cart_id:
                    self._recover_cart(cart_id)
                return True
            if self._login():
                if cart_id:
                    self._recover_cart(cart_id)
                return True
            return False
        # denied or other: not expiry
        return False

    # ---------- catalog ----------
    def _get_catalog_products(self):
        products = []
        with self.client.get("/v2/catalog", catch_response=True, allow_redirects=False) as r:
            if r.status_code != 200:
                r.failure(f"catalog status {r.status_code}")
                return products
            try:
                body = r.json()
            except Exception:
                r.failure("catalog not json")
                return products
            data = body.get("data", {})
            for p in data.get("products", []):
                products.append(p)
        # traverse pages up to 3
        next_url = None
        try:
            next_url = body.get("next")
        except Exception:
            next_url = None
        pages = 0
        while next_url and pages < 3:
            pages += 1
            with self.client.get(next_url, catch_response=True, allow_redirects=False) as r:
                if r.status_code != 200:
                    r.failure(f"catalog page status {r.status_code}")
                    break
                try:
                    body = r.json()
                except Exception:
                    r.failure("catalog page not json")
                    break
                # page returns one product plus next
                prod = body.get("product") or body.get("data", {}).get("product")
                if prod:
                    products.append(prod)
                else:
                    data = body.get("data", {})
                    for p in data.get("products", []):
                        products.append(p)
                next_url = body.get("next")
        return products

    def _pick_variant(self, products):
        for p in products:
            variants = p.get("variants") or []
            for v in variants:
                if v.get("in_stock"):
                    return p.get("id"), v.get("id")
        return None, None

    # ---------- challenge ----------
    def _solve_challenge(self):
        with self.client.get("/v2/challenge-form", catch_response=True, allow_redirects=False) as r:
            if r.status_code != 200:
                r.failure(f"challenge-form status {r.status_code}")
                return None
            action, token = _extract_challenge(r.text)
            if not action or not token:
                r.failure("challenge form parse failed")
                return None
        headers = {"X-CSRF-Token": self.csrf or ""}
        with self.client.post(action, json={"challenge": token}, headers=headers,
                              catch_response=True, allow_redirects=False) as r:
            if r.status_code == 302:
                loc = r.headers.get("Location")
                if not loc:
                    r.failure("challenge 302 no Location")
                    return None
                with self.client.get(loc, catch_response=True, allow_redirects=False) as r2:
                    if r2.status_code not in (200, 201):
                        r2.failure(f"challenge redirect status {r2.status_code}")
                        return None
                    try:
                        body = r2.json()
                    except Exception:
                        body = {}
                    if body.get("csrf"):
                        self.csrf = body["csrf"]
                    return body.get("grant_id")
            if r.status_code in (200, 201):
                try:
                    body = r.json()
                except Exception:
                    body = {}
                if body.get("csrf"):
                    self.csrf = body["csrf"]
                return body.get("grant_id")
            r.failure(f"challenge post status {r.status_code}")
            return None

    # ---------- cart ----------
    def _create_cart(self, product_id, variant_id, grant_id=None):
        payload = {"product_id": product_id, "variant_id": variant_id}
        if grant_id:
            payload["grant_id"] = grant_id
        headers = {"X-CSRF-Token": self.csrf or ""}
        with self.client.post("/v2/carts", json=payload, headers=headers,
                              catch_response=True, allow_redirects=False) as r:
            if r.status_code == 401:
                if self._handle_401(r):
                    headers["X-CSRF-Token"] = self.csrf or ""
                    with self.client.post("/v2/carts", json=payload, headers=headers,
                                          catch_response=True, allow_redirects=False) as r2:
                        if r2.status_code == 201:
                            try:
                                body = r2.json()
                            except Exception:
                                body = {}
                            if body.get("csrf"):
                                self.csrf = body["csrf"]
                            return body.get("id"), r2.headers.get("ETag")
                        r2.failure(f"cart create retry status {r2.status_code}")
                        return None, None
                r.failure("cart create 401 unrecovered")
                return None, None
            if r.status_code != 201:
                r.failure(f"cart create status {r.status_code}")
                return None, None
            try:
                body = r.json()
            except Exception:
                body = {}
            if body.get("csrf"):
                self.csrf = body["csrf"]
            return body.get("id"), r.headers.get("ETag")

    def _patch_quantity(self, cart_id, etag, quantity):
        headers = {"X-CSRF-Token": self.csrf or "", "If-Match": etag or ""}
        payload = {"quantity": quantity}
        with self.client.patch(f"/v2/carts/{cart_id}", json=payload, headers=headers,
                               catch_response=True, allow_redirects=False) as r:
            if r.status_code == 412:
                # re-read and retry same payload once
                with self.client.get(f"/v2/carts/{cart_id}", catch_response=True,
                                     allow_redirects=False) as rg:
                    if rg.status_code != 200:
                        rg.failure(f"cart re-read status {rg.status_code}")
                        return False
                    new_etag = rg.headers.get("ETag")
                headers["If-Match"] = new_etag or ""
                with self.client.patch(f"/v2/carts/{cart_id}", json=payload, headers=headers,
                                       catch_response=True, allow_redirects=False) as r2:
                    if r2.status_code in (200, 204):
                        try:
                            body = r2.json()
                        except Exception:
                            body = {}
                        if body.get("csrf"):
                            self.csrf = body["csrf"]
                        return True
                    r2.failure(f"cart patch retry status {r2.status_code}")
                    return False
            if r.status_code == 401:
                if self._handle_401(r, cart_id):
                    headers["X-CSRF-Token"] = self.csrf or ""
                    with self.client.patch(f"/v2/carts/{cart_id}", json=payload, headers=headers,
                                           catch_response=True, allow_redirects=False) as r2:
                        if r2.status_code in (200, 204):
                            try:
                                body = r2.json()
                            except Exception:
                                body = {}
                            if body.get("csrf"):
                                self.csrf = body["csrf"]
                            return True
                        r2.failure(f"cart patch retry status {r2.status_code}")
                        return False
                r.failure("cart patch 401 unrecovered")
                return False
            if r.status_code in (200, 204):
                try:
                    body = r.json()
                except Exception:
                    body = {}
                if body.get("csrf"):
                    self.csrf = body["csrf"]
                return True
            r.failure(f"cart patch status {r.status_code}")
            return False

    # ---------- reservation ----------
    def _reserve(self, cart_id):
        headers = {"X-CSRF-Token": self.csrf or ""}
        with self.client.post("/v2/reservations", json={"cart_id": cart_id}, headers=headers,
                              catch_response=True, allow_redirects=False) as r:
            if r.status_code == 401:
                if self._handle_401(r, cart_id):
                    headers["X-CSRF-Token"] = self.csrf or ""
                    with self.client.post("/v2/reservations", json={"cart_id": cart_id},
                                          headers=headers, catch_response=True,
                                          allow_redirects=False) as r2:
                        if r2.status_code != 202:
                            r2.failure(f"reservation retry status {r2.status_code}")
                            return None
                        try:
                            body = r2.json()
                        except Exception:
                            body = {}
                        if body.get("csrf"):
                            self.csrf = body["csrf"]
                        status_url = body.get("status_url")
                        return self._poll_reservation(status_url)
                r.failure("reservation 401 unrecovered")
                return None
            if r.status_code != 202:
                r.failure(f"reservation status {r.status_code}")
                return None
            try:
                body = r.json()
            except Exception:
                body = {}
            if body.get("csrf"):
                self.csrf = body["csrf"]
            status_url = body.get("status_url")
            return self._poll_reservation(status_url)

    def _poll_reservation(self, status_url):
        if not status_url:
            return None
        for i in range(5):
            if i > 0:
                time.sleep(0.06)
            with self.client.get(status_url, catch_response=True, allow_redirects=False) as r:
                if r.status_code != 200:
                    r.failure(f"reservation poll status {r.status_code}")
                    return None
                try:
                    body = r.json()
                except Exception:
                    r.failure("reservation poll not json")
                    return None
                status = body.get("status")
                if status == "ready":
                    return body.get("reservation_id")
                if status in ("pending",):
                    continue
                if status in ("failed",):
                    return None
        return None

    # ---------- order ----------
    def _checkout(self, cart_id, reservation_id, idem_key):
        headers = {"X-CSRF-Token": self.csrf or "", "Idempotency-Key": idem_key}
        payload = {"cart_id": cart_id}
        if reservation_id:
            payload["reservation_id"] = reservation_id
        with self.client.post("/v2/orders", json=payload, headers=headers,
                              catch_response=True, allow_redirects=False) as r:
            if r.status_code == 401:
                if self._handle_401(r, cart_id):
                    headers["X-CSRF-Token"] = self.csrf or ""
                    with self.client.post("/v2/orders", json=payload, headers=headers,
                                          catch_response=True, allow_redirects=False) as r2:
                        return self._checkout_result(r2)
                r.failure("order 401 unrecovered")
                return False
            return self._checkout_result(r)

    def _checkout_result(self, r):
        if r.status_code == 201:
            try:
                body = r.json()
            except Exception:
                body = {}
            if body.get("accepted") is True:
                if body.get("csrf"):
                    self.csrf = body["csrf"]
                return True
            r.failure("order 201 not accepted")
            return False
        if r.status_code == 200:
            try:
                body = r.json()
            except Exception:
                body = {}
            if body.get("accepted") is False:
                r.failure("order business failure accepted:false")
                return False
            r.failure("order 200 unexpected")
            return False
        r.failure(f"order status {r.status_code}")
        return False

    # ---------- work ----------
    def _do_work(self):
        retries = 0
        while retries <= 4:
            with self.client.post("/v2/work", json={}, catch_response=True,
                                  allow_redirects=False) as r:
                if r.status_code == 429:
                    ra = r.headers.get("Retry-After", "1")
                    try:
                        wait = float(ra)
                    except Exception:
                        wait = 1.0
                    time.sleep(wait)
                    retries += 1
                    continue
                if r.status_code == 200:
                    try:
                        body = r.json()
                    except Exception:
                        body = {}
                    if body.get("ok") is True:
                        return True
                    r.failure("work ok not true")
                    return False
                if r.status_code == 500:
                    r.failure("work 500 unexpected")
                    return False
                r.failure(f"work status {r.status_code}")
                return False
        return False

    # ---------- journey ----------
    @task
    def journey(self):
        if self.iterations_done >= self.target_iterations:
            raise StopUser()

        # fresh login each journey
        if not self._login():
            self.iterations_done += 1
            raise StopUser()

        # stagger subsequent work
        if self.delay > 0:
            time.sleep(self.delay)

        products = self._get_catalog_products()
        product_id, variant_id = self._pick_variant(products)
        if not product_id or not variant_id:
            self.iterations_done += 1
            raise StopUser()

        grant_id = self._solve_challenge()

        cart_id, etag = self._create_cart(product_id, variant_id, grant_id)
        if not cart_id:
            self.iterations_done += 1
            raise StopUser()

        qty = max(1, min(20, int(self.account.get("quantity", 1))))
        if not self._patch_quantity(cart_id, etag, qty):
            self.iterations_done += 1
            raise StopUser()

        reservation_id = self._reserve(cart_id)

        idem_key = f"cart-{cart_id}-{random.randint(100000, 999999)}"
        self._checkout(cart_id, reservation_id, idem_key)

        self._do_work()

        self.iterations_done += 1
        if self.iterations_done >= self.target_iterations:
            raise StopUser()


