import io.gatling.javaapi.core.*;
import io.gatling.javaapi.http.*;

import java.util.*;

import static io.gatling.javaapi.core.CoreDsl.*;
import static io.gatling.javaapi.http.HttpDsl.*;

public class ModelSimulation extends Simulation {

    String baseUrl = System.getenv("BASE_URL");
    if (baseUrl == null || baseUrl.isEmpty()) {
        baseUrl = "http://127.0.0.1:8000";
    }

    HttpProtocolBuilder httpProtocol = http
            .baseUrl(baseUrl)
            .disableFollowRedirect()
            .disableAutoReferer()
            .acceptHeader("application/json")
            .contentTypeHeader("application/json");

    // Extract csrf from login form HTML: input[name=csrf] value=...
    // Tolerant of attribute order / quoting variants.
    private static final String CSRF_FORM_REGEX =
            "<input(?=[^>]*\\bname=[\"']csrf[\"'])(?=[^>]*\\bvalue=[\"']([^\"']+)[\"'])[^>]*>";

    ChainBuilder loginFlow =
            exec(
                    http("GET /v2/login-form")
                            .get("/v2/login-form")
                            .check(status().is(200))
                            .check(regex(CSRF_FORM_REGEX).find(1).saveAs("form"))
            ).exec(
                    http("POST /v2/login")
                            .post("/v2/login")
                            .body(StringBody(session ->
                                    "{\"username\":\"bench-" + session.userId() + "\",\"password\":\"bench\",\"csrf\":\""
                                            + session.getString("form") + "\"}"))
                            .check(status().in(200, 302))
                            .check(jsonPath("$.csrf").optional().saveAs("csrf"))
                            .check(header("Location").optional().saveAs("location"))
            ).exec(session -> {
                String csrf = session.getString("csrf");
                if (csrf == null) {
                    csrf = session.getString("form");
                }
                return session.set("csrf", csrf);
            }).doIf(session -> session.getString("location") != null).then(
                    exec(
                            http("GET login redirect")
                                    .get(session -> session.getString("location"))
                                    .check(status().is(200))
                                    .check(jsonPath("$.csrf").optional().saveAs("csrf"))
                                    .check(jsonPath("$.grant_id").optional().saveAs("grant"))
                    )
            );

    ChainBuilder catalogFlow =
            exec(
                    http("GET /v2/catalog")
                            .get("/v2/catalog")
                            .check(status().is(200))
                            .check(jsonPath("$.data.products[?(@.variants[0].in_stock == true)].id").find(1).saveAs("product"))
                            .check(jsonPath("$.data.products[?(@.variants[0].in_stock == true)].variants[0].id").find(1).saveAs("variant"))
            );

    ChainBuilder cartFlow =
            exec(
                    http("POST /v2/carts")
                            .post("/v2/carts")
                            .header("X-CSRF-Token", session -> session.getString("csrf"))
                            .body(StringBody(session -> {
                                String grant = session.getString("grant");
                                String body = "{\"product_id\":\"" + session.getString("product")
                                        + "\",\"variant_id\":\"" + session.getString("variant") + "\"";
                                if (grant != null && !grant.isEmpty() && !"MISSING".equals(grant)) {
                                    body += ",\"grant_id\":\"" + grant + "\"";
                                }
                                body += "}";
                                return body;
                            }))
                            .check(status().is(201))
                            .check(jsonPath("$.id").saveAs("cart"))
                            .check(jsonPath("$.csrf").optional().saveAs("csrf"))
                            .check(header("ETag").optional().saveAs("etag"))
            );

    ChainBuilder orderFlow =
            exec(
                    http("POST /v2/orders")
                            .post("/v2/orders")
                            .header("X-CSRF-Token", session -> session.getString("csrf"))
                            .header("Idempotency-Key", session -> session.getString("cart"))
                            .header("If-Match", session -> {
                                String etag = session.getString("etag");
                                return etag == null ? "" : etag;
                            })
                            .body(StringBody(session -> "{\"cart_id\":\"" + session.getString("cart") + "\"}"))
                            .check(status().is(201))
                            .check(jsonPath("$.accepted").is("true"))
                            .check(jsonPath("$.csrf").optional().saveAs("csrf"))
            );

    ScenarioBuilder scn = scenario("ModelSimulation")
            .exec(session -> session.set("csrf", "MISSING").set("cart", "MISSING").set("etag", "MISSING"))
            .exec(loginFlow)
            .exec(catalogFlow)
            .exec(cartFlow)
            .exec(orderFlow);

    {
        setUp(
                scn.injectOpen(
                        rampUsers(2).during(0)
                ).protocols(httpProtocol)
        ).maxDuration(java.time.Duration.ofMinutes(5));
    }
}
