import http from 'k6/http';
import { check } from 'k6';

const BASE = __ENV.BASE_URL || 'http://127.0.0.1:8000';

export const options = {
  scenarios: {
    flow: {
      executor: 'per-vu-iterations',
      vus: 2,
      iterations: 2,
      maxDuration: '5m',
    },
  },
  thresholds: {},
};

function parseCsrfFromForm(html) {
  if (!html) return null;
  const re = /<input(?=[^>]*\bname=["']csrf["'])(?=[^>]*\bvalue=["']([^"']+)["'])[^>]*>/i;
  const m = html.match(re);
  return m ? m[1] : null;
}

function getHeader(res, name) {
  const h = res.headers || {};
  for (const k of Object.keys(h)) {
    if (k.toLowerCase() === name.toLowerCase()) return h[k];
  }
  return null;
}

function safeJson(res) {
  try { return res.json(); } catch (e) { return null; }
}

function isExpiredOrSession(res) {
  const body = res.body || '';
  return /"error"\s*:\s*"(?:expired|session)"/.test(body);
}

function isDenied(res) {
  const body = res.body || '';
  return /"error"\s*:\s*"denied"/.test(body);
}

function resolveUrl(loc) {
  if (!loc) return null;
  if (/^https?:\/\//i.test(loc)) return loc;
  if (loc.startsWith('/')) return BASE + loc;
  return BASE + '/' + loc;
}

function loginFlow(vu) {
  const jar = http.cookieJar();
  // fresh login per iteration: clear cookies
  jar.clear(BASE);

  const state = { csrf: null, user: null };

  // GET login form
  const formRes = http.get(`${BASE}/v2/login-form`, {
    redirects: 0,
    tags: { name: 'login-form' },
  });
  check(formRes, { 'login-form 200': (r) => r.status === 200 });
  const formCsrf = parseCsrfFromForm(formRes.body);
  check(formRes, { 'login-form csrf present': () => !!formCsrf });
  state.csrf = formCsrf;

  // POST login
  const username = `bench-${vu}`;
  const loginBody = JSON.stringify({ username, password: 'bench', csrf: formCsrf });
  const loginRes = http.post(`${BASE}/v2/login`, loginBody, {
    headers: { 'Content-Type': 'application/json' },
    redirects: 0,
    tags: { name: 'login' },
  });

  let loginOk = check(loginRes, {
    'login status 200/302': (r) => r.status === 200 || r.status === 302,
  });

  if (loginRes.status === 302) {
    const loc = getHeader(loginRes, 'Location');
    check(loginRes, { 'login has Location': () => !!loc });
    if (loc) {
      const followRes = http.get(resolveUrl(loc), {
        redirects: 0,
        tags: { name: 'login-redirect' },
      });
      check(followRes, { 'login redirect 200': (r) => r.status === 200 });
      const j = safeJson(followRes);
      if (j && j.csrf) state.csrf = j.csrf;
      if (j && j.user) state.user = j.user;
    }
  } else {
    const j = safeJson(loginRes);
    check(loginRes, { 'login body has csrf': () => !!(j && j.csrf) });
    if (j && j.csrf) state.csrf = j.csrf;
    if (j && j.user) state.user = j.user;
  }

  return { ok: loginOk && !!state.csrf, state };
}

function renewSession(state) {
  const res = http.post(`${BASE}/v2/session/renew`, '{}', {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': state.csrf || '',
    },
    redirects: 0,
    tags: { name: 'session-renew' },
  });
  const j = safeJson(res);
  if (j && j.csrf) state.csrf = j.csrf;
  return res;
}

function recoverCart(state, cartId) {
  if (!cartId) return null;
  const res = http.post(`${BASE}/v2/carts/${cartId}/recover`, '{}', {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': state.csrf || '',
    },
    redirects: 0,
    tags: { name: 'cart-recover' },
  });
  const j = safeJson(res);
  if (j && j.csrf) state.csrf = j.csrf;
  return res;
}

function fetchCatalog(state) {
  const res = http.get(`${BASE}/v2/catalog`, {
    headers: { 'X-CSRF-Token': state.csrf || '' },
    redirects: 0,
    tags: { name: 'catalog' },
  });
  check(res, { 'catalog 200': (r) => r.status === 200 });
  const j = safeJson(res);
  if (j && j.csrf) state.csrf = j.csrf;
  let product = null;
  let variant = null;
  if (j && j.data && Array.isArray(j.data.products)) {
    for (const p of j.data.products) {
      if (p && Array.isArray(p.variants)) {
        for (const v of p.variants) {
          if (v && v.in_stock === true) {
            product = p.id;
            variant = v.id;
            break;
          }
        }
      }
      if (product) break;
    }
  }
  check(res, { 'catalog has in-stock product': () => !!product && !!variant });
  return { product, variant };
}

function createCart(state, product, variant, grant) {
  const body = { product_id: product, variant_id: variant };
  if (grant) body.grant_id = grant;
  const res = http.post(`${BASE}/v2/carts`, JSON.stringify(body), {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': state.csrf || '',
    },
    redirects: 0,
    tags: { name: 'cart-create' },
  });
  check(res, { 'cart create 201': (r) => r.status === 201 });
  const j = safeJson(res);
  if (j && j.csrf) state.csrf = j.csrf;
  const cartId = j && j.id ? j.id : null;
  const etag = getHeader(res, 'ETag');
  check(res, { 'cart id present': () => !!cartId });
  return { cartId, etag };
}

function patchCartQuantity(state, cartId, etag, quantity) {
  const headers = {
    'Content-Type': 'application/json',
    'X-CSRF-Token': state.csrf || '',
  };
  if (etag) headers['If-Match'] = etag;
  let res = http.patch(`${BASE}/v2/carts/${cartId}`, JSON.stringify({ quantity }), {
    headers,
    redirects: 0,
    tags: { name: 'cart-patch' },
  });

  if (res.status === 412) {
    // re-read and retry same payload once
    const readRes = http.get(`${BASE}/v2/carts/${cartId}`, {
      headers: { 'X-CSRF-Token': state.csrf || '' },
      redirects: 0,
      tags: { name: 'cart-read' },
    });
    const newEtag = getHeader(readRes, 'ETag');
    const h2 = {
      'Content-Type': 'application/json',
      'X-CSRF-Token': state.csrf || '',
    };
    if (newEtag) h2['If-Match'] = newEtag;
    res = http.patch(`${BASE}/v2/carts/${cartId}`, JSON.stringify({ quantity }), {
      headers: h2,
      redirects: 0,
      tags: { name: 'cart-patch-retry' },
    });
  }

  const j = safeJson(res);
  if (j && j.csrf) state.csrf = j.csrf;
  const newEtag = getHeader(res, 'ETag');
  check(res, { 'cart patch ok': (r) => r.status >= 200 && r.status < 300 });
  return { etag: newEtag || etag };
}

function createOrder(state, cartId, etag) {
  const headers = {
    'Content-Type': 'application/json',
    'X-CSRF-Token': state.csrf || '',
    'Idempotency-Key': cartId,
  };
  if (etag) headers['If-Match'] = etag;
  const res = http.post(`${BASE}/v2/orders`, JSON.stringify({ cart_id: cartId }), {
    headers,
    redirects: 0,
    tags: { name: 'order-create' },
  });
  const j = safeJson(res);
  if (j && j.csrf) state.csrf = j.csrf;
  check(res, {
    'order 201': (r) => r.status === 201,
    'order accepted true': () => !!(j && j.accepted === true),
  });
  return res;
}

export default function () {
  const vu = __VU;
  const login = loginFlow(vu);
  if (!login.ok) return;
  const state = login.state;

  const cat = fetchCatalog(state);
  if (!cat.product || !cat.variant) return;

  const cart = createCart(state, cat.product, cat.variant, null);
  if (!cart.cartId) return;

  const patched = patchCartQuantity(state, cart.cartId, cart.etag, 2);

  createOrder(state, cart.cartId, patched.etag);
}
