from locust import HttpUser, task, between, events
from locust.exception import StopUser


BASE_URL = os.environ.get("BASE_URL", "http://127.0.0.1:8000")
PASSWORD = "bench"


def _extract_csrf_from_html(html):
    if not html:
        return None
    # input[name=csrf] with value, tolerant of attribute order/quoting
    m = re.search(
        r"<input(?=[^>]*\bname=[\"']csrf[\"'])(?=[^>]*\bvalue=[\"']([^\"']+)[\"'])[^>]*>",
        html,
        re.IGNORECASE,
    )
    if m:
        return m.group(1)
    return None


class ShopUser(HttpUser):
    host = BASE_URL
    wait_time = between(0.05, 0.15)

    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self._iterations_done = 0
        self._max_iterations = 2
        self._user_index = None

    def on_start(self):
        # Assign a stable per-user account index (1..16) based on worker slot.
        # Use a class-level counter guarded by simple attribute on the class.
        cls = type(self)
        if not hasattr(cls, "_counter"):
            cls._counter = 0
        cls._counter += 1
        self._user_index = ((cls._counter - 1) % 16) + 1
        self.username = "bench-%d" % self._user_index

    # ---------- helpers ----------

    def _login(self):
        """Fresh login: GET form, extract csrf, POST login, capture session csrf."""
        with self.client.get(
            "/v2/login-form",
            name="GET /v2/login-form",
            catch_response=True,
            allow_redirects=False,
        ) as resp:
            if resp.status_code != 200:
                resp.failure("login-form status %s" % resp.status_code)
                return None
            form_csrf = _extract_csrf_from_html(resp.text)
            if not form_csrf:
                resp.failure("login-form missing csrf")
                return None

        body = {"username": self.username, "password": PASSWORD, "csrf": form_csrf}
        with self.client.post(
            "/v2/login",
            json=body,
            name="POST /v2/login",
            catch_response=True,
            allow_redirects=False,
        ) as resp:
            if resp.status_code == 302:
                loc = resp.headers.get("Location")
                if not loc:
                    resp.failure("login 302 without Location")
                    return None
                with self.client.get(
                    loc,
                    name="GET login redirect",
                    catch_response=True,
                    allow_redirects=False,
