                        r2.failure("login redirect not json")
                        return None
                    csrf = data.get("csrf")
                    if not csrf:
                        r2.failure("login redirect missing csrf")
                        return None
                    return csrf
            elif resp.status_code == 200:
                try:
                    data = resp.json()
                except Exception:
                    resp.failure("login not json")
                    return None
                csrf = data.get("csrf")
                if not csrf:
                    resp.failure("login missing csrf")
                    return None
                return csrf
            else:
                resp.failure("login status %s" % resp.status_code)
                return None

    def _get_catalog_product(self):
        with self.client.get(
            "/v2/catalog",
            name="GET /v2/catalog",
            catch_response=True,
            allow_redirects=False,
        ) as resp:
            if resp.status_code != 200:
                resp.failure("catalog status %s" % resp.status_code)
                return None
            try:
                data = resp.json()
            except Exception:
                resp.failure("catalog not json")
                return None
            products = (data.get("data") or {}).get("products") or []
            for p in products:
