                        r3.failure("cart patch retry status %s" % r3.status_code)
                        return False
                    etag = r3.headers.get("ETag")
                    if etag:
                        cart["etag"] = etag
                    try:
                        d = r3.json()
                        if d.get("csrf"):
                            cart["csrf"] = d["csrf"]
                    except Exception:
                        pass
                    return True
            elif resp.status_code in (200, 204):
                etag = resp.headers.get("ETag")
                if etag:
                    cart["etag"] = etag
                try:
                    d = resp.json()
                    if d.get("csrf"):
                        cart["csrf"] = d["csrf"]
                except Exception:
                    pass
                return True
            else:
                resp.failure("cart patch status %s" % resp.status_code)
                return False

    def _place_order(self, cart):
        headers = {
            "X-CSRF-Token": cart["csrf"],
            "Content-Type": "application/json",
            "Idempotency-Key": cart["id"],
        }
        if cart.get("etag"):
            headers["If-Match"] = cart["etag"]
        body = {"cart_id": cart["id"]}
        with self.client.post(
            "/v2/orders",
            json=body,
            headers=headers,
            name="POST /v2/orders",
            catch_response=True,
            allow_redirects=False,
        ) as resp:
            if resp.status_code != 201:
                resp.failure("order status %s" % resp.status_code)
                return False
            try:
                data = resp.json()
            except Exception:
                resp.failure("order not json")
                return False
            if data.get("accepted") is not True:
                resp.failure("order not accepted")
                return False
            if not data.get("id"):
                resp.failure("order missing id")
                return False
            return True

    # ---------- journey ----------

    @task
    def journey(self):
        if self._iterations_done >= self._max_iterations:
            raise StopUser()

        csrf = self._login()
        if not csrf:
            self._iterations_done += 1
            if self._iterations_done >= self._max_iterations:
                raise StopUser()
            return

        prod = self._get_catalog_product()
        if not prod:
            self._iterations_done += 1
            if self._iterations_done >= self._max_iterations:
                raise StopUser()
            return
        product_id, variant_id = prod

        cart = self._create_cart(csrf, product_id, variant_id)
        if not cart:
            self._iterations_done += 1
            if self._iterations_done >= self._max_iterations:
                raise StopUser()
            return

        if not self._patch_quantity(cart, 2):
            self._iterations_done += 1
            if self._iterations_done >= self._max_iterations:
                raise StopUser()
            return

        self._place_order(cart)

        self._iterations_done += 1
        if self._iterations_done >= self._max_iterations:
            raise StopUser()


class ShopShape(events.EventHook if False else object):
    pass


from locust import LoadTestShape


class ShopLoadShape(LoadTestShape):
    """2 users, 2 iterations each; stop when done."""

    def __init__(self):
        super().__init__()
        self._started = None

    def tick(self):
        if self._started is None:
            self._started = time.time()
        # Run 2 users for a bounded window; harness stops when tick returns None.
        elapsed = time.time() - self._started
        if elapsed > 120:
            return None
        return (2, 2)
