import io.gatling.javaapi.core.*;
import io.gatling.javaapi.http.*;

import java.time.Duration;
import java.util.*;

import static io.gatling.javaapi.core.CoreDsl.*;
import static io.gatling.javaapi.http.HttpDsl.*;

public class ModelSimulation extends Simulation {

    private static final String BASE_URL =
            System.getenv().getOrDefault("BASE_URL", "http://127.0.0.1:8000");

    private static final HttpProtocolBuilder HTTP = http
            .baseUrl(BASE_URL)
            .disableAutoReferer()
            .disableFollowRedirect()
            .acceptHeader("application/json")
            .contentTypeHeader("application/json")
            .shareConnections();

    // ---- helpers ---------------------------------------------------------

    private static String csrfHeader() {
        return "#{csrf}";
    }

    // ---- chains ----------------------------------------------------------

    // GET /v2/login-form -> extract csrf from input[name=csrf]
    private static final ChainBuilder loginForm = exec(
            http("GET /v2/login-form")
                    .get("/v2/login-form")
                    .check(status().is(200))
                    .check(regex("(?i)<input(?=[^>]*\\bname=[\"']csrf[\"'])(?=[^>]*\\bvalue=[\"']([^\"']+)[\"'])[^>]*>")
                            .find(1).saveAs("form"))
    );

    // POST /v2/login -> may 302 with Location; capture csrf from body if present
    private static final ChainBuilder login = exec(
            http("POST /v2/login")
                    .post("/v2/login")
                    .header("X-CSRF-Token", "#{form}")
                    .body(StringBody("{\"username\":\"#{username}\",\"password\":\"bench\",\"csrf\":\"#{form}\"}"))
                    .check(status().in(200, 302))
                    .check(header("Location").optional().saveAs("location"))
                    .check(header("Location").optional().transform(l -> l != null).saveAs("redirect"))
                    .check(bodyString().optional().saveAs("loginBody"))
    ).exec(session -> {
        String body = session.getString("loginBody");
        if (body != null) {
            java.util.regex.Matcher m = java.util.regex.Pattern
                    .compile("\"csrf\"\\s*:\\s*\"([^\"]+)\"").matcher(body);
            if (m.find()) {
                return session.set("csrf", m.group(1));
            }
        }
        return session;
    });

    // Follow the dynamic Location exactly once (only if present)
    private static final ChainBuilder followLoginRedirect = doIf(session -> {
        Boolean r = session.getBoolean("redirect");
        return r != null && r;
    }).then(
            exec(
                    http("GET login redirect")
                            .get("#{location}")
                            .check(status().is(200))
                            .check(bodyString().optional().saveAs("redirectBody"))
            ).exec(session -> {
                String body = session.getString("redirectBody");
                if (body != null) {
                    java.util.regex.Matcher m = java.util.regex.Pattern
                            .compile("\"csrf\"\\s*:\\s*\"([^\"]+)\"").matcher(body);
                    if (m.find()) {
                        return session.set("csrf", m.group(1));
                    }
                }
                return session;
            })
    );

    // GET /v2/catalog -> pick first in-stock product/variant
    private static final ChainBuilder catalog = exec(
            http("GET /v2/catalog")
                    .get("/v2/catalog")
                    .check(status().is(200))
                    .check(jsonPath("$.data.products[?(@.variants[0].in_stock == true)].id").find(1).saveAs("product"))
                    .check(jsonPath("$.data.products[?(@.variants[0].in_stock == true)].variants[0].id").find(1).saveAs("variant"))
    );

    // POST /v2/carts with grant_id once
    private static final ChainBuilder createCart = exec(
            http("POST /v2/carts")
                    .post("/v2/carts")
                    .header("X-CSRF-Token", csrfHeader())
                    .body(StringBody("{\"product_id\":\"#{product}\",\"variant_id\":\"#{variant}\",\"grant_id\":\"#{grant}\"}"))
                    .check(status().is(201))
                    .check(jsonPath("$.id").saveAs("cart"))
                    .check(jsonPath("$.csrf").optional().saveAs("newCsrf"))
                    .check(header("ETag").optional().saveAs("etag"))
    ).exec(session -> {
        String nc = session.getString("newCsrf");
        return nc != null ? session.set("csrf", nc) : session;
    });

    // POST /v2/orders with Idempotency-Key = cart id (stable per cart)
    private static final ChainBuilder placeOrder = exec(
            http("POST /v2/orders")
                    .post("/v2/orders")
                    .header("X-CSRF-Token", csrfHeader())
                    .header("Idempotency-Key", "#{cart}")
                    .body(StringBody("{\"cart_id\":\"#{cart}\"}"))
                    .check(status().is(201))
                    .check(jsonPath("$.accepted").is("true"))
                    .check(jsonPath("$.id").exists())
                    .check(jsonPath("$.csrf").optional().saveAs("newCsrf"))
    ).exec(session -> {
        String nc = session.getString("newCsrf");
        return nc != null ? session.set("csrf", nc) : session;
    });

    // ---- scenario --------------------------------------------------------

    private static final ScenarioBuilder scn = scenario("ModelSimulation")
            .exec(session -> session
                    .set("username", "bench-" + session.userId())
                    .set("csrf", "MISSING")
                    .set("etag", "MISSING")
                    .set("cart", "MISSING")
                    .set("grant", "MISSING"))
            .exec(loginForm)
            .exec(login)
            .exec(followLoginRedirect)
            .exec(catalog)
            .exec(createCart)
            .exec(placeOrder);

    {
        setUp(
                scn.injectOpen(
                        rampUsersPerSec(0).to(2).during(Duration.ofSeconds(1)),
                        constantUsersPerSec(2).during(Duration.ofSeconds(1))
                ).protocols(HTTP)
        ).maxDuration(Duration.ofSeconds(60));
    }
}
