```javascript
import http from 'k6/http';
import { check } from 'k6';

const BASE = __ENV.BASE_URL || 'http://127.0.0.1:8000';

export const options = {
  scenarios: {
    journey: {
      executor: 'per-vu-iterations',
      vus: 2,
      iterations: 2,
      maxDuration: '2m',
    },
  },
  thresholds: {
    checks: ['rate==1'],
  },
};

function jar() {
  return new http.CookieJar();
}

function parseCsrfFromForm(body) {
  if (!body) return null;
  const re = /<input(?=[^>]*\bname=["']csrf["'])(?=[^>]*\bvalue=["']([^"']+)["'])[^>]*>/i;
  const m = body.match(re);
  return m ? m[1] : null;
}

function safeJson(res) {
  try { return res.json(); } catch (e) { return null; }
}

function getHeader(res, name) {
  const h = res.headers;
  if (!h) return null;
  const lower = name.toLowerCase();
  for (const k in h) {
    if (k.toLowerCase() === lower) return h[k];
  }
  return null;
}

function resolveLocation(loc) {
  if (!loc) return null;
  if (/^https?:\/\//i.test(loc)) return loc;
  if (loc.startsWith('/')) return BASE + loc;
  return BASE + '/' + loc;
}

function pickProduct(catalog) {
  if (!catalog || !catalog.data || !Array.isArray(catalog.data.products)) return null;
  for (const p of catalog.data.products) {
    if (!p || !Array.isArray(p.variants)) continue;
    for (const v of p.variants) {
      if (v && v.in_stock === true) {
        return { product: p.id, variant: v.id };
      }
    }
  }
  return null;
}

function loginFlow(jarObj, username) {
  const state = { csrf: null, session: null };

  // GET login form
  const formRes = http.get(`${BASE}/v2/login-form`, { jar: jarObj, redirects: 0 });
  check(formRes, { 'login-form 200': (r) => r.status === 200 });
  const formCsrf = parseCsrfFromForm(formRes.body);
  check(formCsrf, { 'login-form csrf extracted': (v) => !!v });
  if (!formCsrf) return null;

  // POST login
  const loginRes = http.post(
    `${BASE}/v2/login`,
    JSON.stringify({ username, password: 'bench', csrf: formCsrf }),
    {
      jar: jarObj,
      redirects: 0,
      headers: { 'Content-Type': 'application/json' },
    }
  );

  let csrf = null;
  let grant = null;

  if (loginRes.status === 302) {
    const loc = getHeader(loginRes, 'Location');
    check(loc, { 'login 302 has Location': (v) => !!v });
    if (!loc) return null;
    const target = resolveLocation(loc);
    // Follow dynamic Location exactly once
    const followRes = http.get(target, { jar: jarObj, redirects: 0 });
    check(followRes, { 'login redirect follow 200': (r) => r.status === 200 });
    const body = safeJson(followRes);
    if (body) {
      csrf = body.csrf || null;
      grant = body.grant_id || null;
    }
  } else {
    check(loginRes, { 'login 200': (r) => r.status === 200 });
    const body = safeJson(loginRes);
    if (body) {
      csrf = body.csrf || null;
      grant = body.grant_id || null;
    }
  }

  check(csrf, { 'login csrf present': (v) => !!v });
  state.csrf = csrf;
  state.grant = grant;
  return state;
}

function challengeFlow(jarObj, csrf) {
  // GET challenge form
  const cfRes = http.get(`${BASE}/v2/challenge-form`, { jar: jarObj, redirects: 0 });
  check(cfRes, { 'challenge-form 200': (r) => r.status === 200 });
  const body = cfRes.body || '';
  const actionMatch = body.match(/<form[^>]*\baction=["']([^"']+)["']/i);
  const challengeMatch = body.match(/<input(?=[^>]*\bname=["']challenge["'])(?=[^>]*\bvalue=["']([^"']+)["'])[^>]*>/i);
  const action = actionMatch ? actionMatch[1] : null;
  const challenge = challengeMatch ? challengeMatch[1] : null;
  check(action, { 'challenge action extracted': (v) => !!v });
  check(challenge, { 'challenge value extracted': (v) => !!v });
  if (!action || !challenge) return null;

  const actionUrl = resolveLocation(action);
  const postRes = http.post(
    actionUrl,
    JSON.stringify({ challenge }),
    {
      jar: jarObj,
      redirects: 0,
      headers: {
        'Content-Type': 'application/json',
        'X-CSRF-Token': csrf || '',
      },
    }
  );
  check(postRes, { 'challenge post 302': (r) => r.status === 302 });
  const loc = getHeader(postRes, 'Location');
  check(loc, { 'challenge 302 Location': (v) => !!v });
  if (!loc) return null;
  const followRes = http.get(resolveLocation(loc), { jar: jarObj, redirects: 0 });
  check(followRes, { 'challenge follow 200': (r) => r.status === 200 });
  const j = safeJson(followRes);
  const grant = j && j.grant_id ? j.grant_id : null;
  const newCsrf = j && j.csrf ? j.csrf : csrf;
  check(grant, { 'grant_id extracted': (v) => !!v });
  return { grant, csrf: newCsrf };
}

function getCatalog(jarObj, csrf) {
  const res = http.get(`${BASE}/v2/catalog`, {
    jar: jarObj,
    redirects: 0,
    headers: { 'X-CSRF-Token': csrf || '' },
  });
  check(res, { 'catalog 200': (r) => r.status === 200 });
  const body = safeJson(res);
  const pick = pickProduct(body);
  check(pick, { 'catalog product picked': (v) => !!v });
  return pick;
}

function createCart(jarObj, csrf, product, variant, grant) {
  const payload = { product_id: product, variant_id: variant };
  if (grant) payload.grant_id = grant;
  const res = http.post(`${BASE}/v2/carts`, JSON.stringify(payload), {
    jar: jarObj,
    redirects: 0,
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': csrf || '',
    },
  });
  check(res, { 'cart 201': (r) => r.status === 201 });
  const body = safeJson(res);
  const cartId = body && body.id ? body.id : null;
  const newCsrf = body && body.csrf ? body.csrf : csrf;
  const etag = getHeader(res, 'ETag');
  check(cartId, { 'cart id present': (v) => !!v });
  return { cartId, csrf: newCsrf, etag };
}

function placeOrder(jarObj, csrf, cartId, etag) {
  const headers = {
    'Content-Type': 'application/json',
    'X-CSRF-Token': csrf || '',
    'Idempotency-Key': cartId,
  };
  if (etag) headers['If-Match'] = etag;
  const res = http.post(
    `${BASE}/v2/orders`,
    JSON.stringify({ cart_id: cartId }),
    { jar: jarObj, redirects: 0, headers }
  );
  check(res, { 'order 201': (r) => r.status === 201 });
  const body = safeJson(res);
  check(body, { 'order accepted true': (b) => b && b.accepted === true });
  return body;
}

export default function () {
  const vu = __VU;
  const username = `bench-${vu}`;
  const jarObj = jar();

  const login = loginFlow(jarObj, username);
  if (!login) return;

  let csrf = login.csrf;
  let grant = login.grant;

  // If login didn't yield a grant, run challenge flow
  if (!grant) {
    const ch = challengeFlow(jarObj, csrf);
    if (!ch) return;
    grant = ch.grant;
    csrf = ch.csrf;
  }

  const pick = getCatalog(jarObj, csrf);
  if (!pick) return;

  const cart = createCart(jarObj, csrf, pick.product, pick.variant, grant);
  if (!cart || !cart.cartId) return;
  csrf = cart.csrf;

  placeOrder(jarObj, csrf, cart.cartId, cart.etag);
}
