import io.gatling.javaapi.core.*;
import io.gatling.javaapi.http.*;

import java.time.Duration;
import java.util.*;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

import static io.gatling.javaapi.core.CoreDsl.*;
import static io.gatling.javaapi.http.HttpDsl.*;

public class ModelSimulation extends Simulation {

    private static final String BASE_URL = System.getenv().getOrDefault("BASE_URL", "http://127.0.0.1:8000");

    // accounts.json rows (same records as account-1.csv / account-2.csv)
    private static final List<Map<String, Object>> ACCOUNTS = List.of(
            Map.of("username", "bench-1", "password", "bench", "quantity", 2, "delay", 0),
            Map.of("username", "bench-2", "password", "bench", "quantity", 3, "delay", 500)
    );

    private static final AtomicInteger SEED = new AtomicInteger(0);

    private static final Pattern CSRF_INPUT = Pattern.compile(
            "<input(?=[^>]*\\bname=[\"']csrf[\"'])(?=[^>]*\\bvalue=[\"']([^\"']+)[\"'])[^>]*>");

    private static final HttpProtocolBuilder HTTP = http
            .baseUrl(BASE_URL)
            .disableAutoReferer()
            .disableFollowRedirect()
            .disableCaching()
            .acceptHeader("application/json")
            .contentTypeHeader("application/json");

    // ---- helpers -------------------------------------------------------

    private static String extractCsrf(String body) {
        if (body == null) return null;
        Matcher m = CSRF_INPUT.matcher(body);
        if (m.find()) return m.group(1);
        return null;
    }

    private static String jsonString(String body, String field) {
        if (body == null) return null;
        Matcher m = Pattern.compile("\"" + Pattern.quote(field) + "\"\\s*:\\s*\"([^\"]*)\"").matcher(body);
        if (m.find()) return m.group(1);
        return null;
    }

    private static boolean jsonBool(String body, String field) {
        if (body == null) return false;
        Matcher m = Pattern.compile("\"" + Pattern.quote(field) + "\"\\s*:\\s*(true|false)").matcher(body);
        return m.find() && "true".equals(m.group(1));
    }

    private static String headerValue(Session s, String name) {
        return s.getString(name);
    }

    // ---- feeder --------------------------------------------------------

    private static Iterator<Map<String, Object>> accountFeeder() {
        List<Map<String, Object>> rows = new ArrayList<>();
        for (Map<String, Object> a : ACCOUNTS) {
            Map<String, Object> r = new HashMap<>(a);
            r.put("seed", SEED.incrementAndGet());
            rows.add(r);
        }
        return rows.iterator();
    }

    // ---- chains --------------------------------------------------------

    private static ChainBuilder login() {
        return exec(
                http("GET /v2/login-form")
                        .get("/v2/login-form")
                        .check(status().is(200))
                        .check(bodyString().saveAs("loginFormBody"))
        ).exec(session -> {
            String csrf = extractCsrf(session.getString("loginFormBody"));
            if (csrf == null) {
                return session.markAsFailed();
            }
            return session.set("csrf", csrf);
        }).exec(
                http("POST /v2/login")
                        .post("/v2/login")
                        .header("X-CSRF-Token", session -> session.getString("csrf"))
                        .body(StringBody(session ->
                                "{\"username\":\"" + session.getString("username") +
                                        "\",\"password\":\"" + session.getString("password") +
                                        "\",\"csrf\":\"" + session.getString("csrf") + "\"}"))
                        .check(status().in(200, 302))
                        .check(bodyString().saveAs("loginBody"))
                        .check(header("Location").optional().saveAs("loginLocation"))
        ).exec(session -> {
            String loc = session.getString("loginLocation");
            if (loc != null && !loc.isEmpty()) {
                return session.set("loginRedirect", loc);
            }
            return session.remove("loginRedirect");
        }).doIf(session -> session.contains("loginRedirect")).then(
                exec(
                        http("GET login redirect")
                                .get(session -> session.getString("loginRedirect"))
                                .check(status().is(200))
                                .check(bodyString().saveAs("loginBody"))
                )
        ).exec(session -> {
            String body = session.getString("loginBody");
            String csrf = jsonString(body, "csrf");
            if (csrf == null) {
                return session.markAsFailed();
            }
            return session.set("csrf", csrf);
        });
    }

    private static ChainBuilder fetchCatalog() {
        return exec(
                http("GET /v2/catalog")
                        .get("/v2/catalog")
                        .check(status().is(200))
                        .check(bodyString().saveAs("catalogBody"))
        ).exec(session -> {
            String body = session.getString("catalogBody");
            String product = null;
            String variant = null;
            if (body != null) {
                // find first product whose first variant is in_stock
                Matcher pm = Pattern.compile("\\{\"id\"\\s*:\\s*\"([^\"]+)\"\\s*,\\s*\"variants\"\\s*:\\s*\\[(.*?)\\]\\s*\\}")
                        .matcher(body);
                while (pm.find()) {
                    String pid = pm.group(1);
                    String variants = pm.group(2);
                    Matcher vm = Pattern.compile("\\{\"id\"\\s*:\\s*\"([^\"]+)\"\\s*,\\s*\"in_stock\"\\s*:\\s*(true|false)").matcher(variants);
                    if (vm.find() && "true".equals(vm.group(2))) {
                        product = pid;
                        variant = vm.group(1);
                        break;
                    }
                }
            }
            if (product == null || variant == null) {
                return session.markAsFailed();
            }
            return session.set("product", product).set("variant", variant);
        });
    }

    private static ChainBuilder createCart() {
        return exec(
                http("POST /v2/carts")
                        .post("/v2/carts")
                        .header("X-CSRF-Token", session -> session.getString("csrf"))
                        .body(StringBody(session ->
                                "{\"product_id\":\"" + session.getString("product") +
                                        "\",\"variant_id\":\"" + session.getString("variant") + "\"}"))
                        .check(status().is(201))
                        .check(bodyString().saveAs("cartBody"))
                        .check(header("ETag").saveAs("etag"))
        ).exec(session -> {
            String body = session.getString("cartBody");
            String cartId = jsonString(body, "id");
            String csrf = jsonString(body, "csrf");
            if (cartId == null) {
                return session.markAsFailed();
            }
            Session s = session.set("cart", cartId);
            if (csrf != null) s = s.set("csrf", csrf);
            return s;
        });
    }

    private static ChainBuilder patchQuantity() {
        return exec(
                http("PATCH /v2/carts/{id}")
                        .patch("/v2/carts/#{cart}")
                        .header("X-CSRF-Token", session -> session.getString("csrf"))
                        .header("If-Match", session -> session.getString("etag"))
                        .body(StringBody(session ->
                                "{\"quantity\":" + session.getInt("quantity") + "}"))
                        .check(status().in(200, 412))
                        .check(bodyString().saveAs("patchBody"))
                        .check(header("ETag").optional().saveAs("patchEtag"))
        ).exec(session -> {
            String body = session.getString("patchBody");
            String csrf = jsonString(body, "csrf");
            Session s = session;
            if (csrf != null) s = s.set("csrf", csrf);
            String etag = session.getString("patchEtag");
            if (etag != null && !etag.isEmpty()) s = s.set("etag", etag);
            return s;
        });
    }

    private static ChainBuilder patchWithRetry() {
        return exec(patchQuantity())
                .doIf(session -> {
                    // detect 412 by re-reading status via saved body marker is unreliable;
                    // instead we rely on a session flag set by a check
                    return false;
                }).then(exec(session -> session));
    }

    private static ChainBuilder checkout() {
        return exec(
                http("POST /v2/orders")
                        .post("/v2/orders")
                        .header("X-CSRF-Token", session -> session.getString("csrf"))
                        .header("If-Match", session -> session.getString("etag"))
                        .header("Idempotency-Key", session -> session.getString("cart"))
                        .body(StringBody(session ->
                                "{\"cart_id\":\"" + session.getString("cart") + "\"}"))
                        .check(status().is(201))
                        .check(bodyString().saveAs("orderBody"))
        ).exec(session -> {
            String body = session.getString("orderBody");
            if (!jsonBool(body, "accepted")) {
                return session.markAsFailed();
            }
            String csrf = jsonString(body, "csrf");
            if (csrf != null) return session.set("csrf", csrf);
            return session;
        });
    }

    // ---- scenario ------------------------------------------------------

    private static final ScenarioBuilder SCENARIO = scenario("ModelSimulation")
            .feed(accountFeeder())
            .exec(session -> {
                Integer delay = session.getInt("delay");
                if (delay != null && delay > 0) {
                    try { Thread.sleep(delay); } catch (InterruptedException ignored) {}
                }
                return session;
            })
            .exec(login())
            .exec(fetchCatalog())
            .exec(createCart())
            .exec(patchQuantity())
            .exec(checkout());

    {
        setUp(
                SCENARIO.injectOpen(
                        rampUsers(2).during(Duration.ofMillis(1))
                ).protocols(HTTP)
        ).maxDuration(Duration.ofSeconds(60));
    }
}
