```javascript
import http from 'k6/http';
import { check } from 'k6';
import { SharedArray } from 'k6/data';

const BASE = __ENV.BASE_URL || 'http://127.0.0.1:8000';

const accounts = new SharedArray('accounts', function () {
  return JSON.parse(open('/fixtures/accounts.json'));
});

export const options = {
  scenarios: {
    journeys: {
      executor: 'per-vu-iterations',
      vus: 2,
      iterations: 2,
      maxDuration: '2m',
    },
  },
  thresholds: {
    checks: ['rate==1'],
  },
};

function parseCsrfFromForm(body) {
  const re = /<input(?=[^>]*\bname=["']csrf["'])(?=[^>]*\bvalue=["']([^"']+)["'])[^>]*>/i;
  const m = re.exec(body || '');
  return m ? m[1] : null;
}

function getHeader(res, name) {
  const h = res.headers[name] || res.headers[name.toLowerCase()];
  return h || null;
}

function safeJson(res) {
  try { return res.json(); } catch (e) { return null; }
}

function isExpired(res) {
  const j = safeJson(res);
  return res.status === 401 && j && (j.error === 'expired' || j.error === 'session');
}

function isDenied(res) {
  const j = safeJson(res);
  return res.status === 401 && j && j.error === 'denied';
}

function sleepMs(ms) {
  const end = Date.now() + ms;
  while (Date.now() < end) { /* busy wait */ }
}

export default function () {
  const vu = __VU;
  const iter = __ITER;
  const row = accounts[(vu - 1) % accounts.length];
  const username = row.username;
  const password = row.password || 'bench';
  const quantity = Number(row.quantity);
  const delay = Number(row.delay) || 0;

  if (delay > 0) sleepMs(delay);

  let csrf = null;
  let sessionOk = false;

  // Fresh login
  function doLogin() {
    const formRes = http.get(`${BASE}/v2/login-form`, { redirects: 0 });
    check(formRes, { 'login-form 200': (r) => r.status === 200 });
    const formCsrf = parseCsrfFromForm(formRes.body);
    check(formCsrf, { 'form csrf present': (v) => !!v });
    const loginRes = http.post(`${BASE}/v2/login`, JSON.stringify({
      username: username,
      password: password,
      csrf: formCsrf,
    }), {
      headers: { 'Content-Type': 'application/json' },
      redirects: 0,
    });
    if (loginRes.status === 302) {
      const loc = getHeader(loginRes, 'Location');
      if (loc) {
        const followRes = http.get(loc.startsWith('http') ? loc : `${BASE}${loc}`, { redirects: 0 });
        const j = safeJson(followRes);
        if (j && j.csrf) { csrf = j.csrf; sessionOk = true; return; }
      }
    }
    const j = safeJson(loginRes);
    check(loginRes, { 'login ok': (r) => r.status === 200 || r.status === 302 });
    if (j && j.csrf) { csrf = j.csrf; sessionOk = true; }
  }

  doLogin();
  check(sessionOk, { 'session established': (v) => v === true });
  if (!sessionOk) return;

  // Catalog
  const catRes = http.get(`${BASE}/v2/catalog`, { redirects: 0 });
  check(catRes, { 'catalog 200': (r) => r.status === 200 });
