                    return False
                if data.get("accepted") is False:
                    resp.failure("order accepted:false")
                    return False
                resp.failure("order 200 unexpected")
                return False
            if resp.status_code != 201:
                resp.failure(f"order status {resp.status_code}")
                return False
            try:
                data = resp.json()
            except Exception:
                resp.failure("order not JSON")
                return False
            if data.get("accepted") is not True:
                resp.failure("order accepted not true")
                return False
            if not data.get("id"):
                resp.failure("order missing id")
                return False
            if data.get("csrf"):
                self.csrf = data["csrf"]
            resp.success()
            return True

    def _do_work(self):
        for attempt in range(5):
            with self.client.post(
                "/v2/work",
                json={},
                headers=self._headers(),
                name="/v2/work",
                catch_response=True,
                allow_redirects=False,
            ) as resp:
                if resp.status_code == 429:
                    ra = resp.headers.get("Retry-After", "1")
                    try:
                        delay = float(ra)
                    except Exception:
                        delay = 1.0
                    resp.success()
                    if attempt >= 4:
                        return
                    time.sleep(max(delay, 0.05))
                    continue
                if resp.status_code == 200:
                    resp.success()
                    return
                resp.failure(f"work status {resp.status_code}")
                return

    @task
    def journey(self):
        if self.iterations_done >= ITERATIONS:
            raise StopUser()

        self._assign_account()
        self.cart_id = None
        self.etag = None
        self.grant_id = None
        self.reservation_id = None
