            return

        if not self._solve_challenge():
            self.iterations_done += 1
            if self.iterations_done >= ITERATIONS:
                raise StopUser()
            return

        if not self._create_cart():
            self.iterations_done += 1
            if self.iterations_done >= ITERATIONS:
                raise StopUser()
            return

        if not self._read_cart():
            self.iterations_done += 1
            if self.iterations_done >= ITERATIONS:
                raise StopUser()
            return

        if not self._patch_quantity():
            self.iterations_done += 1
            if self.iterations_done >= ITERATIONS:
                raise StopUser()
            return

        if not self._reserve():
            self.iterations_done += 1
            if self.iterations_done >= ITERATIONS:
                raise StopUser()
            return

        if not self._checkout():
            self.iterations_done += 1
            if self.iterations_done >= ITERATIONS:
                raise StopUser()
            return

        self._do_work()

        self.iterations_done += 1
        if self.iterations_done >= ITERATIONS:
            raise StopUser()


