class StageShape(LoadTestShape):
    def __init__(self):
        super().__init__()
        self._start = None
        self._done = False

    def tick(self):
        if self._done:
            return None
        if self._start is None:
            self._start = time.time()
        elapsed = time.time() - self._start
        if elapsed < 1:
