```javascript
import http from 'k6/http';
import { check } from 'k6';
import { Counter, Rate } from 'k6/metrics';

const BASE = __ENV.BASE_URL || 'http://127.0.0.1:8000';

const checkoutStarts = new Counter('checkout_starts');
const businessFailure = new Rate('business_failure');

export const options = {
  scenarios: {
    journey: {
      executor: 'per-vu-iterations',
      vus: 2,
      iterations: 2,
      maxDuration: '40s',
      exec: 'journey',
    },
  },
  thresholds: {
    business_failure: ['rate<=0.01'],
  },
  summaryTrendStats: ['avg', 'min', 'med', 'max', 'p(90)', 'p(95)'],
};

function jar() {
  return http.cookieJar();
}

function parseCsrfFromForm(body) {
  if (!body) return null;
  const m = body.match(/<input(?=[^>]*\bname=["']csrf["'])(?=[^>]*\bvalue=["']([^"']+)["'])[^>]*>/i);
  return m ? m[1] : null;
}

function getHeader(res, name) {
  const h = res.headers[name] || res.headers[name.toLowerCase()];
  return h || null;
}

function isExpired(res) {
  try {
    const b = res.json();
    return b && b.error === 'expired';
  } catch (e) {
    return false;
  }
}

function isSessionRevoked(res) {
  try {
    const b = res.json();
    return b && b.error === 'session';
  } catch (e) {
    return false;
  }
}

function isDenied(res) {
  try {
    const b = res.json();
    return b && b.error === 'denied';
  } catch (e) {
    return false;
  }
}

function recordBusiness(res, expected) {
  // Count business responses; numerator = unexpected failures excluding expected expiry/scheduled429
  if (res.status === 429) {
    // scheduled429 expected, not a failure
    businessFailure.add(false);
    return;
  }
  if (res.status === 401 && (isExpired(res) || isSessionRevoked(res))) {
    // expected expiry, not a failure
    businessFailure.add(false);
    return;
  }
  if (res.status >= 200 && res.status < 300) {
    businessFailure.add(false);
    return;
  }
  businessFailure.add(true);
}

function sleepMs(ms) {
  const end = Date.now() + ms;
  while (Date.now() < end) {
    // busy wait minimal; k6 has no sub-second sleep
  }
}

function doLogin(user) {
  const cj = jar();
  const params = { jar: cj, redirects: 0, tags: { name: 'login-form' } };
  let res = http.get(`${BASE}/v2/login-form`, params);
  check(res, { 'login-form 200': (r) => r.status === 200 });
  let csrf = parseCsrfFromForm(res.body);

  const loginBody = JSON.stringify({ username: user, password: 'bench', csrf: csrf });
  const loginParams = {
    jar: cj,
    redirects: 0,
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf || '' },
    tags: { name: 'login' },
  };
  res = http.post(`${BASE}/v2/login`, loginBody, loginParams);
  recordBusiness(res, true);

  let sessionCsrf = csrf;
  if (res.status === 302) {
    const loc = getHeader(res, 'Location');
    if (loc) {
      const followParams = { jar: cj, redirects: 0, tags: { name: 'login-redirect' } };
      const r2 = http.get(loc.startsWith('http') ? loc : `${BASE}${loc}`, followParams);
      try {
        const b = r2.json();
        if (b && b.csrf) sessionCsrf = b.csrf;
      } catch (e) {}
    }
  } else {
    try {
      const b = res.json();
      if (b && b.csrf) sessionCsrf = b.csrf;
    } catch (e) {}
  }
  return { jar: cj, csrf: sessionCsrf };
}

function renewSession(ctx) {
  const params = {
    jar: ctx.jar,
    redirects: 0,
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': ctx.csrf || '' },
    tags: { name: 'renew' },
  };
  const res = http.post(`${BASE}/v2/session/renew`, '{}', params);
  recordBusiness(res, true);
  if (res.status >= 200 && res.status < 300) {
    try {
      const b = res.json();
      if (b && b.csrf) ctx.csrf = b.csrf;
    } catch (e) {}
    return true;
  }
  return false;
}

function recoverCart(ctx, cartId) {
  if (!cartId) return;
  const params = {
    jar: ctx.jar,
    redirects: 0,
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': ctx.csrf || '' },
    tags: { name: 'recover' },
  };
  const res = http.post(`${BASE}/v2/carts/${cartId}/recover`, '{}', params);
  recordBusiness(res, true);
  if (res.status >= 200 && res.status < 300) {
    try {
      const b = res.json();
      if (b && b.csrf) ctx.csrf = b.csrf;
    } catch (e) {}
  }
}

function handleAuthError(ctx, res, cartId) {
  if (res.status !== 401) return false;
  if (isExpired(res)) {
    if (renewSession(ctx)) {
      if (cartId) recoverCart(ctx, cartId);
      return true;
    }
    return false;
  }
  if (isSessionRevoked(res)) {
    // renew may fail; get fresh form/login, recover cart
    const fresh = doLogin(ctx.user);
    ctx.jar = fresh.jar;
    ctx.csrf = fresh.csrf;
    if (cartId) recoverCart(ctx, cartId);
    return true;
  }
  if (isDenied(res)) {
    check(res, { 'denied is not expiry': () => false });
    return false;
  }
  return false;
}

function getCatalog(ctx) {
  const params = {
    jar: ctx.jar,
    redirects: 0,
    headers: { 'X-CSRF-Token': ctx.csrf || '' },
    tags: { name: 'catalog' },
  };
  let res = http.get(`${BASE}/v2/catalog`, params);
  recordBusiness(res, true);
  if (handleAuthError(ctx, res, null)) {
    res = http.get(`${BASE}/v2/catalog`, params);
    recordBusiness(res, true);
  }
  let product = null;
  let variant = null;
  try {
    const b = res.json();
    if (b && b.csrf) ctx.csrf = b.csrf;
    if (b && b.data && b.data.products) {
      for (const p of b.data.products) {
        if (p.variants && p.variants.length) {
          for (const v of p.variants) {
            if (v.in_stock) {
              product = p.id;
              variant = v.id;
              break;
            }
          }
        }
        if (product) break;
      }
    }
  } catch (e) {}
  return { product, variant };
