  recordBusiness(res, true);
  if (handleAuthError(ctx, res, null)) {
    res = http.get(`${BASE}/v2/challenge-form`, params);
    recordBusiness(res, true);
  }
  let action = null;
  let challenge = null;
  if (res.body) {
    const am = res.body.match(/action=["']([^"']+)["']/i);
    if (am) action = am[1];
    const cm = res.body.match(/<input(?=[^>]*\bname=["']challenge["'])(?=[^>]*\bvalue=["']([^"']+)["'])[^>]*>/i);
    if (cm) challenge = cm[1];
  }
