  recordBusiness(r2, true);
  if (handleAuthError(ctx, r2, null)) {
    r2 = http.post(action.startsWith('http') ? action : `${BASE}${action}`, body, postParams);
    recordBusiness(r2, true);
  }
  let grant = null;
  if (r2.status === 302) {
    const loc = getHeader(r2, 'Location');
    if (loc) {
      const followParams = { jar: ctx.jar, redirects: 0, tags: { name: 'challenge-follow' } };
      const r3 = http.get(loc.startsWith('http') ? loc : `${BASE}${loc}`, followParams);
      recordBusiness(r3, true);
      try {
        const b = r3.json();
        if (b && b.csrf) ctx.csrf = b.csrf;
        if (b && b.grant_id) grant = b.grant_id;
      } catch (e) {}
    }
  } else {
    try {
      const b = r2.json();
      if (b && b.csrf) ctx.csrf = b.csrf;
      if (b && b.grant_id) grant = b.grant_id;
    } catch (e) {}
  }
  return grant;
}

function createCart(ctx, product, variant, grant) {
  const body = { product_id: product, variant_id: variant };
  if (grant) body.grant_id = grant;
  const params = {
    jar: ctx.jar,
    redirects: 0,
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': ctx.csrf || '' },
    tags: { name: 'cart-create' },
  };
  let res = http.post(`${BASE}/v2/carts`, JSON.stringify(body), params);
  recordBusiness(res, true);
  if (handleAuthError(ctx, res, null)) {
    res = http.post(`${BASE}/v2/carts`, JSON.stringify(body), params);
    recordBusiness(res, true);
  }
