function patchCart(ctx, cartId, etag, quantity) {
  const params = {
    jar: ctx.jar,
    redirects: 0,
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': ctx.csrf || '',
      'If-Match': etag || '',
    },
    tags: { name: 'cart-patch' },
  };
  const body = JSON.stringify({ quantity: quantity });
  let res = http.patch(`${BASE}/v2/carts/${cartId}`, body, params);
  recordBusiness(res, true);
  if (res.status === 412) {
    // re-read and retry same payload once
    const getParams = {
      jar: ctx.jar,
      redirects: 0,
      headers: { 'X-CSRF-Token': ctx.csrf || '' },
      tags: { name: 'cart-get' },
    };
    const r2 = http.get(`${BASE}/v2/carts/${cartId}`, getParams);
    recordBusiness(r2, true);
    const newEtag = getHeader(r2, 'ETag');
    if (newEtag) {
      params.headers['If-Match'] = newEtag;
      res = http.patch(`${BASE}/v2/carts/${cartId}`, body, params);
      recordBusiness(res, true);
    }
  } else if (handleAuthError(ctx, res, cartId)) {
    res = http.patch(`${BASE}/v2/carts/${cartId}`, body, params);
    recordBusiness(res, true);
  }
  const newEtag = getHeader(res, 'ETag');
  try {
    const b = res.json();
    if (b && b.csrf) ctx.csrf = b.csrf;
  } catch (e) {}
  return { etag: newEtag || etag };
}

function createReservation(ctx, cartId) {
  const params = {
    jar: ctx.jar,
    redirects: 0,
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': ctx.csrf || '' },
    tags: { name: 'reservation' },
  };
  const body = JSON.stringify({ cart_id: cartId });
  let res = http.post(`${BASE}/v2/reservations`, body, params);
  recordBusiness(res, true);
  if (handleAuthError(ctx, res, cartId)) {
    res = http.post(`${BASE}/v2/reservations`, body, params);
    recordBusiness(res, true);
  }
  let statusUrl = null;
  try {
    const b = res.json();
    if (b && b.csrf) ctx.csrf = b.csrf;
    if (b && b.status_url) statusUrl = b.status_url;
  } catch (e) {}
  if (!statusUrl) return null;

  let reservationId = null;
  for (let i = 0; i < 5; i++) {
    if (i > 0) sleepMs(60);
    const pollParams = {
      jar: ctx.jar,
      redirects: 0,
      headers: { 'X-CSRF-Token': ctx.csrf || '' },
      tags: { name: 'reservation-poll' },
    };
    const pr = http.get(statusUrl.startsWith('http') ? statusUrl : `${BASE}${statusUrl}`, pollParams);
    recordBusiness(pr, true);
    try {
      const b = pr.json();
      if (b && b.csrf) ctx.csrf = b.csrf;
      if (b && b.status === 'ready' && b.reservation_id) {
        reservationId = b.reservation_id;
        break;
      }
      if (b && (b.status === 'failed')) break;
    } catch (e) {}
  }
  return reservationId;
}

function placeOrder(ctx, cartId, etag, reservationId) {
  const body = { cart_id: cartId };
  if (reservationId) body.reservation_id = reservationId;
  const idemKey = `idem-${cartId}-${Date.now()}`;
  const headers = {
    'Content-Type': 'application/json',
    'X-CSRF-Token': ctx.csrf || '',
    'Idempotency-Key': idemKey,
  };
  if (etag) headers['If-Match'] = etag;
  const params = {
    jar: ctx.jar,
    redirects: 0,
    headers: headers,
    tags: { name: 'orders' },
  };
  let res = http.post(`${BASE}/v2/orders`, JSON.stringify(body), params);
  recordBusiness(res, true);
  if (handleAuthError(ctx, res, cartId)) {
    res = http.post(`${BASE}/v2/orders`, JSON.stringify(body), params);
    recordBusiness(res, true);
  }
  let committed = false;
  try {
    const b = res.json();
    if (b && b.csrf) ctx.csrf = b.csrf;
    if (res.status === 201 && b && b.accepted === true) committed = true;
  } catch (e) {}
  return committed;
}

export function journey() {
  const vu = __VU;
  const user = `bench-${((vu - 1) % 16) + 1}`;
  const ctx = { user: user, jar: null, csrf: null };

  const login = doLogin(user);
  ctx.jar = login.jar;
  ctx.csrf = login.csrf;

  const cat = getCatalog(ctx);
  if (!cat.product || !cat.variant) {
    check(null, { 'catalog has in-stock product': () => false });
    return;
  }

  const grant = getChallenge(ctx);

  const cart = createCart(ctx, cat.product, cat.variant, grant);
  if (!cart.cartId) {
    check(null, { 'cart created': () => false });
    return;
  }

  const patched = patchCart(ctx, cart.cartId, cart.etag, 2);

  const reservationId = createReservation(ctx, cart.cartId);

  const committed = placeOrder(ctx, cart.cartId, patched.etag, reservationId);
  if (committed) {
    checkoutStarts.add(1);
  }
  check(null, { 'order committed': () => committed });
}
