BASE_URL = os.environ.get("BASE_URL", "http://127.0.0.1:8000")


def _extract_csrf_from_form(text):
    if not text:
        return None
    # find input tags with name=csrf and capture value
    for m in re.finditer(r"<input\b[^>]*>", text, re.IGNORECASE):
        tag = m.group(0)
        if re.search(r"""name\s*=\s*["']csrf["']""", tag, re.IGNORECASE):
            vm = re.search(r"""value\s*=\s*["']([^"']*)["']""", tag, re.IGNORECASE)
            if vm:
