            "/v2/session/renew",
            json={},
            headers=self._headers(),
            catch_response=True,
            name="POST /v2/session/renew",
        ) as r:
            if r.status_code == 200:
                try:
                    j = r.json()
                except Exception:
                    j = {}
                if j.get("csrf"):
