                    r.success()
                    return rid
                if st in ("pending",):
                    r.success()
                    continue
                # failed
                r.failure(f"reservation status {st}")
                return None
        return None

    def _checkout(self, cart_id, reservation_id):
        idem = f"idem-{cart_id}-{uuid.uuid4().hex[:8]}"
        body = {"cart_id": cart_id}
        if reservation_id:
            body["reservation_id"] = reservation_id

