                    return "fail"
                if j.get("csrf"):
                    self.csrf = j["csrf"]
                if j.get("accepted") is not True:
                    r.failure("order not accepted")
                    return "fail"
                r.success()
                return "ok"

        res = _do()
        if res == "401":
            res = _do()
        return res == "ok"

    # ---------- main task ----------
    @task
    def journey(self):
        if self.iterations_done >= self.max_iterations:
            raise StopUser()

        if not self._login():
            self.iterations_done += 1
            if self.iterations_done >= self.max_iterations:
                raise StopUser()
            return

        prod = self._get_catalog()
        if not prod:
            self.iterations_done += 1
            if self.iterations_done >= self.max_iterations:
                raise StopUser()
            return
        product_id, variant_id = prod

        grant_id = self._get_challenge_grant()

        cart_id = self._create_cart(product_id, variant_id, grant_id)
        if not cart_id:
            self.iterations_done += 1
            if self.iterations_done >= self.max_iterations:
                raise StopUser()
            return

        if not self._patch_quantity(cart_id, 2):
            self.iterations_done += 1
            if self.iterations_done >= self.max_iterations:
                raise StopUser()
            return

        reservation_id = self._reserve(cart_id)
        if not reservation_id:
            self.iterations_done += 1
            if self.iterations_done >= self.max_iterations:
                raise StopUser()
            return

        self._checkout(cart_id, reservation_id)

        self.iterations_done += 1
        if self.iterations_done >= self.max_iterations:
            raise StopUser()


class PhasedShape(LoadTestShape):
    """
    Phased targets 5/15/5 over three 10s scored plateaus.
    Warmup 5s, score window [T0+5, T0+35), drain <=5s.
    Total duration ~40s. Users capped at 4 (max_vus).
    """

    def tick(self):
        run_time = self.get_run_time()
        # warmup 5s
        if run_time < 5:
            return (2, 2)
        # plateau 1: 5s..15s target 5 (capped at 4 users)
        if run_time < 15:
            return (4, 4)
        # plateau 2: 15s..25s target 15 (capped at 4 users)
        if run_time < 25:
            return (4, 4)
        # plateau 3: 25s..35s target 5 (capped at 4 users)
        if run_time < 35:
            return (4, 4)
        # drain <=5s
        if run_time < 40:
            return (2, 2)
        return None
