import io.gatling.javaapi.core.*;
import io.gatling.javaapi.http.*;

import java.util.*;

import static io.gatling.javaapi.core.CoreDsl.*;
import static io.gatling.javaapi.http.HttpDsl.*;

public class ModelSimulation extends Simulation {

    private static final String BASE_URL = System.getenv("BASE_URL") != null
            ? System.getenv("BASE_URL") : "http://127.0.0.1:8000";

    private static final HttpProtocolBuilder HTTP = http
            .baseUrl(BASE_URL)
            .disableAutoReferer()
            .disableFollowRedirect()
            .disableCaching()
            .shareConnections()
            .acceptHeader("application/json")
            .contentTypeHeader("application/json");

    // ---- helpers ---------------------------------------------------------

    private static final String CSRF_FORM_REGEX =
            "<input(?=[^>]*\\bname=[\"']csrf[\"'])(?=[^>]*\\bvalue=[\"']([^\"']+)[\"'])[^>]*>";

    private static final String EXPIRED_REGEX = "\"error\"\\s*:\\s*\"(?:expired|session)\"";

    // ---- chains ----------------------------------------------------------

    private static ChainBuilder loginForm() {
        return exec(
                http("GET /v2/login-form")
                        .get("/v2/login-form")
                        .check(status().is(200))
                        .check(regex(CSRF_FORM_REGEX).find(1).saveAs("form"))
        );
    }

    private static ChainBuilder login(String user) {
        return exec(
                http("POST /v2/login")
                        .post("/v2/login")
                        .body(StringBody(session ->
                                "{\"username\":\"" + user + "\",\"password\":\"bench\",\"csrf\":\""
                                        + session.getString("form") + "\"}"))
                        .check(status().in(200, 302))
                        .check(bodyString().saveAs("loginBody"))
                        .check(header("Location").optional().saveAs("location"))
                        .check(jsonPath("$.csrf").optional().saveAs("csrf"))
        ).exec(session -> {
            String loc = session.getString("location");
            String csrf = session.getString("csrf");
            if (loc != null && !loc.isEmpty()) {
                return session.set("needRedirect", true);
            }
            return session.set("needRedirect", false);
        }).doIf(session -> Boolean.TRUE.equals(session.get("needRedirect"))).then(
                exec(
                        http("GET login redirect")
                                .get(session -> session.getString("location"))
                                .check(status().is(200))
                                .check(jsonPath("$.csrf").saveAs("csrf"))
                                .check(jsonPath("$.grant_id").optional().saveAs("grant"))
                )
        );
    }

    private static ChainBuilder catalog() {
        return exec(
                http("GET /v2/catalog")
                        .get("/v2/catalog")
                        .check(status().is(200))
                        .check(jsonPath("$.data.products[?(@.variants[0].in_stock == true)].id")
                                .find(1).saveAs("product"))
                        .check(jsonPath("$.data.products[?(@.variants[0].in_stock == true)].variants[0].id")
                                .find(1).saveAs("variant"))
        );
    }

    private static ChainBuilder createCart() {
        return exec(
                http("POST /v2/carts")
                        .post("/v2/carts")
                        .header("X-CSRF-Token", session -> session.getString("csrf"))
                        .body(StringBody(session -> {
                            String grant = session.getString("grant");
                            String base = "{\"product_id\":\"" + session.getString("product")
                                    + "\",\"variant_id\":\"" + session.getString("variant") + "\"";
                            if (grant != null && !grant.isEmpty() && !"MISSING".equals(grant)) {
                                base += ",\"grant_id\":\"" + grant + "\"";
                            }
                            return base + "}";
                        }))
                        .check(status().is(201))
                        .check(jsonPath("$.id").saveAs("cart"))
                        .check(jsonPath("$.csrf").optional().saveAs("csrfNew"))
                        .check(header("ETag").optional().saveAs("etag"))
        ).exec(session -> {
            String c = session.getString("csrfNew");
            return c != null ? session.set("csrf", c) : session;
        });
    }

    private static ChainBuilder placeOrder() {
        return exec(
                http("POST /v2/orders")
                        .post("/v2/orders")
                        .header("X-CSRF-Token", session -> session.getString("csrf"))
                        .header("Idempotency-Key", session -> session.getString("cart"))
                        .header("If-Match", session -> {
                            String e = session.getString("etag");
                            return e != null ? e : "";
                        })
                        .body(StringBody(session ->
                                "{\"cart_id\":\"" + session.getString("cart") + "\"}"))
                        .check(status().is(201))
                        .check(jsonPath("$.accepted").is("true"))
                        .check(jsonPath("$.id").exists())
                        .check(jsonPath("$.csrf").optional().saveAs("csrfNew"))
        ).exec(session -> {
            String c = session.getString("csrfNew");
            return c != null ? session.set("csrf", c) : session;
        });
    }

    // ---- scenario --------------------------------------------------------

    private static final ScenarioBuilder SCENARIO = scenario("ModelSimulation")
            .exec(session -> session.set("csrf", "").set("grant", "").set("etag", ""))
            .exec(loginForm())
            .exec(login("bench"))
            .exec(catalog())
            .exec(createCart())
            .exec(placeOrder());

    {
        setUp(
                SCENARIO.injectClosed(
                        constantConcurrentUsers(2).during(1)
                ).protocols(HTTP)
        ).assertions(
                global().failedRequests().count().is(0L)
        );
    }
}
