```javascript
import http from 'k6/http';
import { check, group, sleep } from 'k6';
import { Counter, Rate, Trend } from 'k6/metrics';
import { randomIntBetween } from 'https://jslib.k6.io/k6-utils/1.4.0/index.js';

const BASE = __ENV.BASE_URL || 'http://127.0.0.1:8000';

// ---- Custom metrics (transaction-level tagging) ----
const businessFailure = new Rate('business_failure');
const unexpectedFailure = new Counter('unexpected_failure');
const expectedExpiry = new Counter('expected_expiry');
const scheduled429 = new Counter('scheduled_429');
const journeySuccess = new Rate('journey_success');
const orderCommitted = new Counter('order_committed');
const cartCreated = new Counter('cart_created');
const duplicateCart = new Counter('duplicate_cart');
const loginOk = new Rate('login_ok');
const catalogOk = new Rate('catalog_ok');
const cartOk = new Rate('cart_ok');
const orderOk = new Rate('order_ok');
const challengeOk = new Rate('challenge_ok');
const reservationOk = new Rate('reservation_ok');
const workOk = new Rate('work_ok');
const checkoutLatency = new Trend('checkout_latency', true);

// ---- Execution contract ----
export const options = {
  scenarios: {
    journey: {
      executor: 'per-vu-iterations',
      vus: 2,
      iterations: 2,
      maxDuration: '5m',
    },
  },
  thresholds: {
    // Safety: threshold scope/denominator exactly match contract.
    // business_failure denominator = all business responses (incl. expected expiry).
    // numerator = unexpected failures (excl. expected expiry / scheduled 429).
    'business_failure': ['rate<0.05'],
    'journey_success': ['rate>0.95'],
    'http_req_failed': ['rate<0.10'],
    'checks': ['rate>0.95'],
  },
  // Disable auto redirects globally; we follow dynamic Location manually.
  noConnectionReuse: false,
  discardResponseBodies: false,
};

// ---- Fixture variants (two count equally) ----
const PROFILES = [
  {},
  { html_layout: 1, reverse_catalog: true },
];

// ---- Negative-control overrides ----
const NEGATIVE_CONTROLS = [
  { decline_orders: true },
];

function pickProfile(vu, iter) {
  // Alternate profiles so both variants count equally.
  return PROFILES[(vu + iter) % PROFILES.length];
}

function pickNegativeControl(vu, iter) {
  // Apply negative control on a deterministic subset so both success and
  // business-failure controls retain source outcomes.
  return NEGATIVE_CONTROLS[(vu + iter) % NEGATIVE_CONTROLS.length];
}

// ---- Per-VU cookie jar (preserve per-user cookies) ----
function makeJar() {
  return http.cookieJar();
}

// ---- Helpers ----
function parseCsrfFromForm(html) {
  if (!html) return null;
  // input[name=csrf] mixed with decoys/attribute variants.
  const re = /<input\b[^>]*\bname\s*=\s*["']csrf["'][^>]*>/gi;
  let m;
  while ((m = re.exec(html)) !== null) {
    const tag = m[0];
    const vm = tag.match(/\bvalue\s*=\s*["']([^"']+)["']/i);
    if (vm) return vm[1];
  }
  // Fallback: value before name.
  const re2 = /<input\b[^>]*\bvalue\s*=\s*["']([^"']+)["'][^>]*\bname\s*=\s*["']csrf["'][^>]*>/gi;
  while ((m = re2.exec(html)) !== null) {
    return m[1];
  }
  return null;
}

function parseChallengeForm(html) {
  if (!html) return null;
  const actionM = html.match(/<form\b[^>]*\baction\s*=\s*["']([^"']*\/v2\/challenges\/[^"']+)["']/i);
  const inputM = html.match(/<input\b[^>]*\bname\s*=\s*["']challenge["'][^>]*>/i);
  let challengeVal = null;
  if (inputM) {
    const vm = inputM[0].match(/\bvalue\s*=\s*["']([^"']+)["']/i);
    if (vm) challengeVal = vm[1];
  }
  if (!actionM) return null;
  return { action: actionM[1], challenge: challengeVal };
}

function getHeader(res, name) {
  const h = res.headers[name] || res.headers[name.toLowerCase()];
  return h || null;
}

function isExpired(res) {
  try {
    const b = res.json();
    return b && b.error === 'expired';
  } catch (e) {
    return false;
  }
}

function isSessionRevoked(res) {
  try {
    const b = res.json();
    return b && b.error === 'session';
  } catch (e) {
    return false;
  }
}

function isDenied(res) {
  try {
    const b = res.json();
    return b && b.error === 'denied';
  } catch (e) {
    return false;
  }
}

function recordBusiness(res, expected) {
  // Denominator: all business responses including expected expiry.
  // Numerator: unexpected failures excluding expected expiry / scheduled 429.
  if (res.status === 429) {
    scheduled429.add(1);
    businessFailure.add(false);
    return;
  }
  if (res.status === 401 && (isExpired(res) || isSessionRevoked(res))) {
    expectedExpiry.add(1);
    businessFailure.add(false);
    return;
  }
  if (res.status >= 500) {
    unexpectedFailure.add(1);
    businessFailure.add(true);
    return;
  }
  if (expected) {
    businessFailure.add(false);
  } else {
    unexpectedFailure.add(1);
    businessFailure.add(true);
  }
}

function sleepRetryAfter(res) {
  const ra = getHeader(res, 'Retry-After');
  const secs = ra ? parseFloat(ra) : 1;
  sleep(Math.max(0.05, isNaN(secs) ? 1 : secs));
}

// ---- Session / auth ----
function freshLogin(jar, username) {
  const formRes = http.get(`${BASE}/v2/login-form`, { jar, redirects: 0, tags: { name: 'login-form' } });
  const csrfForm = parseCsrfFromForm(formRes.body);
  check(formRes, { 'login-form 200': (r) => r.status === 200 });
  check(csrfForm, { 'login-form csrf present': (v) => !!v });

  const loginRes = http.post(
    `${BASE}/v2/login`,
    JSON.stringify({ username, password: 'bench', csrf: csrfForm }),
    { jar, redirects: 0, headers: { 'Content-Type': 'application/json' }, tags: { name: 'login' } }
  );

  let csrf = null;
  let user = null;
  if (loginRes.status === 302) {
    const loc = getHeader(loginRes, 'Location');
    if (loc) {
      const followRes = http.get(loc.startsWith('http') ? loc : `${BASE}${loc}`, {
        jar, redirects: 0, tags: { name: 'login-redirect' },
      });
      try {
        const b = followRes.json();
        csrf = b.csrf;
        user = b.user;
      } catch (e) { /* ignore */ }
    }
  } else {
    try {
      const b = loginRes.json();
      csrf = b.csrf;
      user = b.user;
    } catch (e) { /* ignore */ }
  }

  const ok = !!(csrf && user);
  loginOk.add(ok);
  check(loginRes, { 'login ok': () => ok });
  return { csrf, user, ok };
}

function renewSession(jar, csrf) {
  const res = http.post(`${BASE}/v2/session/renew`, '{}', {
    jar, redirects: 0,
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf || '' },
    tags: { name: 'session-renew' },
  });
  let newCsrf = csrf;
  try {
    const b = res.json();
    if (b && b.csrf) newCsrf = b.csrf;
  } catch (e) { /* ignore */ }
  return { res, csrf: newCsrf };
}

function recoverCart(jar, csrf, cartId) {
  if (!cartId) return { res: null, csrf };
  const res = http.post(`${BASE}/v2/carts/${cartId}/recover`, '{}', {
    jar, redirects: 0,
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf || '' },
    tags: { name: 'cart-recover' },
  });
  let newCsrf = csrf;
  try {
    const b = res.json();
    if (b && b.csrf) newCsrf = b.csrf;
  } catch (e) { /* ignore */ }
  return { res, csrf: newCsrf };
}

// ---- Catalog ----
function fetchCatalog(jar, csrf, profile) {
  const res = http.get(`${BASE}/v2/catalog`, {
    jar, redirects: 0,
    headers: { 'X-CSRF-Token': csrf || '' },
    tags: { name: 'catalog' },
  });
  let products = [];
  try {
    const b = res.json();
    if (b && b.data && Array.isArray(b.data.products)) products = b.data.products;
  } catch (e) { /* ignore */ }

  // Traverse at most 3 pages via /v2/catalog/page.
  let next = null;
  try {
    const b = res.json();
    next = b && b.next;
  } catch (e) { /* ignore */ }

  let pages = 0;
  while (next && pages < 3) {
    const url = next.startsWith('http') ? next : `${BASE}${next}`;
    const pRes = http.get(url, {
      jar, redirects: 0,
      headers: { 'X-CSRF-Token': csrf || '' },
      tags: { name: 'catalog-page' },
    });
    try {
      const b = pRes.json();
      if (b && b.data && Array.isArray(b.data.products)) {
        products = products.concat(b.data.products);
      }
      next = b && b.next;
    } catch (e) {
      next = null;
    }
    pages++;
  }

  if (profile && profile.reverse_catalog) products = products.slice().reverse();

  const ok = products.length > 0;
  catalogOk.add(ok);
  check(res, { 'catalog ok': () => ok });
  return { products, ok };
}

function pickInStockVariant(products) {
  for (const p of products) {
    if (!p || !Array.isArray(p.variants)) continue;
    for (const v of p.variants) {
      if (v && v.in_stock) return { product: p.id, variant: v.id };
    }
  }
  return null;
}

// ---- Challenge / grant ----
function obtainGrant(jar, csrf) {
  const formRes = http.get(`${BASE}/v2/challenge-form`, {
    jar, redirects: 0,
    headers: { 'X-CSRF-Token': csrf || '' },
    tags: { name: 'challenge-form' },
  });
  const parsed = parseChallengeForm(formRes.body);
  if (!parsed || !parsed.action) {
    challengeOk.add(false);
    return { grant: null, csrf };
  }
  const actionUrl = parsed.action.startsWith('http') ? parsed.action : `${BASE}${parsed.action}`;
  const postRes = http.post(actionUrl, JSON.stringify({ challenge: parsed.challenge }), {
    jar, redirects: 0,
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf || '' },
    tags: { name: 'challenge-post' },
  });
  let newCsrf = csrf;
  let grant = null;
  if (postRes.status === 302) {
    const loc = getHeader(postRes, 'Location');
    if (loc) {
      const followRes = http.get(loc.startsWith('http') ? loc : `${BASE}${loc}`, {
        jar, redirects: 0, tags: { name: 'challenge-redirect' },
      });
      try {
        const b = followRes.json();
        grant = b.grant_id;
        if (b.csrf) newCsrf = b.csrf;
      } catch (e) { /* ignore */ }
    }
  } else {
    try {
      const b = postRes.json();
      grant = b.grant_id;
      if (b.csrf) newCsrf = b.csrf;
    } catch (e) { /* ignore */ }
  }
  const ok = !!grant;
  challengeOk.add(ok);
  check(postRes, { 'challenge grant': () => ok });
  return { grant, csrf: newCsrf };
}

// ---- Cart ----
function createCart(jar, csrf, product, variant, grant) {
  const body = { product_id: product, variant_id: variant };
  if (grant) body.grant_id = grant;
  const res = http.post(`${BASE}/v2/carts`, JSON.stringify(body), {
    jar, redirects: 0,
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf || '' },
    tags: { name: 'cart-create' },
  });
  let cartId = null;
  let newCsrf = csrf;
  let etag = getHeader(res, 'ETag');
  try {
    const b = res.json();
    if (b && b.id) cartId = b.id;
    if (b && b.csrf) newCsrf = b.csrf;
  } catch (e) { /* ignore */ }
  const ok = res.status === 201 && !!cartId;
  cartOk.add(ok);
  if (ok) cartCreated.add(1);
  check(res, { 'cart created 201': () => ok });
  return { cartId, csrf: newCsrf, etag, res };
}

function patchCartQuantity(jar, csrf, cartId, etag, quantity) {
  const url = `${BASE}/v2/carts/${cartId}`;
  const headers = {
    'Content-Type': 'application/json',
    'X-CSRF-Token': csrf || '',
    'If-Match': etag || '',
  };
  let res = http.patch(url, JSON.stringify({ quantity }), {
    jar, redirects: 0, headers, tags: { name: 'cart-patch' },
  });
  let newEtag = getHeader(res, 'ETag') || etag;
  let newCsrf = csrf;
  try {
    const b = res.json();
    if (b && b.csrf) newCsrf = b.csrf;
  } catch (e) { /* ignore */ }

  if (res.status === 412) {
    // Re-read and retry the same payload once.
    const readRes = http.get(url, {
      jar, redirects: 0,
      headers: { 'X-CSRF-Token': newCsrf || '' },
      tags: { name: 'cart-read' },
    });
    newEtag = getHeader(readRes, 'ETag') || newEtag;
    res = http.patch(url, JSON.stringify({ quantity }), {
      jar, redirects: 0,
      headers: {
        'Content-Type': 'application/json',
        'X-CSRF-Token': newCsrf || '',
        'If-Match': newEtag || '',
      },
      tags: { name: 'cart-patch-retry' },
    });
    newEtag = getHeader(res, 'ETag') || newEtag;
    try {
      const b = res.json();
      if (b && b.csrf) newCsrf = b.csrf;
    } catch (e) { /* ignore */ }
  }

  const ok = res.status === 200 || res.status === 204;
  check(res, { 'cart patch ok': () => ok });
  return { ok, csrf: newCsrf, etag: newEtag, res };
}

// ---- Reservation ----
function reserveCart(jar, csrf, cartId) {
  const res = http.post(`${BASE}/v2/reservations`, JSON.stringify({ cart_id: cartId }), {
    jar, redirects: 0,
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf || '' },
    tags: { name: 'reservation-create' },
  });
  let statusUrl = null;
  let newCsrf = csrf;
  try {
    const b = res.json();
    if (b && b.status_url) statusUrl = b.status_url;
    if (b && b.csrf) newCsrf = b.csrf;
  } catch (e) { /* ignore */ }

  if (res.status !== 202 || !statusUrl) {
    reservationOk.add(false);
    check(res, { 'reservation 202': () => false });
    return { reservationId: null, csrf: newCsrf, ok: false };
  }

  // Poll at least 50ms apart, at most 5 times.
  let reservationId = null;
  let status = null;
  for (let i = 0; i < 5; i++) {
    sleep(0.05);
    const url = statusUrl.startsWith('http') ? statusUrl : `${BASE}${statusUrl}`;
    const pRes = http.get(url, {
      jar, redirects: 0,
      headers: { 'X-CSRF-Token': newCsrf || '' },
      tags: { name: 'reservation-poll' },
    });
    try {
      const b = pRes.json();
      status = b && b.status;
      if (b && b.csrf) newCsrf = b.csrf;
      if (status === 'ready' && b.reservation_id) {
        reservationId = b.reservation_id;
        break;
      }
      if (status === 'failed') break;
    } catch (e) { /* ignore */ }
  }

  const ok = status === 'ready' && !!reservationId;
  reservationOk.add(ok);
  check(res, { 'reservation ready': () => ok });
  return { reservationId, csrf: newCsrf, ok };
}

// ---- Order ----
function placeOrder(jar, csrf, cartId, etag, reservationId, idemKey, decline) {
  const body = { cart_id: cartId };
  if (reservationId) body.reservation_id = reservationId;
  const headers = {
    'Content-Type': 'application/json',
    'X-CSRF-Token': csrf || '',
    'Idempotency-Key': idemKey,
  };
  if (etag) headers['If-Match'] = etag;

  const start = Date.now();
  let res = http.post(`${BASE}/v2/orders`, JSON.stringify(body), {
    jar, redirects: 0, headers, tags: { name: 'order-create' },
  });
  checkoutLatency.add(Date.now() - start);

  let newCsrf = csrf;
  try {
    const b = res.json();
    if (b && b.csrf) newCsrf = b.csrf;
  } catch (e) { /* ignore */ }

  // Handle expiry / session revocation with bounded recovery.
  if (res.status === 401 && (isExpired(res) || isSessionRevoked(res))) {
    const r = renewSession(jar, newCsrf);
    newCsrf = r.csrf;
    if (cartId) {
      const rc = recoverCart(jar, newCsrf, cartId);
      newCsrf = rc.csrf;
    }
    // Retry only the interrupted operation once.
    res = http.post(`${BASE}/v2/orders`, JSON.stringify(body), {
      jar, redirects: 0,
      headers: {
        'Content-Type': 'application/json',
        'X-CSRF-Token': newCsrf || '',
        'Idempotency-Key': idemKey,
        ...(etag ? { 'If-Match': etag } : {}),
      },
      tags: { name: 'order-create-retry' },
    });
    try {
      const b = res.json();
      if (b && b.csrf) newCsrf = b.csrf;
    } catch (e) { /* ignore */ }
  }

  let accepted = false;
  let orderId = null;
  try {
    const b = res.json();
    accepted = b && b.accepted === true;
    orderId = b && b.id;
  } catch (e) { /* ignore */ }

  // HTTP 200 accepted:false is a business failure, not success.
  const isBusinessFailure = res.status === 200 && !accepted;
  const isSuccess = res.status === 201 && accepted && !!orderId;

  if (decline) {
    // Negative control: order must NOT be committed.
    const ok = !isSuccess;
    orderOk.add(ok);
    check(res, { 'decline control: no commit': () => ok });
    return { ok, csrf: newCsrf, committed: false };
  }

  const ok = isSuccess;
  orderOk.add(ok);
  if (ok) orderCommitted.add(1);
  check(res, { 'order committed 201': () => ok });
  check(res, { 'order not business-failure': () => !isBusinessFailure });
  return { ok, csrf: newCsrf, committed: ok };
}

// ---- Work / browse (business responses) ----
function doWork(jar, csrf) {
  let attempts = 0;
  let res;
  while (attempts < 5) {
    res = http.post(`${BASE}/v2/work`, '{}', {
      jar, redirects: 0,
      headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf || '' },
      tags: { name: 'work' },
    });
    if (res.status === 429) {
      scheduled429.add(1);
      sleepRetryAfter(res);
      attempts++;
      continue;
    }
    break;
  }
  let ok = false;
  try {
    const b = res.json();
    ok = res.status === 200 && b && b.ok === true;
  } catch (e) { /* ignore */ }
  workOk.add(ok);
  recordBusiness(res, ok);
  check(res, { 'work ok': () => ok });
  return ok;
}

// ---- Journey ----
export default function () {
  const vu = __VU;
  const iter = __ITER;
  const profile = pickProfile(vu, iter);
  const negative = pickNegativeControl(vu, iter);
  const decline = !!(negative && negative.decline_orders);

  const jar = makeJar();
  const username = `bench-${((vu - 1) % 16) + 1}`;

  let journeyOk = true;

  group('login', () => {
    const auth = freshLogin(jar, username);
    if (!auth.ok) { journeyOk = false; return; }
    __state.csrf = auth.csrf;
  });
  if (!journeyOk) { journeySuccess.add(false); return; }

  let csrf = __state.csrf;

  group('catalog', () => {
    const cat = fetchCatalog(jar, csrf, profile);
    if (!cat.ok) { journeyOk = false; return; }
    const pick = pickInStockVariant(cat.products);
    if (!pick) { journeyOk = false; return; }
    __state.product = pick.product;
    __state.variant = pick.variant;
  });
  if (!journeyOk) { journeySuccess.add(false); return; }

  group('challenge', () => {
    const g = obtainGrant(jar, csrf);
    csrf = g.csrf;
    __state.grant = g.grant;
  });

  group('cart', () => {
    const c = createCart(jar, csrf, __state.product, __state.variant, __state.grant);
    csrf = c.csrf;
    if (!c.cartId) { journeyOk = false; return; }
    __state.cartId = c.cartId;
    __state.etag = c.etag;

    const p = patchCartQuantity(jar, csrf, c.cartId, c.etag, 2);
    csrf = p.csrf;
    __state.etag = p.etag;
    if (!p.ok) { journeyOk = false; return; }
  });
  if (!journeyOk) { journeySuccess.add(false); return; }

  group('reservation', () => {
    const r = reserveCart(jar, csrf, __state.cartId);
    csrf = r.csrf;
    __state.reservationId = r.reservationId;
    if (!r.ok) { journeyOk = false; return; }
  });
  if (!journeyOk) { journeySuccess.add(false); return; }

  group('order', () => {
    const idemKey = `idem-${__state.cartId}-${vu}-${iter}`;
    const o = placeOrder(
      jar, csrf, __state.cartId, __state.etag,
      __state.reservationId, idemKey, decline
    );
    csrf = o.csrf;
    if (!o.ok) { journeyOk = false; return; }
  });

  group('work', () => {
    doWork(jar, csrf);
  });

  journeySuccess.add(journeyOk);
}

