                reservation_id = sdata.get("reservation_id")
                if not reservation_id:
                    sr.failure("reservation ready without id")
                    return None, csrf
                sr.success()
                return reservation_id, sdata.get("csrf", csrf)
            if status in ("pending",):
                sr.success()
                continue
            sr.failure("reservation status %s" % status)
            return None, csrf
        return None, csrf

    def _order(self, csrf, cart_id, etag, reservation_id):
        body = {"cart_id": cart_id}
        if reservation_id:
            body["reservation_id"] = reservation_id
        headers = {"X-CSRF-Token": csrf, "Idempotency-Key": cart_id}
        if etag:
            headers["If-Match"] = etag
        with self.client.post(
            "/v2/orders",
            json=body,
            headers=headers,
            name="POST /v2/orders",
            catch_response=True,
        ) as r:
            if r.status_code == 200:
                try:
                    data = r.json()
                except Exception:
                    r.failure("order not json")
                    return False
                if data.get("accepted") is False:
                    r.failure("order business failure accepted=false")
                    return False
                r.failure("order 200 without accepted=true")
                return False
            if r.status_code != 201:
                r.failure("order status %s" % r.status_code)
                return False
            try:
                data = r.json()
            except Exception:
                r.failure("order not json")
                return False
            if data.get("accepted") is not True:
                r.failure("order missing accepted=true")
                return False
            if not data.get("id"):
                r.failure("order missing id")
                return False
            r.success()
            return True

    # ---- journey -------------------------------------------------------
    @task
    def journey(self):
        if self.iterations_done >= MAX_ITERATIONS:
            raise StopUser()

        csrf = self._login()
        if not csrf:
            self.iterations_done += 1
            if self.iterations_done >= MAX_ITERATIONS:
                raise StopUser()
            return

        picked = self._pick_product()
        if not picked:
            self.iterations_done += 1
            if self.iterations_done >= MAX_ITERATIONS:
                raise StopUser()
            return
        product, variant = picked

        grant, csrf = self._challenge(csrf)
        if not grant:
            self.iterations_done += 1
            if self.iterations_done >= MAX_ITERATIONS:
                raise StopUser()
            return

        cart_id, etag, csrf = self._create_cart(csrf, product, variant, grant)
        if not cart_id:
            self.iterations_done += 1
            if self.iterations_done >= MAX_ITERATIONS:
                raise StopUser()
            return

        etag, csrf = self._patch_quantity(csrf, cart_id, etag, 2)
        if etag is None:
            self.iterations_done += 1
            if self.iterations_done >= MAX_ITERATIONS:
                raise StopUser()
            return

        reservation_id, csrf = self._reserve(csrf, cart_id)
        if not reservation_id:
            self.iterations_done += 1
            if self.iterations_done >= MAX_ITERATIONS:
                raise StopUser()
            return

        self._order(csrf, cart_id, etag, reservation_id)

        self.iterations_done += 1
        if self.iterations_done >= MAX_ITERATIONS:
            raise StopUser()


class ShopShape(LoadTestShape):
    def tick(self):
        run_time = self.get_run_time()
        if run_time < 1:
            return (2, 2)
        return None
