import java.time.Duration;
import java.util.*;

import static io.gatling.javaapi.core.CoreDsl.*;
import static io.gatling.javaapi.http.HttpDsl.*;

public class ModelSimulation extends Simulation {

    String baseUrl = System.getenv("BASE_URL");
    if (baseUrl == null || baseUrl.isEmpty()) baseUrl = "http://127.0.0.1:8000";

    HttpProtocolBuilder httpProtocol = http
        .baseUrl(baseUrl)
        .disableAutoRedirect()
        .disableCaching()
        .acceptHeader("application/json")
        .contentTypeHeader("application/json");

    // Extract csrf from login form HTML
    static final String CSRF_FORM_REGEX =
        "<input(?=[^>]*\\bname=[\"']csrf[\"'])(?=[^>]*\\bvalue=[\"']([^\"']+)[\"'])[^>]*>";

    ChainBuilder loginFlow =
        exec(
            http("GET /v2/login-form")
                .get("/v2/login-form")
                .check(status().is(200))
                .check(regex(CSRF_FORM_REGEX).saveAs("formCsrf"))
        )
        .exec(session -> {
            String user = "bench-" + session.userId();
            return session.set("username", user);
        })
        .exec(
            http("POST /v2/login")
                .post("/v2/login")
                .body(StringBody(session ->
                    "{\"username\":\"" + session.getString("username") +
                    "\",\"password\":\"bench\",\"csrf\":\"" + session.getString("formCsrf") + "\"}"))
                .check(status().in(200, 302))
                .check(header("Location").optional().saveAs("loginLocation"))
                .check(bodyString().optional().saveAs("loginBody"))
        )
        .exec(session -> {
            String loc = session.getString("loginLocation");
            if (loc != null && !loc.isEmpty()) {
                return session.set("loginRedirect", true);
            }
            return session.set("loginRedirect", false);
        })
        .doIf(session -> Boolean.TRUE.equals(session.get("loginRedirect"))).then(
            exec(
                http("GET login redirect")
                    .get(session -> session.getString("loginLocation"))
                    .check(status().is(200))
                    .check(jsonPath("$.csrf").saveAs("csrf"))
                    .check(jsonPath("$.grant_id").optional().saveAs("grant"))
            )
        )
        .doIf(session -> !Boolean.TRUE.equals(session.get("loginRedirect"))).then(
            exec(session -> {
                String body = session.getString("loginBody");
                String csrf = null;
                if (body != null) {
                    java.util.regex.Matcher m = java.util.regex.Pattern
                        .compile("\"csrf\"\\s*:\\s*\"([^\"]+)\"").matcher(body);
                    if (m.find()) csrf = m.group(1);
                }
                return session.set("csrf", csrf);
            })
        );

    ChainBuilder catalogFlow =
        exec(
            http("GET /v2/catalog")
                .get("/v2/catalog")
                .check(status().is(200))
                .check(jsonPath("$.data.products[?(@.variants[0].in_stock == true)].id").find().saveAs("product"))
                .check(jsonPath("$.data.products[?(@.variants[0].in_stock == true)].variants[0].id").find().saveAs("variant"))
        );

    ChainBuilder createCart =
        exec(
            http("POST /v2/carts")
                .post("/v2/carts")
                .header("X-CSRF-Token", session -> session.getString("csrf"))
                .body(StringBody(session -> {
                    String grant = session.getString("grant");
                    StringBuilder sb = new StringBuilder();
                    sb.append("{\"product_id\":\"").append(session.getString("product"))
                      .append("\",\"variant_id\":\"").append(session.getString("variant")).append("\"");
                    if (grant != null && !grant.isEmpty() && !"MISSING".equals(grant)) {
                        sb.append(",\"grant_id\":\"").append(grant).append("\"");
                    }
                    sb.append("}");
                    return sb.toString();
                }))
                .check(status().is(201))
                .check(jsonPath("$.id").saveAs("cart"))
                .check(jsonPath("$.csrf").optional().saveAs("newCsrf"))
                .check(header("ETag").optional().saveAs("etag"))
        )
        .exec(session -> {
            String nc = session.getString("newCsrf");
            if (nc != null && !nc.isEmpty()) return session.set("csrf", nc);
            return session;
        })
        .exec(session -> session.set("hasCart", true));

    ChainBuilder placeOrder =
        exec(
            http("POST /v2/orders")
                .post("/v2/orders")
                .header("X-CSRF-Token", session -> session.getString("csrf"))
                .header("Idempotency-Key", session -> session.getString("cart"))
                .header("If-Match", session -> {
                    String e = session.getString("etag");
                    return e == null ? "" : e;
                })
                .body(StringBody(session -> "{\"cart_id\":\"" + session.getString("cart") + "\"}"))
                .check(status().is(201))
                .check(jsonPath("$.accepted").is("true"))
                .check(jsonPath("$.id").exists())
                .check(jsonPath("$.csrf").optional().saveAs("newCsrf2"))
        )
        .exec(session -> {
            String nc = session.getString("newCsrf2");
            if (nc != null && !nc.isEmpty()) return session.set("csrf", nc);
            return session;
        });

    // Recovery: renew session, recover cart, retry order once
    ChainBuilder recoverAndRetry =
        exec(
            http("POST /v2/session/renew")
                .post("/v2/session/renew")
                .header("X-CSRF-Token", session -> session.getString("csrf"))
                .body(StringBody("{}"))
                .check(status().in(200, 401))
                .check(jsonPath("$.csrf").optional().saveAs("renewCsrf"))
        )
        .exec(session -> {
            String nc = session.getString("renewCsrf");
            if (nc != null && !nc.isEmpty()) return session.set("csrf", nc);
            return session;
        })
        .doIf(session -> Boolean.TRUE.equals(session.get("hasCart"))).then(
            exec(
                http("POST /v2/carts/{id}/recover")
                    .post(session -> "/v2/carts/" + session.getString("cart") + "/recover")
                    .header("X-CSRF-Token", session -> session.getString("csrf"))
                    .body(StringBody("{}"))
                    .check(status().in(200, 201, 401))
                    .check(jsonPath("$.csrf").optional().saveAs("recoverCsrf"))
            )
            .exec(session -> {
                String nc = session.getString("recoverCsrf");
                if (nc != null && !nc.isEmpty()) return session.set("csrf", nc);
                return session;
            })
        )
        .exec(
            http("POST /v2/orders (retry)")
                .post("/v2/orders")
                .header("X-CSRF-Token", session -> session.getString("csrf"))
                .header("Idempotency-Key", session -> session.getString("cart"))
                .header("If-Match", session -> {
                    String e = session.getString("etag");
                    return e == null ? "" : e;
                })
                .body(StringBody(session -> "{\"cart_id\":\"" + session.getString("cart") + "\"}"))
                .check(status().is(201))
                .check(jsonPath("$.accepted").is("true"))
                .check(jsonPath("$.id").exists())
        );

    ScenarioBuilder scn = scenario("ModelSimulation")
        .exec(loginFlow)
        .exec(catalogFlow)
        .exec(createCart)
        .exec(placeOrder)
        .doIf(session -> {
            // If order failed (no accepted), attempt recovery once
            Object accepted = session.get("accepted");
            return accepted == null;
        }).then(
            exec(recoverAndRetry)
        );

    {
        setUp(
            scn.injectOpen(atOnceUsers(2))
        ).protocols(httpProtocol)
         .maxDuration(Duration.ofMinutes(5));
    }
}
