import http from 'k6/http';
import { check } from 'k6';

export const options = {
  scenarios: {
    journeys: {
      executor: 'per-vu-iterations',
      vus: 2,
      iterations: 2,
      maxDuration: '2m',
    },
  },
  thresholds: {
    checks: ['rate==1'],
  },
};

const BASE = __ENV.BASE_URL || 'http://127.0.0.1:8000';

function jar() {
  return new http.CookieJar();
}

function parseCsrfFromForm(html) {
  if (!html) return null;
  const re = /<input(?=[^>]*\bname=["']csrf["'])(?=[^>]*\bvalue=["']([^"']+)["'])[^>]*>/i;
  const m = html.match(re);
  return m ? m[1] : null;
}

function safeJson(res) {
  try { return res.json(); } catch (e) { return null; }
}

function isExpired(res) {
  const b = safeJson(res);
  return res.status === 401 && b && (b.error === 'expired' || b.error === 'session');
}

function isDenied(res) {
  const b = safeJson(res);
  return res.status === 401 && b && b.error === 'denied';
}

function getHeader(res, name) {
  const h = res.headers[name] || res.headers[name.toLowerCase()];
  return h || null;
}

function loginForm(jarRef) {
  const res = http.get(`${BASE}/v2/login-form`, { jar: jarRef, redirects: 0 });
  check(res, { 'login-form 200': (r) => r.status === 200 });
  return parseCsrfFromForm(res.body);
}

function doLogin(jarRef, username, formCsrf) {
  const res = http.post(
    `${BASE}/v2/login`,
    JSON.stringify({ username, password: 'bench', csrf: formCsrf }),
    { jar: jarRef, redirects: 0, headers: { 'Content-Type': 'application/json' } }
  );
  let csrf = null;
  let user = null;
  if (res.status === 302) {
    const loc = getHeader(res, 'Location');
    if (loc) {
      const follow = http.get(loc.startsWith('http') ? loc : `${BASE}${loc}`, { jar: jarRef, redirects: 0 });
      const b = safeJson(follow);
      if (b) { csrf = b.csrf || null; user = b.user || null; }
    }
  } else {
    const b = safeJson(res);
    if (b) { csrf = b.csrf || null; user = b.user || null; }
  }
  check(res, { 'login ok': (r) => r.status === 200 || r.status === 302 });
  return { csrf, user };
}

function fetchCatalog(jarRef) {
  const res = http.get(`${BASE}/v2/catalog`, { jar: jarRef, redirects: 0 });
  check(res, { 'catalog 200': (r) => r.status === 200 });
  const b = safeJson(res);
  if (!b || !b.data || !Array.isArray(b.data.products)) return null;
  for (const p of b.data.products) {
    if (p && Array.isArray(p.variants)) {
      for (const v of p.variants) {
        if (v && v.in_stock === true) {
          return { product: p.id, variant: v.id };
        }
      }
    }
  }
  return null;
}

function fetchChallenge(jarRef, csrf) {
  const formRes = http.get(`${BASE}/v2/challenge-form`, { jar: jarRef, redirects: 0 });
  check(formRes, { 'challenge-form 200': (r) => r.status === 200 });
  const body = formRes.body || '';
  const actionMatch = body.match(/action=["']([^"']+)["']/i);
  const challengeMatch = body.match(/<input(?=[^>]*\bname=["']challenge["'])(?=[^>]*\bvalue=["']([^"']+)["'])[^>]*>/i);
  if (!actionMatch || !challengeMatch) return null;
  const action = actionMatch[1];
  const challenge = challengeMatch[1];
  const url = action.startsWith('http') ? action : `${BASE}${action}`;
  const postRes = http.post(
