  );
  const b = safeJson(res);
  return { ok: res.status === 200, csrf: b && b.csrf ? b.csrf : csrf };
}

function recoverCart(jarRef, csrf, cartId) {
  const res = http.post(
    `${BASE}/v2/carts/${cartId}/recover`,
    JSON.stringify({}),
    { jar: jarRef, redirects: 0, headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf } }
  );
  const b = safeJson(res);
  return { ok: res.status === 200 || res.status === 204, csrf: b && b.csrf ? b.csrf : csrf };
}

function placeOrder(jarRef, csrf, cartId, etag, idemKey) {
