  const res = http.post(
    `${BASE}/v2/orders`,
    JSON.stringify({ cart_id: cartId }),
    { jar: jarRef, redirects: 0, headers }
  );
  return res;
}

function handleExpiry(jarRef, state, username) {
  // state: { csrf, cartId, etag }
  let renewed = renewSession(jarRef, state.csrf);
  state.csrf = renewed.csrf;
  if (!renewed.ok) {
    // session revoked: fresh login
    const formCsrf = loginForm(jarRef);
    if (formCsrf) {
      const l = doLogin(jarRef, username, formCsrf);
      if (l.csrf) state.csrf = l.csrf;
    }
  }
  if (state.cartId) {
    const rec = recoverCart(jarRef, state.csrf, state.cartId);
    state.csrf = rec.csrf;
  }
