import os
import re
import time
import json
import uuid

from locust import HttpUser, task, between, LoadTestShape
from locust.exception import StopUser


BASE_URL = os.environ.get("BASE_URL", "http://127.0.0.1:8000")

CSRF_INPUT_RE = re.compile(
    r"""<input(?=[^>]*\bname=["']csrf["'])(?=[^>]*\bvalue=["']([^"']+)["'])[^>]*>""",
    re.IGNORECASE,
)


def _extract_csrf_from_form(text):
    if not text:
        return None
    m = CSRF_INPUT_RE.search(text)
    if m:
        return m.group(1)
    return None


class ShopUser(HttpUser):
    host = BASE_URL
    wait_time = between(0.05, 0.15)

    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self.iterations_done = 0
        self.max_iterations = 2
        self.username = None
        self.csrf = None
        self.cart_id = None
        self.etag = None
        self.grant_id = None
        self.idem_key = None

    # ---------- helpers ----------

    def _headers(self, extra=None, include_csrf=True, include_ifmatch=False, include_idem=False):
        h = {"Content-Type": "application/json"}
        if include_csrf and self.csrf:
            h["X-CSRF-Token"] = self.csrf
        if include_ifmatch and self.etag:
            h["If-Match"] = self.etag
        if include_idem and self.idem_key:
            h["Idempotency-Key"] = self.idem_key
        if extra:
            h.update(extra)
        return h

    def _update_csrf_from_json(self, resp):
        try:
            data = resp.json()
        except Exception:
            return
        if isinstance(data, dict) and data.get("csrf"):
            self.csrf = data["csrf"]

    def _update_etag(self, resp):
        etag = resp.headers.get("ETag")
        if etag:
            self.etag = etag

    def _is_expired(self, resp):
        if resp.status_code != 401:
            return False
        try:
            data = resp.json()
        except Exception:
            return False
        return isinstance(data, dict) and data.get("error") == "expired"

    def _is_session_revoked(self, resp):
        if resp.status_code != 401:
            return False
        try:
            data = resp.json()
        except Exception:
            return False
        return isinstance(data, dict) and data.get("error") == "session"

    def _is_denied(self, resp):
        if resp.status_code != 401:
            return False
        try:
            data = resp.json()
        except Exception:
            return False
        return isinstance(data, dict) and data.get("error") == "denied"

    # ---------- auth ----------

    def _fetch_login_form(self):
        with self.client.get(
            "/v2/login-form",
            name="GET /v2/login-form",
            catch_response=True,
            allow_redirects=False,
        ) as resp:
            if resp.status_code != 200:
                resp.failure(f"login-form status {resp.status_code}")
                return None
            token = _extract_csrf_from_form(resp.text)
            if not token:
                resp.failure("login-form missing csrf")
                return None
            resp.success()
            return token

    def _do_login(self, form_csrf):
        payload = {
            "username": self.username,
            "password": "bench",
            "csrf": form_csrf,
        }
        with self.client.post(
            "/v2/login",
            json=payload,
            name="POST /v2/login",
            catch_response=True,
            allow_redirects=False,
            headers={"Content-Type": "application/json"},
        ) as resp:
            if resp.status_code == 302:
                loc = resp.headers.get("Location")
                if not loc:
                    resp.failure("login 302 without Location")
                    return False
                resp.success()
                with self.client.get(
                    loc,
                    name="GET login-redirect",
                    catch_response=True,
                    allow_redirects=False,
                ) as r2:
                    if r2.status_code != 200:
                        r2.failure(f"login redirect status {r2.status_code}")
                        return False
                    try:
                        data = r2.json()
                    except Exception:
                        r2.failure("login redirect not json")
                        return False
                    if not isinstance(data, dict) or "csrf" not in data:
                        r2.failure("login redirect missing csrf")
                        return False
                    self.csrf = data["csrf"]
                    r2.success()
                    return True
            if resp.status_code != 200:
                resp.failure(f"login status {resp.status_code}")
                return False
            try:
                data = resp.json()
            except Exception:
                resp.failure("login not json")
                return False
            if not isinstance(data, dict) or "csrf" not in data:
                resp.failure("login missing csrf")
                return False
            self.csrf = data["csrf"]
            resp.success()
            return True

    def _fresh_login(self):
        form_csrf = self._fetch_login_form()
        if not form_csrf:
            return False
        return self._do_login(form_csrf)

    # ---------- catalog ----------

    def _pick_product(self):
        with self.client.get(
            "/v2/catalog",
            name="GET /v2/catalog",
            catch_response=True,
            allow_redirects=False,
        ) as resp:
            if resp.status_code != 200:
                resp.failure(f"catalog status {resp.status_code}")
                return None
            try:
                data = resp.json()
            except Exception:
                resp.failure("catalog not json")
                return None
            products = (data or {}).get("data", {}).get("products") or []
            for p in products:
                variants = p.get("variants") or []
                for v in variants:
                    if v.get("in_stock"):
                        resp.success()
                        return (p.get("id"), v.get("id"))
            resp.failure("no in-stock product")
            return None

    # ---------- challenge ----------

    def _do_challenge(self):
        with self.client.get(
            "/v2/challenge-form",
            name="GET /v2/challenge-form",
            catch_response=True,
            allow_redirects=False,
        ) as resp:
            if resp.status_code != 200:
                resp.failure(f"challenge-form status {resp.status_code}")
                return False
            text = resp.text or ""
            action_m = re.search(r'<form[^>]*action=["\']([^"\']+)["\']', text, re.IGNORECASE)
            chal_m = re.search(
                r"""<input(?=[^>]*\bname=["']challenge["'])(?=[^>]*\bvalue=["']([^"']+)["'])[^>]*>""",
                text,
                re.IGNORECASE,
            )
            if not action_m or not chal_m:
                resp.failure("challenge-form missing action/challenge")
                return False
            action = action_m.group(1)
            challenge = chal_m.group(1)
            resp.success()

        with self.client.post(
            action,
            json={"challenge": challenge},
            name="POST /v2/challenges/{id}",
            catch_response=True,
            allow_redirects=False,
            headers=self._headers(),
        ) as resp:
            if resp.status_code != 302:
                resp.failure(f"challenge status {resp.status_code}")
                return False
            loc = resp.headers.get("Location")
            if not loc:
                resp.failure("challenge 302 without Location")
                return False
            resp.success()

        with self.client.get(
            loc,
            name="GET challenge-redirect",
            catch_response=True,
            allow_redirects=False,
        ) as resp:
            if resp.status_code != 200:
                resp.failure(f"challenge redirect status {resp.status_code}")
                return False
            try:
                data = resp.json()
            except Exception:
                resp.failure("challenge redirect not json")
                return False
            if not isinstance(data, dict) or "grant_id" not in data:
                resp.failure("challenge redirect missing grant_id")
                return False
            self.grant_id = data["grant_id"]
            if data.get("csrf"):
                self.csrf = data["csrf"]
            resp.success()
            return True

    # ---------- cart ----------

    def _create_cart(self, product_id, variant_id):
        payload = {"product_id": product_id, "variant_id": variant_id}
        if self.grant_id:
            payload["grant_id"] = self.grant_id
        with self.client.post(
            "/v2/carts",
            json=payload,
            name="POST /v2/carts",
            catch_response=True,
            allow_redirects=False,
            headers=self._headers(),
        ) as resp:
            if resp.status_code != 201:
                resp.failure(f"cart create status {resp.status_code}")
                return False
            try:
                data = resp.json()
            except Exception:
                resp.failure("cart create not json")
                return False
            if not isinstance(data, dict) or not data.get("id"):
                resp.failure("cart create missing id")
                return False
            self.cart_id = data["id"]
            if data.get("csrf"):
                self.csrf = data["csrf"]
            self._update_etag(resp)
            self.idem_key = str(uuid.uuid4())
            resp.success()
            return True

    def _recover_cart(self):
        if not self.cart_id:
            return True
        with self.client.post(
            f"/v2/carts/{self.cart_id}/recover",
            json={},
            name="POST /v2/carts/{id}/recover",
            catch_response=True,
            allow_redirects=False,
            headers=self._headers(),
        ) as resp:
            if resp.status_code not in (200, 201, 204):
                resp.failure(f"cart recover status {resp.status_code}")
                return False
            self._update_csrf_from_json(resp)
            self._update_etag(resp)
            resp.success()
            return True

    def _renew_session(self):
        with self.client.post(
            "/v2/session/renew",
            json={},
            name="POST /v2/session/renew",
            catch_response=True,
            allow_redirects=False,
            headers=self._headers(),
        ) as resp:
            if resp.status_code != 200:
                resp.failure(f"renew status {resp.status_code}")
                return False
            self._update_csrf_from_json(resp)
            resp.success()
            return True

    def _handle_expiry(self):
        # renew, then recover cart if exists
        if not self._renew_session():
            # fall back to fresh login
            if not self._fresh_login():
                return False
        if self.cart_id:
            if not self._recover_cart():
                return False
        return True

    # ---------- reservation ----------

    def _reserve(self):
        with self.client.post(
            "/v2/reservations",
            json={"cart_id": self.cart_id},
            name="POST /v2/reservations",
            catch_response=True,
            allow_redirects=False,
            headers=self._headers(),
        ) as resp:
            if resp.status_code != 202:
                resp.failure(f"reservation status {resp.status_code}")
                return None
            try:
                data = resp.json()
            except Exception:
                resp.failure("reservation not json")
                return None
            if not isinstance(data, dict) or not data.get("status_url"):
                resp.failure("reservation missing status_url")
                return None
            status_url = data["status_url"]
            if data.get("csrf"):
                self.csrf = data["csrf"]
            resp.success()

        reservation_id = None
        for attempt in range(5):
            time.sleep(0.06)
            with self.client.get(
                status_url,
                name="GET reservation-status",
                catch_response=True,
                allow_redirects=False,
            ) as resp:
                if resp.status_code != 200:
                    resp.failure(f"reservation status poll {resp.status_code}")
                    return None
                try:
                    data = resp.json()
                except Exception:
                    resp.failure("reservation poll not json")
                    return None
                status = (data or {}).get("status")
                if status == "ready":
                    reservation_id = data.get("reservation_id")
                    if not reservation_id:
                        resp.failure("reservation ready without id")
                        return None
                    resp.success()
                    return reservation_id
                if status in ("pending",):
                    resp.success()
                    continue
                if status in ("failed",):
                    resp.failure("reservation failed")
                    return None
                resp.failure(f"reservation unknown status {status}")
                return None
        return None

    # ---------- order ----------

    def _place_order(self, reservation_id):
        payload = {"cart_id": self.cart_id}
        if reservation_id:
            payload["reservation_id"] = reservation_id
        headers = self._headers(include_ifmatch=True, include_idem=True)
        with self.client.post(
            "/v2/orders",
            json=payload,
            name="POST /v2/orders",
            catch_response=True,
            allow_redirects=False,
            headers=headers,
        ) as resp:
            if resp.status_code == 200:
                try:
                    data = resp.json()
                except Exception:
                    resp.failure("order not json")
                    return False
                if isinstance(data, dict) and data.get("accepted") is False:
                    resp.failure("order accepted:false")
                    return False
                if isinstance(data, dict) and data.get("accepted") is True:
                    if data.get("csrf"):
                        self.csrf = data["csrf"]
                    resp.success()
                    return True
                resp.failure("order unexpected body")
                return False
            if resp.status_code == 201:
                try:
                    data = resp.json()
                except Exception:
                    resp.failure("order not json")
                    return False
                if not isinstance(data, dict) or data.get("accepted") is not True:
                    resp.failure("order 201 without accepted:true")
                    return False
                if data.get("csrf"):
                    self.csrf = data["csrf"]
                resp.success()
                return True
            resp.failure(f"order status {resp.status_code}")
            return False

    # ---------- journey ----------

    def _journey(self):
        # fresh login
        if not self._fresh_login():
            return False

        # catalog
        picked = self._pick_product()
        if not picked:
            return False
        product_id, variant_id = picked

        # challenge
        if not self._do_challenge():
            return False

        # create cart
        if not self._create_cart(product_id, variant_id):
            return False

        # reserve
        reservation_id = self._reserve()
        if not reservation_id:
            return False

        # order
        if not self._place_order(reservation_id):
            return False

        return True

    @task
    def run_journey(self):
        if self.iterations_done >= self.max_iterations:
            raise StopUser()
        self.username = f"bench-{self.environment.runner.user_count if self.environment.runner else 1}"
        # Use a stable per-user name based on a counter
        self.username = f"bench-{getattr(self, '_uid', None) or self._assign_uid()}"
        try:
            ok = self._journey()
        except StopUser:
            raise
        except Exception:
            ok = False
        self.iterations_done += 1
        if self.iterations_done >= self.max_iterations:
            raise StopUser()

    def _assign_uid(self):
        # derive a stable uid from the user's greenlet id
        import greenlet
        gid = id(greenlet.getcurrent())
        uid = (gid % 16) + 1
        self._uid = uid
        return uid


class ShopShape(LoadTestShape):
    def __init__(self):
        super().__init__()
        self.start_time = None
        self.done = False

    def tick(self):
        if self.done:
            return None
        if self.start_time is None:
            self.start_time = time.time()
        elapsed = time.time() - self.start_time
        # 2 users, each does 2 iterations; stop after enough time
        if elapsed > 120:
            self.done = True
            return None
        return (2, 2)
