                                 name=name, catch_response=True,
                                 allow_redirects=False, timeout=3) as response:
            try:
                body = response.json()
            except ValueError:
                body = {}
            if body.get('csrf'):
                self.csrf = body['csrf']
            if expect_ok:
                if response.status_code >= 400:
                    response.failure('unexpected status %s' % response.status_code)
                else:
                    response.success()
            return response, body

