        } catch (IOException error) {
            return session;
        }
        return session;
    }

    private static ChainBuilder flow() {
        ChainBuilder chain = exec(flushCookieJar()).exec(login());
        if (MODE.equals("challenge")) chain = chain.exec(challenge());
        if (MODE.equals("ownership")) {
