                            .exec(login())
                            .exec(session -> session.set("cart", session.getString("recoveryCart"))
                                .set("etag", session.getString("recoveryEtag")))
                            .exec(http("cart recovery").post("/v2/carts/#{cart}/recover")
                                .header("X-CSRF-Token", "#{csrf}")
