                .exec(http("catalog retry").get(catalogPath).header("X-CSRF-Token", "#{csrf}")
                    .check(status().is(200), bodyString().saveAs("catalogBody"),
                        jsonPath("$.csrf").optional().saveAs("csrf"),
                        jsonPath("$.next").optional().saveAs("nextPage")))))
