  {"username": "bench-13", "password": "bench", "quantity": 14},
  {"username": "bench-14", "password": "bench", "quantity": 15},
  {"username": "bench-15", "password": "bench", "quantity": 16},
  {"username": "bench-16", "password": "bench", "quantity": 17}
];

const failure = new Rate('business_failure');

export const options = {
  scenarios: {
    journeys: {
      executor: 'per-vu-iterations',
      vus: 2,
      iterations: 3,
      maxDuration: '30s'
    }
  },
  thresholds: {"checks": ["rate==1"]}
};

const base = __ENV.BASE_URL;

// Per-VU state
let csrf = '';
let cart = '';
let grant = '';
let etag = '';

function body(r) {
  try { return r.json(); } catch (_) { return {}; }
}

function raw(path, method = 'GET', data = null, extra = {}) {
  const r = http.request(method, base + path, data === null ? null : JSON.stringify(data), {
    headers: Object.assign({'Content-Type': 'application/json', 'X-CSRF-Token': csrf}, extra),
    redirects: 0,
    timeout: '3s'
  });
  const b = body(r);
  if (b.csrf) csrf = b.csrf;
  if (path === '/v2/work') {
    const expected = (r.status === 401 && b.error === 'expired') || r.status === 429;
    failure.add(r.status >= 400 && !expected);
  }
  return r;
}

function login() {
  let r = raw('/v2/login-form');
  const token = r.html().find('input[name="csrf"]').first().attr('value');
  const row = rows[(__VU - 1) % rows.length];
  r = raw('/v2/login', 'POST', {username: row.username, password: row.password, csrf: token});
  if (r.status === 302) {
    r = raw(r.headers.Location);
  }
  check(r, {'login': r => r.status === 200});
}

// Renew session and recover cart. Returns true if recovery succeeded.
function recover() {
  const renewed = raw('/v2/session/renew', 'POST', {});
  if (renewed.status !== 200) {
    // session revoked: fresh login
    login();
  }
  if (cart) {
    const rec = raw('/v2/carts/' + cart + '/recover', 'POST', {});
    if (rec.status !== 200 && rec.status !== 201) {
      // cart unrecoverable; caller must not restart checkout
      return false;
    }
  }
  return true;
}

// Perform an operation with bounded expiry recovery (once per operation).
function request(path, method = 'GET', data = null, extra = {}) {
  let r = raw(path, method, data, extra);
  if (r.status === 401) {
    const err = body(r).error;
    if (err === 'expired' || err === 'session') {
      if (!recover()) {
        check(false, {'recovery': x => x});
        return r;
      }
      r = raw(path, method, data, extra);
    } else if (err === 'denied') {
      check(false, {'not denied': x => x});
    }
  }
  return r;
}

function work(override) {
  if (!csrf) login();
  const path = override || '/v2/work';
  let r = request(path, 'POST', {});
  for (let n = 0; n < 4 && r.status === 429; n++) {
    const ra = Number(r.headers['Retry-After'] || 1);
    sleep(ra + 0.01);
    r = request(path, 'POST', {});
  }
  check(r, {'operation ok': r => r.status === 200 && body(r).ok === true});
}

function flow() {
  csrf = '';
  cart = '';
  grant = '';
  etag = '';

  login();

  // Catalog traversal (max 3 pages)
  let page = '/v2/catalog';
  let product = null;
  for (let n = 0; n < 3 && page; n++) {
    const b = body(request(page));
    const products = (b.data && b.data.products) || [];
    product = products.find(p => p.variants && p.variants.some(v => v.in_stock));
    if (product) break;
    page = b.next;
  }
  if (!product) {
    check(false, {'eligible product': x => x});
    return;
  }
  const variant = product.variants.find(v => v.in_stock);

  // Create cart
  let r = request('/v2/carts', 'POST', {product_id: product.id, variant_id: variant.id, grant_id: grant});
  cart = body(r).id;
  etag = r.headers.Etag;
  check(r, {'cart': r => r.status === 201});
  if (!cart) return;

  // Update quantity
  const quantity = rows[(__VU - 1) % rows.length].quantity;
  r = request('/v2/carts/' + cart, 'PATCH', {quantity: quantity}, {'If-Match': etag});
  if (r.status === 412) {
    etag = request('/v2/carts/' + cart).headers.Etag;
    r = request('/v2/carts/' + cart, 'PATCH', {quantity: quantity}, {'If-Match': etag});
  }
  etag = r.headers.Etag || etag;
  check(r, {'update': r => r.status === 200});

  // Checkout — single committed order, idempotency key stable per cart
  r = request('/v2/orders', 'POST', {cart_id: cart}, {'Idempotency-Key': cart, 'If-Match': etag});
  check(r, {'accepted': r => r.status === 201 && body(r).accepted === true});
}

export default function () {
  flow();
}

export function browse() { work('/v2/browse'); }
export function checkout() { flow(); }
