                        .check(bodyString().saveAs("loginFormBody")))
                .exec(session -> {
                    String body = session.getString("loginFormBody");
                    String csrf = firstGroup(CSRF_INPUT, body);
                    return session.set("csrf", csrf == null ? "" : csrf);
                })
                .exec(http("login")
                        .post("/v2/login")
                        .header("Content-Type", JSON_CT)
                        .body(StringBody(session ->
                                "{\"username\":\"" + session.getString("username") +
                                        "\",\"password\":\"bench\",\"csrf\":\"" +
                                        session.getString("csrf") + "\"}"))
                        .check(status().in(200, 302))
                        .check(header("Location").optional().saveAs("loginLocation"))
                        .check(bodyString().optional().saveAs("loginBody")))
                .exec(session -> {
                    String loc = session.getString("loginLocation");
                    if (loc != null && !loc.isEmpty()) {
                        return session.set("loginRedirect", loc);
                    }
                    return session;
                })
                .doIf(session -> session.getString("loginRedirect") != null).then(
                        exec(http("login-redirect")
                                .get(session -> session.getString("loginRedirect"))
                                .check(status().lt(400))
                                .check(bodyString().optional().saveAs("loginBody2")))
                )
                .exec(session -> {
                    String b = session.getString("loginBody2");
                    if (b == null) b = session.getString("loginBody");
                    String csrf = firstGroup(CSRF_INPUT, b);
                    if (csrf != null) return session.set("csrf", csrf);
                    return session;
                });
    }

    private ChainBuilder workFlow() {
        return exec(http("work")
                .post("/v2/work")
                .header("Content-Type", JSON_CT)
                .header("X-CSRF-Token", session -> session.getString("csrf"))
                .body(StringBody("{}"))
                .check(status().in(200, 429))
                .check(bodyString().optional().saveAs("workBody")))
                .exec(session -> {
                    Integer status = session.get("workStatus");
                    return session;
                });
    }

    private ScenarioBuilder scenario() {
        return scenario("ModelSimulation")
                .exec(loginFlow())
                .exec(workFlow());
    }

    {
        setUp(
                scenario().injectOpen(
                        rampUsers(2).during(Duration.ofSeconds(1)),
                        constantUsersPerSec(5).during(Duration.ofSeconds(40))
                )
        ).protocols(httpProtocol)
                .maxDuration(Duration.ofSeconds(60));
    }
}
