import http from 'k6/http';
import { check } from 'k6';
import { Counter, Rate } from 'k6/metrics';

const BASE = __ENV.BASE_URL || 'http://127.0.0.1:8000';

const workStarts = new Counter('work_starts');
const workUnexpected = new Counter('work_unexpected');
const workBusiness = new Counter('work_business');
const businessFailure = new Rate('business_failure');

export const options = {
  scenarios: {
    measured: {
      executor: 'constant-arrival-rate',
      rate: 5,
      timeUnit: '1s',
      duration: '40s',
      preAllocatedVUs: 8,
      maxVUs: 32,
      startTime: '0s',
    },
  },
  thresholds: {
    'business_failure': ['rate<0.01'],
  },
  discardResponseBodies: false,
};

function parseCsrf(html) {
  if (!html) return null;
  const re = /<input[^>]*name\s*=\s*["']?csrf["']?[^>]*>/gi;
  let m;
  while ((m = re.exec(html)) !== null) {
    const tag = m[0];
    const vm = tag.match(/value\s*=\s*["']([^"']*)["']/i);
    if (vm) return vm[1];
  }
  const re2 = /<input[^>]*value\s*=\s*["']([^"']*)["'][^>]*name\s*=\s*["']?csrf["']?/gi;
  while ((m = re2.exec(html)) !== null) {
    return m[1];
  }
  return null;
}

function parseChallenge(html) {
  if (!html) return null;
  const re = /<input[^>]*name\s*=\s*["']?challenge["']?[^>]*>/gi;
  let m;
  while ((m = re.exec(html)) !== null) {
    const tag = m[0];
    const vm = tag.match(/value\s*=\s*["']([^"']*)["']/i);
    if (vm) return vm[1];
  }
  return null;
}

function parseAction(html) {
  if (!html) return null;
  const re = /<form[^>]*action\s*=\s*["']([^"']*)["']/i;
  const m = html.match(re);
  return m ? m[1] : null;
}

function jar() {
  return http.cookieJar();
}

function get(url, params) {
  return http.get(url, params);
}

function post(url, body, params) {
  return http.post(url, body, params);
}

function patch(url, body, params) {
  return http.patch(url, body, params);
}

function login(user) {
  const cj = jar();
  const params = { jar: cj, redirects: 0, tags: { name: 'login' } };
  const formRes = get(`${BASE}/v2/login-form`, params);
  if (formRes.status !== 200) return null;
  const csrf = parseCsrf(formRes.body);
  if (!csrf) return null;
  const loginRes = post(
    `${BASE}/v2/login`,
    JSON.stringify({ username: user, password: 'bench', csrf }),
    {
      jar: cj,
      redirects: 0,
      headers: { 'Content-Type': 'application/json' },
      tags: { name: 'login' },
    }
  );
  let sessionCsrf = null;
  if (loginRes.status === 302) {
    const loc = loginRes.headers['Location'];
    if (loc) {
      const followRes = get(loc.startsWith('http') ? loc : `${BASE}${loc}`, {
        jar: cj,
        redirects: 0,
        tags: { name: 'login' },
      });
      try {
        const j = JSON.parse(followRes.body);
        sessionCsrf = j.csrf;
      } catch (e) {}
    }
  } else if (loginRes.status === 200) {
    try {
      const j = JSON.parse(loginRes.body);
      sessionCsrf = j.csrf;
    } catch (e) {}
  }
  if (!sessionCsrf) return null;
  return { jar: cj, csrf: sessionCsrf };
}

function renew(session) {
  const res = post(
    `${BASE}/v2/session/renew`,
    '{}',
    {
      jar: session.jar,
      redirects: 0,
      headers: {
        'Content-Type': 'application/json',
        'X-CSRF-Token': session.csrf,
      },
      tags: { name: 'renew' },
    }
  );
  if (res.status === 200) {
    try {
      const j = JSON.parse(res.body);
      if (j.csrf) session.csrf = j.csrf;
    } catch (e) {}
    return true;
  }
  return false;
}

function doWork(session) {
  let attempts = 0;
  let res;
  while (attempts < 5) {
    res = post(
      `${BASE}/v2/work`,
      '{}',
      {
        jar: session.jar,
        redirects: 0,
        headers: {
          'Content-Type': 'application/json',
          'X-CSRF-Token': session.csrf,
        },
        tags: { name: 'work' },
      }
    );
    if (res.status === 429) {
      const ra = res.headers['Retry-After'];
      const wait = ra ? parseFloat(ra) * 1000 : 1000;
      if (attempts >= 4) break;
      attempts++;
      // sleep via busy wait not allowed; use http.batch trick? Use sleep
      // k6 sleep
      // eslint-disable-next-line no-undef
      // We'll import sleep
      break;
    }
    break;
  }
  return res;
}

import { sleep } from 'k6';

function workWithRetry(session) {
  let attempts = 0;
  let res;
  while (attempts <= 4) {
    res = post(
      `${BASE}/v2/work`,
      '{}',
      {
        jar: session.jar,
        redirects: 0,
        headers: {
          'Content-Type': 'application/json',
          'X-CSRF-Token': session.csrf,
        },
        tags: { name: 'work' },
      }
    );
    if (res.status === 429) {
      const ra = res.headers['Retry-After'];
      const wait = ra ? parseFloat(ra) : 1;
      attempts++;
      if (attempts > 4) break;
      sleep(wait);
      continue;
    }
    break;
  }
  return res;
}

export default function () {
  const user = `bench-${1 + (__VU % 16)}`;
  const session = login(user);
  if (!session) {
    businessFailure.add(true);
    return;
  }

  const res = workWithRetry(session);
  if (!res) {
    businessFailure.add(true);
    return;
  }

  workBusiness.add(1);

  if (res.status === 200) {
    let ok = false;
    try {
      const j = JSON.parse(res.body);
      ok = j && j.ok === true;
    } catch (e) {}
    if (ok) {
      workStarts.add(1);
      businessFailure.add(false);
    } else {
      workUnexpected.add(1);
      businessFailure.add(true);
    }
  } else if (res.status === 401) {
    // try renew once
    if (renew(session)) {
      const res2 = workWithRetry(session);
      if (res2 && res2.status === 200) {
        let ok = false;
        try {
          const j = JSON.parse(res2.body);
          ok = j && j.ok === true;
        } catch (e) {}
        if (ok) {
          workStarts.add(1);
          businessFailure.add(false);
        } else {
          workUnexpected.add(1);
          businessFailure.add(true);
        }
      } else {
        workUnexpected.add(1);
        businessFailure.add(true);
      }
    } else {
      workUnexpected.add(1);
      businessFailure.add(true);
    }
  } else if (res.status === 429) {
    // exhausted retries, scheduled - not a completion
    businessFailure.add(false);
  } else {
    workUnexpected.add(1);
    businessFailure.add(true);
  }
}
