import os
import re
import time
import uuid
from urllib.parse import urljoin

from locust import HttpUser, task, between, LoadTestShape
from locust.exception import StopUser


BASE_URL = os.environ.get("BASE_URL", "http://127.0.0.1:8000")


def _abs(url):
    if not url:
        return url
    return urljoin(BASE_URL + "/", url)


class ShopUser(HttpUser):
    host = BASE_URL
    wait_time = between(0.05, 0.15)

    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self.username = None
        self.password = "bench"
        self.csrf = None
        self.iterations_done = 0
        self.max_iterations = 2

    # ---------- helpers ----------
    def _extract_csrf_from_form(self, text):
        # input[name=csrf] with mixed attribute variants / decoys
        patterns = [
            r'<input[^>]*name=["\']csrf["\'][^>]*value=["\']([^"\']+)["\']',
            r'<input[^>]*value=["\']([^"\']+)["\'][^>]*name=["\']csrf["\']',
        ]
        for p in patterns:
            m = re.search(p, text, re.IGNORECASE)
            if m:
                return m.group(1)
        return None

    def _extract_challenge(self, text):
        action = None
        token = None
        m = re.search(r'<form[^>]*action=["\']([^"\']+)["\']', text, re.IGNORECASE)
        if m:
            action = m.group(1)
        m = re.search(
            r'<input[^>]*name=["\']challenge["\'][^>]*value=["\']([^"\']*)["\']',
            text, re.IGNORECASE)
        if m:
            token = m.group(1)
        return action, token

    def _login(self):
        # pick account
        idx = (id(self) % 16) + 1
        self.username = "bench-%d" % idx
        with self.client.get("/v2/login-form", name="GET /v2/login-form",
                             catch_response=True, allow_redirects=False) as r:
            if r.status_code >= 400:
                r.failure("login-form status %s" % r.status_code)
                return False
            csrf = self._extract_csrf_from_form(r.text or "")
            if not csrf:
                r.failure("no csrf in login form")
                return False
        with self.client.post("/v2/login",
                              json={"username": self.username,
                                    "password": self.password,
                                    "csrf": csrf},
                              name="POST /v2/login",
                              catch_response=True, allow_redirects=False) as r:
            if r.status_code == 302:
                loc = r.headers.get("Location")
                if loc:
                    with self.client.get(_abs(loc), name="GET login-redirect",
                                         catch_response=True,
                                         allow_redirects=False) as r2:
                        if r2.status_code >= 400:
                            r2.failure("redirect status %s" % r2.status_code)
                            return False
                        try:
                            data = r2.json()
                        except Exception:
                            data = {}
                        if data.get("csrf"):
                            self.csrf = data["csrf"]
                        else:
                            self.csrf = csrf
                else:
                    self.csrf = csrf
                return True
            if r.status_code >= 400:
                r.failure("login status %s" % r.status_code)
                return False
            try:
                data = r.json()
            except Exception:
                data = {}
            if data.get("csrf"):
                self.csrf = data["csrf"]
            else:
                self.csrf = csrf
            return True

    def _renew(self):
        with self.client.post("/v2/session/renew", json={},
                              headers={"X-CSRF-Token": self.csrf or ""},
                              name="POST /v2/session/renew",
                              catch_response=True, allow_redirects=False) as r:
            if r.status_code >= 400:
                r.failure("renew status %s" % r.status_code)
                return False
            try:
                data = r.json()
            except Exception:
                data = {}
            if data.get("csrf"):
                self.csrf = data["csrf"]
            return True

    def _recover_cart(self, cart_id):
        if not cart_id:
            return
        with self.client.post("/v2/carts/%s/recover" % cart_id, json={},
                              headers={"X-CSRF-Token": self.csrf or ""},
                              name="POST /v2/carts/[id]/recover",
                              catch_response=True, allow_redirects=False) as r:
            if r.status_code >= 400:
                r.failure("recover status %s" % r.status_code)
                return
            try:
                data = r.json()
            except Exception:
                data = {}
            if data.get("csrf"):
                self.csrf = data["csrf"]

    def _handle_401(self, r, cart_id):
        try:
            data = r.json()
        except Exception:
            data = {}
        err = data.get("error")
        if err == "expired":
            if self._renew():
                if cart_id:
                    self._recover_cart(cart_id)
                return "retry"
            return "fail"
        if err == "session":
            if self._renew():
                if cart_id:
                    self._recover_cart(cart_id)
                return "retry"
            # fresh login
            if self._login():
                if cart_id:
                    self._recover_cart(cart_id)
                return "retry"
            return "fail"
        # denied or other
        return "fail"

    def _get_catalog_product(self):
        with self.client.get("/v2/catalog", name="GET /v2/catalog",
                             catch_response=True, allow_redirects=False) as r:
            if r.status_code >= 400:
                r.failure("catalog status %s" % r.status_code)
                return None
            try:
                data = r.json()
            except Exception:
                r.failure("catalog json")
                return None
        products = (data.get("data") or {}).get("products") or []
        for p in products:
            for v in (p.get("variants") or []):
                if v.get("in_stock"):
                    return p.get("id"), v.get("id")
        # fallback: traverse pages
        next_url = data.get("next")
        pages = 0
        while next_url and pages < 3:
            pages += 1
            with self.client.get(_abs(next_url), name="GET /v2/catalog/page",
                                 catch_response=True, allow_redirects=False) as r:
                if r.status_code >= 400:
                    r.failure("catalog page status %s" % r.status_code)
                    return None
                try:
                    pdata = r.json()
                except Exception:
                    r.failure("catalog page json")
                    return None
            prod = pdata.get("product") or pdata.get("data") or {}
            if isinstance(prod, dict):
                for v in (prod.get("variants") or []):
                    if v.get("in_stock"):
                        return prod.get("id"), v.get("id")
            next_url = pdata.get("next")
        return None

    def _maybe_challenge(self):
        # attempt challenge flow; returns grant_id or None
        with self.client.get("/v2/challenge-form", name="GET /v2/challenge-form",
                             catch_response=True, allow_redirects=False) as r:
            if r.status_code >= 400:
                r.failure("challenge-form status %s" % r.status_code)
                return None
            action, token = self._extract_challenge(r.text or "")
        if not action or token is None:
            return None
        with self.client.post(_abs(action), json={"challenge": token},
                              headers={"X-CSRF-Token": self.csrf or ""},
                              name="POST /v2/challenges/[id]",
                              catch_response=True, allow_redirects=False) as r:
            if r.status_code == 302:
                loc = r.headers.get("Location")
                if not loc:
                    r.failure("challenge no location")
                    return None
                with self.client.get(_abs(loc), name="GET challenge-redirect",
                                     catch_response=True,
                                     allow_redirects=False) as r2:
                    if r2.status_code >= 400:
                        r2.failure("challenge redirect status %s" % r2.status_code)
                        return None
                    try:
                        data = r2.json()
                    except Exception:
                        return None
                    if data.get("csrf"):
                        self.csrf = data["csrf"]
                    return data.get("grant_id")
            if r.status_code >= 400:
                r.failure("challenge status %s" % r.status_code)
            return None

    def _create_cart(self, product_id, variant_id, grant_id):
        payload = {"product_id": product_id, "variant_id": variant_id}
        if grant_id:
            payload["grant_id"] = grant_id
        with self.client.post("/v2/carts", json=payload,
                              headers={"X-CSRF-Token": self.csrf or ""},
                              name="POST /v2/carts",
                              catch_response=True, allow_redirects=False) as r:
            if r.status_code == 401:
                action = self._handle_401(r, None)
                if action == "retry":
                    return self._create_cart(product_id, variant_id, grant_id)
                r.failure("cart 401")
                return None
            if r.status_code >= 400:
                r.failure("cart status %s" % r.status_code)
                return None
            try:
                data = r.json()
            except Exception:
                r.failure("cart json")
                return None
            if data.get("csrf"):
                self.csrf = data["csrf"]
            return data.get("id")

    def _patch_cart(self, cart_id, quantity):
        # read etag
        with self.client.get("/v2/carts/%s" % cart_id,
                             name="GET /v2/carts/[id]",
                             catch_response=True, allow_redirects=False) as r:
            if r.status_code == 401:
                action = self._handle_401(r, cart_id)
                if action == "retry":
                    return self._patch_cart(cart_id, quantity)
                r.failure("cart get 401")
                return False
            if r.status_code >= 400:
                r.failure("cart get status %s" % r.status_code)
                return False
            etag = r.headers.get("ETag")
        headers = {"X-CSRF-Token": self.csrf or ""}
        if etag:
            headers["If-Match"] = etag
        payload = {"quantity": quantity}
        with self.client.patch("/v2/carts/%s" % cart_id, json=payload,
                               headers=headers,
                               name="PATCH /v2/carts/[id]",
                               catch_response=True, allow_redirects=False) as r:
            if r.status_code == 412:
                # re-read and retry once
                with self.client.get("/v2/carts/%s" % cart_id,
                                     name="GET /v2/carts/[id]",
                                     catch_response=True,
                                     allow_redirects=False) as r2:
                    if r2.status_code >= 400:
                        r2.failure("cart re-read status %s" % r2.status_code)
                        return False
                    etag2 = r2.headers.get("ETag")
                headers2 = {"X-CSRF-Token": self.csrf or ""}
                if etag2:
                    headers2["If-Match"] = etag2
                with self.client.patch("/v2/carts/%s" % cart_id, json=payload,
                                       headers=headers2,
                                       name="PATCH /v2/carts/[id]",
                                       catch_response=True,
                                       allow_redirects=False) as r3:
                    if r3.status_code >= 400:
                        r3.failure("cart patch retry status %s" % r3.status_code)
                        return False
                    try:
                        d = r3.json()
                    except Exception:
                        d = {}
                    if d.get("csrf"):
                        self.csrf = d["csrf"]
                    return True
            if r.status_code == 401:
                action = self._handle_401(r, cart_id)
                if action == "retry":
                    return self._patch_cart(cart_id, quantity)
                r.failure("cart patch 401")
                return False
            if r.status_code >= 400:
                r.failure("cart patch status %s" % r.status_code)
                return False
            try:
                d = r.json()
            except Exception:
                d = {}
            if d.get("csrf"):
                self.csrf = d["csrf"]
            return True

    def _reserve(self, cart_id):
        with self.client.post("/v2/reservations", json={"cart_id": cart_id},
                              headers={"X-CSRF-Token": self.csrf or ""},
                              name="POST /v2/reservations",
                              catch_response=True, allow_redirects=False) as r:
            if r.status_code == 401:
                action = self._handle_401(r, cart_id)
                if action == "retry":
                    return self._reserve(cart_id)
                r.failure("reservation 401")
                return None
            if r.status_code >= 400:
                r.failure("reservation status %s" % r.status_code)
                return None
            try:
                data = r.json()
            except Exception:
                r.failure("reservation json")
                return None
            if data.get("csrf"):
                self.csrf = data["csrf"]
            status_url = data.get("status_url")
        if not status_url:
            return None
        for _ in range(5):
            time.sleep(0.06)
            with self.client.get(_abs(status_url), name="GET reservation status",
                                 catch_response=True, allow_redirects=False) as r:
                if r.status_code >= 400:
                    r.failure("res status %s" % r.status_code)
                    return None
                try:
                    sdata = r.json()
                except Exception:
                    r.failure("res json")
                    return None
            status = sdata.get("status")
            if status == "ready":
                return sdata.get("reservation_id")
            if status in ("pending",):
                continue
            return None
        return None

    def _order(self, cart_id, reservation_id):
        headers = {"X-CSRF-Token": self.csrf or "",
                   "Idempotency-Key": "cart-%s" % cart_id}
        payload = {"cart_id": cart_id}
        if reservation_id:
            payload["reservation_id"] = reservation_id
        with self.client.post("/v2/orders", json=payload, headers=headers,
                              name="POST /v2/orders",
                              catch_response=True, allow_redirects=False) as r:
            if r.status_code == 401:
                action = self._handle_401(r, cart_id)
                if action == "retry":
                    return self._order(cart_id, reservation_id)
                r.failure("order 401")
                return False
            if r.status_code >= 400:
                r.failure("order status %s" % r.status_code)
                return False
            try:
                data = r.json()
            except Exception:
                r.failure("order json")
                return False
            if data.get("csrf"):
                self.csrf = data["csrf"]
            if data.get("accepted") is True:
                return True
            r.failure("order not accepted")
            return False

    def _work(self):
        # POST /v2/work with scheduled 429 handling
        retries = 0
        while True:
            with self.client.post("/v2/work", json={},
                                  headers={"X-CSRF-Token": self.csrf or ""},
                                  name="POST /v2/work",
                                  catch_response=True,
                                  allow_redirects=False) as r:
                if r.status_code == 429:
                    ra = r.headers.get("Retry-After", "1")
                    try:
                        delay = float(ra)
                    except Exception:
                        delay = 1.0
                    if retries >= 4:
                        r.failure("work 429 exhausted")
                        return False
                    retries += 1
                    time.sleep(delay)
                    continue
                if r.status_code == 401:
                    action = self._handle_401(r, None)
                    if action == "retry":
                        continue
                    r.failure("work 401")
                    return False
                if r.status_code >= 400:
                    r.failure("work status %s" % r.status_code)
                    return False
                try:
                    data = r.json()
                except Exception:
                    r.failure("work json")
                    return False
                if data.get("ok") is True:
                    return True
                r.failure("work not ok")
                return False

    # ---------- journey ----------
    @task
    def journey(self):
        if self.iterations_done >= self.max_iterations:
            raise StopUser()
        if not self._login():
            self.iterations_done += 1
            if self.iterations_done >= self.max_iterations:
                raise StopUser()
            return

        prod = self._get_catalog_product()
        if not prod:
            self.iterations_done += 1
            if self.iterations_done >= self.max_iterations:
                raise StopUser()
            return
        product_id, variant_id = prod

        grant_id = self._maybe_challenge()
        cart_id = self._create_cart(product_id, variant_id, grant_id)
        if not cart_id:
            self.iterations_done += 1
            if self.iterations_done >= self.max_iterations:
                raise StopUser()
            return

        if not self._patch_cart(cart_id, 1):
            self.iterations_done += 1
            if self.iterations_done >= self.max_iterations:
                raise StopUser()
            return

        reservation_id = self._reserve(cart_id)
        if reservation_id:
            self._order(cart_id, reservation_id)

        self._work()

        self.iterations_done += 1
        if self.iterations_done >= self.max_iterations:
            raise StopUser()


class PhasedShape(LoadTestShape):
    # Phased targets 5/15/5 over three 10s plateaus, warmup 5s, drain <=5s.
    # Total scored window 30s. Users=2, iterations=2, rate=5.
    def tick(self):
        t = self.get_run_time()
        if t < 5:
            return (2, 5)
        if t < 15:
            return (2, 5)
        if t < 25:
            return (2, 5)
        if t < 35:
            return (2, 5)
        if t < 40:
            return (1, 5)
        return None
