import io.gatling.javaapi.core.*;
import io.gatling.javaapi.http.*;

import java.time.Duration;
import java.util.*;
import java.util.concurrent.ThreadLocalRandom;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

import static io.gatling.javaapi.core.CoreDsl.*;
import static io.gatling.javaapi.http.HttpDsl.*;

public class ModelSimulation extends Simulation {

    private static final String BASE_URL = System.getenv().getOrDefault("BASE_URL", "http://127.0.0.1:8000");

    private static final Pattern CSRF_INPUT = Pattern.compile(
            "name=[\"']csrf[\"'][^>]*value=[\"']([^\"']+)[\"']|value=[\"']([^\"']+)[\"'][^>]*name=[\"']csrf[\"']");
    private static final Pattern CHALLENGE_ACTION = Pattern.compile("action=[\"']([^\"']*?/v2/challenges/[^\"']+)[\"']");
    private static final Pattern CHALLENGE_INPUT = Pattern.compile(
            "name=[\"']challenge[\"'][^>]*value=[\"']([^\"']*)[\"']|value=[\"']([^\"']*)[\"'][^>]*name=[\"']challenge[\"']");

    private static final int USERS = 2;
    private static final int ITERATIONS = 2;

    private static final HttpProtocolBuilder HTTP = http
            .baseUrl(BASE_URL)
            .disableAutoRedirect()
            .acceptHeader("application/json, text/html")
            .contentTypeHeader("application/json")
            .shareConnections();

    private static String pick(Matcher m) {
        if (m == null || !m.find()) return null;
        for (int i = 1; i <= m.groupCount(); i++) {
            if (m.group(i) != null) return m.group(i);
        }
        return null;
    }

    private static ChainBuilder login() {
        return exec(
                http("login-form")
                        .get("/v2/login-form")
                        .check(status().lt(400))
                        .check(bodyString().saveAs("loginFormBody"))
        ).exec(session -> {
            String body = session.getString("loginFormBody");
            String csrf = pick(CSRF_INPUT.matcher(body == null ? "" : body));
            return session.set("loginCsrf", csrf == null ? "" : csrf);
        }).exec(
                http("login")
                        .post("/v2/login")
                        .body(StringBody(session -> {
                            String user = session.getString("username");
                            String csrf = session.getString("loginCsrf");
                            return "{\"username\":\"" + user + "\",\"password\":\"bench\",\"csrf\":\"" + csrf + "\"}";
                        }))
                        .check(status().in(200, 201, 302))
                        .check(bodyString().saveAs("loginBody"))
        ).exec(session -> {
            String body = session.getString("loginBody");
            String csrf = null;
            if (body != null) {
                Matcher m = Pattern.compile("\"csrf\"\\s*:\\s*\"([^\"]+)\"").matcher(body);
                if (m.find()) csrf = m.group(1);
            }
            if (csrf == null) csrf = session.getString("loginCsrf");
            return session.set("csrf", csrf == null ? "" : csrf);
        });
    }

    private static ChainBuilder renew() {
        return exec(
                http("renew")
                        .post("/v2/session/renew")
                        .header("X-CSRF-Token", session -> session.getString("csrf"))
                        .body(StringBody("{}"))
                        .check(status().lt(400))
                        .check(bodyString().saveAs("renewBody"))
        ).exec(session -> {
            String body = session.getString("renewBody");
            String csrf = null;
            if (body != null) {
                Matcher m = Pattern.compile("\"csrf\"\\s*:\\s*\"([^\"]+)\"").matcher(body);
                if (m.find()) csrf = m.group(1);
            }
            return csrf == null ? session : session.set("csrf", csrf);
        });
    }

    private static ChainBuilder workOnce() {
        return exec(
                http("work")
                        .post("/v2/work")
                        .header("X-CSRF-Token", session -> session.getString("csrf"))
                        .body(StringBody("{}"))
                        .check(status().in(200, 429))
                        .check(bodyString().saveAs("workBody"))
        ).exec(session -> {
            Integer status = session.getInt("workStatus");
            return session;
        });
    }

    private static ChainBuilder workWithRetry() {
        return asLongAs(session -> {
            Integer retries = session.getInt("workRetries");
            return retries != null && retries < 4;
        }, exec(session -> session.set("workRetries", session.getInt("workRetries") + 1))
                .exec(
                        http("work-retry")
                                .post("/v2/work")
                                .header("X-CSRF-Token", session -> session.getString("csrf"))
                                .body(StringBody("{}"))
                                .check(status().in(200, 429))
                                .check(bodyString().saveAs("workBody"))
                )
                .exec(session -> {
                    Integer status = session.getInt("workStatus");
                    if (status != null && status == 429) {
                        return session;
                    }
                    return session.set("workRetries", 4);
                })
                .pause(Duration.ofMillis(1000))
        );
    }

    private static ChainBuilder browse() {
        return exec(
                http("browse")
                        .post("/v2/browse")
                        .header("X-CSRF-Token", session -> session.getString("csrf"))
                        .body(StringBody("{}"))
                        .check(status().lt(400))
        );
    }

    private static ChainBuilder catalog() {
        return exec(
                http("catalog")
                        .get("/v2/catalog")
                        .check(status().lt(400))
                        .check(bodyString().saveAs("catalogBody"))
        ).exec(session -> {
            String body = session.getString("catalogBody");
            String pid = null, vid = null;
            if (body != null) {
                Matcher pm = Pattern.compile("\"id\"\\s*:\\s*\"([^\"]+)\"[^}]*?\"variants\"\\s*:\\s*\\[\\s*\\{[^}]*?\"id\"\\s*:\\s*\"([^\"]+)\"").matcher(body);
                if (pm.find()) {
                    pid = pm.group(1);
                    vid = pm.group(2);
                }
            }
            return session.set("productId", pid == null ? "" : pid).set("variantId", vid == null ? "" : vid);
        });
    }

    private static ChainBuilder cartCreate() {
        return exec(
                http("cart-create")
                        .post("/v2/carts")
                        .header("X-CSRF-Token", session -> session.getString("csrf"))
                        .body(StringBody(session -> {
                            String pid = session.getString("productId");
                            String vid = session.getString("variantId");
                            return "{\"product_id\":\"" + pid + "\",\"variant_id\":\"" + vid + "\"}";
                        }))
                        .check(status().in(200, 201))
                        .check(bodyString().saveAs("cartBody"))
        ).exec(session -> {
            String body = session.getString("cartBody");
            String cartId = null, csrf = null;
            if (body != null) {
                Matcher cm = Pattern.compile("\"id\"\\s*:\\s*\"([^\"]+)\"").matcher(body);
                if (cm.find()) cartId = cm.group(1);
                Matcher sm = Pattern.compile("\"csrf\"\\s*:\\s*\"([^\"]+)\"").matcher(body);
                if (sm.find()) csrf = sm.group(1);
            }
            Session s = session.set("cartId", cartId == null ? "" : cartId);
            if (csrf != null) s = s.set("csrf", csrf);
            return s;
        });
    }

    private static ChainBuilder cartPatch() {
        return exec(
                http("cart-get")
                        .get(session -> "/v2/carts/" + session.getString("cartId"))
                        .check(status().lt(400))
                        .check(header("ETag").saveAs("etag"))
        ).exec(
                http("cart-patch")
                        .patch(session -> "/v2/carts/" + session.getString("cartId"))
                        .header("X-CSRF-Token", session -> session.getString("csrf"))
                        .header("If-Match", session -> session.getString("etag"))
                        .body(StringBody("{\"quantity\":1}"))
                        .check(status().in(200, 204, 412))
        );
    }

    private static ChainBuilder order() {
        return exec(
                http("order")
                        .post("/v2/orders")
                        .header("X-CSRF-Token", session -> session.getString("csrf"))
                        .header("Idempotency-Key", session -> "idem-" + session.getString("cartId"))
                        .body(StringBody(session -> "{\"cart_id\":\"" + session.getString("cartId") + "\"}"))
                        .check(status().in(200, 201))
                        .check(bodyString().saveAs("orderBody"))
        ).exec(session -> {
            String body = session.getString("orderBody");
            boolean accepted = body != null && body.contains("\"accepted\":true");
            return session.set("orderAccepted", accepted);
        });
    }

    private static ChainBuilder journey() {
        return exec(session -> session
                        .set("username", "bench-" + (1 + ThreadLocalRandom.current().nextInt(16)))
                        .set("workRetries", 0))
                .exec(login())
                .exec(catalog())
                .exec(cartCreate())
                .exec(cartPatch())
                .exec(workOnce())
                .exec(session -> {
                    Integer status = session.getInt("workStatus");
                    if (status != null && status == 429) {
                        return session.set("workRetries", 0);
                    }
                    return session.set("workRetries", 4);
                })
                .exec(workWithRetry())
                .exec(browse())
                .exec(order());
    }

    private static final ScenarioBuilder SCENARIO = scenario("ModelSimulation")
            .exec(journey())
            .repeat(ITERATIONS - 1).on(exec(journey()));

    {
        setUp(
                SCENARIO.injectOpen(
                        rampUsers(USERS).during(Duration.ofSeconds(1))
                )
        ).protocols(HTTP)
                .maxDuration(Duration.ofSeconds(60));
    }
}
