import http from 'k6/http';
import { check, sleep } from 'k6';
import { Counter, Rate, Trend } from 'k6/metrics';
import encoding from 'k6/encoding';

const BASE = __ENV.BASE_URL || 'http://127.0.0.1:8000';

const workStarts = new Counter('work_starts');
const workOk = new Counter('work_ok');
const workUnexpected = new Counter('work_unexpected');
const workScheduled = new Counter('work_scheduled');
const workDropped = new Counter('work_dropped');
const workRate = new Rate('work_rate');
const workLatency = new Trend('work_latency');

export const options = {
  scenarios: {
    work: {
      executor: 'constant-arrival-rate',
      rate: 5,
      timeUnit: '1s',
      duration: '40s',
      preAllocatedVUs: 8,
      maxVUs: 32,
      gracefulStop: '5s',
    },
  },
  thresholds: {
    work_rate: ['rate>0.99'],
  },
  discardResponseBodies: false,
  noConnectionReuse: false,
};

function parseCsrf(html) {
  if (!html) return null;
  // find input[name=csrf] with value, tolerant of attribute order/quotes
  const re = /<input\b[^>]*>/gi;
  let m;
  while ((m = re.exec(html)) !== null) {
    const tag = m[0];
    if (!/\bname\s*=\s*["']?csrf["']?/i.test(tag)) continue;
    const vm = tag.match(/\bvalue\s*=\s*["']([^"']*)["']/i);
    if (vm) return vm[1];
  }
  return null;
}

function parseChallengeAction(html) {
  if (!html) return null;
  const re = /<form\b[^>]*>/gi;
  let m;
  while ((m = re.exec(html)) !== null) {
    const tag = m[0];
    const am = tag.match(/\baction\s*=\s*["']([^"']*)["']/i);
    if (am && /\/v2\/challenges\//.test(am[1])) return am[1];
  }
  return null;
}

function parseChallengeInput(html) {
  if (!html) return null;
  const re = /<input\b[^>]*>/gi;
  let m;
  while ((m = re.exec(html)) !== null) {
    const tag = m[0];
    if (!/\bname\s*=\s*["']?challenge["']?/i.test(tag)) continue;
    const vm = tag.match(/\bvalue\s*=\s*["']([^"']*)["']/i);
    if (vm) return vm[1];
  }
  return null;
}

function jarFor(user) {
  return new http.CookieJar();
}

function getCsrfFromJar(jar) {
  const cookies = jar.cookiesForURL(BASE);
  if (cookies && cookies.csrf && cookies.csrf.length) return cookies.csrf[0];
  return null;
}

function login(user, jar) {
  const formRes = http.get(`${BASE}/v2/login-form`, { jar, redirects: 0 });
  if (formRes.status !== 200) return null;
  const csrf = parseCsrf(formRes.body);
  if (!csrf) return null;
  const loginRes = http.post(
    `${BASE}/v2/login`,
    JSON.stringify({ username: user, password: 'bench', csrf }),
    { jar, redirects: 0, headers: { 'Content-Type': 'application/json' } }
  );
  if (loginRes.status === 302) {
    const loc = loginRes.headers['Location'];
    if (loc) {
      const follow = http.get(loc.startsWith('http') ? loc : `${BASE}${loc}`, { jar, redirects: 0 });
      if (follow.status >= 400) return null;
    }
  } else if (loginRes.status >= 400) {
    return null;
  }
  let body = null;
  try { body = loginRes.json(); } catch (e) { body = null; }
  let token = body && body.csrf ? body.csrf : null;
  if (!token) token = getCsrfFromJar(jar);
  return token;
}

function renew(jar, csrf) {
  const res = http.post(`${BASE}/v2/session/renew`, JSON.stringify({}), {
    jar,
    redirects: 0,
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf || '' },
  });
  if (res.status >= 400) return null;
  let body = null;
  try { body = res.json(); } catch (e) { body = null; }
  return (body && body.csrf) ? body.csrf : csrf;
}

function doWork(jar, csrf) {
  let token = csrf;
  let attempts = 0;
  let scheduledRetries = 0;
  while (attempts < 2) {
    attempts++;
    const res = http.post(`${BASE}/v2/work`, JSON.stringify({}), {
      jar,
      redirects: 0,
      headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': token || '' },
      tags: { op: 'work' },
    });
    workStarts.add(1);
    workLatency.add(res.timings.duration);

    if (res.status === 429) {
      workScheduled.add(1);
      if (scheduledRetries >= 4) {
        workDropped.add(1);
        workRate.add(false);
        return { ok: false, token };
      }
      scheduledRetries++;
      const ra = res.headers['Retry-After'];
      let wait = 1;
      if (ra) {
        const n = parseFloat(ra);
        if (!isNaN(n)) wait = n;
      }
      sleep(wait);
      continue;
    }

    if (res.status === 401) {
      let err = null;
      try { err = res.json(); } catch (e) { err = null; }
      const code = err && err.error;
      if (code === 'expired') {
        const fresh = renew(jar, token);
        if (!fresh) {
          workUnexpected.add(1);
          workRate.add(false);
          return { ok: false, token };
        }
        token = fresh;
        continue;
      }
      // denied or session: not retryable here
      workUnexpected.add(1);
      workRate.add(false);
      return { ok: false, token };
    }

    if (res.status >= 400) {
      workUnexpected.add(1);
      workRate.add(false);
      return { ok: false, token };
    }

    let body = null;
    try { body = res.json(); } catch (e) { body = null; }
    if (body && body.csrf) token = body.csrf;
    const ok = !!(body && body.ok === true);
    if (ok) {
      workOk.add(1);
      workRate.add(true);
    } else {
      workUnexpected.add(1);
      workRate.add(false);
    }
    return { ok, token };
  }
  workDropped.add(1);
  workRate.add(false);
  return { ok: false, token };
}

export default function () {
  const user = `bench-${((__VU - 1) % 16) + 1}`;
  const jar = jarFor(user);
  const csrf = login(user, jar);
  if (!csrf) {
    workDropped.add(1);
    workRate.add(false);
    return;
  }
  doWork(jar, csrf);
}
