import os
import re
import time
import uuid
import random
from urllib.parse import urljoin

from locust import HttpUser, task, between, events
from locust.exception import StopUser, RescheduleTaskImmediately


BASE_URL = os.environ.get("BASE_URL", "http://127.0.0.1:8000")
PASSWORD = "bench"
USERS = ["bench-1", "bench-2", "bench-3", "bench-4", "bench-5", "bench-6",
         "bench-7", "bench-8", "bench-9", "bench-10", "bench-11", "bench-12",
         "bench-13", "bench-14", "bench-15", "bench-16", "bench"]

CSRF_INPUT_RE = re.compile(
    r"""<input[^>]*name\s*=\s*["']?csrf["']?[^>]*>""", re.IGNORECASE)
VALUE_RE = re.compile(r"""value\s*=\s*["']([^"']*)["']""", re.IGNORECASE)
ACTION_RE = re.compile(r"""action\s*=\s*["']([^"']*)["']""", re.IGNORECASE)
CHALLENGE_INPUT_RE = re.compile(
    r"""<input[^>]*name\s*=\s*["']?challenge["']?[^>]*>""", re.IGNORECASE)


def _extract_csrf(html):
    m = CSRF_INPUT_RE.search(html or "")
    if not m:
        return None
    v = VALUE_RE.search(m.group(0))
    return v.group(1) if v else None


def _extract_challenge(html):
    m = CHALLENGE_INPUT_RE.search(html or "")
    if not m:
        return None
    v = VALUE_RE.search(m.group(0))
    return v.group(1) if v else None


def _extract_action(html):
    m = ACTION_RE.search(html or "")
    return m.group(1) if m else None


class ShopUser(HttpUser):
    host = BASE_URL
    wait_time = between(0.05, 0.15)

    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self.username = random.choice(USERS)
        self.csrf = None
        self.session_ready = False
        self.iterations_done = 0
        self.max_iterations = 2
        self.cart_id = None
        self.cart_etag = None
        self.grant_id = None
        self.reservation_id = None
        self.idem_key = None

    # ---------- low level helpers ----------
    def _req(self, method, path, name=None, **kwargs):
        kwargs.setdefault("allow_redirects", False)
        return self.client.request(method, path, name=name or path, **kwargs)

    def _auth_headers(self, extra=None):
        h = {}
        if self.csrf:
            h["X-CSRF-Token"] = self.csrf
        if extra:
            h.update(extra)
        return h

    def _capture_csrf(self, resp):
        try:
            data = resp.json()
        except Exception:
            return
        if isinstance(data, dict) and data.get("csrf"):
            self.csrf = data["csrf"]

    # ---------- auth ----------
    def do_login(self):
        r = self._req("GET", "/v2/login-form", name="GET /v2/login-form")
        if r.status_code >= 400:
            return False
        csrf = _extract_csrf(r.text)
        if not csrf:
            return False
        r = self._req(
            "POST", "/v2/login", name="POST /v2/login",
            json={"username": self.username, "password": PASSWORD, "csrf": csrf},
            headers={"X-CSRF-Token": csrf},
        )
        if r.status_code == 302:
            loc = r.headers.get("Location")
            if loc:
                r2 = self._req("GET", loc, name="GET login redirect")
                if r2.status_code >= 400:
                    return False
                self._capture_csrf(r2)
        if r.status_code >= 400:
            return False
        self._capture_csrf(r)
        if not self.csrf:
            self.csrf = csrf
        self.session_ready = True
        return True

    def renew(self):
        r = self._req(
            "POST", "/v2/session/renew", name="POST /v2/session/renew",
            json={}, headers=self._auth_headers(),
        )
        if r.status_code >= 400:
            return False
        self._capture_csrf(r)
        return True

    def recover_cart(self):
        if not self.cart_id:
            return True
        r = self._req(
            "POST", "/v2/carts/%s/recover" % self.cart_id,
            name="POST /v2/carts/[id]/recover",
            json={}, headers=self._auth_headers(),
        )
        if r.status_code >= 400:
            return False
        self._capture_csrf(r)
        return True

    def handle_401(self, resp):
        try:
            data = resp.json()
        except Exception:
            data = {}
        err = (data or {}).get("error")
        if err == "denied":
            return False
        if err == "expired":
            if not self.renew():
                return False
            self.recover_cart()
            return True
        if err == "session":
            self.session_ready = False
            if not self.do_login():
                return False
            self.recover_cart()
            return True
        return False

    # ---------- catalog ----------
    def fetch_catalog(self):
        r = self._req("GET", "/v2/catalog", name="GET /v2/catalog")
        if r.status_code >= 400:
            return None
        try:
            data = r.json()
        except Exception:
            return None
        products = (data.get("data") or {}).get("products") or []
        if not products:
            return None
        return products

    def fetch_catalog_page(self):
        products = []
        url = "/v2/catalog/page"
        for _ in range(3):
            r = self._req("GET", url, name="GET /v2/catalog/page")
            if r.status_code >= 400:
                break
            try:
                data = r.json()
            except Exception:
                break
            if isinstance(data, dict) and data.get("product"):
                products.append(data["product"])
            elif isinstance(data, dict) and data.get("data"):
                p = data["data"].get("product")
                if p:
                    products.append(p)
            nxt = data.get("next") if isinstance(data, dict) else None
            if not nxt:
                break
            url = nxt if nxt.startswith("/") else "/" + nxt.lstrip("./")
        return products

    def pick_variant(self, products):
        for p in products:
            variants = p.get("variants") or []
            for v in variants:
                if v.get("in_stock"):
                    return p.get("id"), v.get("id")
        return None, None

    # ---------- challenge ----------
    def solve_challenge(self):
        r = self._req("GET", "/v2/challenge-form", name="GET /v2/challenge-form")
        if r.status_code >= 400:
            return False
        action = _extract_action(r.text)
        challenge = _extract_challenge(r.text)
        if not action or not challenge:
            return False
        r = self._req(
            "POST", action, name="POST /v2/challenges/[id]",
            json={"challenge": challenge}, headers=self._auth_headers(),
        )
        if r.status_code == 302:
            loc = r.headers.get("Location")
            if loc:
                r2 = self._req("GET", loc, name="GET challenge redirect")
                if r2.status_code >= 400:
                    return False
                try:
                    data = r2.json()
                except Exception:
                    data = {}
                if isinstance(data, dict) and data.get("grant_id"):
                    self.grant_id = data["grant_id"]
                self._capture_csrf(r2)
                return True
        return False

    # ---------- cart ----------
    def create_cart(self, product_id, variant_id):
        body = {"product_id": product_id, "variant_id": variant_id}
        if self.grant_id:
            body["grant_id"] = self.grant_id
            self.grant_id = None
        r = self._req(
            "POST", "/v2/carts", name="POST /v2/carts",
            json=body, headers=self._auth_headers(),
        )
        if r.status_code == 401 and self.handle_401(r):
            r = self._req(
                "POST", "/v2/carts", name="POST /v2/carts",
                json=body, headers=self._auth_headers(),
            )
        if r.status_code >= 400:
            return False
        try:
            data = r.json()
        except Exception:
            return False
        self.cart_id = data.get("id")
        self.cart_etag = r.headers.get("ETag")
        self._capture_csrf(r)
        self.idem_key = str(uuid.uuid4())
        return bool(self.cart_id)

    def patch_cart(self):
        if not self.cart_id:
            return False
        payload = {"quantity": random.randint(1, 5)}
        headers = self._auth_headers()
        if self.cart_etag:
            headers["If-Match"] = self.cart_etag
        r = self._req(
            "PATCH", "/v2/carts/%s" % self.cart_id,
            name="PATCH /v2/carts/[id]",
            json=payload, headers=headers,
        )
        if r.status_code == 401 and self.handle_401(r):
            headers = self._auth_headers()
            if self.cart_etag:
                headers["If-Match"] = self.cart_etag
            r = self._req(
                "PATCH", "/v2/carts/%s" % self.cart_id,
                name="PATCH /v2/carts/[id]",
                json=payload, headers=headers,
            )
        if r.status_code == 412:
            rr = self._req("GET", "/v2/carts/%s" % self.cart_id,
                           name="GET /v2/carts/[id]")
            if rr.status_code < 400:
                self.cart_etag = rr.headers.get("ETag")
            headers = self._auth_headers()
            if self.cart_etag:
                headers["If-Match"] = self.cart_etag
            r = self._req(
                "PATCH", "/v2/carts/%s" % self.cart_id,
                name="PATCH /v2/carts/[id]",
                json=payload, headers=headers,
            )
        if r.status_code >= 400:
            return False
        self.cart_etag = r.headers.get("ETag", self.cart_etag)
        self._capture_csrf(r)
        return True

    # ---------- reservation ----------
    def reserve(self):
        if not self.cart_id:
            return False
        r = self._req(
            "POST", "/v2/reservations", name="POST /v2/reservations",
            json={"cart_id": self.cart_id}, headers=self._auth_headers(),
        )
        if r.status_code == 401 and self.handle_401(r):
            r = self._req(
                "POST", "/v2/reservations", name="POST /v2/reservations",
                json={"cart_id": self.cart_id}, headers=self._auth_headers(),
            )
        if r.status_code >= 400:
            return False
        try:
            data = r.json()
        except Exception:
            return False
        self._capture_csrf(r)
        status_url = data.get("status_url")
        if not status_url:
            return False
        for _ in range(5):
            time.sleep(0.06)
            sr = self._req("GET", status_url, name="GET reservation status")
            if sr.status_code >= 400:
                return False
            try:
                sd = sr.json()
            except Exception:
                return False
            st = sd.get("status")
            if st == "ready":
                self.reservation_id = sd.get("reservation_id")
                return bool(self.reservation_id)
            if st in ("pending",):
                continue
            return False
        return False

    # ---------- order ----------
    def place_order(self):
        if not self.cart_id or not self.idem_key:
            return False
        body = {"cart_id": self.cart_id}
        if self.reservation_id:
            body["reservation_id"] = self.reservation_id
        headers = self._auth_headers({"Idempotency-Key": self.idem_key})
        if self.cart_etag:
            headers["If-Match"] = self.cart_etag
        r = self._req(
            "POST", "/v2/orders", name="POST /v2/orders",
            json=body, headers=headers,
        )
        if r.status_code == 401 and self.handle_401(r):
            headers = self._auth_headers({"Idempotency-Key": self.idem_key})
            if self.cart_etag:
                headers["If-Match"] = self.cart_etag
            r = self._req(
                "POST", "/v2/orders", name="POST /v2/orders",
                json=body, headers=headers,
            )
        if r.status_code >= 400:
            return False
        try:
            data = r.json()
        except Exception:
            return False
        self._capture_csrf(r)
        if data.get("accepted") is True and data.get("id"):
            return True
        return False

    # ---------- work ----------
    def do_work(self):
        attempts = 0
        while attempts < 5:
            attempts += 1
            with self.client.post(
                "/v2/work", name="POST /v2/work",
                json={}, headers=self._auth_headers(),
                catch_response=True, allow_redirects=False,
            ) as resp:
                if resp.status_code == 401:
                    if self.handle_401(resp):
                        resp.failure("renewed")
                        continue
                    resp.failure("401 denied/unrecoverable")
                    return False
                if resp.status_code == 429:
                    ra = resp.headers.get("Retry-After", "1")
                    try:
                        delay = float(ra)
                    except Exception:
                        delay = 1.0
                    resp.failure("scheduled 429")
                    time.sleep(min(max(delay, 0.05), 1.0))
                    continue
                if resp.status_code >= 500:
                    resp.failure("unexpected %d" % resp.status_code)
                    return False
                if resp.status_code >= 400:
                    resp.failure("unexpected %d" % resp.status_code)
                    return False
                try:
                    data = resp.json()
                except Exception:
                    resp.failure("bad json")
                    return False
                if not (isinstance(data, dict) and data.get("ok") is True):
                    resp.failure("ok!=true")
                    return False
                self._capture_csrf(resp)
                resp.success()
                return True
        return False

    # ---------- journey ----------
    @task
    def journey(self):
        if self.iterations_done >= self.max_iterations:
            raise StopUser()
        self.iterations_done += 1

        self.session_ready = False
        self.cart_id = None
        self.cart_etag = None
        self.grant_id = None
        self.reservation_id = None
        self.idem_key = None

        if not self.do_login():
            raise StopUser()

        products = self.fetch_catalog()
        if not products:
            products = self.fetch_catalog_page()
        if not products:
            raise StopUser()

        pid, vid = self.pick_variant(products)
        if not pid or not vid:
            raise StopUser()

        # challenge (best effort)
        self.solve_challenge()

        if not self.create_cart(pid, vid):
            raise StopUser()

        self.patch_cart()

        if not self.reserve():
            raise StopUser()

        if not self.place_order():
            raise StopUser()

        self.do_work()

        if self.iterations_done >= self.max_iterations:
            raise StopUser()


class LoadTestShape:
    def __init__(self):
        self.start = None
        self.phase = 0

    def tick(self):
        now = time.time()
        if self.start is None:
            self.start = now
        elapsed = now - self.start

        # warmup 5s, then 3x10s plateaus: 5, 15, 5 users, then drain 5s
        if elapsed < 5:
            return (2, 1)
        if elapsed < 15:
            return (5, 1)
        if elapsed < 25:
            return (15, 1)
        if elapsed < 35:
            return (5, 1)
        if elapsed < 40:
            return (0, 1)
        return None
