import io.gatling.javaapi.core.*;
import io.gatling.javaapi.http.*;

import java.time.Duration;
import java.util.*;
import java.util.concurrent.ThreadLocalRandom;
import java.util.concurrent.atomic.AtomicInteger;

import static io.gatling.javaapi.core.CoreDsl.*;
import static io.gatling.javaapi.http.HttpDsl.*;

public class ModelSimulation extends Simulation {

    private static final String BASE_URL = System.getenv().getOrDefault("BASE_URL", "http://127.0.0.1:8000");

    private static final HttpProtocolBuilder HTTP = http
            .baseUrl(BASE_URL)
            .disableAutoReferer()
            .disableCaching()
            .disableFollowRedirect()
            .acceptHeader("application/json")
            .contentTypeHeader("application/json");

    // ---- helpers ----
    private static String csrfFrom(String body) {
        // extract csrf from JSON {"csrf":"..."} or {"data":{"csrf":"..."}}
        if (body == null) return null;
        int i = body.indexOf("\"csrf\"");
        if (i < 0) return null;
        int c = body.indexOf(':', i);
        if (c < 0) return null;
        int q1 = body.indexOf('"', c);
        if (q1 < 0) return null;
        int q2 = body.indexOf('"', q1 + 1);
        if (q2 < 0) return null;
        return body.substring(q1 + 1, q2);
    }

    private static String jsonStr(String body, String key) {
        if (body == null) return null;
        int i = body.indexOf("\"" + key + "\"");
        if (i < 0) return null;
        int c = body.indexOf(':', i);
        if (c < 0) return null;
        int q1 = body.indexOf('"', c);
        if (q1 < 0) return null;
        int q2 = body.indexOf('"', q1 + 1);
        if (q2 < 0) return null;
        return body.substring(q1 + 1, q2);
    }

    private static String jsonNum(String body, String key) {
        if (body == null) return null;
        int i = body.indexOf("\"" + key + "\"");
        if (i < 0) return null;
        int c = body.indexOf(':', i);
        if (c < 0) return null;
        int s = c + 1;
        while (s < body.length() && (body.charAt(s) == ' ' || body.charAt(s) == '\t')) s++;
        int e = s;
        while (e < body.length() && (Character.isDigit(body.charAt(e)) || body.charAt(e) == '-')) e++;
        if (e <= s) return null;
        return body.substring(s, e);
    }

    private static String extractAttr(String html, String name) {
        if (html == null) return null;
        // find input with name=name, then value="..."
        int idx = 0;
        while (true) {
            int n = html.indexOf("name=\"" + name + "\"", idx);
            int n2 = html.indexOf("name='" + name + "'", idx);
            int n3 = html.indexOf("name=" + name, idx);
            int best = -1;
            if (n >= 0) best = n;
            if (n2 >= 0 && (best < 0 || n2 < best)) best = n2;
            if (n3 >= 0 && (best < 0 || n3 < best)) best = n3;
            if (best < 0) return null;
            // find enclosing tag start
            int tagStart = html.lastIndexOf('<', best);
            int tagEnd = html.indexOf('>', best);
            if (tagStart < 0 || tagEnd < 0) return null;
            String tag = html.substring(tagStart, tagEnd + 1);
            // find value
            int v = tag.indexOf("value=\"");
            if (v >= 0) {
                int q1 = v + 7;
                int q2 = tag.indexOf('"', q1);
                if (q2 > q1) return tag.substring(q1, q2);
            }
            int v2 = tag.indexOf("value='");
            if (v2 >= 0) {
                int q1 = v2 + 7;
                int q2 = tag.indexOf('\'', q1);
                if (q2 > q1) return tag.substring(q1, q2);
            }
            idx = tagEnd + 1;
        }
    }

    private static String extractFormAction(String html) {
        if (html == null) return null;
        int f = html.indexOf("<form");
        if (f < 0) return null;
        int e = html.indexOf('>', f);
        if (e < 0) return null;
        String tag = html.substring(f, e + 1);
        int a = tag.indexOf("action=\"");
        if (a >= 0) {
            int q1 = a + 8;
            int q2 = tag.indexOf('"', q1);
            if (q2 > q1) return tag.substring(q1, q2);
        }
        int a2 = tag.indexOf("action='");
        if (a2 >= 0) {
            int q1 = a2 + 8;
            int q2 = tag.indexOf('\'', q1);
            if (q2 > q1) return tag.substring(q1, q2);
        }
        return null;
    }

    private static String extractLocation(String header) {
        return header;
    }

    // ---- chains ----

    // Login chain: GET form -> POST login -> (302 -> GET location) -> session ready
    private static ChainBuilder login(String user) {
        return exec(
                http("login-form")
                        .get("/v2/login-form")
                        .check(status().is(200))
                        .check(bodyString().saveAs("loginFormBody"))
        ).exec(session -> {
            String body = session.getString("loginFormBody");
            String csrf = extractAttr(body, "csrf");
            if (csrf == null) csrf = extractAttr(body, "_csrf");
            return session.set("loginCsrf", csrf == null ? "" : csrf);
        }).exec(
                http("login-post")
                        .post("/v2/login")
                        .body(StringBody(session -> {
                            String csrf = session.getString("loginCsrf");
                            return "{\"username\":\"" + user + "\",\"password\":\"bench\",\"csrf\":\"" + csrf + "\"}";
                        }))
                        .check(status().in(200, 302))
                        .check(header("Location").optional().saveAs("loginLocation"))
                        .check(bodyString().optional().saveAs("loginBody"))
        ).exec(session -> {
            String loc = session.getString("loginLocation");
            String body = session.getString("loginBody");
            String csrf = csrfFrom(body);
            if (csrf != null) session = session.set("csrf", csrf);
            return session.set("loginRedirect", loc == null ? "" : loc);
        }).doIf(session -> {
            String loc = session.getString("loginRedirect");
            return loc != null && !loc.isEmpty();
        }).then(
                exec(
                        http("login-redirect")
                                .get(session -> session.getString("loginRedirect"))
                                .check(status().is(200))
                                .check(bodyString().saveAs("loginRedirectBody"))
                ).exec(session -> {
                    String body = session.getString("loginRedirectBody");
                    String csrf = csrfFrom(body);
                    if (csrf != null) return session.set("csrf", csrf);
                    return session;
                })
        );
    }

    // Renewal chain
    private static ChainBuilder renew() {
        return exec(
                http("renew")
                        .post("/v2/session/renew")
                        .header("X-CSRF-Token", session -> session.getString("csrf"))
                        .body(StringBody("{}"))
                        .check(status().in(200, 401))
                        .check(bodyString().optional().saveAs("renewBody"))
        ).exec(session -> {
            String body = session.getString("renewBody");
            String csrf = csrfFrom(body);
            if (csrf != null) return session.set("csrf", csrf);
            return session;
        });
    }

    // Work operation with retry on scheduled 429 and expiry
    private static ChainBuilder workOp() {
        return asLongAs(session -> session.getInt("workAttempt") < 5).on(
                exec(session -> session.set("workAttempt", session.getInt("workAttempt") + 1))
                        .exec(
                                http("work")
                                        .post("/v2/work")
                                        .header("X-CSRF-Token", session -> session.getString("csrf"))
                                        .body(StringBody("{}"))
                                        .check(status().saveAs("workStatus"))
                                        .check(bodyString().optional().saveAs("workBody"))
                                        .check(header("Retry-After").optional().saveAs("retryAfter"))
                        )
                        .exec(session -> {
                            int st = session.getInt("workStatus");
                            if (st == 429) {
                                String ra = session.getString("retryAfter");
                                long ms = 1000L;
                                try { if (ra != null) ms = (long) (Double.parseDouble(ra) * 1000); } catch (Exception ignored) {}
                                return session.set("workSleep", ms);
                            }
                            return session.set("workSleep", 0L);
                        })
                        .doIf(session -> session.getInt("workStatus") == 429).then(
                                pause(session -> Duration.ofMillis(session.getLong("workSleep")))
                        )
                        .doIf(session -> session.getInt("workStatus") == 401).then(
                                renew()
                        )
                        .doIf(session -> session.getInt("workStatus") == 200).then(
                                exec(session -> session.set("workDone", true))
                        )
                        .doIf(session -> session.getInt("workStatus") >= 400 && session.getInt("workStatus") != 429 && session.getInt("workStatus") != 401).then(
                                exec(session -> session.markAsFailed("work failed status " + session.getInt("workStatus")))
                        )
        ).exec(session -> {
            if (!session.getBoolean("workDone")) {
                return session.markAsFailed("work not completed");
            }
            return session;
        });
    }

    // Full journey: login, work, done
    private static ScenarioBuilder journey(String name, String user) {
        return scenario(name)
                .exec(session -> session
                        .set("workAttempt", 0)
                        .set("workDone", false)
                        .set("csrf", "")
                )
                .exec(login(user))
                .exec(workOp());
    }

    // ---- setup ----
    // Rate: 10 starts/s. 2 users, 2 iterations each = 4 total work ops.
    // We need sustained 10/s over 30s scored window => 300 ops. But contract says users=2, iterations=2.
    // The contract's "users/iterations" is the harness shape; we honor it but pace to sustain rate.
    // With 2 users and 2 iterations, we cannot reach 300 ops. We interpret: run 2 users, each looping
    // to sustain 10/s for the scored window. Use a paced loop.

    private static final int TARGET_RPS = 10;
    private static final int SCORED_SECONDS = 30;
    private static final int WARMUP_SECONDS = 5;
    private static final int DRAIN_SECONDS = 5;

    public ModelSimulation() {
        // 2 users, each paced at 5/s to total 10/s, running for warmup+scored+drain.
        // Each user does iterations = (warmup+scored+drain) * 5 = 40*5 = 200 iterations.
        int perUserRps = TARGET_RPS / 2;
        int totalSeconds = WARMUP_SECONDS + SCORED_SECONDS + DRAIN_SECONDS;
        int iterationsPerUser = perUserRps * totalSeconds;

        ScenarioBuilder scn1 = journey("journey-1", "bench-1")
                .during(Duration.ofSeconds(totalSeconds)).on(
                        pace(Duration.ofMillis(1000 / perUserRps)).exec(workOp())
                );

        // Simpler: use a single scenario with 2 users, each doing paced work.
        // But login must happen per journey. We do login once per user, then paced work.
        ScenarioBuilder scn = scenario("work-pool")
                .exec(session -> session
                        .set("workAttempt", 0)
                        .set("workDone", false)
                        .set("csrf", "")
                )
                .exec(login("bench-1"))
                .during(Duration.ofSeconds(totalSeconds)).on(
                        pace(Duration.ofMillis(1000 / perUserRps))
                                .exec(session -> session.set("workAttempt", 0).set("workDone", false))
                                .exec(workOp())
                );

        setUp(
                scn.injectOpen(
                        atOnceUsers(2)
                )
        ).protocols(HTTP)
                .maxDuration(Duration.ofSeconds(totalSeconds + 10));
    }
}
