import http from 'k6/http';
import { check } from 'k6';
import { Counter, Rate } from 'k6/metrics';

const BASE = __ENV.BASE_URL || 'http://127.0.0.1:8000';

const workStarts = new Counter('work_starts');
const workOk = new Counter('work_ok');
const workScheduled = new Counter('work_scheduled');
const workUnexpected = new Counter('work_unexpected');
const businessFailure = new Rate('business_failure');

export const options = {
  scenarios: {
    work: {
      executor: 'constant-arrival-rate',
      rate: 10,
      timeUnit: '1s',
      duration: '40s',
      preAllocatedVUs: 20,
      maxVUs: 32,
      exec: 'workFlow',
    },
  },
  thresholds: {
    business_failure: ['rate<0.01'],
  },
  discardResponseBodies: false,
};

function parseCsrf(html) {
  if (!html) return null;
  const re = /<input[^>]*name=["']?csrf["']?[^>]*>/gi;
  let m;
  while ((m = re.exec(html)) !== null) {
    const tag = m[0];
    const v = /value=["']([^"']*)["']/i.exec(tag);
    if (v) return v[1];
  }
  return null;
}

function login() {
  const formRes = http.get(`${BASE}/v2/login-form`, { tags: { name: 'login-form' } });
  const csrf = parseCsrf(formRes.body);
  if (!csrf) return null;
  const user = `bench-${1 + Math.floor(Math.random() * 16)}`;
  const res = http.post(
    `${BASE}/v2/login`,
    JSON.stringify({ username: user, password: 'bench', csrf }),
    {
      headers: { 'Content-Type': 'application/json' },
      redirects: 0,
      tags: { name: 'login' },
    }
  );
  if (res.status === 302) {
    const loc = res.headers['Location'];
    if (loc) {
      const follow = http.get(loc.startsWith('http') ? loc : `${BASE}${loc}`, {
        redirects: 0,
        tags: { name: 'login-redirect' },
      });
      try {
        const b = JSON.parse(follow.body);
        if (b && b.csrf) return b.csrf;
      } catch (e) {}
    }
  }
  try {
    const b = JSON.parse(res.body);
    if (b && b.csrf) return b.csrf;
  } catch (e) {}
  return null;
}

function doWork(csrf) {
  workStarts.add(1);
  const res = http.post(`${BASE}/v2/work`, '{}', {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': csrf,
    },
    tags: { name: 'work' },
  });
  if (res.status === 429) {
    workScheduled.add(1);
    businessFailure.add(false);
    return { ok: false, scheduled: true, csrf };
  }
  if (res.status >= 400) {
    workUnexpected.add(1);
    businessFailure.add(true);
    return { ok: false, scheduled: false, csrf };
  }
  let body = null;
  try { body = JSON.parse(res.body); } catch (e) {}
  if (body && body.ok === true) {
    workOk.add(1);
    businessFailure.add(false);
    const fresh = res.headers['X-CSRF-Token'] || res.headers['X-Csrf-Token'];
    return { ok: true, scheduled: false, csrf: fresh || csrf };
  }
  workUnexpected.add(1);
  businessFailure.add(true);
  return { ok: false, scheduled: false, csrf };
}

export function workFlow() {
  let csrf = login();
  if (!csrf) {
    check(null, { 'login ok': () => false });
    return;
  }
  check(csrf, { 'login ok': () => true });

  let attempts = 0;
  let currentCsrf = csrf;
  while (attempts < 5) {
    const r = doWork(currentCsrf);
    if (r.ok) return;
    if (r.scheduled) {
      attempts++;
      if (attempts >= 4) return;
      // Retry-After 1s
      const start = Date.now();
      while (Date.now() - start < 1000) {}
      continue;
    }
    // unexpected error - try renew once
    const renew = http.post(`${BASE}/v2/session/renew`, '{}', {
      headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': currentCsrf },
      tags: { name: 'renew' },
    });
    if (renew.status < 400) {
      try {
        const b = JSON.parse(renew.body);
        if (b && b.csrf) currentCsrf = b.csrf;
      } catch (e) {}
      attempts++;
      continue;
    }
    return;
  }
}
