BASE_URL = os.environ.get("BASE_URL", "http://127.0.0.1:8000")

ACCOUNTS = [f"bench-{i}" for i in range(1, 17)] + ["bench"]
PASSWORD = "bench"


def _abs(url):
    if not url:
        return url
    return urljoin(BASE_URL + "/", url)


class ShopUser(HttpUser):
    host = BASE_URL
    wait_time = between(0.05, 0.15)

    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self.username = random.choice(ACCOUNTS)
        self.csrf = None
        self.session_ok = False
        self.iterations_done = 0
        self.max_iterations = 2

    # ---------- helpers ----------
    def _extract_csrf_from_form(self, text):
        # input[name=csrf] with mixed attribute variants
        m = re.search(
            r'<input[^>]*name\s*=\s*["\']?csrf["\']?[^>]*>',
            text,
            re.IGNORECASE,
        )
        if not m:
            return None
        tag = m.group(0)
        vm = re.search(r'value\s*=\s*["\']([^"\']*)["\']', tag, re.IGNORECASE)
        if vm:
            return vm.group(1)
        return None

    def _extract_challenge_form(self, text):
        action = None
        am = re.search(
            r'<form[^>]*action\s*=\s*["\']([^"\']+)["\']',
            text,
            re.IGNORECASE,
        )
        if am:
            action = am.group(1)
        cm = re.search(
            r'<input[^>]*name\s*=\s*["\']?challenge["\']?[^>]*>',
            text,
            re.IGNORECASE,
        )
        if not cm:
            return action, None
        tag = cm.group(0)
        vm = re.search(r'value\s*=\s*["\']([^"\']*)["\']', tag, re.IGNORECASE)
        return action, (vm.group(1) if vm else None)

    def _login(self):
        with self.client.get(
            "/v2/login-form", name="GET /v2/login-form", catch_response=True
        ) as r:
            if r.status_code != 200:
                r.failure(f"login-form status {r.status_code}")
                return False
            csrf = self._extract_csrf_from_form(r.text)
            if not csrf:
                r.failure("no csrf in login form")
                return False
        with self.client.post(
            "/v2/login",
            json={"username": self.username, "password": PASSWORD, "csrf": csrf},
            name="POST /v2/login",
            catch_response=True,
            allow_redirects=False,
        ) as r:
            if r.status_code == 302:
                loc = r.headers.get("Location")
                if not loc:
                    r.failure("302 without Location")
                    return False
                with self.client.get(
                    _abs(loc), name="GET login redirect", catch_response=True
                ) as r2:
                    if r2.status_code >= 400:
                        r2.failure(f"redirect status {r2.status_code}")
                        return False
                    try:
                        data = r2.json()
                    except Exception:
                        data = {}
                    if data.get("csrf"):
                        self.csrf = data["csrf"]
            elif r.status_code == 200:
                try:
                    data = r.json()
                except Exception:
                    data = {}
                if data.get("csrf"):
                    self.csrf = data["csrf"]
            else:
                r.failure(f"login status {r.status_code}")
                return False
        if not self.csrf:
            return False
        self.session_ok = True
        return True

    def _renew(self):
        if not self.csrf:
            return False
        with self.client.post(
            "/v2/session/renew",
            json={},
            headers={"X-CSRF-Token": self.csrf},
            name="POST /v2/session/renew",
            catch_response=True,
        ) as r:
            if r.status_code >= 400:
                r.failure(f"renew status {r.status_code}")
                return False
            try:
                data = r.json()
            except Exception:
                data = {}
            if data.get("csrf"):
                self.csrf = data["csrf"]
        return True

    def _recover_cart(self, cart_id):
        if not cart_id or not self.csrf:
            return
        with self.client.post(
            f"/v2/carts/{cart_id}/recover",
            json={},
            headers={"X-CSRF-Token": self.csrf},
            name="POST /v2/carts/{id}/recover",
            catch_response=True,
        ) as r:
            if r.status_code >= 400:
                r.failure(f"recover status {r.status_code}")
                return
            try:
                data = r.json()
            except Exception:
                data = {}
            if data.get("csrf"):
                self.csrf = data["csrf"]

    def _handle_401(self, r, cart_id=None):
        try:
            data = r.json()
        except Exception:
            data = {}
        err = data.get("error")
        if err == "expired":
            if self._renew():
                if cart_id:
                    self._recover_cart(cart_id)
                return True
            return False
        if err == "session":
            self.session_ok = False
            if self._login():
                if cart_id:
                    self._recover_cart(cart_id)
                return True
            return False
        # denied or other -> not recoverable
        return False

    def _get_catalog(self):
        with self.client.get(
            "/v2/catalog", name="GET /v2/catalog", catch_response=True
        ) as r:
            if r.status_code == 401:
                if self._handle_401(r):
                    r.success()
                    return None
                r.failure("catalog 401 unrecoverable")
                return None
            if r.status_code != 200:
                r.failure(f"catalog status {r.status_code}")
                return None
            try:
                data = r.json()
            except Exception:
                r.failure("catalog bad json")
                return None
            products = (data.get("data") or {}).get("products") or []
            if not products:
                r.failure("catalog empty")
                return None
            return products

    def _pick_variant(self, products):
        for p in products:
            variants = p.get("variants") or []
            for v in variants:
                if v.get("in_stock"):
                    return p.get("id"), v.get("id")
        return None, None

    def _solve_challenge(self):
        with self.client.get(
            "/v2/challenge-form", name="GET /v2/challenge-form", catch_response=True
        ) as r:
            if r.status_code != 200:
                r.failure(f"challenge-form status {r.status_code}")
                return None
            action, challenge = self._extract_challenge_form(r.text)
            if not action or not challenge:
                r.failure("challenge form parse failed")
                return None
        with self.client.post(
            _abs(action),
            json={"challenge": challenge},
            headers={"X-CSRF-Token": self.csrf},
            name="POST /v2/challenges/{id}",
            catch_response=True,
            allow_redirects=False,
        ) as r:
            if r.status_code == 401:
                if self._handle_401(r):
                    r.success()
                else:
                    r.failure("challenge 401")
                return None
            if r.status_code != 302:
                r.failure(f"challenge status {r.status_code}")
                return None
            loc = r.headers.get("Location")
            if not loc:
                r.failure("challenge no Location")
                return None
        with self.client.get(
            _abs(loc), name="GET challenge redirect", catch_response=True
        ) as r:
            if r.status_code != 200:
                r.failure(f"challenge redirect status {r.status_code}")
                return None
            try:
                data = r.json()
            except Exception:
                r.failure("challenge redirect bad json")
                return None
            if data.get("csrf"):
                self.csrf = data["csrf"]
            return data.get("grant_id")

    def _create_cart(self, product_id, variant_id, grant_id=None):
        payload = {"product_id": product_id, "variant_id": variant_id}
        if grant_id:
            payload["grant_id"] = grant_id
        with self.client.post(
            "/v2/carts",
            json=payload,
            headers={"X-CSRF-Token": self.csrf},
            name="POST /v2/carts",
            catch_response=True,
        ) as r:
            if r.status_code == 401:
                if self._handle_401(r):
                    r.success()
                    return None
                r.failure("cart 401")
                return None
            if r.status_code != 201:
                r.failure(f"cart status {r.status_code}")
                return None
            try:
                data = r.json()
            except Exception:
                r.failure("cart bad json")
                return None
            if data.get("csrf"):
                self.csrf = data["csrf"]
            return data.get("id")

    def _patch_cart(self, cart_id, quantity):
        # read etag
        with self.client.get(
            f"/v2/carts/{cart_id}",
            name="GET /v2/carts/{id}",
            catch_response=True,
        ) as r:
            if r.status_code == 401:
                if self._handle_401(r, cart_id):
                    r.success()
                    return False
                r.failure("cart get 401")
                return False
            if r.status_code != 200:
                r.failure(f"cart get status {r.status_code}")
                return False
            etag = r.headers.get("ETag")
        if not etag:
            return False
        payload = {"quantity": quantity}
        for attempt in range(2):
            with self.client.patch(
                f"/v2/carts/{cart_id}",
                json=payload,
                headers={"X-CSRF-Token": self.csrf, "If-Match": etag},
                name="PATCH /v2/carts/{id}",
                catch_response=True,
            ) as r:
                if r.status_code == 401:
                    if self._handle_401(r, cart_id):
                        r.success()
                        return False
                    r.failure("cart patch 401")
                    return False
                if r.status_code == 412 and attempt == 0:
                    r.success()
                    with self.client.get(
                        f"/v2/carts/{cart_id}",
                        name="GET /v2/carts/{id}",
                        catch_response=True,
                    ) as r2:
                        if r2.status_code == 200:
                            etag = r2.headers.get("ETag")
                        else:
                            r2.failure(f"cart re-read {r2.status_code}")
                            return False
                    continue
                if r.status_code >= 400:
                    r.failure(f"cart patch status {r.status_code}")
                    return False
                try:
                    data = r.json()
                except Exception:
                    data = {}
                if data.get("csrf"):
                    self.csrf = data["csrf"]
                return True
        return False

    def _reserve(self, cart_id):
        with self.client.post(
            "/v2/reservations",
            json={"cart_id": cart_id},
            headers={"X-CSRF-Token": self.csrf},
            name="POST /v2/reservations",
            catch_response=True,
        ) as r:
            if r.status_code == 401:
                if self._handle_401(r, cart_id):
                    r.success()
                    return None
                r.failure("reservation 401")
                return None
            if r.status_code != 202:
                r.failure(f"reservation status {r.status_code}")
                return None
            try:
                data = r.json()
            except Exception:
                r.failure("reservation bad json")
                return None
            if data.get("csrf"):
                self.csrf = data["csrf"]
            status_url = data.get("status_url")
        if not status_url:
            return None
        for _ in range(5):
            time.sleep(0.06)
            with self.client.get(
                _abs(status_url),
                name="GET reservation status",
                catch_response=True,
            ) as r:
                if r.status_code == 401:
                    if self._handle_401(r, cart_id):
                        r.success()
                        continue
                    r.failure("reservation status 401")
                    return None
                if r.status_code != 200:
                    r.failure(f"reservation status {r.status_code}")
                    return None
                try:
                    data = r.json()
                except Exception:
                    r.failure("reservation status bad json")
                    return None
                if data.get("csrf"):
                    self.csrf = data["csrf"]
                status = data.get("status")
                if status == "ready":
                    return data.get("reservation_id")
                if status in ("pending",):
                    continue
                return None
        return None

    def _order(self, cart_id, reservation_id):
        idem = str(uuid.uuid4())
        payload = {"cart_id": cart_id}
        if reservation_id:
            payload["reservation_id"] = reservation_id
        headers = {"X-CSRF-Token": self.csrf, "Idempotency-Key": idem}
        with self.client.post(
            "/v2/orders",
            json=payload,
            headers=headers,
            name="POST /v2/orders",
            catch_response=True,
        ) as r:
            if r.status_code == 401:
                if self._handle_401(r, cart_id):
                    r.success()
                    return False
                r.failure("order 401")
                return False
            if r.status_code != 201:
                r.failure(f"order status {r.status_code}")
                return False
            try:
                data = r.json()
            except Exception:
                r.failure("order bad json")
                return False
            if data.get("csrf"):
                self.csrf = data["csrf"]
            if not data.get("accepted"):
                r.failure("order not accepted")
                return False
            return True

    def _work(self):
        # POST /v2/work with scheduled 429 handling
        for attempt in range(5):
            with self.client.post(
                "/v2/work",
                json={},
                headers={"X-CSRF-Token": self.csrf},
                name="POST /v2/work",
                catch_response=True,
            ) as r:
                if r.status_code == 401:
                    if self._handle_401(r):
                        r.success()
                        continue
                    r.failure("work 401")
                    return False
                if r.status_code == 429:
                    ra = r.headers.get("Retry-After", "1")
                    try:
                        delay = float(ra)
                    except Exception:
                        delay = 1.0
                    r.success()
                    if attempt >= 4:
                        return False
                    time.sleep(delay)
                    continue
                if r.status_code >= 500:
                    r.failure(f"work status {r.status_code}")
                    return False
                if r.status_code >= 400:
                    r.failure(f"work status {r.status_code}")
                    return False
                try:
                    data = r.json()
                except Exception:
                    r.failure("work bad json")
                    return False
                if not data.get("ok"):
                    r.failure("work not ok")
                    return False
                return True
        return False

    # ---------- journey ----------
    @task
    def journey(self):
        if self.iterations_done >= self.max_iterations:
            raise StopUser()
        self.iterations_done += 1

        if not self.session_ok:
            if not self._login():
                raise StopUser()

        products = self._get_catalog()
        if not products:
            return
        product_id, variant_id = self._pick_variant(products)
        if not product_id:
            return

        grant_id = self._solve_challenge()
        cart_id = self._create_cart(product_id, variant_id, grant_id)
        if not cart_id:
            return

        if not self._patch_cart(cart_id, random.randint(1, 5)):
            return

        reservation_id = self._reserve(cart_id)
        if not reservation_id:
            return

        if not self._order(cart_id, reservation_id):
            return

        self._work()


