class PhasedShape(LoadTestShape):
    """
    Warmup 5s, then three 10s scored plateaus at 5/15/5 users,
    then drain. Total ~35s + drain.
    """

    def tick(self):
        run_time = self.get_run_time()
        if run_time < 5:
            return (2, 2)
        if run_time < 15:
            return (5, 5)
        if run_time < 25:
            return (15, 15)
        if run_time < 35:
            return (5, 5)
        if run_time < 40:
            return (2, 2)
        return None
