import io.gatling.javaapi.core.*;
import io.gatling.javaapi.http.*;

import java.time.Duration;
import java.util.*;
import java.util.concurrent.ThreadLocalRandom;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

import static io.gatling.javaapi.core.CoreDsl.*;
import static io.gatling.javaapi.http.HttpDsl.*;

public class ModelSimulation extends Simulation {

    private static final String BASE = System.getenv().getOrDefault("BASE_URL", "http://127.0.0.1:8000");

    private static final Pattern CSRF_INPUT = Pattern.compile(
            "name\\s*=\\s*[\"']csrf[\"'][^>]*value\\s*=\\s*[\"']([^\"']+)[\"']" +
            "|value\\s*=\\s*[\"']([^\"']+)[\"'][^>]*name\\s*=\\s*[\"']csrf[\"']",
            Pattern.CASE_INSENSITIVE);
    private static final Pattern CHALLENGE_ACTION = Pattern.compile(
            "action\\s*=\\s*[\"']([^\"']*\\/v2\\/challenges\\/[^\"']+)[\"']", Pattern.CASE_INSENSITIVE);
    private static final Pattern CHALLENGE_INPUT = Pattern.compile(
            "name\\s*=\\s*[\"']challenge[\"'][^>]*value\\s*=\\s*[\"']([^\"']*)[\"']" +
            "|value\\s*=\\s*[\"']([^\"']*)[\"'][^>]*name\\s*=\\s*[\"']challenge[\"']",
            Pattern.CASE_INSENSITIVE);

    private static String pick(Pattern p, String body, int... groups) {
        if (body == null) return null;
        Matcher m = p.matcher(body);
        if (!m.find()) return null;
        for (int g : groups) {
            String v = m.group(g);
            if (v != null && !v.isEmpty()) return v;
        }
        return null;
    }

    private static String csrfFrom(String body) {
        return pick(CSRF_INPUT, body, 1, 2);
    }

    private static String challengeActionFrom(String body) {
        return pick(CHALLENGE_ACTION, body, 1);
    }

    private static String challengeValueFrom(String body) {
        return pick(CHALLENGE_INPUT, body, 1, 2);
    }

    private static String userFor(int i) {
        return "bench-" + (1 + (i % 16));
    }

    private final HttpProtocolBuilder httpProtocol = http
            .baseUrl(BASE)
            .disableAutoRedirect()
            .acceptHeader("application/json, text/html")
            .contentTypeHeader("application/json")
            .shareConnections();

    // ---------- Chains ----------

    private ChainBuilder loginChain() {
        return exec(session -> {
                    int idx = session.getInt("userIdx");
                    return session.set("username", userFor(idx));
                })
                .exec(http("login-form")
                        .get("/v2/login-form")
                        .check(status().lt(400))
                        .check(bodyString().saveAs("loginFormBody")))
                .exec(session -> {
                    String csrf = csrfFrom(session.getString("loginFormBody"));
                    return session.set("csrf", csrf == null ? "" : csrf);
                })
                .exec(http("login")
                        .post("/v2/login")
                        .body(StringBody(session ->
                                "{\"username\":\"" + session.getString("username") +
                                "\",\"password\":\"bench\",\"csrf\":\"" + session.getString("csrf") + "\"}"))
                        .check(status().in(200, 201, 302))
                        .check(bodyString().saveAs("loginBody")))
                .exec(session -> {
                    String b = session.getString("loginBody");
                    String csrf = csrfFrom(b);
                    if (csrf == null) csrf = session.getString("csrf");
                    return session.set("csrf", csrf == null ? "" : csrf);
                });
    }

    private ChainBuilder catalogChain() {
        return exec(http("catalog")
                .get("/v2/catalog")
                .check(status().is(200))
                .check(bodyString().saveAs("catalogBody")))
                .exec(session -> {
                    String body = session.getString("catalogBody");
                    String pid = null, vid = null;
                    if (body != null) {
                        Matcher m = Pattern.compile(
                                "\"id\"\\s*:\\s*\"?([^,\"}]+)\"?[^}]*?\"variants\"\\s*:\\s*\\[\\s*\\{[^}]*?\"id\"\\s*:\\s*\"?([^,\"}]+)\"?",
                                Pattern.DOTALL).matcher(body);
                        if (m.find()) {
                            pid = m.group(1);
                            vid = m.group(2);
                        }
                    }
                    return session.set("productId", pid).set("variantId", vid);
                });
    }

    private ChainBuilder challengeChain() {
        return exec(http("challenge-form")
                .get("/v2/challenge-form")
                .check(status().lt(400))
                .check(bodyString().saveAs("challengeFormBody")))
                .exec(session -> {
                    String body = session.getString("challengeFormBody");
                    String action = challengeActionFrom(body);
                    String val = challengeValueFrom(body);
                    return session.set("challengeAction", action).set("challengeValue", val);
                })
                .exec(http("challenge-submit")
                        .post(session -> session.getString("challengeAction"))
                        .header("X-CSRF-Token", session -> session.getString("csrf"))
                        .body(StringBody(session ->
                                "{\"challenge\":\"" + session.getString("challengeValue") + "\"}"))
                        .check(status().in(200, 201, 302))
                        .check(header("Location").saveAs("challengeLocation")))
                .exec(http("challenge-follow")
                        .get(session -> session.getString("challengeLocation"))
                        .check(status().is(200))
                        .check(bodyString().saveAs("grantBody")))
                .exec(session -> {
                    String b = session.getString("grantBody");
                    String grant = null;
                    if (b != null) {
                        Matcher m = Pattern.compile("\"grant_id\"\\s*:\\s*\"?([^,\"}]+)\"?").matcher(b);
                        if (m.find()) grant = m.group(1);
                    }
                    String csrf = csrfFrom(b);
                    if (csrf != null) session = session.set("csrf", csrf);
                    return session.set("grantId", grant);
                });
    }

    private ChainBuilder cartChain() {
        return exec(http("cart-create")
                .post("/v2/carts")
                .header("X-CSRF-Token", session -> session.getString("csrf"))
                .body(StringBody(session -> {
                    String g = session.getString("grantId");
                    String base = "{\"product_id\":\"" + session.getString("productId") +
                            "\",\"variant_id\":\"" + session.getString("variantId") + "\"";
                    if (g != null && !g.isEmpty()) base += ",\"grant_id\":\"" + g + "\"";
                    return base + "}";
                }))
                .check(status().is(201))
                .check(bodyString().saveAs("cartBody")))
                .exec(session -> {
                    String b = session.getString("cartBody");
                    String id = null;
                    if (b != null) {
                        Matcher m = Pattern.compile("\"id\"\\s*:\\s*\"?([^,\"}]+)\"?").matcher(b);
                        if (m.find()) id = m.group(1);
                    }
                    String csrf = csrfFrom(b);
                    if (csrf != null) session = session.set("csrf", csrf);
                    return session.set("cartId", id);
                });
    }

    private ChainBuilder reservationChain() {
        return exec(http("reservation-create")
                .post("/v2/reservations")
                .header("X-CSRF-Token", session -> session.getString("csrf"))
                .body(StringBody(session ->
                        "{\"cart_id\":\"" + session.getString("cartId") + "\"}"))
                .check(status().is(202))
                .check(bodyString().saveAs("resBody")))
                .exec(session -> {
                    String b = session.getString("resBody");
                    String url = null;
                    if (b != null) {
                        Matcher m = Pattern.compile("\"status_url\"\\s*:\\s*\"([^\"]+)\"").matcher(b);
                        if (m.find()) url = m.group(1);
                    }
                    String csrf = csrfFrom(b);
                    if (csrf != null) session = session.set("csrf", csrf);
                    return session.set("statusUrl", url).set("pollCount", 0).set("reservationId", null);
                })
                .asLongAs(session -> session.getInt("pollCount") < 5 && session.getString("reservationId") == null)
                .on(
                        pause(Duration.ofMillis(60))
                                .exec(http("reservation-poll")
                                        .get(session -> session.getString("statusUrl"))
                                        .check(status().is(200))
                                        .check(bodyString().saveAs("pollBody")))
                                .exec(session -> {
                                    String b = session.getString("pollBody");
                                    String status = null, rid = null;
                                    if (b != null) {
                                        Matcher sm = Pattern.compile("\"status\"\\s*:\\s*\"([^\"]+)\"").matcher(b);
                                        if (sm.find()) status = sm.group(1);
                                        Matcher rm = Pattern.compile("\"reservation_id\"\\s*:\\s*\"?([^,\"}]+)\"?").matcher(b);
                                        if (rm.find()) rid = rm.group(1);
                                    }
                                    int pc = session.getInt("pollCount") + 1;
                                    session = session.set("pollCount", pc);
                                    if ("ready".equals(status) && rid != null) {
                                        session = session.set("reservationId", rid);
                                    }
                                    return session;
                                })
                );
    }

    private ChainBuilder orderChain() {
        return exec(http("order-create")
                .post("/v2/orders")
                .header("X-CSRF-Token", session -> session.getString("csrf"))
                .header("Idempotency-Key", session -> "idem-" + session.getString("cartId"))
                .body(StringBody(session -> {
                    String rid = session.getString("reservationId");
                    String base = "{\"cart_id\":\"" + session.getString("cartId") + "\"";
                    if (rid != null && !rid.isEmpty()) base += ",\"reservation_id\":\"" + rid + "\"";
                    return base + "}";
                }))
                .check(status().is(201))
                .check(bodyString().saveAs("orderBody")))
                .exec(session -> {
                    String b = session.getString("orderBody");
                    boolean accepted = b != null && b.contains("\"accepted\":true");
                    String csrf = csrfFrom(b);
                    if (csrf != null) session = session.set("csrf", csrf);
                    return session.set("orderAccepted", accepted);
                });
    }

    private ChainBuilder workChain() {
        return exec(http("work")
                .post("/v2/work")
                .header("X-CSRF-Token", session -> session.getString("csrf"))
                .body(StringBody("{}"))
                .check(status().lt(400))
                .check(bodyString().saveAs("workBody")))
                .exec(session -> {
                    String b = session.getString("workBody");
                    boolean ok = b != null && b.contains("\"ok\":true");
                    String csrf = csrfFrom(b);
                    if (csrf != null) session = session.set("csrf", csrf);
                    return session.set("workOk", ok);
                });
    }

    private ChainBuilder fullJourney() {
        return loginChain()
                .exec(catalogChain())
                .exec(challengeChain())
                .exec(cartChain())
                .exec(reservationChain())
                .exec(orderChain())
                .exec(workChain());
    }

    // ---------- Scenarios ----------

    private ScenarioBuilder buildScenario(String name, int userIdx) {
        return scenario(name)
                .exec(session -> session.set("userIdx", userIdx))
                .exec(fullJourney());
    }

    {
        List<PopulationBuilder> pops = new ArrayList<>();
        int users = 2;
        int iterations = 2;
        for (int i = 0; i < users; i++) {
            pops.add(buildScenario("model-" + i, i).injectOpen(atOnceUsers(1)).protocols(httpProtocol));
        }
        setUp(pops);
    }
}
