```javascript
import http from 'k6/http';
import { check, sleep } from 'k6';
import { Counter, Rate, Trend } from 'k6/metrics';
import encoding from 'k6/encoding';

const BASE = __ENV.BASE_URL || 'http://127.0.0.1:8000';

const workOk = new Counter('work_ok');
const workErr = new Counter('work_err');
const workSched = new Counter('work_sched');
const workUnexpected = new Counter('work_unexpected');
const bizRate = new Rate('business_failure');
const workLatency = new Trend('work_latency');

export const options = {
  scenarios: {
    phased: {
      executor: 'ramping-arrival-rate',
      startRate: 5,
      timeUnit: '1s',
      preAllocatedVUs: 32,
      maxVUs: 32,
      stages: [
        { target: 5, duration: '10s' },
        { target: 15, duration: '10s' },
        { target: 5, duration: '10s' },
      ],
      gracefulStop: '5s',
    },
  },
  thresholds: {
    business_failure: ['rate<0.01'],
  },
  discardResponseBodies: false,
};

function parseCsrf(html) {
  if (!html) return null;
  const re = /<input[^>]*name\s*=\s*["']?csrf["']?[^>]*>/gi;
  let m;
  while ((m = re.exec(html)) !== null) {
    const tag = m[0];
    const vm = tag.match(/value\s*=\s*["']([^"']*)["']/i);
    if (vm) return vm[1];
  }
  const re2 = /<input[^>]*value\s*=\s*["']([^"']*)["'][^>]*name\s*=\s*["']?csrf["']?/gi;
  while ((m = re2.exec(html)) !== null) {
    return m[1];
  }
  return null;
}

function parseChallenge(html) {
  if (!html) return null;
  const am = html.match(/<form[^>]*action\s*=\s*["']([^"']*\/v2\/challenges\/[^"']*)["']/i);
  const im = html.match(/<input[^>]*name\s*=\s*["']?challenge["']?[^>]*>/i);
  let val = null;
  if (im) {
    const vm = im[0].match(/value\s*=\s*["']([^"']*)["']/i);
    if (vm) val = vm[1];
  }
  if (!am || !val) return null;
  return { action: am[1], value: val };
}

function jar() {
  return http.cookieJar();
}

function getCsrfFromResp(res, prev) {
  try {
    const b = res.json();
    if (b && b.csrf) return b.csrf;
  } catch (e) {}
  return prev;
}

function login(user) {
  const cj = jar();
  const formRes = http.get(`${BASE}/v2/login-form`, { redirects: 0, jar: cj });
  const csrf = parseCsrf(formRes.body);
  if (!csrf) return null;
  const loginRes = http.post(
    `${BASE}/v2/login`,
    JSON.stringify({ username: user, password: 'bench', csrf }),
    { headers: { 'Content-Type': 'application/json' }, redirects: 0, jar: cj }
  );
  let token = csrf;
  if (loginRes.status === 302) {
    const loc = loginRes.headers['Location'];
    if (loc) {
      const r2 = http.get(loc.startsWith('http') ? loc : `${BASE}${loc}`, { redirects: 0, jar: cj });
      token = getCsrfFromResp(r2, token);
    }
  } else if (loginRes.status >= 200 && loginRes.status < 300) {
    token = getCsrfFromResp(loginRes, token);
  } else {
    return null;
  }
  return { jar: cj, csrf: token };
}

function renew(sess) {
  const r = http.post(`${BASE}/v2/session/renew`, '{}', {
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': sess.csrf },
    redirects: 0,
    jar: sess.jar,
  });
  if (r.status >= 200 && r.status < 300) {
    sess.csrf = getCsrfFromResp(r, sess.csrf);
    return true;
  }
  return false;
}

function doWork(sess) {
  let attempts = 0;
  let schedRetries = 0;
  while (attempts < 2) {
    attempts++;
    const res = http.post(`${BASE}/v2/work`, '{}', {
      headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': sess.csrf },
      redirects: 0,
      jar: sess.jar,
      tags: { name: 'work' },
    });
    workLatency.add(res.timings.duration);
    if (res.status === 429) {
      workSched.add(1);
      bizRate.add(false);
      if (schedRetries < 4) {
        schedRetries++;
        const ra = res.headers['Retry-After'];
        let wait = 1;
        if (ra) {
          const n = parseFloat(ra);
          if (!isNaN(n)) wait = n;
        }
        sleep(wait);
        continue;
      }
      return;
    }
    if (res.status === 401) {
      let err = null;
      try { err = res.json().error; } catch (e) {}
      if (err === 'expired') {
        bizRate.add(false);
        if (renew(sess)) {
          continue;
        }
        return;
      }
      if (err === 'denied') {
        workErr.add(1);
        bizRate.add(true);
        return;
      }
      workErr.add(1);
      bizRate.add(true);
      return;
    }
    if (res.status >= 500) {
      workUnexpected.add(1);
      workErr.add(1);
      bizRate.add(true);
      return;
    }
    if (res.status >= 400) {
      workErr.add(1);
      bizRate.add(true);
      return;
    }
    let ok = false;
    try {
      const b = res.json();
      ok = b && b.ok === true;
    } catch (e) {}
    if (ok) {
      workOk.add(1);
      bizRate.add(false);
    } else {
      workErr.add(1);
      bizRate.add(true);
    }
    return;
  }
}

export default function () {
  const idx = (__VU % 16) + 1;
  const user = `bench-${idx}`;
  const sess = login(user);
  if (!sess) {
    bizRate.add(true);
    return;
  }
  doWork(sess);
}
