```python
import os
import re
import time
import json
import random
from urllib.parse import urljoin

from locust import HttpUser, task, between, LoadTestShape
from locust.exception import StopUser

BASE_URL = os.environ.get("BASE_URL", "http://127.0.0.1:8000")
PASSWORD = "bench"


def _abs(path):
    if path is None:
        return None
    if path.startswith("http://") or path.startswith("https://"):
        return path
    return urljoin(BASE_URL + "/", path.lstrip("/"))


class ShopUser(HttpUser):
    host = BASE_URL
    wait_time = between(0.05, 0.15)

    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self.username = None
        self.csrf = None
        self.session_ready = False
        self.iterations_done = 0
        self.max_iterations = 2

    # ---------- low level helpers ----------
    def _req(self, method, path, name=None, expect=None, **kwargs):
        url = _abs(path)
        with self.client.request(
            method, url, name=name or path, catch_response=True,
            allow_redirects=False, **kwargs
        ) as resp:
            if expect is not None:
                if resp.status_code not in expect:
                    resp.failure("unexpected status %s for %s" % (resp.status_code, path))
            return resp

    def _json(self, resp):
        try:
            return resp.json()
        except Exception:
            return None

    # ---------- auth ----------
    def _pick_username(self):
        n = random.randint(1, 16)
        return "bench-%d" % n

    def _login(self):
        self.username = self._pick_username()
        r = self._req("GET", "/v2/login-form", name="GET /v2/login-form", expect=[200])
        if not r.ok:
            return False
        html = r.text or ""
        m = re.search(r'<input[^>]*name=["\']csrf["\'][^>]*>', html, re.I)
        token = None
        if m:
            tag = m.group(0)
            vm = re.search(r'value=["\']([^"\']*)["\']', tag, re.I)
            if vm:
                token = vm.group(1)
        if token is None:
            # fallback: any input with name=csrf in any attribute order
            for tag in re.findall(r'<input[^>]*>', html, re.I):
                if re.search(r'name=["\']csrf["\']', tag, re.I):
                    vm = re.search(r'value=["\']([^"\']*)["\']', tag, re.I)
                    if vm:
                        token = vm.group(1)
                        break
        if token is None:
            r.failure("no csrf token in login form")
            return False
        body = {"username": self.username, "password": PASSWORD, "csrf": token}
        r2 = self._req("POST", "/v2/login", name="POST /v2/login",
                       json=body, expect=[200, 302])
        if not r2.ok:
            return False
        if r2.status_code == 302:
            loc = r2.headers.get("Location")
            if loc:
                r3 = self._req("GET", loc, name="GET login redirect", expect=[200])
                if not r3.ok:
                    return False
                data = self._json(r3) or {}
                if data.get("csrf"):
                    self.csrf = data["csrf"]
        else:
            data = self._json(r2) or {}
            if data.get("csrf"):
                self.csrf = data["csrf"]
        if not self.csrf:
            # try to obtain csrf from a follow-up
            return False
        self.session_ready = True
        return True

    def _renew(self):
        if not self.csrf:
            return False
        r = self._req("POST", "/v2/session/renew", name="POST /v2/session/renew",
                      json={}, headers={"X-CSRF-Token": self.csrf},
                      expect=[200, 401])
        if r.status_code == 200:
            data = self._json(r) or {}
            if data.get("csrf"):
                self.csrf = data["csrf"]
            return True
        return False

    def _relogin(self):
        self.session_ready = False
        self.csrf = None
        return self._login()

    # ---------- catalog ----------
    def _get_catalog(self):
        r = self._req("GET", "/v2/catalog", name="GET /v2/catalog", expect=[200])
        if not r.ok:
            return None
        return self._json(r)

    def _pick_product(self, catalog):
        if not catalog:
            return None
        data = catalog.get("data") or {}
        products = data.get("products") or []
        if not products:
            return None
        random.shuffle(products)
        for p in products:
            variants = p.get("variants") or []
            for v in variants:
                if v.get("in_stock"):
                    return (p.get("id"), v.get("id"))
        return None

    # ---------- challenge ----------
    def _do_challenge(self):
        r = self._req("GET", "/v2/challenge-form", name="GET /v2/challenge-form",
                      expect=[200])
        if not r.ok:
            return None
        html = r.text or ""
        action = None
        m = re.search(r'<form[^>]*action=["\']([^"\']+)["\']', html, re.I)
        if m:
            action = m.group(1)
        if not action:
            return None
        token = None
        for tag in re.findall(r'<input[^>]*>', html, re.I):
            if re.search(r'name=["\']challenge["\']', tag, re.I):
                vm = re.search(r'value=["\']([^"\']*)["\']', tag, re.I)
                if vm:
                    token = vm.group(1)
                    break
        if token is None:
            return None
        r2 = self._req("POST", action, name="POST challenge",
                       json={"challenge": token},
                       headers={"X-CSRF-Token": self.csrf},
                       expect=[302, 200])
        if not r2.ok:
            return None
        loc = r2.headers.get("Location")
        if not loc:
            return None
        r3 = self._req("GET", loc, name="GET challenge result", expect=[200])
        if not r3.ok:
            return None
        data = self._json(r3) or {}
        if data.get("csrf"):
            self.csrf = data["csrf"]
        return data.get("grant_id")

    # ---------- cart ----------
    def _create_cart(self, product_id, variant_id, grant_id=None):
        body = {"product_id": product_id, "variant_id": variant_id}
        if grant_id:
            body["grant_id"] = grant_id
        r = self._req("POST", "/v2/carts", name="POST /v2/carts",
                      json=body, headers={"X-CSRF-Token": self.csrf},
                      expect=[201, 401])
        if r.status_code == 401:
            return ("401", r)
        if not r.ok:
            return (None, r)
        data = self._json(r) or {}
        if data.get("csrf"):
            self.csrf = data["csrf"]
        return (data.get("id"), r)

    def _patch_cart(self, cart_id, quantity, etag):
        headers = {"X-CSRF-Token": self.csrf, "If-Match": etag or ""}
        r = self._req("PATCH", "/v2/carts/%s" % cart_id, name="PATCH /v2/carts/{id}",
                      json={"quantity": quantity}, headers=headers,
                      expect=[200, 412, 401])
        if r.status_code == 412:
            r2 = self._req("GET", "/v2/carts/%s" % cart_id, name="GET /v2/carts/{id}",
                           expect=[200])
            if not r2.ok:
                return r2
            etag2 = r2.headers.get("ETag")
            headers["If-Match"] = etag2 or ""
            r = self._req("PATCH", "/v2/carts/%s" % cart_id, name="PATCH /v2/carts/{id}",
                          json={"quantity": quantity}, headers=headers,
                          expect=[200, 401])
        return r

    def _reserve(self, cart_id):
        r = self._req("POST", "/v2/reservations", name="POST /v2/reservations",
                      json={"cart_id": cart_id},
                      headers={"X-CSRF-Token": self.csrf},
                      expect=[202, 401])
        if r.status_code == 401:
            return ("401", r)
        if not r.ok:
            return (None, r)
        data = self._json(r) or {}
        if data.get("csrf"):
            self.csrf = data["csrf"]
        status_url = data.get("status_url")
        if not status_url:
            return (None, r)
        for _ in range(5):
            time.sleep(0.06)
            r2 = self._req("GET", status_url, name="GET reservation status",
                           expect=[200])
            if not r2.ok:
                return (None, r2)
            d2 = self._json(r2) or {}
            st = d2.get("status")
            if st == "ready":
                return (d2.get("reservation_id"), r2)
            if st in ("pending",):
                continue
            return (None, r2)
        return (None, r)

    def _order(self, cart_id, reservation_id, idem_key, etag):
        body = {"cart_id": cart_id}
        if reservation_id:
            body["reservation_id"] = reservation_id
        headers = {"X-CSRF-Token": self.csrf, "Idempotency-Key": idem_key}
        if etag:
            headers["If-Match"] = etag
        r = self._req("POST", "/v2/orders", name="POST /v2/orders",
                      json=body, headers=headers, expect=[201, 200, 401])
        if r.status_code == 401:
            return ("401", r)
        if r.status_code == 200:
            data = self._json(r) or {}
            if data.get("accepted") is False:
                r.failure("order accepted:false")
                return (None, r)
        if r.ok:
            data = self._json(r) or {}
            if data.get("csrf"):
                self.csrf = data["csrf"]
        return (r.status_code, r)

    def _recover_cart(self, cart_id):
        if not cart_id:
            return
        self._req("POST", "/v2/carts/%s/recover" % cart_id,
                  name="POST /v2/carts/{id}/recover",
                  json={}, headers={"X-CSRF-Token": self.csrf},
                  expect=[200, 401, 404])

    # ---------- work ----------
    def _do_work(self):
        headers = {"X-CSRF-Token": self.csrf}
        for attempt in range(5):
            r = self._req("POST", "/v2/work", name="POST /v2/work",
                          json={}, headers=headers, expect=[200, 429, 401, 500])
            if r.status_code == 429:
                ra = r.headers.get("Retry-After", "1")
                try:
                    delay = float(ra)
                except Exception:
                    delay = 1.0
                time.sleep(max(delay, 0.05))
                continue
            if r.status_code == 401:
                data = self._json(r) or {}
                err = data.get("error")
                if err == "expired":
                    if self._renew():
                        continue
                    if self._relogin():
                        continue
                    r.failure("renew failed")
                    return False
                if err == "session":
                    if self._relogin():
                        continue
                    r.failure("relogin failed")
                    return False
                r.failure("denied")
                return False
            if r.status_code == 500:
                r.failure("unexpected 500")
                return False
            if r.status_code == 200:
                data = self._json(r) or {}
                if data.get("ok") is True:
                    return True
                r.failure("work ok!=true")
                return False
            r.failure("unexpected status")
            return False
        return False

    # ---------- journey ----------
    def _journey(self):
        if not self.session_ready:
            if not self._login():
                return
        # fresh cart each journey
        catalog = self._get_catalog()
        pick = self._pick_product(catalog)
        if not pick:
            return
        product_id, variant_id = pick
        grant_id = self._do_challenge()
        cart_id, r = self._create_cart(product_id, variant_id, grant_id)
        if cart_id == "401":
            data = self._json(r) or {}
            if data.get("error") == "expired":
                if self._renew():
                    cart_id, r = self._create_cart(product_id, variant_id, grant_id)
            if cart_id == "401":
                if self._relogin():
                    cart_id, r = self._create_cart(product_id, variant_id, grant_id)
        if not cart_id or cart_id == "401":
            return
        etag = r.headers.get("ETag")
        qty = random.randint(1, 20)
        pr = self._patch_cart(cart_id, qty, etag)
        if pr.status_code == 401:
            data = self._json(pr) or {}
            if data.get("error") == "expired":
                if self._renew():
                    self._recover_cart(cart_id)
                    pr = self._patch_cart(cart_id, qty, etag)
            if pr.status_code == 401:
                if self._relogin():
                    self._recover_cart(cart_id)
                    pr = self._patch_cart(cart_id, qty, etag)
        if pr.status_code != 200:
            return
        etag2 = pr.headers.get("ETag") or etag
        rid, rr = self._reserve(cart_id)
        if rid == "401":
            data = self._json(rr) or {}
            if data.get("error") == "expired":
                if self._renew():
                    self._recover_cart(cart_id)
                    rid, rr = self._reserve(cart_id)
            if rid == "401":
                if self._relogin():
                    self._recover_cart(cart_id)
                    rid, rr = self._reserve(cart_id)
        if not rid or rid == "401":
            return
        idem = "idem-%s-%s" % (cart_id, random.randint(1, 10**9))
        st, orr = self._order(cart_id, rid, idem, etag2)
        if st == "401":
            data = self._json(orr) or {}
            if data.get("error") == "expired":
                if self._renew():
                    self._recover_cart(cart_id)
                    st, orr = self._order(cart_id, rid, idem, etag2)
            if st == "401":
                if self._relogin():
                    self._recover_cart(cart_id)
                    st, orr = self._order(cart_id, rid, idem, etag2)
        # work operation
        self._do_work()

    @task
    def run(self):
        if self.iterations_done >= self.max_iterations:
            raise StopUser()
        try:
            self._journey()
        except StopUser:
            raise
        except Exception:
            pass
        self.iterations_done += 1
        if self.iterations_done >= self.max_iterations:
            raise StopUser()


class PhasedShape(LoadTestShape):
    # 5s warmup, then 3x10s plateaus at 5/15/5, then drain
    def tick(self):
        t = self.get_run_time()
        if t < 5:
            return (2, 2)
        if t < 15:
            return (5, 5)
        if t < 25:
            return (15, 15)
        if t < 35:
            return (5, 5)
        if t < 40:
            return (0, 0)
        return None
