import io.gatling.javaapi.core.*;
import io.gatling.javaapi.http.*;

import java.time.Duration;
import java.util.*;
import java.util.concurrent.ThreadLocalRandom;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

import static io.gatling.javaapi.core.CoreDsl.*;
import static io.gatling.javaapi.http.HttpDsl.*;

public class ModelSimulation extends Simulation {

    private static final String BASE = System.getenv().getOrDefault("BASE_URL", "http://127.0.0.1:8000");

    private static final Pattern CSRF_INPUT = Pattern.compile("name=\"csrf\"[^>]*value=\"([^\"]+)\"");
    private static final Pattern CSRF_INPUT2 = Pattern.compile("value=\"([^\"]+)\"[^>]*name=\"csrf\"");
    private static final Pattern CHALLENGE_INPUT = Pattern.compile("name=\"challenge\"[^>]*value=\"([^\"]*)\"");
    private static final Pattern CHALLENGE_INPUT2 = Pattern.compile("value=\"([^\"]*)\"[^>]*name=\"challenge\"");
    private static final Pattern ACTION = Pattern.compile("action=\"([^\"]*\\/v2\\/challenges\\/[^\"]+)\"");

    private static String extractCsrf(String body) {
        if (body == null) return null;
        Matcher m = CSRF_INPUT.matcher(body);
        if (m.find()) return m.group(1);
        m = CSRF_INPUT2.matcher(body);
        if (m.find()) return m.group(1);
        return null;
    }

    private static String extractChallenge(String body) {
        if (body == null) return "";
        Matcher m = CHALLENGE_INPUT.matcher(body);
        if (m.find()) return m.group(1);
        m = CHALLENGE_INPUT2.matcher(body);
        if (m.find()) return m.group(1);
        return "";
    }

    private static String extractAction(String body) {
        if (body == null) return null;
        Matcher m = ACTION.matcher(body);
        if (m.find()) return m.group(1);
        return null;
    }

    private static final AtomicInteger USER_SEQ = new AtomicInteger(0);

    private static String nextUser() {
        int n = USER_SEQ.getAndIncrement() % 16 + 1;
        return "bench-" + n;
    }

    private final HttpProtocolBuilder httpProtocol = http
            .baseUrl(BASE)
            .disableAutoRedirect()
            .acceptHeader("application/json, text/html")
            .contentTypeHeader("application/json")
            .shareConnections();

    // ---- Work operation with Retry-After honoring and raw ceiling ----
    // Raw ceiling: 12 POST /v2/work starts per 1s bucket globally.
    // We implement a simple token-bucket style pacing via a shared gate.
    private static final class WorkGate {
        private static final long WINDOW_MS = 1000L;
        private static final int MAX_PER_WINDOW = 12;
        private static long windowStart = System.currentTimeMillis();
        private static int count = 0;

        static synchronized void acquire() {
            while (true) {
                long now = System.currentTimeMillis();
                if (now - windowStart >= WINDOW_MS) {
                    windowStart = now;
                    count = 0;
                }
                if (count < MAX_PER_WINDOW) {
                    count++;
                    return;
                }
                long sleep = WINDOW_MS - (now - windowStart) + 1;
                try {
                    Thread.sleep(Math.max(1, sleep));
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                    return;
                }
            }
        }
    }

    private static final class RetryAfter {
        static long parse(String header) {
            if (header == null) return 1000L;
            try {
                double v = Double.parseDouble(header.trim());
                return (long) (v * 1000.0);
            } catch (Exception e) {
                return 1000L;
            }
        }
    }

    // ---- Chains ----

    private ChainBuilder loginChain() {
        return exec(session -> session.set("username", nextUser()))
                .exec(http("login-form")
                        .get("/v2/login-form")
                        .check(status().is(200))
                        .check(bodyString().saveAs("loginFormBody")))
                .exec(session -> {
                    String csrf = extractCsrf(session.getString("loginFormBody"));
                    return session.set("csrf", csrf == null ? "" : csrf);
                })
                .exec(http("login")
                        .post("/v2/login")
                        .body(StringBody(session -> {
                            String u = session.getString("username");
                            String c = session.getString("csrf");
                            return "{\"username\":\"" + u + "\",\"password\":\"bench\",\"csrf\":\"" + c + "\"}";
                        }))
                        .check(status().in(200, 302))
                        .check(header("Location").optional().saveAs("loginLocation"))
                        .check(bodyString().optional().saveAs("loginBody")))
                .exec(session -> {
                    String loc = session.getString("loginLocation");
                    if (loc != null && !loc.isEmpty()) {
                        return session.set("loginRedirect", loc);
                    }
                    return session;
                })
                .doIf(session -> session.getString("loginRedirect") != null)
                .then(
                        exec(http("login-redirect")
                                .get(session -> session.getString("loginRedirect"))
                                .check(status().is(200))
                                .check(bodyString().saveAs("loginBody2")))
                                .exec(session -> {
                                    String b = session.getString("loginBody2");
                                    String csrf = extractCsrf(b);
                                    if (csrf != null) return session.set("csrf", csrf);
                                    return session;
                                })
                )
                .exec(session -> {
                    String b = session.getString("loginBody");
                    if (b != null) {
                        String csrf = extractCsrf(b);
                        if (csrf != null) return session.set("csrf", csrf);
                    }
                    return session;
                });
    }

    private ChainBuilder catalogChain() {
        return exec(http("catalog")
                .get("/v2/catalog")
                .check(status().is(200))
                .check(jsonPath("$.data.products[0].id").saveAs("productId"))
                .check(jsonPath("$.data.products[0].variants[0].id").saveAs("variantId")));
    }

    private ChainBuilder challengeChain() {
        return exec(http("challenge-form")
                .get("/v2/challenge-form")
                .check(status().is(200))
                .check(bodyString().saveAs("challengeBody")))
                .exec(session -> {
                    String b = session.getString("challengeBody");
                    String action = extractAction(b);
                    String ch = extractChallenge(b);
                    return session.set("challengeAction", action == null ? "" : action)
                            .set("challengeValue", ch);
                })
                .doIf(session -> {
                    String a = session.getString("challengeAction");
                    return a != null && !a.isEmpty();
                })
                .then(
                        exec(http("challenge-submit")
                                .post(session -> session.getString("challengeAction"))
                                .header("X-CSRF-Token", session -> session.getString("csrf"))
                                .body(StringBody(session -> "{\"challenge\":\"" + session.getString("challengeValue") + "\"}"))
                                .check(status().in(200, 302))
                                .check(header("Location").optional().saveAs("challengeLocation")))
                                .doIf(session -> session.getString("challengeLocation") != null)
                                .then(
                                        exec(http("challenge-claim")
                                                .get(session -> session.getString("challengeLocation"))
                                                .check(status().is(200))
                                                .check(bodyString().saveAs("claimBody")))
                                                .exec(session -> {
                                                    String b = session.getString("claimBody");
                                                    String csrf = extractCsrf(b);
                                                    String grant = null;
                                                    if (b != null) {
                                                        Matcher m = Pattern.compile("\"grant_id\"\\s*:\\s*\"([^\"]+)\"").matcher(b);
                                                        if (m.find()) grant = m.group(1);
                                                    }
                                                    if (csrf != null) session = session.set("csrf", csrf);
                                                    if (grant != null) session = session.set("grantId", grant);
                                                    return session;
                                                })
                                )
                );
    }

    private ChainBuilder cartChain() {
        return exec(http("cart-create")
                .post("/v2/carts")
                .header("X-CSRF-Token", session -> session.getString("csrf"))
                .body(StringBody(session -> {
                    String pid = session.getString("productId");
                    String vid = session.getString("variantId");
                    String grant = session.getString("grantId");
                    StringBuilder sb = new StringBuilder();
                    sb.append("{\"product_id\":\"").append(pid).append("\",\"variant_id\":\"").append(vid).append("\"");
                    if (grant != null && !grant.isEmpty()) {
                        sb.append(",\"grant_id\":\"").append(grant).append("\"");
                    }
                    sb.append("}");
                    return sb.toString();
                }))
                .check(status().is(201))
                .check(header("ETag").optional().saveAs("cartEtag"))
                .check(bodyString().saveAs("cartBody")))
                .exec(session -> {
                    String b = session.getString("cartBody");
                    String id = null;
                    String csrf = null;
                    if (b != null) {
                        Matcher m = Pattern.compile("\"id\"\\s*:\\s*\"([^\"]+)\"").matcher(b);
                        if (m.find()) id = m.group(1);
                        csrf = extractCsrf(b);
                    }
                    if (csrf != null) session = session.set("csrf", csrf);
                    if (id != null) session = session.set("cartId", id);
                    return session;
                });
    }

    private ChainBuilder workChain() {
        return exec(session -> {
            WorkGate.acquire();
            return session;
        })
                .asLongAs(session -> session.getInt("workRetries") < 4)
                .on(
                        exec(http("work")
                                .post("/v2/work")
                                .header("X-CSRF-Token", session -> session.getString("csrf"))
                                .body(StringBody("{}"))
                                .check(status().saveAs("workStatus"))
                                .check(header("Retry-After").optional().saveAs("retryAfter"))
                                .check(bodyString().optional().saveAs("workBody")))
                                .exec(session -> {
                                    int st = session.getInt("workStatus");
                                    if (st == 429) {
                                        long wait = RetryAfter.parse(session.getString("retryAfter"));
                                        try {
                                            Thread.sleep(wait);
                                        } catch (InterruptedException e) {
                                            Thread.currentThread().interrupt();
                                        }
                                        return session.set("workRetries", session.getInt("workRetries") + 1);
                                    }
                                    return session.set("workRetries", 4);
                                })
                )
                .exec(session -> {
                    int st = session.getInt("workStatus");
                    if (st >= 400 && st != 429) {
                        return session.markAsFailed();
                    }
                    return session;
                });
    }

    private ChainBuilder journey() {
        return exec(session -> session
                        .set("workRetries", 0)
                        .set("grantId", "")
                        .set("cartId", "")
                        .set("csrf", ""))
                .exec(loginChain())
                .exec(catalogChain())
                .exec(challengeChain())
                .exec(cartChain())
                .exec(workChain());
    }

    private final ScenarioBuilder scn = scenario("ModelSimulation")
            .forever()
            .on(journey());

    {
        setUp(
                scn.injectOpen(
                        rampUsers(2).during(Duration.ofSeconds(1))
                )
        ).protocols(httpProtocol)
                .maxDuration(Duration.ofSeconds(60));
    }
}
