import http from 'k6/http';
import { check, sleep } from 'k6';
import { Counter, Rate, Trend } from 'k6/metrics';
import encoding from 'k6/encoding';

const BASE = __ENV.BASE_URL || 'http://127.0.0.1:8000';

const workOk = new Counter('work_ok');
const work429 = new Counter('work_429');
const workErr = new Counter('work_err');
const workRaw = new Counter('work_raw');
const bizFail = new Rate('business_failure');
const opDur = new Trend('op_duration');

export const options = {
  scenarios: {
    flow: {
      executor: 'per-vu-iterations',
      vus: 2,
      iterations: 2,
      maxDuration: '60s',
    },
  },
  thresholds: {
    'work_ok': ['count>=1'],
  },
  discardResponseBodies: false,
};

function parseCsrf(html) {
  if (!html) return null;
  const re = /<input[^>]*name\s*=\s*["']?csrf["']?[^>]*>/gi;
  let m;
  while ((m = re.exec(html)) !== null) {
    const tag = m[0];
    const vm = tag.match(/value\s*=\s*["']([^"']*)["']/i);
    if (vm) return vm[1];
  }
  const re2 = /name\s*=\s*["']?csrf["']?[^>]*value\s*=\s*["']([^"']*)["']/i;
  const m2 = html.match(re2);
  if (m2) return m2[1];
  return null;
}

function parseChallengeForm(html) {
  if (!html) return null;
  const actionM = html.match(/<form[^>]*action\s*=\s*["']([^"']+)["']/i);
  const inputM = html.match(/<input[^>]*name\s*=\s*["']?challenge["']?[^>]*>/i);
  let val = null;
  if (inputM) {
    const vm = inputM[0].match(/value\s*=\s*["']([^"']*)["']/i);
    if (vm) val = vm[1];
  }
  if (!actionM || val === null) return null;
  return { action: actionM[1], value: val };
}

function jarFor(user) {
  return http.cookieJar();
}

function req(method, url, body, params) {
  params = params || {};
  params.redirects = 0;
  params.headers = params.headers || {};
  if (method === 'GET') return http.get(url, params);
  if (method === 'POST') return http.post(url, body, params);
  if (method === 'PATCH') return http.patch(url, body, params);
  return http.request(method, url, body, params);
}

function login(user) {
  const jar = jarFor(user);
  const p = { jar, headers: {} };
  let r = req('GET', BASE + '/v2/login-form', null, p);
  if (r.status !== 200) return null;
  let csrf = parseCsrf(r.body);
  if (!csrf) return null;
  const payload = JSON.stringify({ username: user, password: 'bench', csrf });
  r = req('POST', BASE + '/v2/login', payload, {
    jar,
    headers: { 'Content-Type': 'application/json' },
  });
  if (r.status === 302) {
    const loc = r.headers['Location'] || r.headers['location'];
    if (loc) {
      const u = loc.startsWith('http') ? loc : BASE + loc;
      r = req('GET', u, null, { jar });
    }
  }
  if (r.status !== 200) return null;
  let body;
  try { body = JSON.parse(r.body); } catch (e) { return null; }
  if (!body || !body.csrf) return null;
  return { jar, csrf: body.csrf, user };
}

function renew(sess) {
  const r = req('POST', BASE + '/v2/session/renew', '{}', {
    jar: sess.jar,
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': sess.csrf },
  });
  if (r.status === 200) {
    try {
      const b = JSON.parse(r.body);
      if (b && b.csrf) sess.csrf = b.csrf;
    } catch (e) {}
    return true;
  }
  return false;
}

function doWork(sess) {
  const start = Date.now();
  let attempts = 0;
  let retries429 = 0;
  while (attempts < 8) {
    attempts++;
    workRaw.add(1);
    const r = req('POST', BASE + '/v2/work', '{}', {
      jar: sess.jar,
      headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': sess.csrf },
    });
    if (r.status === 200) {
      let ok = false;
      try { const b = JSON.parse(r.body); ok = b && b.ok === true; } catch (e) {}
      if (ok) {
        workOk.add(1);
        bizFail.add(false);
        opDur.add(Date.now() - start);
        return true;
      }
      workErr.add(1);
      bizFail.add(true);
      return false;
    }
    if (r.status === 429) {
      work429.add(1);
      bizFail.add(false);
      if (retries429 >= 4) return false;
      retries429++;
      let ra = 1;
      const h = r.headers['Retry-After'] || r.headers['retry-after'];
      if (h) { const n = parseFloat(h); if (!isNaN(n)) ra = n; }
      sleep(ra);
      continue;
    }
    if (r.status === 401) {
      let err = null;
      try { const b = JSON.parse(r.body); err = b && b.error; } catch (e) {}
      if (err === 'expired') {
        if (!renew(sess)) return false;
        continue;
      }
      if (err === 'session') {
        const ns = login(sess.user);
        if (!ns) return false;
        sess.jar = ns.jar;
        sess.csrf = ns.csrf;
        continue;
      }
      workErr.add(1);
      bizFail.add(true);
      return false;
    }
    if (r.status >= 500) {
      workErr.add(1);
      bizFail.add(true);
      return false;
    }
    workErr.add(1);
    bizFail.add(true);
    return false;
  }
  return false;
}

export default function () {
  const user = 'bench-' + ((__VU - 1) % 16 + 1);
  const sess = login(user);
  if (!sess) {
    check(null, { 'login ok': () => false });
    return;
  }
  check(sess, { 'login ok': () => true });
  const ok = doWork(sess);
  check(ok, { 'work ok': (v) => v === true });
}
