import os
import re
import time
import uuid
from urllib.parse import urljoin

from locust import HttpUser, task, between, events
from locust.exception import StopUser


BASE_URL = os.environ.get("BASE_URL", "http://127.0.0.1:8000")
PASSWORD = "bench"


def _abs(url):
    if not url:
        return url
    return urljoin(BASE_URL + "/", url)


class ShopUser(HttpUser):
    host = BASE_URL
    wait_time = between(0.05, 0.15)

    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self.username = None
        self.csrf = None
        self.cart_id = None
        self.cart_etag = None
        self.iterations_done = 0
        self.max_iterations = 2
        self._work_retries = 0

    # ---------- helpers ----------
    def _headers(self, extra=None):
        h = {}
        if self.csrf:
            h["X-CSRF-Token"] = self.csrf
        if extra:
            h.update(extra)
        return h

    def _capture_csrf(self, resp):
        try:
            data = resp.json()
        except Exception:
            return
        if isinstance(data, dict) and data.get("csrf"):
            self.csrf = data["csrf"]

    def _login(self):
        # pick a bench account
        if self.username is None:
            idx = (id(self) % 16) + 1
            self.username = "bench-%d" % idx
        with self.client.get("/v2/login-form", name="GET /v2/login-form",
                             catch_response=True, allow_redirects=False) as r:
            if r.status_code >= 400:
                r.failure("login-form status %s" % r.status_code)
                return False
            m = re.search(r'name=["\']csrf["\'][^>]*value=["\']([^"\']+)["\']', r.text)
            if not m:
                m = re.search(r'value=["\']([^"\']+)["\'][^>]*name=["\']csrf["\']', r.text)
            if not m:
                r.failure("no csrf in login form")
                return False
            form_csrf = m.group(1)
            r.success()
        with self.client.post("/v2/login",
                              json={"username": self.username, "password": PASSWORD, "csrf": form_csrf},
                              name="POST /v2/login", catch_response=True,
                              allow_redirects=False) as r:
            if r.status_code == 302:
                loc = r.headers.get("Location")
                if loc:
                    with self.client.get(_abs(loc), name="GET login-redirect",
                                         catch_response=True, allow_redirects=False) as r2:
                        if r2.status_code >= 400:
                            r2.failure("redirect status %s" % r2.status_code)
                        else:
                            self._capture_csrf(r2)
                            r2.success()
                r.success()
            elif r.status_code >= 400:
                r.failure("login status %s" % r.status_code)
                return False
            else:
                self._capture_csrf(r)
                r.success()
        return self.csrf is not None

    def _renew(self):
        with self.client.post("/v2/session/renew", json={},
                              headers=self._headers(),
                              name="POST /v2/session/renew",
                              catch_response=True, allow_redirects=False) as r:
            if r.status_code >= 400:
                r.failure("renew status %s" % r.status_code)
                return False
            self._capture_csrf(r)
            r.success()
        return True

    def _recover_cart(self):
        if not self.cart_id:
            return True
        with self.client.post("/v2/carts/%s/recover" % self.cart_id, json={},
                              headers=self._headers(),
                              name="POST /v2/carts/recover",
                              catch_response=True, allow_redirects=False) as r:
            if r.status_code >= 400:
                r.failure("recover status %s" % r.status_code)
                return False
            self._capture_csrf(r)
            r.success()
        return True

    def _handle_401(self, resp):
        try:
            data = resp.json()
        except Exception:
            return False
        err = data.get("error") if isinstance(data, dict) else None
        if err == "expired":
            if self._renew():
                self._recover_cart()
                return True
            return False
        if err == "session":
            self.csrf = None
            self.cart_id = None
            self.cart_etag = None
            if self._login():
                return True
            return False
        return False

    def _get_catalog(self):
        with self.client.get("/v2/catalog", name="GET /v2/catalog",
                             catch_response=True, allow_redirects=False) as r:
            if r.status_code >= 400:
                r.failure("catalog status %s" % r.status_code)
                return None
            try:
                data = r.json()
            except Exception:
                r.failure("catalog json")
                return None
            r.success()
            return data

    def _pick_product(self, data):
        try:
            products = data["data"]["products"]
        except Exception:
            return None
        for p in products:
            for v in p.get("variants", []):
                if v.get("in_stock"):
                    return p["id"], v["id"]
        return None

    def _get_challenge_grant(self):
        with self.client.get("/v2/challenge-form", name="GET /v2/challenge-form",
                             catch_response=True, allow_redirects=False) as r:
            if r.status_code >= 400:
                r.failure("challenge-form status %s" % r.status_code)
                return None
            m = re.search(r'action=["\']([^"\']*?/v2/challenges/[^"\']+)["\']', r.text)
            if not m:
                r.failure("no challenge action")
                return None
            action = m.group(1)
            m2 = re.search(r'name=["\']challenge["\'][^>]*value=["\']([^"\']+)["\']', r.text)
            if not m2:
                m2 = re.search(r'value=["\']([^"\']+)["\'][^>]*name=["\']challenge["\']', r.text)
            if not m2:
                r.failure("no challenge value")
                return None
            chal = m2.group(1)
            r.success()
        with self.client.post(_abs(action), json={"challenge": chal},
                              headers=self._headers(),
                              name="POST /v2/challenges",
                              catch_response=True, allow_redirects=False) as r:
            if r.status_code == 302:
                loc = r.headers.get("Location")
                r.success()
                if not loc:
                    return None
                with self.client.get(_abs(loc), name="GET challenge-redirect",
                                     catch_response=True, allow_redirects=False) as r2:
                    if r2.status_code >= 400:
                        r2.failure("challenge redirect status %s" % r2.status_code)
                        return None
                    try:
                        d = r2.json()
                    except Exception:
                        r2.failure("challenge redirect json")
                        return None
                    self._capture_csrf(r2)
                    r2.success()
                    return d.get("grant_id")
            elif r.status_code >= 400:
                r.failure("challenge status %s" % r.status_code)
                return None
            else:
                try:
                    d = r.json()
                except Exception:
                    r.failure("challenge json")
                    return None
                self._capture_csrf(r)
                r.success()
                return d.get("grant_id")

    def _create_cart(self, product_id, variant_id, grant_id):
        payload = {"product_id": product_id, "variant_id": variant_id}
        if grant_id:
            payload["grant_id"] = grant_id
        with self.client.post("/v2/carts", json=payload,
                              headers=self._headers(),
                              name="POST /v2/carts",
                              catch_response=True, allow_redirects=False) as r:
            if r.status_code == 401:
                if self._handle_401(r):
                    r.success()
                    return self._create_cart(product_id, variant_id, grant_id)
                r.failure("cart 401")
                return None
            if r.status_code >= 400:
                r.failure("cart status %s" % r.status_code)
                return None
            try:
                d = r.json()
            except Exception:
                r.failure("cart json")
                return None
            self._capture_csrf(r)
            self.cart_id = d.get("id")
            self.cart_etag = r.headers.get("ETag")
            r.success()
            return self.cart_id

    def _patch_cart(self, quantity):
        if not self.cart_id:
            return False
        headers = self._headers()
        if self.cart_etag:
            headers["If-Match"] = self.cart_etag
        with self.client.patch("/v2/carts/%s" % self.cart_id,
                               json={"quantity": quantity},
                               headers=headers,
                               name="PATCH /v2/carts",
                               catch_response=True, allow_redirects=False) as r:
            if r.status_code == 412:
                # re-read and retry once
                with self.client.get("/v2/carts/%s" % self.cart_id,
                                     name="GET /v2/carts",
                                     catch_response=True, allow_redirects=False) as rg:
                    if rg.status_code >= 400:
                        rg.failure("cart get status %s" % rg.status_code)
                        r.failure("412 and reread failed")
                        return False
                    self.cart_etag = rg.headers.get("ETag")
                    rg.success()
                headers2 = self._headers()
                if self.cart_etag:
                    headers2["If-Match"] = self.cart_etag
                with self.client.patch("/v2/carts/%s" % self.cart_id,
                                       json={"quantity": quantity},
                                       headers=headers2,
                                       name="PATCH /v2/carts retry",
                                       catch_response=True, allow_redirects=False) as r2:
                    if r2.status_code >= 400:
                        r2.failure("patch retry status %s" % r2.status_code)
                        r.failure("patch retry failed")
                        return False
                    self._capture_csrf(r2)
                    r2.success()
                    r.success()
                    return True
            if r.status_code == 401:
                if self._handle_401(r):
                    r.success()
                    return self._patch_cart(quantity)
                r.failure("patch 401")
                return False
            if r.status_code >= 400:
                r.failure("patch status %s" % r.status_code)
                return False
            self._capture_csrf(r)
            r.success()
            return True

    def _reserve(self):
        if not self.cart_id:
            return None
        with self.client.post("/v2/reservations", json={"cart_id": self.cart_id},
                              headers=self._headers(),
                              name="POST /v2/reservations",
                              catch_response=True, allow_redirects=False) as r:
            if r.status_code == 401:
                if self._handle_401(r):
                    r.success()
                    return self._reserve()
                r.failure("reservation 401")
                return None
            if r.status_code >= 400:
                r.failure("reservation status %s" % r.status_code)
                return None
            try:
                d = r.json()
            except Exception:
                r.failure("reservation json")
                return None
            self._capture_csrf(r)
            status_url = d.get("status_url")
            r.success()
        if not status_url:
            return None
        for _ in range(5):
            time.sleep(0.06)
            with self.client.get(_abs(status_url), name="GET reservation status",
                                 catch_response=True, allow_redirects=False) as r:
                if r.status_code >= 400:
                    r.failure("status poll %s" % r.status_code)
                    return None
                try:
                    d = r.json()
                except Exception:
                    r.failure("status json")
                    return None
                self._capture_csrf(r)
                st = d.get("status")
                r.success()
                if st == "ready":
                    return d.get("reservation_id")
                if st in ("pending",):
                    continue
                return None
        return None

    def _order(self, reservation_id):
        if not self.cart_id:
            return False
        idem = "idem-%s-%s" % (self.cart_id, uuid.uuid4().hex[:8])
        headers = self._headers({"Idempotency-Key": idem})
        if self.cart_etag:
            headers["If-Match"] = self.cart_etag
        payload = {"cart_id": self.cart_id}
        if reservation_id:
            payload["reservation_id"] = reservation_id
        with self.client.post("/v2/orders", json=payload,
                              headers=headers,
                              name="POST /v2/orders",
                              catch_response=True, allow_redirects=False) as r:
            if r.status_code == 401:
                if self._handle_401(r):
                    r.success()
                    return self._order(reservation_id)
                r.failure("order 401")
                return False
            if r.status_code >= 400:
                r.failure("order status %s" % r.status_code)
                return False
            try:
                d = r.json()
            except Exception:
                r.failure("order json")
                return False
            if d.get("accepted") is not True:
                r.failure("order not accepted")
                return False
            self._capture_csrf(r)
            r.success()
            return True

    def _do_work(self):
        # native worker honoring Retry-After
        attempts = 0
        while attempts <= 4:
            attempts += 1
            with self.client.post("/v2/work", json={},
                                  headers=self._headers(),
                                  name="POST /v2/work",
                                  catch_response=True, allow_redirects=False) as r:
                if r.status_code == 429:
                    ra = r.headers.get("Retry-After", "1")
                    try:
                        delay = float(ra)
                    except Exception:
                        delay = 1.0
                    r.success()
                    time.sleep(delay)
                    continue
                if r.status_code == 401:
                    if self._handle_401(r):
                        r.success()
                        continue
                    r.failure("work 401")
                    return False
                if r.status_code >= 500:
                    r.failure("work status %s" % r.status_code)
                    return False
                if r.status_code >= 400:
                    r.failure("work status %s" % r.status_code)
                    return False
                try:
                    d = r.json()
                except Exception:
                    r.failure("work json")
                    return False
                if not d.get("ok"):
                    r.failure("work not ok")
                    return False
                self._capture_csrf(r)
                r.success()
                return True
        return False

    # ---------- journey ----------
    @task
    def journey(self):
        if self.iterations_done >= self.max_iterations:
            raise StopUser()
        self.csrf = None
        self.cart_id = None
        self.cart_etag = None
        if not self._login():
            self.iterations_done += 1
            if self.iterations_done >= self.max_iterations:
                raise StopUser()
            return
        cat = self._get_catalog()
        if not cat:
            self.iterations_done += 1
            if self.iterations_done >= self.max_iterations:
                raise StopUser()
            return
        pick = self._pick_product(cat)
        if not pick:
            self.iterations_done += 1
            if self.iterations_done >= self.max_iterations:
                raise StopUser()
            return
        pid, vid = pick
        grant = self._get_challenge_grant()
        if not self._create_cart(pid, vid, grant):
            self.iterations_done += 1
            if self.iterations_done >= self.max_iterations:
                raise StopUser()
            return
        if not self._patch_cart(1):
            self.iterations_done += 1
            if self.iterations_done >= self.max_iterations:
                raise StopUser()
            return
        res_id = self._reserve()
        if res_id is None:
            self.iterations_done += 1
            if self.iterations_done >= self.max_iterations:
                raise StopUser()
            return
        self._order(res_id)
        self._do_work()
        self.iterations_done += 1
        if self.iterations_done >= self.max_iterations:
            raise StopUser()


class LoadTestShape:
    def __init__(self):
        self.start = None
        self.phase = 0

    def tick(self):
        now = time.time()
        if self.start is None:
            self.start = now
        elapsed = now - self.start
        # warmup 5s, then 3 plateaus of 10s: 5, 15, 5 users
        if elapsed < 5:
            return (2, 2)
        if elapsed < 15:
            return (5, 5)
        if elapsed < 25:
            return (15, 15)
        if elapsed < 35:
            return (5, 5)
        if elapsed < 40:
            return (0, 0)
        return None
