import io.gatling.javaapi.core.*;
import io.gatling.javaapi.http.*;

import java.time.Duration;
import java.util.*;
import java.util.concurrent.ThreadLocalRandom;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

import static io.gatling.javaapi.core.CoreDsl.*;
import static io.gatling.javaapi.http.HttpDsl.*;

public class ModelSimulation extends Simulation {

    private static final String BASE = System.getenv().getOrDefault("BASE_URL", "http://127.0.0.1:8000");
    private static final String PASSWORD = "bench";

    private static final Pattern CSRF_INPUT = Pattern.compile(
            "name=\"csrf\"[^>]*value=\"([^\"]+)\"|value=\"([^\"]+)\"[^>]*name=\"csrf\"");
    private static final Pattern CHALLENGE_INPUT = Pattern.compile(
            "name=\"challenge\"[^>]*value=\"([^\"]+)\"|value=\"([^\"]+)\"[^>]*name=\"challenge\"");
    private static final Pattern CHALLENGE_ACTION = Pattern.compile(
            "action=\"(/v2/challenges/[^\"]+)\"");

    private static String firstGroup(Matcher m) {
        if (m.find()) {
            return m.group(1) != null ? m.group(1) : m.group(2);
        }
        return null;
    }

    private static String extractCsrf(String body) {
        if (body == null) return null;
        return firstGroup(CSRF_INPUT.matcher(body));
    }

    private static String extractChallenge(String body) {
        if (body == null) return null;
        return firstGroup(CHALLENGE_INPUT.matcher(body));
    }

    private static String extractChallengeAction(String body) {
        if (body == null) return null;
        Matcher m = CHALLENGE_ACTION.matcher(body);
        return m.find() ? m.group(1) : null;
    }

    private static String jsonStr(String body, String key) {
        if (body == null) return null;
        Matcher m = Pattern.compile("\"" + Pattern.quote(key) + "\"\\s*:\\s*\"([^\"]*)\"").matcher(body);
        return m.find() ? m.group(1) : null;
    }

    private static String jsonNum(String body, String key) {
        if (body == null) return null;
        Matcher m = Pattern.compile("\"" + Pattern.quote(key) + "\"\\s*:\\s*(-?\\d+)").matcher(body);
        return m.find() ? m.group(1) : null;
    }

    private static boolean jsonBool(String body, String key) {
        if (body == null) return false;
        Matcher m = Pattern.compile("\"" + Pattern.quote(key) + "\"\\s*:\\s*(true|false)").matcher(body);
        return m.find() && "true".equals(m.group(1));
    }

    private static String pickAccount() {
        int n = ThreadLocalRandom.current().nextInt(1, 17);
        return "bench-" + n;
    }

    private final HttpProtocolBuilder httpProtocol = http
            .baseUrl(BASE)
            .disableAutoRedirect()
            .acceptHeader("application/json, text/html")
            .contentTypeHeader("application/json")
            .userAgentHeader("gatling-model-sim");

    // ---------- Chains ----------

    private ChainBuilder loginFlow() {
        return exec(session -> session.set("username", pickAccount()))
                .exec(http("login-form")
                        .get("/v2/login-form")
                        .check(status().lt(400))
                        .check(bodyString().saveAs("loginFormBody")))
                .exec(session -> {
                    String csrf = extractCsrf(session.getString("loginFormBody"));
                    return session.set("csrf", csrf);
                })
                .exec(http("login")
                        .post("/v2/login")
                        .body(StringBody(session ->
                                "{\"username\":\"" + session.getString("username") +
                                        "\",\"password\":\"" + PASSWORD +
                                        "\",\"csrf\":\"" + session.getString("csrf") + "\"}"))
                        .check(status().in(200, 201, 302))
                        .check(bodyString().saveAs("loginBody")))
                .exec(session -> {
                    String csrf = jsonStr(session.getString("loginBody"), "csrf");
                    if (csrf == null) csrf = session.getString("csrf");
                    return session.set("csrf", csrf);
                });
    }

    private ChainBuilder catalogFlow() {
        return exec(http("catalog")
                .get("/v2/catalog")
                .check(status().is(200))
                .check(bodyString().saveAs("catalogBody")))
                .exec(session -> {
                    String body = session.getString("catalogBody");
                    String pid = null, vid = null;
                    if (body != null) {
                        Matcher pm = Pattern.compile("\"id\"\\s*:\\s*\"([^\"]+)\"").matcher(body);
                        if (pm.find()) pid = pm.group(1);
                        Matcher vm = Pattern.compile("\"variants\"\\s*:\\s*\\[\\s*\\{[^}]*\"id\"\\s*:\\s*\"([^\"]+)\"").matcher(body);
                        if (vm.find()) vid = vm.group(1);
                    }
                    return session.set("productId", pid).set("variantId", vid);
                });
    }

    private ChainBuilder challengeFlow() {
        return exec(http("challenge-form")
                .get("/v2/challenge-form")
                .check(status().lt(400))
                .check(bodyString().saveAs("challengeFormBody")))
                .exec(session -> {
                    String body = session.getString("challengeFormBody");
                    return session.set("challengeAction", extractChallengeAction(body))
                            .set("challengeValue", extractChallenge(body));
                })
                .doIf(session -> session.getString("challengeAction") != null
                        && session.getString("challengeValue") != null).then(
                        exec(http("challenge-submit")
                                .post(session -> session.getString("challengeAction"))
                                .body(StringBody(session ->
                                        "{\"challenge\":\"" + session.getString("challengeValue") + "\"}"))
                                .check(status().in(200, 201, 302))
                                .check(header("Location").saveAs("challengeLocation")))
                                .doIf(session -> session.getString("challengeLocation") != null).then(
                                        exec(http("challenge-follow")
                                                .get(session -> session.getString("challengeLocation"))
                                                .check(status().is(200))
                                                .check(bodyString().saveAs("grantBody")))
                                                .exec(session -> session.set("grantId",
                                                        jsonStr(session.getString("grantBody"), "grant_id")))
                                )
                );
    }

    private ChainBuilder cartFlow() {
        return exec(http("cart-create")
                .post("/v2/carts")
                .body(StringBody(session -> {
                    String gid = session.getString("grantId");
                    StringBuilder sb = new StringBuilder();
                    sb.append("{\"product_id\":\"").append(session.getString("productId"))
                            .append("\",\"variant_id\":\"").append(session.getString("variantId")).append("\"");
                    if (gid != null) sb.append(",\"grant_id\":\"").append(gid).append("\"");
                    sb.append("}");
                    return sb.toString();
                }))
                .check(status().in(200, 201))
                .check(bodyString().saveAs("cartBody")))
                .exec(session -> {
                    String body = session.getString("cartBody");
                    String csrf = jsonStr(body, "csrf");
                    if (csrf != null) session = session.set("csrf", csrf);
                    return session.set("cartId", jsonStr(body, "id"));
                });
    }

    private ChainBuilder reservationFlow() {
        return exec(http("reservation-create")
                .post("/v2/reservations")
                .body(StringBody(session -> "{\"cart_id\":\"" + session.getString("cartId") + "\"}"))
                .check(status().in(200, 202))
                .check(bodyString().saveAs("resBody")))
                .exec(session -> session.set("statusUrl", jsonStr(session.getString("resBody"), "status_url")))
                .asLongAs(session -> session.getString("statusUrl") != null
                        && !"ready".equals(session.getString("resStatus"))
                        && session.getInt("pollCount") < 5).on(
                        exec(session -> session.set("pollCount", session.getInt("pollCount") + 1))
                                .pause(Duration.ofMillis(60))
                                .exec(http("reservation-poll")
                                        .get(session -> session.getString("statusUrl"))
                                        .check(status().is(200))
                                        .check(bodyString().saveAs("pollBody")))
                                .exec(session -> {
                                    String body = session.getString("pollBody");
                                    String status = jsonStr(body, "status");
                                    String rid = jsonStr(body, "reservation_id");
                                    return session.set("resStatus", status).set("reservationId", rid);
                                })
                );
    }

    private ChainBuilder orderFlow() {
        return exec(http("order-create")
                .post("/v2/orders")
                .header("Idempotency-Key", session -> "idem-" + session.getString("cartId"))
                .body(StringBody(session -> {
                    String rid = session.getString("reservationId");
                    StringBuilder sb = new StringBuilder();
                    sb.append("{\"cart_id\":\"").append(session.getString("cartId")).append("\"");
                    if (rid != null) sb.append(",\"reservation_id\":\"").append(rid).append("\"");
                    sb.append("}");
                    return sb.toString();
                }))
                .check(status().in(200, 201))
                .check(bodyString().saveAs("orderBody")))
                .exec(session -> {
                    String body = session.getString("orderBody");
                    boolean accepted = jsonBool(body, "accepted");
                    String csrf = jsonStr(body, "csrf");
                    if (csrf != null) session = session.set("csrf", csrf);
                    return session.set("orderAccepted", accepted);
                });
    }

    private ChainBuilder workFlow() {
        return asLongAs(session -> session.getInt("workRetries") < 4).on(
                exec(http("work")
                        .post("/v2/work")
                        .header("X-CSRF-Token", session -> session.getString("csrf"))
                        .body(StringBody("{}"))
                        .check(status().saveAs("workStatus"))
                        .check(bodyString().saveAs("workBody")))
                        .exec(session -> {
                            int st = session.getInt("workStatus");
                            if (st == 429) {
                                return session.set("workRetries", session.getInt("workRetries") + 1);
                            }
                            return session.set("workRetries", 4);
                        })
                        .doIf(session -> session.getInt("workStatus") == 429).then(
                                pause(Duration.ofSeconds(1))
                        )
        );
    }

    private ChainBuilder journey() {
        return exec(session -> session
                        .set("workRetries", 0)
                        .set("pollCount", 0)
                        .set("resStatus", null)
                        .set("reservationId", null)
                        .set("grantId", null)
                        .set("cartId", null)
                        .set("orderAccepted", false))
                .exec(loginFlow())
                .exec(catalogFlow())
                .exec(challengeFlow())
                .exec(cartFlow())
                .exec(reservationFlow())
                .exec(orderFlow())
                .exec(workFlow());
    }

    // ---------- Scenario ----------

    private final ScenarioBuilder scn = scenario("ModelSimulation")
            .forever().on(journey());

    {
        setUp(
                scn.injectOpen(
                        rampUsers(2).during(Duration.ofSeconds(1))
                )
        ).protocols(httpProtocol)
                .maxDuration(Duration.ofSeconds(45));
    }
}
