import http from 'k6/http';
import { check, sleep } from 'k6';
import { Counter, Rate, Trend } from 'k6/metrics';
import encoding from 'k6/encoding';

const BASE = __ENV.BASE_URL || 'http://127.0.0.1:8000';

const workStarts = new Counter('work_starts');
const workOk = new Counter('work_ok');
const workUnexpected = new Counter('work_unexpected');
const workScheduled = new Counter('work_scheduled');
const workDropped = new Counter('work_dropped');
const businessResponses = new Counter('business_responses');
const businessFailure = new Rate('business_failure');
const burstGuard = new Counter('burst_guard');

const TARGET_RATE = 8;
const WARMUP = 5;
const SCORE_START = 5;
const SCORE_END = 35;
const DRAIN = 5;
const WINDOW = 5;
const WINDOWS = 6;

export const options = {
  scenarios: {
    work: {
      executor: 'constant-arrival-rate',
      rate: TARGET_RATE,
      timeUnit: '1s',
      duration: `${SCORE_END + DRAIN}s`,
      preAllocatedVUs: 8,
      maxVUs: 32,
      gracefulStop: '5s',
    },
  },
  thresholds: {
    business_failure: ['rate<0.01'],
  },
  discardResponseBodies: false,
  noConnectionReuse: false,
};

function parseCsrf(html) {
  if (!html) return null;
  const re = /<input[^>]*name=["']?csrf["']?[^>]*>/gi;
  let m;
  while ((m = re.exec(html)) !== null) {
    const tag = m[0];
    const vm = tag.match(/value=["']([^"']*)["']/i);
    if (vm) return vm[1];
  }
  const re2 = /<input[^>]*value=["']([^"']*)["'][^>]*name=["']?csrf["']?/gi;
  while ((m = re2.exec(html)) !== null) {
    return m[1];
  }
  return null;
}

function parseChallengeForm(html) {
  if (!html) return null;
  const actionM = html.match(/<form[^>]*action=["']([^"']+)["']/i);
  const inputM = html.match(/<input[^>]*name=["']?challenge["']?[^>]*>/i);
  let value = null;
  if (inputM) {
    const vm = inputM[0].match(/value=["']([^"']*)["']/i);
    if (vm) value = vm[1];
  }
  if (!actionM || !value) return null;
  return { action: actionM[1], value };
}

function jarFor(user) {
  return http.cookieJar();
}

function login(user) {
  const jar = http.cookieJar();
  const formRes = http.get(`${BASE}/v2/login-form`, { redirects: 0, tags: { name: 'login_form' } });
  const csrf = parseCsrf(formRes.body);
  if (!csrf) return null;
  const loginRes = http.post(`${BASE}/v2/login`, JSON.stringify({ username: user, password: 'bench', csrf }), {
    headers: { 'Content-Type': 'application/json' },
    redirects: 0,
    tags: { name: 'login' },
  });
  let body = null;
  try { body = loginRes.json(); } catch (e) { body = null; }
  if (loginRes.status === 302) {
    const loc = loginRes.headers['Location'];
    if (loc) {
      const follow = http.get(loc.startsWith('http') ? loc : `${BASE}${loc}`, { redirects: 0, tags: { name: 'login_follow' } });
      try { body = follow.json(); } catch (e) { body = null; }
    }
  }
  if (!body || !body.csrf) return null;
  return { csrf: body.csrf, user: body.user };
}

function renew(csrf) {
  const res = http.post(`${BASE}/v2/session/renew`, JSON.stringify({}), {
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf },
    redirects: 0,
    tags: { name: 'renew' },
  });
  let body = null;
  try { body = res.json(); } catch (e) { body = null; }
  if (body && body.csrf) return body.csrf;
  return csrf;
}

function doWork(csrf) {
  let attempts = 0;
  let currentCsrf = csrf;
  while (attempts < 5) {
    attempts++;
    const res = http.post(`${BASE}/v2/work`, JSON.stringify({}), {
      headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': currentCsrf },
      redirects: 0,
      tags: { name: 'work' },
    });
    businessResponses.add(1);
    if (res.status === 429) {
      workScheduled.add(1);
      const ra = res.headers['Retry-After'];
      const wait = ra ? parseFloat(ra) : 1;
      sleep(Math.max(0.05, wait));
      continue;
    }
    if (res.status === 401) {
      let body = null;
      try { body = res.json(); } catch (e) { body = null; }
      if (body && body.error === 'expired') {
        currentCsrf = renew(currentCsrf);
        continue;
      }
      businessFailure.add(true);
      workUnexpected.add(1);
      return false;
    }
    if (res.status >= 400) {
      businessFailure.add(true);
      workUnexpected.add(1);
      return false;
    }
    let body = null;
    try { body = res.json(); } catch (e) { body = null; }
    if (body && body.ok === true) {
      workOk.add(1);
      businessFailure.add(false);
      return true;
    }
    businessFailure.add(true);
    workUnexpected.add(1);
    return false;
  }
  workDropped.add(1);
  businessFailure.add(true);
  return false;
}

export default function () {
  const user = `bench-${((__VU - 1) % 16) + 1}`;
  const auth = login(user);
  if (!auth) {
    workDropped.add(1);
    return;
  }
  workStarts.add(1);
  doWork(auth.csrf);
}
