    def _extract_csrf_from_form(self, text):
        # input[name=csrf] mixed with decoys/attribute variants
        patterns = [
            r'<input[^>]*name=["\']csrf["\'][^>]*value=["\']([^"\']+)["\']',
            r'<input[^>]*value=["\']([^"\']+)["\'][^>]*name=["\']csrf["\']',
        ]
        for p in patterns:
            m = re.search(p, text, re.IGNORECASE)
            if m:
                return m.group(1)
        return None

    def _extract_challenge_action(self, text):
        m = re.search(r'<form[^>]*action=["\']([^"\']*?/v2/challenges/[^"\']+)["\']', text, re.IGNORECASE)
        if m:
            return m.group(1)
        m = re.search(r'action=["\']([^"\']*?/v2/challenges/[^"\']+)["\']', text, re.IGNORECASE)
        return m.group(1) if m else None

    def _extract_challenge_input(self, text):
        patterns = [
            r'<input[^>]*name=["\']challenge["\'][^>]*value=["\']([^"\']*)["\']',
            r'<input[^>]*value=["\']([^"\']*)["\'][^>]*name=["\']challenge["\']',
        ]
        for p in patterns:
            m = re.search(p, text, re.IGNORECASE)
            if m:
                return m.group(1)
        return None

    def _pick_account(self):
        idx = random.randint(1, 16)
        self.username = "bench-%d" % idx

    def _login(self):
        self._pick_account()
        with self.client.get("/v2/login-form", name="GET /v2/login-form",
                             catch_response=True, allow_redirects=False) as r:
            if r.status_code >= 400:
                r.failure("login-form status %s" % r.status_code)
                return False
            csrf = self._extract_csrf_from_form(r.text or "")
            if not csrf:
                r.failure("no csrf in login form")
                return False
            self.csrf = csrf
        with self.client.post("/v2/login",
                              json={"username": self.username, "password": self.password, "csrf": self.csrf},
                              name="POST /v2/login", catch_response=True, allow_redirects=False) as r:
            if r.status_code == 302:
                loc = r.headers.get("Location")
                if not loc:
                    r.failure("302 without Location")
                    return False
                with self.client.get(loc, name="GET login redirect", catch_response=True,
                                     allow_redirects=False) as r2:
                    if r2.status_code >= 400:
                        r2.failure("redirect status %s" % r2.status_code)
                        return False
                    try:
                        data = r2.json()
                    except Exception:
                        data = {}
                    if data.get("csrf"):
                        self.csrf = data["csrf"]
            elif r.status_code >= 400:
                r.failure("login status %s" % r.status_code)
                return False
            else:
                try:
                    data = r.json()
                except Exception:
                    data = {}
                if data.get("csrf"):
                    self.csrf = data["csrf"]
        self.session_ready = True
        return True

    def _renew(self):
        if not self.csrf:
            return False
        with self.client.post("/v2/session/renew", json={},
                              headers={"X-CSRF-Token": self.csrf},
                              name="POST /v2/session/renew", catch_response=True,
                              allow_redirects=False) as r:
