        with self.client.post("/v2/carts/%s/recover" % cart_id, json={},
                              headers={"X-CSRF-Token": self.csrf},
                              name="POST /v2/carts/{id}/recover", catch_response=True,
                              allow_redirects=False) as r:
            if r.status_code >= 400:
                r.failure("recover status %s" % r.status_code)
                return
            try:
                data = r.json()
            except Exception:
                data = {}
            if data.get("csrf"):
                self.csrf = data["csrf"]

    def _handle_401(self, resp, cart_id=None):
        try:
            data = resp.json()
        except Exception:
            data = {}
        err = data.get("error")
        if err == "expired":
            if self._renew():
                if cart_id:
                    self._recover_cart(cart_id)
                return True
            return False
        if err == "session":
            self._login()
            if cart_id:
                self._recover_cart(cart_id)
            return True
        # denied or other: not expiry
        return False

    def _get_catalog_product(self):
        with self.client.get("/v2/catalog", name="GET /v2/catalog",
                             catch_response=True, allow_redirects=False) as r:
            if r.status_code >= 400:
                r.failure("catalog status %s" % r.status_code)
                return None
            try:
                data = r.json()
            except Exception:
                r.failure("catalog not json")
                return None
        products = (data.get("data") or {}).get("products") or []
        for p in products:
            for v in p.get("variants") or []:
                if v.get("in_stock"):
                    return p.get("id"), v.get("id")
        # fallback to paged catalog
        next_url = data.get("next")
        pages = 0
        while next_url and pages < 3:
            pages += 1
            with self.client.get(next_url, name="GET /v2/catalog/page",
                                 catch_response=True, allow_redirects=False) as r:
                if r.status_code >= 400:
                    r.failure("catalog page status %s" % r.status_code)
                    return None
                try:
                    pd = r.json()
                except Exception:
                    r.failure("catalog page not json")
                    return None
            prod = pd.get("product") or pd.get("data") or {}
            if isinstance(prod, dict):
                for v in prod.get("variants") or []:
                    if v.get("in_stock"):
                        return prod.get("id"), v.get("id")
            next_url = pd.get("next")
        return None

    def _solve_challenge(self):
        with self.client.get("/v2/challenge-form", name="GET /v2/challenge-form",
                             catch_response=True, allow_redirects=False) as r:
            if r.status_code >= 400:
                r.failure("challenge-form status %s" % r.status_code)
                return None
            action = self._extract_challenge_action(r.text or "")
            chal = self._extract_challenge_input(r.text or "")
            if not action or chal is None:
                r.failure("challenge form parse failed")
                return None
        with self.client.post(action, json={"challenge": chal},
                              headers={"X-CSRF-Token": self.csrf},
                              name="POST /v2/challenges/{id}", catch_response=True,
                              allow_redirects=False) as r:
            if r.status_code == 302:
                loc = r.headers.get("Location")
                if not loc:
                    r.failure("challenge 302 no Location")
                    return None
                with self.client.get(loc, name="GET challenge redirect",
                                     catch_response=True, allow_redirects=False) as r2:
                    if r2.status_code >= 400:
                        r2.failure("challenge redirect status %s" % r2.status_code)
                        return None
                    try:
                        data = r2.json()
                    except Exception:
                        data = {}
                    if data.get("csrf"):
                        self.csrf = data["csrf"]
                    return data.get("grant_id")
            elif r.status_code >= 400:
                r.failure("challenge status %s" % r.status_code)
                return None
            else:
                try:
                    data = r.json()
                except Exception:
                    data = {}
                if data.get("csrf"):
                    self.csrf = data["csrf"]
                return data.get("grant_id")

    def _create_cart(self, product_id, variant_id, grant_id=None):
        payload = {"product_id": product_id, "variant_id": variant_id}
        if grant_id:
            payload["grant_id"] = grant_id
        with self.client.post("/v2/carts", json=payload,
                              headers={"X-CSRF-Token": self.csrf},
                              name="POST /v2/carts", catch_response=True,
                              allow_redirects=False) as r:
            if r.status_code == 401:
                if self._handle_401(r):
                    with self.client.post("/v2/carts", json=payload,
                                          headers={"X-CSRF-Token": self.csrf},
                                          name="POST /v2/carts", catch_response=True,
                                          allow_redirects=False) as r2:
                        if r2.status_code >= 400:
                            r2.failure("cart retry status %s" % r2.status_code)
                            return None
                        try:
                            data = r2.json()
                        except Exception:
                            r2.failure("cart retry not json")
                            return None
                        if data.get("csrf"):
                            self.csrf = data["csrf"]
                        return data.get("id")
                r.failure("cart 401 unrecoverable")
                return None
            if r.status_code >= 400:
                r.failure("cart status %s" % r.status_code)
                return None
            try:
                data = r.json()
            except Exception:
                r.failure("cart not json")
                return None
            if data.get("csrf"):
                self.csrf = data["csrf"]
            return data.get("id")

    def _patch_cart(self, cart_id, quantity):
        # read etag
        with self.client.get("/v2/carts/%s" % cart_id, name="GET /v2/carts/{id}",
                             catch_response=True, allow_redirects=False) as r:
            if r.status_code == 401:
                if self._handle_401(r, cart_id):
                    with self.client.get("/v2/carts/%s" % cart_id, name="GET /v2/carts/{id}",
                                         catch_response=True, allow_redirects=False) as r2:
                        if r2.status_code >= 400:
                            r2.failure("cart get retry status %s" % r2.status_code)
                            return False
                        etag = r2.headers.get("ETag")
                else:
                    r.failure("cart get 401 unrecoverable")
                    return False
            elif r.status_code >= 400:
                r.failure("cart get status %s" % r.status_code)
                return False
            else:
                etag = r.headers.get("ETag")
        if not etag:
            return False
        payload = {"quantity": quantity}
        headers = {"X-CSRF-Token": self.csrf, "If-Match": etag}
        with self.client.patch("/v2/carts/%s" % cart_id, json=payload, headers=headers,
                               name="PATCH /v2/carts/{id}", catch_response=True,
                               allow_redirects=False) as r:
            if r.status_code == 412:
                # re-read and retry once
                with self.client.get("/v2/carts/%s" % cart_id, name="GET /v2/carts/{id}",
                                     catch_response=True, allow_redirects=False) as r2:
                    if r2.status_code >= 400:
                        r2.failure("cart re-read status %s" % r2.status_code)
                        return False
                    etag2 = r2.headers.get("ETag")
                if not etag2:
                    return False
                headers["If-Match"] = etag2
                with self.client.patch("/v2/carts/%s" % cart_id, json=payload, headers=headers,
                                       name="PATCH /v2/carts/{id}", catch_response=True,
                                       allow_redirects=False) as r3:
                    if r3.status_code >= 400:
                        r3.failure("cart patch retry status %s" % r3.status_code)
                        return False
                    try:
                        data = r3.json()
                    except Exception:
                        data = {}
                    if data.get("csrf"):
                        self.csrf = data["csrf"]
                    return True
            if r.status_code == 401:
                if self._handle_401(r, cart_id):
                    return self._patch_cart(cart_id, quantity)
                r.failure("cart patch 401 unrecoverable")
                return False
            if r.status_code >= 400:
                r.failure("cart patch status %s" % r.status_code)
                return False
            try:
                data = r.json()
            except Exception:
                data = {}
            if data.get("csrf"):
                self.csrf = data["csrf"]
            return True

    def _reserve(self, cart_id):
        with self.client.post("/v2/reservations", json={"cart_id": cart_id},
                              headers={"X-CSRF-Token": self.csrf},
                              name="POST /v2/reservations", catch_response=True,
                              allow_redirects=False) as r:
            if r.status_code == 401:
                if self._handle_401(r, cart_id):
                    with self.client.post("/v2/reservations", json={"cart_id": cart_id},
                                          headers={"X-CSRF-Token": self.csrf},
                                          name="POST /v2/reservations", catch_response=True,
                                          allow_redirects=False) as r2:
                        if r2.status_code >= 400:
                            r2.failure("reservation retry status %s" % r2.status_code)
                            return None
                        try:
                            data = r2.json()
                        except Exception:
                            r2.failure("reservation retry not json")
                            return None
                        if data.get("csrf"):
                            self.csrf = data["csrf"]
                        return data.get("status_url")
                r.failure("reservation 401 unrecoverable")
                return None
            if r.status_code >= 400:
                r.failure("reservation status %s" % r.status_code)
                return None
            try:
                data = r.json()
            except Exception:
                r.failure("reservation not json")
                return None
            if data.get("csrf"):
                self.csrf = data["csrf"]
            return data.get("status_url")

    def _poll_reservation(self, status_url):
        for i in range(5):
            time.sleep(0.06)
            with self.client.get(status_url, name="GET reservation status",
                                 catch_response=True, allow_redirects=False) as r:
                if r.status_code >= 400:
                    r.failure("reservation status %s" % r.status_code)
                    return None
                try:
                    data = r.json()
                except Exception:
                    r.failure("reservation status not json")
                    return None
            status = data.get("status")
            if status == "ready":
                return data.get("reservation_id")
            if status in ("pending",):
                continue
            return None
        return None

    def _checkout(self, cart_id, reservation_id):
        idem = str(uuid.uuid4())
        headers = {"X-CSRF-Token": self.csrf, "Idempotency-Key": idem}
        payload = {"cart_id": cart_id}
        if reservation_id:
            payload["reservation_id"] = reservation_id
        with self.client.post("/v2/orders", json=payload, headers=headers,
                              name="POST /v2/orders", catch_response=True,
                              allow_redirects=False) as r:
            if r.status_code == 401:
                if self._handle_401(r, cart_id):
                    with self.client.post("/v2/orders", json=payload, headers=headers,
                                          name="POST /v2/orders", catch_response=True,
                                          allow_redirects=False) as r2:
                        return self._checkout_result(r2)
                r.failure("order 401 unrecoverable")
                return False
            return self._checkout_result(r)

    def _checkout_result(self, r):
        if r.status_code >= 400:
            r.failure("order status %s" % r.status_code)
            return False
        try:
            data = r.json()
        except Exception:
            r.failure("order not json")
            return False
        if data.get("csrf"):
            self.csrf = data["csrf"]
        if r.status_code == 200 and data.get("accepted") is False:
            r.failure("order accepted:false")
            return False
        if data.get("accepted") is True:
            return True
        r.failure("order unexpected body")
        return False

    def _do_work(self):
        # raw /v2/work with scheduled 429 handling
        attempts = 0
        while attempts <= 4:
            attempts += 1
            with self.client.post("/v2/work", json={},
                                  headers={"X-CSRF-Token": self.csrf},
                                  name="POST /v2/work", catch_response=True,
                                  allow_redirects=False) as r:
                if r.status_code == 429:
                    ra = r.headers.get("Retry-After")
                    try:
                        delay = float(ra) if ra else 1.0
                    except Exception:
                        delay = 1.0
                    r.success()
                    if attempts > 4:
                        return False
                    time.sleep(max(delay, 0.05))
                    continue
                if r.status_code == 401:
                    if self._handle_401(r):
                        continue
                    r.failure("work 401 unrecoverable")
                    return False
                if r.status_code >= 500:
                    r.failure("work status %s" % r.status_code)
                    return False
                if r.status_code >= 400:
                    r.failure("work status %s" % r.status_code)
                    return False
                try:
                    data = r.json()
                except Exception:
                    r.failure("work not json")
                    return False
                if data.get("ok") is True:
                    return True
                r.failure("work ok!=true")
                return False
        return False

    # ---------- journey ----------
    @task
    def journey(self):
        if self.iterations_done >= self.max_iterations:
            raise StopUser()
        if not self.session_ready:
            if not self._login():
                raise StopUser()

        # fresh login/cart each journey
        if not self._login():
            raise StopUser()

        prod = self._get_catalog_product()
        if not prod:
            self.iterations_done += 1
            if self.iterations_done >= self.max_iterations:
                raise StopUser()
            return
        product_id, variant_id = prod

        grant_id = self._solve_challenge()
        cart_id = self._create_cart(product_id, variant_id, grant_id)
        if not cart_id:
            self.iterations_done += 1
            if self.iterations_done >= self.max_iterations:
                raise StopUser()
            return

        if not self._patch_cart(cart_id, random.randint(1, 5)):
            self.iterations_done += 1
            if self.iterations_done >= self.max_iterations:
                raise StopUser()
            return

        status_url = self._reserve(cart_id)
        reservation_id = None
        if status_url:
            reservation_id = self._poll_reservation(status_url)

        if reservation_id:
            self._checkout(cart_id, reservation_id)

        # the pool operation
        self._do_work()

        self.iterations_done += 1
        if self.iterations_done >= self.max_iterations:
            raise StopUser()


class LoadTestShape:
    def __init__(self):
        self.start_time = None
        self.t0 = None
        self.phase = 0

    def tick(self):
        now = time.time()
        if self.start_time is None:
            self.start_time = now
        elapsed = now - self.start_time

        # warmup 5s, then 3x10s plateaus at 5/15/5, then drain <=5s
        if elapsed < 5:
            return (2, 1)
        if elapsed < 15:
            return (5, 1)
        if elapsed < 25:
            return (15, 1)
        if elapsed < 35:
            return (5, 1)
        if elapsed < 40:
            return (1, 1)
        return None
