            String loc = session.getString("loginLoc");
            if (loc != null) {
                return session.set("loginLoc", loc);
            }
            return session;
        }).doIf(session -> session.getString("loginLoc") != null).then(
                http("login-follow")
                        .get(session -> session.getString("loginLoc"))
                        .check(status().is(200))
                        .check(jsonPath("$.csrf").saveAs("csrfNew").optional())
        ).exec(session -> {
            String c = session.getString("csrfNew");
            if (c != null) session = session.set("csrf", c);
            return session;
        });
    }

    static ChainBuilder renewFlow() {
        return exec(
                http(RENEW)
                        .post("/v2/session/renew")
                        .header("X-CSRF-Token", session -> session.getString("csrf"))
                        .body(StringBody("{}"))
                        .check(status().in(200, 401))
                        .check(jsonPath("$.csrf").saveAs("csrfNew").optional())
        ).exec(session -> {
            String c = session.getString("csrfNew");
            if (c != null) session = session.set("csrf", c);
            return session;
        });
    }

    static ChainBuilder recoverFlow() {
        return exec(
                http(RECOVER)
                        .post(session -> "/v2/carts/" + session.getString("cartId") + "/recover")
                        .header("X-CSRF-Token", session -> session.getString("csrf"))
                        .body(StringBody("{}"))
                        .check(status().in(200, 201, 204, 401))
                        .check(jsonPath("$.csrf").saveAs("csrfNew").optional())
        ).exec(session -> {
            String c = session.getString("csrfNew");
            if (c != null) session = session.set("csrf", c);
            return session;
        });
    }

    static ChainBuilder catalogFlow() {
        return exec(
                http(CATALOG)
                        .get("/v2/catalog")
                        .check(status().is(200))
                        .check(jsonPath("$.data.products[0].id").saveAs("productId"))
                        .check(jsonPath("$.data.products[0].variants[0].id").saveAs("variantId"))
        );
    }

    static ChainBuilder challengeFlow() {
        return exec(
                http(CHALLENGE_FORM)
                        .get("/v2/challenge-form")
                        .check(status().is(200))
                        .check(regex("action=\"(/v2/challenges/[^\"]+)\"").saveAs("challengeAction"))
                        .check(css("input[name=challenge]", "value").saveAs("challengeVal"))
        ).exec(
                http(CHALLENGE_POST)
                        .post(session -> session.getString("challengeAction"))
                        .header("X-CSRF-Token", session -> session.getString("csrf"))
                        .body(StringBody(s -> "{\"challenge\":\"" + s.getString("challengeVal") + "\"}"))
                        .check(status().in(200, 302))
                        .check(header("Location").saveAs("challengeLoc"))
        ).exec(
                http(CHALLENGE_FOLLOW)
                        .get(session -> session.getString("challengeLoc"))
                        .check(status().is(200))
                        .check(jsonPath("$.grant_id").saveAs("grantId"))
                        .check(jsonPath("$.csrf").saveAs("csrfNew").optional())
        ).exec(session -> {
            String c = session.getString("csrfNew");
            if (c != null) session = session.set("csrf", c);
            return session;
        });
    }

    static ChainBuilder cartCreateFlow() {
        return exec(
                http(CART_CREATE)
                        .post("/v2/carts")
                        .header("X-CSRF-Token", session -> session.getString("csrf"))
                        .body(StringBody(s -> {
                            String g = s.getString("grantId");
                            String base = "{\"product_id\":\"" + s.getString("productId") + "\",\"variant_id\":\"" + s.getString("variantId") + "\"";
                            if (g != null) base += ",\"grant_id\":\"" + g + "\"";
                            return base + "}";
                        }))
                        .check(status().is(201))
                        .check(jsonPath("$.id").saveAs("cartId"))
                        .check(jsonPath("$.csrf").saveAs("csrfNew").optional())
                        .check(header("ETag").saveAs("etag"))
        ).exec(session -> {
            String c = session.getString("csrfNew");
            if (c != null) session = session.set("csrf", c);
            return session.set("idemKey", UUID.randomUUID().toString());
        });
    }

    static ChainBuilder cartPatchFlow() {
        return exec(
                http(CART_GET)
                        .get(session -> "/v2/carts/" + session.getString("cartId"))
                        .check(status().is(200))
                        .check(header("ETag").saveAs("etag"))
        ).exec(
                http(CART_PATCH)
                        .patch(session -> "/v2/carts/" + session.getString("cartId"))
                        .header("X-CSRF-Token", session -> session.getString("csrf"))
                        .header("If-Match", session -> session.getString("etag"))
                        .body(StringBody("{\"quantity\":1}"))
                        .check(status().in(200, 412))
                        .check(jsonPath("$.csrf").saveAs("csrfNew").optional())
        ).exec(session -> {
            String c = session.getString("csrfNew");
            if (c != null) session = session.set("csrf", c);
            return session;
        });
    }

    static ChainBuilder reserveFlow() {
        return exec(
                http(RESERVE)
                        .post("/v2/reservations")
                        .header("X-CSRF-Token", session -> session.getString("csrf"))
                        .body(StringBody(s -> "{\"cart_id\":\"" + s.getString("cartId") + "\"}"))
                        .check(status().is(202))
                        .check(jsonPath("$.status_url").saveAs("statusUrl"))
                        .check(jsonPath("$.csrf").saveAs("csrfNew").optional())
        ).exec(session -> {
            String c = session.getString("csrfNew");
            if (c != null) session = session.set("csrf", c);
            return session;
        }).asLongAs(session -> session.getString("reservationId") == null, "poll").on(
                pause(Duration.ofMillis(60)).exec(
                        http(RESERVE_POLL)
                                .get(session -> session.getString("statusUrl"))
                                .check(status().is(200))
                                .check(jsonPath("$.status").saveAs("resStatus"))
                                .check(jsonPath("$.reservation_id").saveAs("reservationId").optional())
                )
        );
    }

    static ChainBuilder orderFlow() {
        return exec(
                http(ORDER)
                        .post("/v2/orders")
                        .header("X-CSRF-Token", session -> session.getString("csrf"))
                        .header("Idempotency-Key", session -> session.getString("idemKey"))
                        .header("If-Match", session -> session.getString("etag"))
                        .body(StringBody(s -> {
                            String r = s.getString("reservationId");
                            String base = "{\"cart_id\":\"" + s.getString("cartId") + "\"";
                            if (r != null) base += ",\"reservation_id\":\"" + r + "\"";
                            return base + "}";
                        }))
                        .check(status().is(201))
                        .check(jsonPath("$.accepted").is("true"))
                        .check(jsonPath("$.csrf").saveAs("csrfNew").optional())
        ).exec(session -> {
            String c = session.getString("csrfNew");
            if (c != null) session = session.set("csrf", c);
            return session;
        });
    }

    static ChainBuilder workFlow() {
        return exec(session -> {
            WORK_STARTS.incrementAndGet();
            return session;
        }).exec(
                http(WORK)
                        .post("/v2/work")
                        .header("X-CSRF-Token", session -> session.getString("csrf"))
                        .body(StringBody("{}"))
                        .check(status().in(200, 429))
                        .check(jsonPath("$.ok").is("true").optional())
                        .check(header("Retry-After").saveAs("retryAfter").optional())
        ).exec(session -> {
            Integer st = session.getInt("status");
            return session;
        });
    }

    static ChainBuilder workWithRetry() {
        return asLongAs(session -> {
            Integer code = session.getInt("workStatus");
            return code != null && code == 429 && session.getInt("workRetries") < 4;
        }, "retry429").on(
                pause(Duration.ofSeconds(1)).exec(
                        http(WORK + "-retry")
                                .post("/v2/work")
                                .header("X-CSRF-Token", session -> session.getString("csrf"))
                                .body(StringBody("{}"))
                                .check(status().in(200, 429))
                                .check(jsonPath("$.ok").is("true").optional())
                                .check(header("Retry-After").saveAs("retryAfter").optional())
                ).exec(session -> {
                    Integer r = session.getInt("workRetries");
                    return session.set("workRetries", r == null ? 1 : r + 1);
                })
        );
    }

    static ChainBuilder fullJourney() {
        return exec(session -> session.set("workRetries", 0))
                .exec(loginFlow())
                .exec(catalogFlow())
                .exec(challengeFlow())
                .exec(cartCreateFlow())
                .exec(cartPatchFlow())
                .exec(reserveFlow())
                .exec(orderFlow())
                .exec(workFlow())
                .exec(workWithRetry());
    }

    static final ScenarioBuilder SCENARIO = scenario("ModelSimulation")
            .exec(fullJourney());

    {
        setUp(
                SCENARIO.injectOpen(
                        constantUsersPerSec(TARGET_RATE).during(Duration.ofSeconds(40))
                ).protocols(HTTP)
        ).maxDuration(Duration.ofSeconds(60));
    }
}
