```javascript
import http from 'k6/http';
import { check, sleep } from 'k6';
import { Counter, Rate, Trend } from 'k6/metrics';
import { randomIntBetween } from 'https://jslib.k6.io/k6-utils/1.4.0/index.js';

const BASE = __ENV.BASE_URL || 'http://127.0.0.1:8000';

const workOk = new Counter('work_ok');
const workScheduled = new Counter('work_scheduled');
const workUnexpected = new Counter('work_unexpected');
const workExpiry = new Counter('work_expiry');
const businessFailure = new Rate('business_failure');
const workLatency = new Trend('work_latency', true);

const TARGET_RATE = 10;
const WARMUP = 5;
const SCORE_START = 5;
const SCORE_END = 35;
const DRAIN = 5;
const TOTAL = SCORE_END + DRAIN;

export const options = {
  scenarios: {
    work: {
      executor: 'constant-arrival-rate',
      rate: TARGET_RATE,
      timeUnit: '1s',
      duration: `${TOTAL}s`,
      preAllocatedVUs: 8,
      maxVUs: 32,
      gracefulStop: '5s',
    },
  },
  thresholds: {
    business_failure: ['rate<0.01'],
  },
  discardResponseBodies: false,
  summaryTrendStats: ['avg', 'min', 'med', 'max', 'p(95)'],
};

function parseCsrf(html) {
  if (!html) return null;
  const re = /<input[^>]*name=["']?csrf["']?[^>]*>/gi;
  let m;
  while ((m = re.exec(html)) !== null) {
    const tag = m[0];
    const vm = tag.match(/value=["']([^"']*)["']/i);
    if (vm) return vm[1];
  }
  const re2 = /<input[^>]*value=["']([^"']*)["'][^>]*name=["']?csrf["']?/gi;
  while ((m = re2.exec(html)) !== null) {
    return m[1];
  }
  return null;
}

function parseChallenge(html) {
  if (!html) return null;
  const re = /<form[^>]*action=["']([^"']*\/v2\/challenges\/[^"']*)["'][^>]*>/i;
  const m = html.match(re);
  if (!m) return null;
  const action = m[1];
  const re2 = /<input[^>]*name=["']?challenge["']?[^>]*>/i;
  const m2 = html.match(re2);
  let value = null;
  if (m2) {
    const vm = m2[0].match(/value=["']([^"']*)["']/i);
    if (vm) value = vm[1];
  }
  return { action, value };
}

function jarFor(user) {
  return http.cookieJar();
}

function login(user) {
  const jar = http.cookieJar();
  const formRes = http.get(`${BASE}/v2/login-form`, { jar, redirects: 0 });
  if (formRes.status !== 200) return null;
  const csrf = parseCsrf(formRes.body);
  if (!csrf) return null;
  const loginRes = http.post(
    `${BASE}/v2/login`,
    JSON.stringify({ username: user, password: 'bench', csrf }),
    { jar, redirects: 0, headers: { 'Content-Type': 'application/json' } }
  );
  let body = null;
  try { body = loginRes.json(); } catch (e) { body = null; }
  if (loginRes.status === 302) {
    const loc = loginRes.headers['Location'];
    if (loc) {
      const follow = http.get(loc.startsWith('http') ? loc : `${BASE}${loc}`, { jar, redirects: 0 });
      try { body = follow.json(); } catch (e) { body = null; }
    }
  }
  if (!body || !body.csrf) return null;
  return { jar, csrf: body.csrf, user };
}

function renew(session) {
  const res = http.post(
    `${BASE}/v2/session/renew`,
    JSON.stringify({}),
    { jar: session.jar, redirects: 0, headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': session.csrf } }
  );
  let body = null;
  try { body = res.json(); } catch (e) { body = null; }
  if (res.status === 200 && body && body.csrf) {
    session.csrf = body.csrf;
    return true;
  }
  return false;
}

function doWork(session) {
  const headers = { 'Content-Type': 'application/json', 'X-CSRF-Token': session.csrf };
  let res = http.post(`${BASE}/v2/work`, JSON.stringify({}), { jar: session.jar, redirects: 0, headers, tags: { op: 'work' } });
  let retries = 0;
  while (res.status === 429 && retries < 4) {
    const ra = parseInt(res.headers['Retry-After'] || '1', 10);
    sleep(Math.max(ra, 1));
    res = http.post(`${BASE}/v2/work`, JSON.stringify({}), { jar: session.jar, redirects: 0, headers, tags: { op: 'work' } });
    retries++;
  }
  if (res.status === 401) {
    let body = null;
    try { body = res.json(); } catch (e) { body = null; }
    if (body && body.error === 'expired') {
      workExpiry.add(1);
      businessFailure.add(false);
      if (renew(session)) {
        const h2 = { 'Content-Type': 'application/json', 'X-CSRF-Token': session.csrf };
        res = http.post(`${BASE}/v2/work`, JSON.stringify({}), { jar: session.jar, redirects: 0, headers: h2, tags: { op: 'work' } });
      }
    } else {
      businessFailure.add(true);
      workUnexpected.add(1);
      return;
    }
  }
  if (res.status === 429) {
    workScheduled.add(1);
    businessFailure.add(false);
    return;
  }
  if (res.status >= 400) {
    workUnexpected.add(1);
    businessFailure.add(true);
    return;
  }
  let body = null;
  try { body = res.json(); } catch (e) { body = null; }
  if (res.status === 200 && body && body.ok === true) {
    workOk.add(1);
    businessFailure.add(false);
    workLatency.add(res.timings.duration);
  } else {
    workUnexpected.add(1);
    businessFailure.add(true);
  }
}

export default function () {
  const user = `bench-${randomIntBetween(1, 16)}`;
  const session = login(user);
  if (!session) {
    sleep(0.1);
    return;
  }
  doWork(session);
}
