```python
import os
import re
import time
import uuid
import random
from urllib.parse import urljoin

from locust import HttpUser, task, between, events
from locust.exception import StopUser


BASE_URL = os.environ.get("BASE_URL", "http://127.0.0.1:8000")
PASSWORD = "bench"
USERS = [f"bench-{i}" for i in range(1, 17)] + ["bench"]

# Global shape state
_STATE = {
    "t0": None,
    "started": False,
}


def _now():
    return time.time()


def _parse_csrf(html):
    # input[name=csrf] with mixed attribute variants / decoys
    if not html:
        return None
    # find input tags
    for m in re.finditer(r"<input\b[^>]*>", html, re.IGNORECASE):
        tag = m.group(0)
        if re.search(r"""name\s*=\s*["']?csrf["']?""", tag, re.IGNORECASE):
            vm = re.search(r"""value\s*=\s*["']([^"']*)["']""", tag, re.IGNORECASE)
            if vm:
                return vm.group(1)
    return None


def _parse_challenge_form(html):
    if not html:
        return None, None
    action = None
    for m in re.finditer(r"<form\b[^>]*>", html, re.IGNORECASE):
        tag = m.group(0)
        am = re.search(r"""action\s*=\s*["']([^"']*)["']""", tag, re.IGNORECASE)
        if am and "/v2/challenges/" in am.group(1):
            action = am.group(1)
            break
    if action is None:
        am = re.search(r"""action\s*=\s*["']([^"']*/v2/challenges/[^"']*)["']""", html, re.IGNORECASE)
        if am:
            action = am.group(1)
    token = None
    for m in re.finditer(r"<input\b[^>]*>", html, re.IGNORECASE):
        tag = m.group(0)
        if re.search(r"""name\s*=\s*["']?challenge["']?""", tag, re.IGNORECASE):
            vm = re.search(r"""value\s*=\s*["']([^"']*)["']""", tag, re.IGNORECASE)
            if vm:
                token = vm.group(1)
                break
    return action, token


class ShopUser(HttpUser):
    host = BASE_URL
    wait_time = between(0.0, 0.0)

    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self.username = random.choice(USERS)
        self.csrf = None
        self.session_ok = False
        self.iterations_done = 0
        self.max_iterations = 2

    # ---------- helpers ----------
    def _req(self, method, path, name=None, **kwargs):
        kwargs.setdefault("allow_redirects", False)
        return self.client.request(method, path, name=name or path, **kwargs)

    def _login(self):
        # fresh login
        r = self._req("GET", "/v2/login-form", name="GET /v2/login-form")
        if r.status_code >= 400:
            return False
        csrf = _parse_csrf(r.text)
        if not csrf:
            return False
        r = self._req(
            "POST",
            "/v2/login",
            name="POST /v2/login",
            json={"username": self.username, "password": PASSWORD, "csrf": csrf},
        )
        if r.status_code == 302:
            loc = r.headers.get("Location")
            if loc:
                r2 = self._req("GET", loc, name="GET login redirect")
                if r2.status_code >= 400:
                    return False
                try:
                    data = r2.json()
                    if data.get("csrf"):
                        self.csrf = data["csrf"]
                except Exception:
                    pass
        if r.status_code >= 400:
            return False
        try:
            data = r.json()
        except Exception:
            data = {}
        if data.get("csrf"):
            self.csrf = data["csrf"]
        if not self.csrf:
            return False
        self.session_ok = True
        return True

    def _renew(self):
        if not self.csrf:
            return False
        r = self._req(
            "POST",
            "/v2/session/renew",
            name="POST /v2/session/renew",
            json={},
            headers={"X-CSRF-Token": self.csrf},
        )
        if r.status_code >= 400:
            return False
        try:
            data = r.json()
        except Exception:
            data = {}
        if data.get("csrf"):
            self.csrf = data["csrf"]
        return True

    def _recover_cart(self, cart_id):
        if not cart_id or not self.csrf:
            return
        self._req(
            "POST",
            f"/v2/carts/{cart_id}/recover",
            name="POST /v2/carts/{id}/recover",
            json={},
            headers={"X-CSRF-Token": self.csrf},
        )

    def _handle_401(self, r, cart_id=None):
        try:
            data = r.json()
        except Exception:
            data = {}
        err = data.get("error")
        if err == "expired":
            if self._renew():
                if cart_id:
                    self._recover_cart(cart_id)
                return True
            return False
        if err == "session":
            self.session_ok = False
            if self._login():
                if cart_id:
                    self._recover_cart(cart_id)
                return True
            return False
        # denied or other -> not recoverable
        return False

    def _get_catalog(self):
        r = self._req("GET", "/v2/catalog", name="GET /v2/catalog")
        if r.status_code >= 400:
            return None
        try:
            data = r.json()
        except Exception:
            return None
        products = (data.get("data") or {}).get("products") or []
        if not products:
            return None
        return products

    def _get_catalog_page(self):
        r = self._req("GET", "/v2/catalog/page", name="GET /v2/catalog/page")
        if r.status_code >= 400:
            return None
        try:
            data = r.json()
        except Exception:
            return None
        return data

    def _pick_variant(self, products):
        for p in products:
            variants = p.get("variants") or []
            for v in variants:
                if v.get("in_stock"):
                    return p.get("id"), v.get("id")
        return None, None

    def _solve_challenge(self):
        r = self._req("GET", "/v2/challenge-form", name="GET /v2/challenge-form")
        if r.status_code >= 400:
            return None
        action, token = _parse_challenge_form(r.text)
        if not action or not token:
            return None
        if not self.csrf:
            return None
        r = self._req(
            "POST",
            action,
            name="POST /v2/challenges/{id}",
            json={"challenge": token},
            headers={"X-CSRF-Token": self.csrf},
        )
        if r.status_code == 302:
            loc = r.headers.get("Location")
            if loc:
                r2 = self._req("GET", loc, name="GET challenge redirect")
                if r2.status_code < 400:
                    try:
                        data = r2.json()
                    except Exception:
                        data = {}
                    if data.get("csrf"):
                        self.csrf = data["csrf"]
                    return data.get("grant_id")
        return None

    def _create_cart(self, product_id, variant_id, grant_id=None):
        payload = {"product_id": product_id, "variant_id": variant_id}
        if grant_id:
            payload["grant_id"] = grant_id
        r = self._req(
            "POST",
            "/v2/carts",
            name="POST /v2/carts",
            json=payload,
            headers={"X-CSRF-Token": self.csrf},
        )
        if r.status_code == 401:
            if self._handle_401(r):
                r = self._req(
                    "POST",
                    "/v2/carts",
                    name="POST /v2/carts",
                    json=payload,
                    headers={"X-CSRF-Token": self.csrf},
                )
        if r.status_code != 201:
            return None, None
        try:
            data = r.json()
        except Exception:
            return None, None
        if data.get("csrf"):
            self.csrf = data["csrf"]
        return data.get("id"), r.headers.get("ETag")

    def _patch_cart(self, cart_id, etag):
        payload = {"quantity": random.randint(1, 20)}
        headers = {"X-CSRF-Token": self.csrf, "Content-Type": "application/json"}
        if etag:
            headers["If-Match"] = etag
        r = self._req(
            "PATCH",
            f"/v2/carts/{cart_id}",
            name="PATCH /v2/carts/{id}",
            json=payload,
            headers=headers,
        )
        if r.status_code == 401:
            if self._handle_401(r, cart_id):
                r = self._req(
                    "PATCH",
                    f"/v2/carts/{cart_id}",
                    name="PATCH /v2/carts/{id}",
                    json=payload,
                    headers=headers,
                )
        if r.status_code == 412:
            # re-read and retry once
            r2 = self._req("GET", f"/v2/carts/{cart_id}", name="GET /v2/carts/{id}")
            if r2.status_code < 400:
                new_etag = r2.headers.get("ETag")
                if new_etag:
                    headers["If-Match"] = new_etag
                r = self._req(
                    "PATCH",
                    f"/v2/carts/{cart_id}",
                    name="PATCH /v2/carts/{id}",
                    json=payload,
                    headers=headers,
                )
        return r

    def _reserve(self, cart_id):
        r = self._req(
            "POST",
            "/v2/reservations",
            name="POST /v2/reservations",
            json={"cart_id": cart_id},
            headers={"X-CSRF-Token": self.csrf},
        )
        if r.status_code == 401:
            if self._handle_401(r, cart_id):
                r = self._req(
                    "POST",
                    "/v2/reservations",
                    name="POST /v2/reservations",
                    json={"cart_id": cart_id},
                    headers={"X-CSRF-Token": self.csrf},
                )
        if r.status_code != 202:
            return None
        try:
            data = r.json()
        except Exception:
            return None
        if data.get("csrf"):
            self.csrf = data["csrf"]
        status_url = data.get("status_url")
        if not status_url:
            return None
        for _ in range(5):
            time.sleep(0.06)
            r = self._req("GET", status_url, name="GET reservation status")
            if r.status_code >= 400:
                return None
            try:
                sdata = r.json()
            except Exception:
                return None
            if sdata.get("csrf"):
                self.csrf = sdata["csrf"]
            status = sdata.get("status")
            if status == "ready":
                return sdata.get("reservation_id")
            if status in ("pending",):
                continue
            return None
        return None

    def _order(self, cart_id, reservation_id, etag):
        idem = str(uuid.uuid4())
        payload = {"cart_id": cart_id}
        if reservation_id:
            payload["reservation_id"] = reservation_id
        headers = {"X-CSRF-Token": self.csrf, "Idempotency-Key": idem}
        if etag:
            headers["If-Match"] = etag
        r = self._req(
            "POST",
            "/v2/orders",
            name="POST /v2/orders",
            json=payload,
            headers=headers,
        )
        if r.status_code == 401:
            if self._handle_401(r, cart_id):
                r = self._req(
                    "POST",
                    "/v2/orders",
                    name="POST /v2/orders",
                    json=payload,
                    headers=headers,
                )
        if r.status_code != 201:
            return False
        try:
            data = r.json()
        except Exception:
            return False
        if data.get("csrf"):
            self.csrf = data["csrf"]
        return bool(data.get("accepted"))

    def _do_work(self):
        # POST /v2/work is the operation
        retries = 0
        while True:
            with self.client.post(
                "/v2/work",
                name="POST /v2/work",
                json={},
                headers={"X-CSRF-Token": self.csrf} if self.csrf else {},
                catch_response=True,
                allow_redirects=False,
            ) as resp:
                if resp.status_code == 401:
                    if self._handle_401(resp):
                        resp.success()
                        retries += 1
                        if retries > 4:
                            return
                        continue
                    resp.failure("401 unrecoverable")
                    return
                if resp.status_code == 429:
                    ra = resp.headers.get("Retry-After", "1")
                    try:
                        delay = float(ra)
                    except Exception:
                        delay = 1.0
                    resp.success()
                    retries += 1
                    if retries > 4:
                        return
                    time.sleep(delay)
                    continue
                if resp.status_code >= 500:
                    resp.failure(f"unexpected {resp.status_code}")
                    return
                if resp.status_code >= 400:
                    resp.failure(f"status {resp.status_code}")
                    return
                try:
                    data = resp.json()
                except Exception:
                    resp.failure("bad json")
                    return
                if not data.get("ok"):
                    resp.failure("ok false")
                    return
                resp.success()
                return

    # ---------- journey ----------
    @task
    def journey(self):
        if self.iterations_done >= self.max_iterations:
            raise StopUser()
        self.iterations_done += 1

        if not self.session_ok:
            if not self._login():
                raise StopUser()

        products = self._get_catalog()
        if not products:
            page = self._get_catalog_page()
            if page:
                p = page.get("product")
                if p:
                    products = [p]
        if not products:
            raise StopUser()

        product_id, variant_id = self._pick_variant(products)
        if not product_id or not variant_id:
            raise StopUser()

        grant_id = self._solve_challenge()
        cart_id, etag = self._create_cart(product_id, variant_id, grant_id)
        if not cart_id:
            raise StopUser()

        self._patch_cart(cart_id, etag)

        reservation_id = self._reserve(cart_id)
        if not reservation_id:
            raise StopUser()

        # refresh etag
        r = self._req("GET", f"/v2/carts/{cart_id}", name="GET /v2/carts/{id}")
        if r.status_code < 400:
            etag = r.headers.get("ETag", etag)

        if not self._order(cart_id, reservation_id, etag):
            raise StopUser()

        self._do_work()

        if self.iterations_done >= self.max_iterations:
            raise StopUser()


class LoadTestShape:
    def tick(self):
        now = _now()
        if not _STATE["started"]:
            _STATE["started"] = True
            _STATE["t0"] = now
        t0 = _STATE["t0"]
        elapsed = now - t0

        # warmup 5s, score [5,35), drain <=5s
        if elapsed < 5:
            return (2, 1)
        if elapsed < 35:
            # phased targets 5/15/5 over three 10s plateaus
            phase = int((elapsed - 5) // 10)
            if phase == 0:
                return (5, 1)
            elif phase == 1:
                return (15, 1)
            else:
                return (5, 1)
        if elapsed < 40:
            return (2, 1)
        return None
