                                .compile("\"accepted\"\\s*:\\s*true").matcher(body);
                        if (am.find()) committed = true;
                        java.util.regex.Matcher cm = java.util.regex.Pattern
                                .compile("\"csrf\"\\s*:\\s*\"([^\"]+)\"").matcher(body);
                        if (cm.find()) csrf = cm.group(1);
                    }
                    return session.set("csrf", csrf).set("orderCommitted", committed);
                });
    }

    static ChainBuilder checkoutJourney() {
        return exec(session -> session.set("username", USERS[ThreadLocalRandom.current().nextInt(USERS.length)]))
                .exec(login())
                .exec(catalogSelect())
                .exec(challenge())
                .exec(createCart())
                .exec(patchCart())
                .exec(reservation())
                .exec(pollReservation())
                .exec(checkoutOrder());
    }

    // ---------- scenarios ----------

    ScenarioBuilder browseScenario = scenario("browse")
            .exec(browseJourney());

    ScenarioBuilder checkoutScenario = scenario("checkout")
            .exec(checkoutJourney());

    {
        setUp(
                browseScenario.injectOpen(
                        constantUsersPerSec(8).during(Duration.ofSeconds(40))
                ),
                checkoutScenario.injectOpen(
                        constantUsersPerSec(2).during(Duration.ofSeconds(40))
                )
        ).protocols(httpProtocol)
                .maxDuration(Duration.ofSeconds(60));
    }
}
