import { Counter, Rate, Trend } from 'k6/metrics';
import encoding from 'k6/encoding';

const BASE = __ENV.BASE_URL || 'http://127.0.0.1:8000';

// ---- metrics ----
const browseStarts = new Counter('browse_starts');
const checkoutStarts = new Counter('checkout_starts');
const browseErrors = new Counter('browse_errors');
const checkoutErrors = new Counter('checkout_errors');
const unexpected = new Counter('unexpected_failures');
const businessResponses = new Counter('business_responses');
const businessFailureRate = new Rate('business_failure');
const checkoutLatency = new Trend('checkout_latency');
const browseLatency = new Trend('browse_latency');
const cartCorrect = new Counter('cart_correct');
const cartIncorrect = new Counter('cart_incorrect');

// ---- config ----
const BROWSE_RATE = 8;
const CHECKOUT_RATE = 2;
const WARMUP = 5;
const SCORE_START = 5;
const SCORE_END = 35;
const DRAIN = 5;
const TOTAL = SCORE_END + DRAIN; // 40s

export const options = {
  scenarios: {
    browse: {
      executor: 'constant-arrival-rate',
      exec: 'browseFlow',
      rate: BROWSE_RATE,
      timeUnit: '1s',
      duration: `${TOTAL}s`,
      preAllocatedVUs: 8,
      maxVUs: 32,
      startTime: '0s',
    },
    checkout: {
      executor: 'constant-arrival-rate',
      exec: 'checkoutFlow',
      rate: CHECKOUT_RATE,
      timeUnit: '1s',
      duration: `${TOTAL}s`,
      preAllocatedVUs: 4,
      maxVUs: 32,
      startTime: '0s',
    },
  },
  discardResponseBodies: false,
  noConnectionReuse: false,
  thresholds: {
    business_failure: ['rate<0.01'],
  },
};

// ---- helpers ----
function parseCsrf(html) {
  // find input[name=csrf] value, tolerate attribute variants
  const re = /<input[^>]*name\s*=\s*["']?csrf["']?[^>]*>/gi;
  let m;
  while ((m = re.exec(html)) !== null) {
    const tag = m[0];
    const vm = /value\s*=\s*["']([^"']*)["']/i.exec(tag);
    if (vm) return vm[1];
  }
  // fallback: value before name
  const re2 = /<input[^>]*value\s*=\s*["']([^"']*)["'][^>]*name\s*=\s*["']?csrf["']?/gi;
  const m2 = re2.exec(html);
  if (m2) return m2[1];
  return null;
