function solveChallenge(session) {
  const formRes = http.get(`${BASE}/v2/challenge-form`, { redirects: 0, tags: { name: 'challenge-form' } });
  if (formRes.status >= 400) return null;
  const actionMatch = /action\s*=\s*["']([^"']+)["']/i.exec(formRes.body);
  const challengeMatch = /name\s*=\s*["']?challenge["']?[^>]*value\s*=\s*["']([^"']*)["']/i.exec(formRes.body)
    || /value\s*=\s*["']([^"']*)["'][^>]*name\s*=\s*["']?challenge["']?/i.exec(formRes.body);
  if (!actionMatch || !challengeMatch) return null;
  const action = actionMatch[1];
  const challenge = challengeMatch[1];
  const postRes = http.post(action.startsWith('http') ? action : `${BASE}${action}`, JSON.stringify({ challenge }), {
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': session.csrf },
    redirects: 0,
    tags: { name: 'challenge-post' },
  });
  if (postRes.status === 302) {
    const loc = postRes.headers['Location'];
    if (loc) {
      const follow = http.get(loc.startsWith('http') ? loc : `${BASE}${loc}`, { redirects: 0, tags: { name: 'challenge-redirect' } });
      if (follow.status >= 400) return null;
      try {
        const b = JSON.parse(follow.body);
        if (b && b.csrf) session.csrf = b.csrf;
        return b && b.grant_id ? b.grant_id : null;
      } catch (e) { return null; }
    }
  }
  return null;
}

function createCart(session, product, grantId) {
  const payload = { product_id: product.product_id, variant_id: product.variant_id };
  if (grantId) payload.grant_id = grantId;
  const res = http.post(`${BASE}/v2/carts`, JSON.stringify(payload), {
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': session.csrf },
    redirects: 0,
    tags: { name: 'cart-create' },
  });
  if (isExpired(res)) {
    if (!renew(session)) return null;
    return createCart(session, product, grantId);
  }
  if (res.status >= 400) return null;
  let body = null;
  try { body = JSON.parse(res.body); } catch (e) { return null; }
  if (body && body.csrf) session.csrf = body.csrf;
  const etag = res.headers['ETag'] || res.headers['Etag'];
  return { id: body.id, etag };
}

function patchCart(session, cartId, etag, quantity, retried) {
