    const getRes = http.get(`${BASE}/v2/carts/${cartId}`, { redirects: 0, tags: { name: 'cart-get' } });
    if (getRes.status >= 400) return null;
    const newEtag = getRes.headers['ETag'] || getRes.headers['Etag'];
    return patchCart(session, cartId, newEtag, quantity, true);
  }
