  let body = null;
  try { body = JSON.parse(res.body); } catch (e) { body = null; }
  if (body && body.csrf) session.csrf = body.csrf;
  const newEtag = res.headers['ETag'] || res.headers['Etag'];
  return { etag: newEtag || etag };
}

function reserve(session, cartId) {
  const res = http.post(`${BASE}/v2/reservations`, JSON.stringify({ cart_id: cartId }), {
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': session.csrf },
    redirects: 0,
    tags: { name: 'reservation' },
  });
  if (isExpired(res)) {
    if (!renew(session)) return null;
    if (!recoverCart(session, cartId)) return null;
    return reserve(session, cartId);
  }
  if (res.status >= 400) return null;
  let body = null;
  try { body = JSON.parse(res.body); } catch (e) { return null; }
  if (body && body.csrf) session.csrf = body.csrf;
  const statusUrl = body.status_url;
  if (!statusUrl) return null;
  for (let i = 0; i < 5; i++) {
    sleep(0.06);
    const pollRes = http.get(statusUrl.startsWith('http') ? statusUrl : `${BASE}${statusUrl}`, { redirects: 0, tags: { name: 'reservation-poll' } });
    if (pollRes.status >= 400) return null;
    let pb = null;
    try { pb = JSON.parse(pollRes.body); } catch (e) { return null; }
    if (pb && pb.csrf) session.csrf = pb.csrf;
    if (pb && pb.status === 'ready') return pb.reservation_id || null;
    if (pb && (pb.status === 'failed')) return null;
  }
  return null;
}

function placeOrder(session, cartId, reservationId, idemKey, etag) {
  const payload = { cart_id: cartId };
  if (reservationId) payload.reservation_id = reservationId;
  const headers = {
    'Content-Type': 'application/json',
    'X-CSRF-Token': session.csrf,
    'Idempotency-Key': idemKey,
  };
  if (etag) headers['If-Match'] = etag;
  const res = http.post(`${BASE}/v2/orders`, JSON.stringify(payload), {
    headers,
    redirects: 0,
    tags: { name: 'order' },
  });
  if (isExpired(res)) {
    if (!renew(session)) return { ok: false, res };
    if (!recoverCart(session, cartId)) return { ok: false, res };
    return placeOrder(session, cartId, reservationId, idemKey, etag);
  }
  if (isRevoked(res)) {
    // fresh login
    const s2 = login(session.user);
    if (!s2) return { ok: false, res };
    session.csrf = s2.csrf;
    if (!recoverCart(session, cartId)) return { ok: false, res };
    return placeOrder(session, cartId, reservationId, idemKey, etag);
  }
  if (isDenied(res)) return { ok: false, res, denied: true };
  if (res.status >= 400) return { ok: false, res };
  let body = null;
  try { body = JSON.parse(res.body); } catch (e) { return { ok: false, res }; }
  if (body && body.csrf) session.csrf = body.csrf;
  if (body && body.accepted === true && body.id) return { ok: true, res, body };
  return { ok: false, res, body };
}

function doWork(session, path) {
  let retries = 0;
  while (retries <= 4) {
    const res = http.post(`${BASE}${path}`, '{}', {
      headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': session.csrf },
      redirects: 0,
      tags: { name: path },
    });
    businessResponses.add(1);
    if (res.status === 429) {
      const ra = res.headers['Retry-After'];
      const wait = ra ? parseFloat(ra) : 1;
      sleep(wait);
      retries++;
      continue;
    }
    if (isExpired(res)) {
      if (!renew(session)) { unexpected.add(1); businessFailure.add(1); return false; }
      retries++;
      continue;
    }
    if (res.status >= 400) {
      unexpected.add(1);
      businessFailure.add(1);
      return false;
    }
    businessFailure.add(0);
    return true;
  }
  unexpected.add(1);
  businessFailure.add(1);
  return false;
}

function pickUser() {
  const n = (__VU % 16) + 1;
  return `bench-${n}`;
}

// ---- scenarios ----
export function browseFlow() {
  const user = pickUser();
  const session = login(user);
  if (!session) { browseErrors.add(1); return; }
  const t0 = Date.now();
  const ok = doWork(session, '/v2/browse');
  if (ok) {
    browseStarts.add(1);
    browseLatency.add(Date.now() - t0);
  } else {
    browseErrors.add(1);
  }
}

export function checkoutFlow() {
  const user = pickUser();
  const session = login(user);
  if (!session) { checkoutErrors.add(1); return; }

  // catalog
  let catalog = fetchCatalog(session);
  let product = pickProduct(catalog);
  if (!product) {
    // try pages
    let next = catalog && catalog.next;
    let pages = 0;
    while (next && pages < 3) {
      const page = fetchCatalogPage(session, next);
      if (!page) break;
      if (page.data && page.data.products) {
        for (const p of page.data.products) {
          if (!p.variants) continue;
          for (const v of p.variants) {
            if (v.in_stock) { product = { product_id: p.id, variant_id: v.id }; break; }
          }
          if (product) break;
        }
      }
      if (product) break;
      next = page.next;
      pages++;
    }
  }
  if (!product) { checkoutErrors.add(1); return; }

  // challenge
  const grantId = solveChallenge(session);

  // cart
  const cart = createCart(session, product, grantId);
  if (!cart) { checkoutErrors.add(1); return; }

  const patched = patchCart(session, cart.id, cart.etag, 1, false);
  if (!patched) { checkoutErrors.add(1); return; }

  // verify cart
  const getRes = http.get(`${BASE}/v2/carts/${cart.id}`, { redirects: 0, tags: { name: 'cart-verify' } });
  if (getRes.status < 400) {
    try {
      const b = JSON.parse(getRes.body);
      if (b && (b.quantity === 1 || (b.items && b.items.length && b.items[0].quantity === 1))) {
        cartCorrect.add(1);
      } else {
        cartIncorrect.add(1);
      }
    } catch (e) { cartIncorrect.add(1); }
  }

  const reservationId = reserve(session, cart.id);
  if (!reservationId) { checkoutErrors.add(1); return; }

  const idemKey = `idem-${cart.id}-${Date.now()}`;
  const t0 = Date.now();
  const result = placeOrder(session, cart.id, reservationId, idemKey, patched.etag);
  checkoutLatency.add(Date.now() - t0);
  if (result.ok) {
    checkoutStarts.add(1);
  } else {
    checkoutErrors.add(1);
  }
}
