            r.failure("cart status %s" % r.status_code)
            return False
        r.success()
        try:
            data = r.json()
            self.cart_id = data.get("id")
            if data.get("csrf"):
                self.csrf = data["csrf"]
        except Exception:
            r.failure("cart json")
            return False
        self.cart_etag = r.headers.get("ETag")
        self.idem_key = "idem-%s-%s" % (self.username, self.cart_id)
        return bool(self.cart_id)

    def set_quantity(self, qty):
        if not self.cart_id:
            return False
        headers = {}
        if self.cart_etag:
            headers["If-Match"] = self.cart_etag
        r = self._patch("/v2/carts/%s" % self.cart_id,
                        json_body={"quantity": qty}, headers=headers,
                        name="/v2/carts/{id}")
        if r.status_code == 412:
            r.success()
            g = self._get("/v2/carts/%s" % self.cart_id,
                          name="/v2/carts/{id}")
            if g.status_code >= 400:
                g.failure("cart re-read %s" % g.status_code)
                return False
            g.success()
            self.cart_etag = g.headers.get("ETag")
            headers = {}
            if self.cart_etag:
                headers["If-Match"] = self.cart_etag
            r = self._patch("/v2/carts/%s" % self.cart_id,
                            json_body={"quantity": qty}, headers=headers,
                            name="/v2/carts/{id}")
        if r.status_code == 401 and self._handle_401(r):
            headers = {}
            if self.cart_etag:
                headers["If-Match"] = self.cart_etag
            r = self._patch("/v2/carts/%s" % self.cart_id,
                            json_body={"quantity": qty}, headers=headers,
                            name="/v2/carts/{id}")
        if r.status_code >= 400:
            r.failure("patch status %s" % r.status_code)
            return False
        r.success()
        self.cart_etag = r.headers.get("ETag", self.cart_etag)
        try:
            body = r.json()
            if body.get("csrf"):
                self.csrf = body["csrf"]
        except Exception:
            pass
        return True

    def reserve(self):
        if not self.cart_id:
            return False
        r = self._post("/v2/reservations", json_body={"cart_id": self.cart_id},
                       name="/v2/reservations")
        if r.status_code == 401 and self._handle_401(r):
            r = self._post("/v2/reservations",
                           json_body={"cart_id": self.cart_id},
                           name="/v2/reservations")
        if r.status_code >= 400:
            r.failure("reservation status %s" % r.status_code)
            return False
        r.success()
        try:
            body = r.json()
            status_url = body.get("status_url")
            if body.get("csrf"):
                self.csrf = body["csrf"]
        except Exception:
            r.failure("reservation json")
            return False
        if not status_url:
            return False
        for _ in range(5):
            time.sleep(0.06)
            g = self._get(status_url, name="/v2/reservations/status")
            if g.status_code >= 400:
                g.failure("status %s" % g.status_code)
                return False
            g.success()
            try:
                sb = g.json()
            except Exception:
                return False
            st = sb.get("status")
            if st == "ready":
                self.reservation_id = sb.get("reservation_id")
                if sb.get("csrf"):
                    self.csrf = sb["csrf"]
                return bool(self.reservation_id)
            if st in ("pending",):
                continue
            return False
        return False

    # -- work --------------------------------------------------------------
    def do_browse(self):
        ts = _now()
        r = self._post("/v2/browse", json_body={}, name="/v2/browse")
        if r.status_code == 401 and self._handle_401(r):
            r = self._post("/v2/browse", json_body={}, name="/v2/browse")
        if r.status_code == 429:
            ra = r.headers.get("Retry-After", "1")
            try:
                delay = float(ra)
            except Exception:
                delay = 1.0
            r.success()
            time.sleep(min(delay, 1.0))
            return False
        if r.status_code >= 400:
            r.failure("browse status %s" % r.status_code)
            _record_error()
            return False
        r.success()
        try:
            body = r.json()
            if not body.get("ok"):
                r.failure("browse not ok")
                _record_error()
                return False
        except Exception:
            r.failure("browse json")
            _record_error()
            return False
        _record_t0(ts)
        _record_browse(ts)
        return True

    def do_checkout(self):
        # fresh login + cart
        if not self.login():
            _record_drop()
            return False
        prod = self.pick_product()
        if not prod:
            _record_drop()
            return False
        if not self.create_cart(*prod):
            _record_drop()
            return False
        if not self.set_quantity(random.randint(1, 3)):
            _record_drop()
            return False
        if not self.reserve():
            _record_drop()
            return False
        ts = _now()
        headers = {"Idempotency-Key": self.idem_key}
        if self.cart_etag:
            headers["If-Match"] = self.cart_etag
        body = {"cart_id": self.cart_id}
        if self.reservation_id:
            body["reservation_id"] = self.reservation_id
        r = self._post("/v2/orders", json_body=body, headers=headers,
                       name="/v2/orders")
        if r.status_code == 401 and self._handle_401(r):
            r = self._post("/v2/orders", json_body=body, headers=headers,
                           name="/v2/orders")
        if r.status_code == 429:
            ra = r.headers.get("Retry-After", "1")
            try:
                delay = float(ra)
            except Exception:
                delay = 1.0
            r.success()
            time.sleep(min(delay, 1.0))
            return False
        if r.status_code >= 400:
            r.failure("order status %s" % r.status_code)
            _record_error()
            return False
        r.success()
        try:
            data = r.json()
        except Exception:
            r.failure("order json")
            _record_error()
            return False
        if not data.get("accepted"):
            r.failure("order not accepted")
            _record_error()
            return False
        if data.get("csrf"):
            self.csrf = data["csrf"]
        _record_t0(ts)
        _record_checkout(ts, self.username)
        _record_seed("%s:%s" % (self.username, data.get("id")))
        return True

    @task
    def run(self):
        if self.iterations_done >= self.max_iterations:
            raise StopUser()
        # alternate roles deterministically per user
        if self.role is None:
            self.role = "browse" if (hash(self.username) % 5) < 4 else "checkout"
        if self.role == "browse":
            self.do_browse()
        else:
            self.do_checkout()
        self.iterations_done += 1
        if self.iterations_done >= self.max_iterations:
            raise StopUser()


class BrowseUser(ShopUser):
    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self.role = "browse"


class CheckoutUser(ShopUser):
    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self.role = "checkout"


class PhasedShape(LoadTestShape):
    """Two users, two iterations each, phased plateaus 5/15/5."""

    def __init__(self):
        super().__init__()
        self.start = None
        self.done = False

    def tick(self):
        if self.done:
            return None
        now = _now()
        if self.start is None:
            self.start = now
        elapsed = now - self.start
        # warmup 5s, then 3x10s plateaus, then drain 5s
        if elapsed < 5:
            return (2, 2)
        if elapsed < 15:
            return (2, 2)
        if elapsed < 25:
            return (2, 2)
        if elapsed < 35:
            return (2, 2)
        if elapsed < 40:
            return (1, 1)
        self.done = True
        return None
